/*
 * ZOO CURATOR 
 * Current consolidated build. Historical patch-version labels were removed
 * from inline comments so this constant is the single in-code version marker.
 */
const ZOO_CURATOR_VERSION = "V2.43.44";
// Definitive V2 baseline: True-mode systems + current Information-map geography fixes.
const ZOO_REQUIRED_HTML_INTERFACE = 1;
const ZOO_REQUIRED_CSS_INTERFACE = 2;

// ============================================================
// DESKTOP UI SCALE
// 2560 x 1440 is the reference composition. Desktop HUD chrome scales as a
// coherent system below that size, while the zoo world keeps its own zoom.
// Mobile remains a separate purpose-built layout.
// ============================================================
const DESKTOP_UI_REFERENCE_WIDTH = 2560;
const DESKTOP_UI_MIN_SCALE = 0.68;

function desktopUiScale() {
    if (window.matchMedia('(max-width: 700px)').matches) return 1;

    // Scale perceptually rather than as a raw 1:1 viewport ratio. A literal
    // 1920/2560 = 0.75 made the 1080p HUD noticeably too small even though its
    // geometry was technically proportional. Keep a deliberately smaller
    // compact-laptop endpoint (<=1366px), with ordinary 1920x1080 at 0.92 and
    // 2560x1440 at the true 1.0 reference size.
    // Desktop HUD scale follows WIDTH, not the browser content height. A short
    // desktop window (devtools open, split-screen, browser chrome, etc.) must not
    // shrink the entire 2K-derived interface. Height is handled by the board and
    // popup collision logic instead.
    const viewportRatio = Math.min(
        1,
        window.innerWidth / DESKTOP_UI_REFERENCE_WIDTH
    );
    // Width endpoints are intentional viewport classes, not physical-screen
    // guesses. 1366px is the common compact-laptop desktop width; below it
    // (1280x800 / 1280x720 included) keep the same compact HUD scale rather
    // than squeezing the 1080p composition into the available width.
    const laptopRatio = 1366 / DESKTOP_UI_REFERENCE_WIDTH;
    const fullHdRatio = 1920 / DESKTOP_UI_REFERENCE_WIDTH;

    if (viewportRatio <= laptopRatio) return DESKTOP_UI_MIN_SCALE;
    if (viewportRatio <= fullHdRatio) {
        const t = (viewportRatio - laptopRatio) / (fullHdRatio - laptopRatio);
        return DESKTOP_UI_MIN_SCALE + t * (0.92 - DESKTOP_UI_MIN_SCALE);
    }

    const t = (viewportRatio - fullHdRatio) / (1 - fullHdRatio);
    return 0.92 + t * 0.08;
}

let desktopUiScaleFrame = 0;
function applyDesktopUiScaleNow() {
    const scale = desktopUiScale();
    document.documentElement.style.setProperty('--desktop-ui-scale', scale.toFixed(4));
    // One desktop scale now drives both the HUD controls and the header band.
    // Keeping a second, smaller header scale made the whole top UI feel compressed.
    document.documentElement.style.setProperty('--desktop-header-height', `${(220 * scale).toFixed(2)}px`);
    return scale;
}
function refreshDesktopUiScale() {
    if (desktopUiScaleFrame) return;
    desktopUiScaleFrame = requestAnimationFrame(() => {
        desktopUiScaleFrame = 0;
        applyDesktopUiScaleNow();
    });
}

refreshDesktopUiScale();

// V2.22.70 — Desktop peripheral HUD sizing. Keep the centre zoo name and
// Draw / Exchange / Upgrade row at the established size; only the left and
// right information clusters receive the slightly larger mock-up proportions.
function refreshDesktopPeripheralHeaderScale(){
    // V2.22.71: desktop peripheral sizing is CSS-only. Mixing CSS `scale`
    // with JS `transform:scale()` multiplied two independent scale systems and
    // was the reason the left HUD/trade UI kept changing size between builds.
    // JS now only publishes --desktop-ui-scale; CSS owns component geometry.
    if (window.matchMedia('(max-width: 700px)').matches) return;
}

// Hover previews are pointer-context UI. Browsers may suppress mouseleave while
// switching tabs/windows, so explicitly dismiss on document/window context loss.
document.addEventListener('visibilitychange',()=>{
    if(document.hidden)dismissHoverPreviewForContextLoss();
});
window.addEventListener('blur',dismissHoverPreviewForContextLoss);
window.addEventListener('pagehide',dismissHoverPreviewForContextLoss);

let desktopUiResizeRaf=0;
const scheduleDesktopUiScaleRefresh=()=>{
    if(desktopUiResizeRaf)cancelAnimationFrame(desktopUiResizeRaf);
    desktopUiResizeRaf=requestAnimationFrame(()=>{
        desktopUiResizeRaf=0;

        // Apply the new viewport scale synchronously before measuring anything.
        // refreshDesktopUiScale() schedules its own RAF, which meant the old
        // pipeline measured the 1280 layout with the previous 1080 scale when
        // Firefox Responsive Design Mode changed resolution.
        if(desktopUiScaleFrame){
            cancelAnimationFrame(desktopUiScaleFrame);
            desktopUiScaleFrame=0;
        }
        applyDesktopUiScaleNow();
        refreshDesktopPeripheralHeaderScale();

        // CSS custom-property changes participate in style/layout. Measure on
        // the following frame so a 1080 -> 1280 transition produces the same
        // geometry as loading directly at 1280.
        desktopUiResizeRaf=requestAnimationFrame(()=>{
            desktopUiResizeRaf=0;
            fitProgressTrackerAroundActions?.();
            positionOpponentTradeArea?.(true);
            refreshContextualExchangeEligibilityGlows?.();
            scheduleAnimalGlowPrecedenceRefresh?.();
        });
    });
};
window.addEventListener('resize', scheduleDesktopUiScaleRefresh, { passive: true });
window.visualViewport?.addEventListener('resize', scheduleDesktopUiScaleRefresh, { passive: true });

function checkZooInterfaceCompatibility() {
    const htmlInterface = Number(window.ZOO_INTERFACES?.html || 0);
    const cssInterface = Number.parseInt(
        getComputedStyle(document.documentElement).getPropertyValue('--zoo-css-interface'),
        10
    ) || 0;

    const issues = [];
    if (htmlInterface < ZOO_REQUIRED_HTML_INTERFACE) {
        issues.push(`index.html interface ${htmlInterface || 'unknown'}; game.js requires ${ZOO_REQUIRED_HTML_INTERFACE}`);
    }
    if (cssInterface < ZOO_REQUIRED_CSS_INTERFACE) {
        issues.push(`style.css interface ${cssInterface || 'unknown'}; game.js requires ${ZOO_REQUIRED_CSS_INTERFACE}`);
    }

    if (issues.length) {
        console.warn('Zoo Curator compatibility warning:', issues.join('; '));
    }
    return issues;
}

window.__zooCompatibilityIssues = checkZooInterfaceCompatibility();


