    const baseline=areaEvolutionSpeciesMultiset(state.areaEvolutionBaselineSpecies||[]);
    const current=areaEvolutionSpeciesMultiset((state.animals||[]).map(animal=>animalDisplayName(animal)));
    let baselineCount=0,currentCount=0,shared=0;
    for(const n of baseline.values())baselineCount+=n;
