    const minCol=Math.round(b.x/TRUE_ENC_CELL_W),maxCol=Math.round((b.x+b.w)/TRUE_ENC_CELL_W)-1;
    const minRow=Math.round(b.y/TRUE_ENC_CELL_H),maxRow=Math.round((b.y+b.h)/TRUE_ENC_CELL_H)-1;
