    trueGuestAssignInterest(g);
    trueGuestFavouriteAnimal(g);
    // Max speed deliberately has no per-guest popup/click handler. Everything
    // else about the visitor is generated exactly like slower speeds.
    if(Number(state.trueCalendar?.speed)!==3){
        el.addEventListener('pointerdown',event=>trueGuestInspect(g,event));
    }

    // First clear the gate before selecting an attraction. Find a nearby free
    // walk cell farther from the entrance; this prevents the first visitor in
    // a party from immediately stopping across the opening.
