function normalizeOneEarthCode(value){ return String(value||'').trim().toUpperCase(); }
function oneEarthFeatureCode(feature){
    const p=feature?.properties||{};
    // One Earth's distributed layer uses BIOREGIO_1, whose value is normally
    // "Bioregion display name (NT11)". Keep named candidates first, then scan
    // every property so future harmless schema changes cannot blank the map.
    const candidates=[
        p.BIOREGIO_1,p.BIOREGION_,p.BIOREGION,p.bioregion,
        p.code,p.CODE,p.Code,p.bioregion_code,p.BIOREGION_CODE,
        p.biocode,p.BIOCODE,p.Bioregion,
        ...Object.values(p)
    ];
    for(const value of candidates){
        const match=String(value||'').toUpperCase().match(/\b(?:NT|NA|PA|AT|IM|AU|OC|AN)\d+\b/);
        if(match)return match[0];
    }
    return '';
}
function installZooGeographyData(payload){
    ZOO_GEOGRAPHY.factual_regions=Object.create(null);
    ZOO_GEOGRAPHY.zoo_regions=Object.create(null);
    ZOO_GEOGRAPHY.realms=Object.create(null);
    ZOO_GEOGRAPHY.range_display_groups=Object.create(null);
    for(const [key,meta] of Object.entries(payload?.realms||{})){
        ZOO_GEOGRAPHY.realms[String(key).toLowerCase()]={
            label:String(meta?.name||key),
            subrealms:(meta?.subrealms||[]).map(value=>String(value||'').toLowerCase()).filter(Boolean)
        };
    }
    for(const [key,meta] of Object.entries(payload?.subrealms||{})){
        ZOO_GEOGRAPHY.zoo_regions[String(key).toLowerCase()]={
            label:String(meta?.name||key),
            realm:String(meta?.realm||'').toLowerCase(),
            bioregions:(meta?.bioregions||[]).map(normalizeOneEarthCode)
        };
    }
    for(const [code,meta] of Object.entries(payload?.bioregions||{})){
        const key=normalizeOneEarthCode(code).toLowerCase();
        const subrealm=String(meta?.subrealm||'').toLowerCase();
        const realm=String(meta?.realm||ZOO_GEOGRAPHY.zoo_regions[subrealm]?.realm||'').toLowerCase();
        ZOO_GEOGRAPHY.factual_regions[key]={
            code:normalizeOneEarthCode(code),
            label:String(meta?.name||code),
            zoo_region:subrealm,
            realm
        };
    }
    for(const [key,meta] of Object.entries(payload?.range_display_groups||{})){
        ZOO_GEOGRAPHY.range_display_groups[String(key).toLowerCase()]={
            label:String(meta?.name||key),
            realms:(meta?.realms||[]).map(value=>String(value||'').toLowerCase()).filter(Boolean),
            continents:(meta?.continents||[]).map(value=>String(value||'').toLowerCase()).filter(Boolean),
            match:String(meta?.match||'contains').toLowerCase(),
            min_continents:Number(meta?.min_continents)||0
        };
    }
}
function loadZooGeographyData(){
    // Install the bundled labels immediately so tooltips are deterministic even
    // before/failing the optional external geography fetch.
    if(!Object.keys(ZOO_GEOGRAPHY.factual_regions).length){
        installZooGeographyData(ZOO_GEOGRAPHY_BUILTIN_ONE_EARTH);
    }
    if(!zooGeographyDataPromise){
        zooGeographyDataPromise=fetch(`${ZOO_GEOGRAPHY_DATA_URL}?v=${encodeURIComponent(ZOO_CURATOR_VERSION)}`)
            .then(r=>{if(!r.ok)throw new Error(`Geography HTTP ${r.status}`);return r.json();})
            .then(data=>{installZooGeographyData(data);return data;})
            .catch(error=>{
                console.warn('Could not load Zoo Curator geography data; using built-in One Earth labels:',error);
                installZooGeographyData(ZOO_GEOGRAPHY_BUILTIN_ONE_EARTH);
                return ZOO_GEOGRAPHY_BUILTIN_ONE_EARTH;
            });
    }
    return zooGeographyDataPromise;
}
const TRUE_AREA_NAMES_DATA_URL='assets/data/zoo-area-names.json';
let trueAreaNamesData=null;
let trueAreaNamesPromise=null;

function loadTrueAreaNamesData(){
    if(trueAreaNamesPromise)return trueAreaNamesPromise;
    trueAreaNamesPromise=Promise.all([
        loadZooGeographyData(),
        fetch(`${TRUE_AREA_NAMES_DATA_URL}?v=${encodeURIComponent(ZOO_CURATOR_VERSION)}`)
            .then(r=>{if(!r.ok)throw new Error(`Area names HTTP ${r.status}`);return r.json();})
    ]).then(([,data])=>{
        trueAreaNamesData=data;
        if(typeof renderAll==='function')requestAnimationFrame(()=>renderAll());
        return data;
    }).catch(error=>{
        console.warn('Could not load True geographic Area presentation data:',error);
        trueAreaNamesData=null;
        return null;
    });
    return trueAreaNamesPromise;
}

const animalGeographyMetaCache=new Map();
function animalGeographyCacheKey(animal,entry=null){
    return String(entry?.filename||entry?.english_filename||animal?.filename||animal?.scientific_name||animal?.id||'');
}
function animalGeographyMeta(animal){
    const quickKey=animalGeographyCacheKey(animal);
    if(quickKey&&animalGeographyMetaCache.has(quickKey))return animalGeographyMetaCache.get(quickKey);
    const entry=inventoryEntryForAnimal(animal);
    const key=animalGeographyCacheKey(animal,entry)||quickKey;
    if(key&&animalGeographyMetaCache.has(key))return animalGeographyMetaCache.get(key);
    const list=(entry?.wild_regions||[]).map(normalizeOneEarthCode).filter(Boolean);
    const meta={codes:new Set(list),signature:[...list].sort().join(',')};
    if(key)animalGeographyMetaCache.set(key,meta);
    return meta;
}
function animalWildRegionCodes(animal){
    return animalGeographyMeta(animal).codes;
}
function geographyMetaForCodeUncached(code){
    return ZOO_GEOGRAPHY.factual_regions[String(normalizeOneEarthCode(code)||'').toLowerCase()]||null;
}
const geographyMetaCodeCache=new Map();
function geographyMetaForCode(code){
    const normalized=normalizeOneEarthCode(code);
    if(geographyMetaCodeCache.has(normalized))return geographyMetaCodeCache.get(normalized);
    const meta=geographyMetaForCodeUncached(normalized)||null;
    geographyMetaCodeCache.set(normalized,meta);
    return meta;
}
// Species-to-region truth does not depend on zoo layout. Keep these factual
// matches across reconciliation passes instead of throwing thousands of
// identical lookups away after every animal move/draw. Keys include the
// inventory-derived geography signature so a changed data file cannot reuse an
// old answer for the same filename.
const persistentAnimalGeographicMatchCache=new Map();

let activeAnimalGeographicMatchCache=null;
function animalMatchesGeographicUnit(animal,level,key){
    const meta=animalGeographyMeta(animal);
    const species=animalGeographyCacheKey(animal);
    const cacheKey=activeAnimalGeographicMatchCache
        ? `${species}|${meta.signature}|${level}|${key}`
        : null;
    if(cacheKey&&activeAnimalGeographicMatchCache.has(cacheKey))
        return activeAnimalGeographicMatchCache.get(cacheKey);
    const codes=meta.codes;
    let matched=false;
    if(codes.size){
        if(level==='bioregion')matched=codes.has(normalizeOneEarthCode(key));
        else for(const code of codes){
            const meta=geographyMetaForCode(code);
            if(!meta)continue;
            if(level==='subregion'&&meta.zoo_region===key){matched=true;break;}
            if(level==='realm'&&meta.realm===key){matched=true;break;}
        }
    }
    if(cacheKey)activeAnimalGeographicMatchCache.set(cacheKey,matched);
    return matched;
}
function geographicLogicalExhibits(){
    if(state.gameMode==='true')return (state.enclosures||[]).map(enc=>({
        ...enc,
        _geoPhysicalEnclosure:enc,
        _geoGroup:null,
        _geoUnitId:String(enc.id)
    }));
    const units=[];
    for(const enc of (state.enclosures||[])){
        const groups=getGroups(enc);
        for(let gi=0;gi<groups.length;gi++){
            const group=groups[gi];
            units.push({
                ...enc,
                id:`${enc.id}:g${gi}`,
                _geoPhysicalEnclosure:enc,
                _geoGroup:[...group],
                _geoUnitId:`${enc.id}:g${gi}`
            });
        }
    }
    return units;
}
let activeGeographicAnimalIndex=null;
let activeGeographicResidentCache=null;
let activeGeographicQualificationCache=null;
let activeGeographicCandidateKeys=null;
let activeGeographicAdjacencyIndex=null;

// Adjacency depends only on enclosure/logical-cell geometry, never on species.
// Keep it across animal moves/additions so a geography update does not rebuild
// even the spatial graph unless the actual enclosure layout changed.
let geographicAdjacencyGeometryCache={signature:null,index:null};

function geographicAdjacencyGeometrySignature(units){
    const parts=(units||[]).map(unit=>{
        const key=geographicLogicalCellKey(unit);
        const r=geographicUnitRect(unit);
        return `${key}:${Math.round(r.x*100)/100},${Math.round(r.y*100)/100},${Math.round(r.w*100)/100},${Math.round(r.h*100)/100}`;
    }).sort();
    return `${state.gameMode||''}#${parts.join('|')}`;
}

function buildGeographicAdjacencyIndex(units){
    const source=units||[];
    const geometrySignature=geographicAdjacencyGeometrySignature(source);
    if(geographicAdjacencyGeometryCache.signature===geometrySignature &&
       geographicAdjacencyGeometryCache.index instanceof Map){
        return geographicAdjacencyGeometryCache.index;
    }

    const index=new Map(source.map(unit=>[geographicLogicalCellKey(unit),[]]));
    if(source.length<2){
        geographicAdjacencyGeometryCache={signature:geometrySignature,index};
        return index;
    }

    // Large Classic zoos used to test every logical cell against every other
    // logical cell (O(n²)) whenever geography genuinely changed. Area adjacency
    // is local, so use a spatial hash and only test units whose expanded bounds
    // occupy a common bucket. This preserves the exact adjacency predicate while
    // making distant enclosure cards essentially free.
    const bucketSize=Math.max(
        64,
        state.gameMode==='true'?TRUE_ENC_CELL_W:ENCLOSURE_W/2,
        state.gameMode==='true'?TRUE_ENC_CELL_H:ENCLOSURE_H/2
    );
    const reach=(state.gameMode==='true'?TRUE_ENC_EXTERNAL_GAP:ENCLOSURE_GAP)+
        ENCLOSURE_AREA_ADJACENCY_TOLERANCE+10;
    const buckets=new Map();
    const rects=source.map(geographicUnitRect);
    const bucketKey=(x,y)=>`${x},${y}`;

    for(let i=0;i<source.length;i++){
        const r=rects[i];
        const minX=Math.floor((r.x-reach)/bucketSize);
        const maxX=Math.floor((r.x+r.w+reach)/bucketSize);
        const minY=Math.floor((r.y-reach)/bucketSize);
        const maxY=Math.floor((r.y+r.h+reach)/bucketSize);
        for(let bx=minX;bx<=maxX;bx++)for(let by=minY;by<=maxY;by++){
            const key=bucketKey(bx,by);
            if(!buckets.has(key))buckets.set(key,[]);
            buckets.get(key).push(i);
        }
    }

    const tested=new Set();
    for(const members of buckets.values()){
        for(let ai=0;ai<members.length;ai++)for(let bi=ai+1;bi<members.length;bi++){
            const i=members[ai],j=members[bi];
            if(i===j)continue;
            const lo=Math.min(i,j),hi=Math.max(i,j),pair=`${lo}:${hi}`;
            if(tested.has(pair))continue;
            tested.add(pair);
            const a=source[lo],b=source[hi];
            if(!geographicUnitsAdjacent(a,b))continue;
            const ak=geographicLogicalCellKey(a),bk=geographicLogicalCellKey(b);
            index.get(ak)?.push(bk);
            index.get(bk)?.push(ak);
        }
    }
    geographicAdjacencyGeometryCache={signature:geometrySignature,index};
    return index;
}
function verifyGeographicAdjacencyOptimization(){
    const units=geographicLogicalExhibits();
    const optimized=buildGeographicAdjacencyIndex(units);
    const exhaustive=new Map(units.map(unit=>[geographicLogicalCellKey(unit),[]]));
    for(let i=0;i<units.length;i++)for(let j=i+1;j<units.length;j++){
        if(!geographicUnitsAdjacent(units[i],units[j]))continue;
        const a=geographicLogicalCellKey(units[i]),b=geographicLogicalCellKey(units[j]);
        exhaustive.get(a)?.push(b);exhaustive.get(b)?.push(a);
    }
    const normalized=map=>[...map.entries()].map(([k,v])=>[k,[...v].sort()]).sort((a,b)=>a[0].localeCompare(b[0]));
    const ok=JSON.stringify(normalized(optimized))===JSON.stringify(normalized(exhaustive));
    return {ok,units:units.length,optimizedEdges:[...optimized.values()].reduce((n,v)=>n+v.length,0)/2,
        exhaustiveEdges:[...exhaustive.values()].reduce((n,v)=>n+v.length,0)/2};
}

function buildGeographicAnimalIndex(){
    const byEnclosure=new Map();
    for(const animal of state.animals||[]){
        if(!animal||animal.enclosureId==null)continue;
        const key=String(animal.enclosureId);
        if(!byEnclosure.has(key))byEnclosure.set(key,[]);
        byEnclosure.get(key).push(animal);
    }
    return byEnclosure;
}
function animalsInGeographicExhibit(unit){
    if(!unit)return [];
    const residentKey=activeGeographicResidentCache?geographicLogicalCellKey(unit):null;
    if(residentKey&&activeGeographicResidentCache.has(residentKey))
        return activeGeographicResidentCache.get(residentKey);
    const enc=unit._geoPhysicalEnclosure||unit;
    let result;
    if(state.gameMode==='true'||!unit._geoGroup){
        result=activeGeographicAnimalIndex
            ? (activeGeographicAnimalIndex.get(String(enc.id))||[])
            : animalsInWholeEnclosure(enc);
    }else{
        const slots=unit._geoGroupSet||(unit._geoGroupSet=new Set(unit._geoGroup));
        const residents=activeGeographicAnimalIndex
            ? (activeGeographicAnimalIndex.get(String(enc.id))||[])
            : (state.animals||[]).filter(animal=>animal&&animal.enclosureId===enc.id);
        result=residents.filter(animal=>slots.has(animal.slotIndex));
    }
    if(residentKey)activeGeographicResidentCache.set(residentKey,result);
    return result;
}
function geographicLogicalCellKey(unit){
    if(!unit)return '';
    if(unit._geoGroup){
        const enc=unit._geoPhysicalEnclosure||unit;
        const slots=[...unit._geoGroup].map(Number).filter(Number.isFinite).sort((a,b)=>a-b);
        return `classic:${enc.id}:${slots.join('.')}`;
    }
    const enc=unit._geoPhysicalEnclosure||unit;
    if(state.gameMode==='true'){
        const cells=trueBuiltWorldCells(enc).map(c=>`${c.col},${c.row}`).sort();
        return `true:${enc.id}:${cells.join('|')}`;
    }
    return `enc:${enc.id}`;
}
function geographicLogicalCellSet(units){
    return new Set((units||[]).map(geographicLogicalCellKey).filter(Boolean));
}
function geographicCellSetSignature(units){
    return [...geographicLogicalCellSet(units)].sort().join('||');
}
function geographicUnitRect(unit){
    const enc=unit._geoPhysicalEnclosure||unit;
    if(state.gameMode==='true')return trueAreaEnclosureRect(enc);
    const group=unit._geoGroup||getAllSlots(enc);
    const cells=group.map(Number).filter(n=>n>=0&&n<=3).map(n=>({col:n%2,row:Math.floor(n/2)}));
    if(!cells.length)return {x:enc.x,y:enc.y,w:ENCLOSURE_W,h:ENCLOSURE_H};
    const minC=Math.min(...cells.map(c=>c.col)),maxC=Math.max(...cells.map(c=>c.col));
    const minR=Math.min(...cells.map(c=>c.row)),maxR=Math.max(...cells.map(c=>c.row));
    // Logical exhibits are subdivisions *inside* one physical enclosure card.
    // The inter-card gutter belongs between cards and must not be folded into
    // this internal geometry; doing so makes generated Areas disagree with the
    // human Area painter and can extend a right/bottom exhibit past its card.
    const pitchX=ENCLOSURE_W/2,pitchY=ENCLOSURE_H/2;
    return {x:enc.x+minC*pitchX,y:enc.y+minR*pitchY,w:(maxC-minC+1)*pitchX,h:(maxR-minR+1)*pitchY};
}
function geographicUnitsAdjacent(a,b){
    if(state.gameMode==='true')return enclosuresAreAreaAdjacent(a._geoPhysicalEnclosure||a,b._geoPhysicalEnclosure||b);
    const ra=geographicUnitRect(a),rb=geographicUnitRect(b);
    const encA=a._geoPhysicalEnclosure||a,encB=b._geoPhysicalEnclosure||b;
    const sameCard=encA?.id!=null&&encA.id===encB?.id;
    // Logical cells inside one Classic enclosure card meet directly. Cells on
    // neighbouring cards are separated by the normal visual card gutter, which
    // must still count as Area adjacency; otherwise one continuous geographic
    // block is split into parallel Areas merely because it crosses card edges.
    const expectedGap=sameCard?0:ENCLOSURE_GAP;
    const tol=ENCLOSURE_AREA_ADJACENCY_TOLERANCE+8;
    const vo=Math.min(ra.y+ra.h,rb.y+rb.h)-Math.max(ra.y,rb.y);
    const ho=Math.min(ra.x+ra.w,rb.x+rb.w)-Math.max(ra.x,rb.x);
    const horizontalGap=Math.min(Math.abs((ra.x+ra.w+expectedGap)-rb.x),Math.abs((rb.x+rb.w+expectedGap)-ra.x));
    const verticalGap=Math.min(Math.abs((ra.y+ra.h+expectedGap)-rb.y),Math.abs((rb.y+rb.h+expectedGap)-ra.y));
    return (horizontalGap<=tol&&vo>8)||(verticalGap<=tol&&ho>8);
}

function enclosureGeographicQualification(enclosure,level,key){
    const qualificationKey=activeGeographicQualificationCache
        ? `${geographicLogicalCellKey(enclosure)}|${level}|${key}`
        : null;
    if(qualificationKey&&activeGeographicQualificationCache.has(qualificationKey))
        return activeGeographicQualificationCache.get(qualificationKey);

    const animals=animalsInGeographicExhibit(enclosure);
    let result=null;
    if(animals.length){
        let fitting=0;
        for(const animal of animals)if(animalMatchesGeographicUnit(animal,level,key))fitting++;
        const irregular=animals.length-fitting;
        // Geographic Areas are literal: every resident in this logical enclosure
        // cell must belong to the proposed geography. Mixed-range companions do
        // not count as geographic evidence at any hierarchy level.
        const qualifies=fitting===animals.length;
        result={qualifies,fitting,irregular,total:animals.length,pure:qualifies};
    }
    // Cache null as well: empty logical exhibits are tested repeatedly by many
    // later candidate/sibling/card-admission passes.
    if(qualificationKey)activeGeographicQualificationCache.set(qualificationKey,result);
    return result;
}
function geographicAreaTheme(level,key,entry){
    const title=String(entry?.area_name||entry?.canonical_name||key);
    const realmClass={
        'subarctic-america':'theme-north-america','northern-america':'theme-north-america',
        'central-america-caribbean':'theme-north-america','southern-america':'theme-south-america',
        'subarctic-eurasia':'theme-europe','western-eurasia':'theme-europe',
        'central-eurasia':'theme-asia','eastern-eurasia':'theme-asia','southern-eurasia':'theme-asia',
        'afrotropics':'theme-africa','indomalaya':'theme-asia','australasia':'theme-oceania',
        'oceania':'theme-oceania','antarctica':'theme-antarctica'
    };
    const realm=level==='realm'?key:(entry?.realm||'');
    return {
        key:`truegeo:${level}:${key}`,
        title,
        className:level==='realm'?(realmClass[realm]||'theme-subregion'):'theme-subregion',
        layer:level==='realm'?'geography':(level==='subregion'?'subregion':'bioregion'),
        geographicLevel:level,
        geographicKey:key,
        canonicalName:String(entry?.canonical_name||title)
    };
}
function geographicConnectedComponents(eligible){
    // Logical exhibits, not enclosure cards, are the graph nodes. A Classic/
    // Sandbox enclosure card can contain up to four independent enclosures.
    const keyOf=e=>geographicLogicalCellKey(e);
    const unseen=new Set(eligible.map(keyOf));
    const byId=new Map(eligible.map(e=>[keyOf(e),e])),out=[];
    while(unseen.size){
        const firstKey=unseen.values().next().value;unseen.delete(firstKey);
        const first=byId.get(firstKey);if(!first)continue;
        const component=[first];
        if(activeGeographicAdjacencyIndex){
            // Traverse only neighbours that are also eligible for this
            // geography. This turns each candidate's connectivity pass into a
            // small graph walk rather than eligible² geometry comparisons.
            const queue=[firstKey];
            for(let qi=0;qi<queue.length;qi++){
                for(const neighbourKey of activeGeographicAdjacencyIndex.get(queue[qi])||[]){
                    if(!unseen.has(neighbourKey)||!byId.has(neighbourKey))continue;
                    unseen.delete(neighbourKey);
                    queue.push(neighbourKey);
                    component.push(byId.get(neighbourKey));
                }
            }
        }else{
            for(let i=0;i<component.length;i++){
                for(const candidate of eligible){
                    const id=keyOf(candidate);
                    if(!unseen.has(id)||!geographicUnitsAdjacent(component[i],candidate))continue;
                    unseen.delete(id);component.push(candidate);
                }
            }
        }
        out.push(component);
    }
    return out;
}
function geographicFootprintCells(enclosure){
    if(state.gameMode==='true'){
        return trueBuiltWorldCells(enclosure);
    }
    // Classic/Sandbox enclosure cards occupy one logical Area-grid cell.
    // Using True construction-cell dimensions here made V2.20's infill test
    // misread ordinary card positions and could absorb unrelated enclosures.
    const stepX=ENCLOSURE_W+ENCLOSURE_GAP;
    const stepY=ENCLOSURE_H+ENCLOSURE_GAP;
    return [{
        col:Math.round((Number(enclosure.x)||0)/stepX),
        row:Math.round((Number(enclosure.y)||0)/stepY)
    }];
}

function geographicCandidateSupport(unit,candidate,level){
    const candidateKey=level==='bioregion'
        ? normalizeOneEarthCode(candidate?.key)
        : String(candidate?.key||'').toLowerCase();
    const animals=animalsInGeographicExhibit(unit); let score=0;
    for(const animal of animals){
        if(!animalMatchesGeographicUnit(animal,level,candidateKey))continue;
        score+=1;
        if(level==='bioregion')score+=1/(animalWildRegionCodes(animal).size||1);
    }
    return score;
}

function geographicMembershipSet(value){
    if(value instanceof Set)return new Set(value);
    if(Array.isArray(value))return new Set(value);
    if(value instanceof Map)return new Set(value.keys());
    // Older JSON snapshots can contain serialized Set values as plain objects
    // (including {}). Never pass such an object directly to new Set(), because
    // plain objects are not iterable.
    if(value&&typeof value==='object'){
        return new Set(Object.entries(value)
            .filter(([,enabled])=>enabled!==false&&enabled!=null)
            .map(([key])=>{
                const numeric=Number(key);
                return Number.isFinite(numeric)&&String(numeric)===String(key) ? numeric : key;
            }));
    }
    return new Set();
}
function geographicComponentIsPure(component,level,key){
    // Birth rule: EVERY resident animal in EVERY occupied logical enclosure in
    // a brand-new standalone Area must factually match the proposed geography.
    // Empty cells are not species errors and therefore do not block creation.
    let residents=0;
    for(const unit of component||[]){
        for(const animal of animalsInGeographicExhibit(unit)){
            residents++;
            if(!animalMatchesGeographicUnit(animal,level,key))return false;
        }
    }
    return residents>0;
}

function buildActiveGeographicCandidateKeys(){
    const keys={
        realm:new Set(),
        subregion:new Set(),
        bioregion:new Set()
    };
    // Only occupied zoo animals can provide evidence for a new generated Area.
    // Derive all possible hierarchy keys from their factual wild_regions once.
    for(const animal of state.animals||[]){
        if(!animal||animal.enclosureId==null)continue;
        for(const code of animalWildRegionCodes(animal)){
            const normalized=normalizeOneEarthCode(code);
            if(normalized)keys.bioregion.add(normalized);
            const meta=geographyMetaForCode(normalized);
            if(!meta)continue;
            if(meta.zoo_region)keys.subregion.add(String(meta.zoo_region).toLowerCase());
            if(meta.realm)keys.realm.add(String(meta.realm).toLowerCase());
        }
    }
    return keys;
}

function buildGeographicCandidateUnitIndex(units){
    const result={
        realm:new Map(),
        subregion:new Map(),
        bioregion:new Map()
    };
    const add=(level,key,unit)=>{
        if(!key)return;
        const map=result[level];
        if(!map.has(key))map.set(key,[]);
        map.get(key).push(unit);
    };
    for(const unit of units||[]){
        const residents=animalsInGeographicExhibit(unit);
        if(!residents.length)continue;
        let common=null;
        for(const animal of residents){
            const animalKeys={realm:new Set(),subregion:new Set(),bioregion:new Set()};
            for(const code of animalWildRegionCodes(animal)){
                const normalized=normalizeOneEarthCode(code);
                if(normalized)animalKeys.bioregion.add(normalized);
                const meta=geographyMetaForCode(normalized);
                if(!meta)continue;
                if(meta.zoo_region)animalKeys.subregion.add(String(meta.zoo_region).toLowerCase());
                if(meta.realm)animalKeys.realm.add(String(meta.realm).toLowerCase());
            }
            if(common===null){
                common=animalKeys;
            }else{
                for(const level of ['realm','subregion','bioregion']){
                    common[level]=new Set([...common[level]].filter(key=>animalKeys[level].has(key)));
                }
            }
            if(common && !common.realm.size && !common.subregion.size && !common.bioregion.size)break;
        }
        if(!common)continue;
        for(const level of ['realm','subregion','bioregion'])
            for(const key of common[level])add(level,key,unit);
    }
    return result;
}

let activeGeographicCandidateUnitIndex=null;

function geographicCandidateComponents(units,level,entries,minimum){
    const out=[];
    for(const [rawKey,entry] of Object.entries(entries)){
        if(entry?.generate===false)continue;
        const key=level==='bioregion'?normalizeOneEarthCode(rawKey):String(rawKey).toLowerCase();
        // A definition that no current animal can support cannot possibly reach
        // the generation threshold.
        if(activeGeographicCandidateKeys&&!activeGeographicCandidateKeys[level]?.has(key))continue;
        // Qualification comes directly from the factual geography hierarchy.
        // Do NOT gate a child on a rendered/generated parent Area. Generated
        // parents are presentation results and may collapse, be ambiguous, or
        // fail their own threshold while a precise child is still valid.
        const possibleUnits=activeGeographicCandidateUnitIndex?.[level]?.get(key)||[];
        let eligible=possibleUnits.filter(unit=>{
            const q=enclosureGeographicQualification(unit,level,key);
            return !!q?.qualifies;
        });
        if(eligible.length<minimum)continue;
        for(const component of geographicConnectedComponents(eligible)){
            if(component.length<minimum)continue;
            // Baseline rule: generated geography is a direct statement about
            // the animals currently occupying these cells. Every member cell
            // must qualify now; historical membership cannot preserve or expand
            // an Area through an irregular cell.
            const qmap=new Map(component.map(u=>[geographicLogicalCellKey(u),enclosureGeographicQualification(u,level,key)]));
            const stats=component.reduce((acc,u)=>{
                const q=qmap.get(geographicLogicalCellKey(u));
                acc.f+=q?.fitting||0; acc.i+=q?.irregular||0; acc.t+=q?.total||0;
                return acc;
            },{f:0,i:0,t:0});
            if(!geographicComponentIsPure(component,level,key))continue;
            out.push({
                theme:geographicAreaTheme(level,key,entry),
                enclosures:[...component],
                qualifyingEnclosures:component,
                infillEnclosures:[],
                _geoEntry:entry,_minimum:minimum,
                _support:component.reduce((s,u)=>s+geographicCandidateSupport(u,{key,entry},level),0)
            });
        }
    }
    return out;
}
function verifyGeographicCandidateIndexOptimization(){
    const units=geographicLogicalExhibits();
    activeGeographicAnimalIndex=buildGeographicAnimalIndex();
    activeGeographicResidentCache=new Map();
    activeGeographicQualificationCache=new Map();
    const indexed=buildGeographicCandidateUnitIndex(units);
    const mismatches=[];
    const data=trueAreaNamesData||{};
    const defs=[
        ['realm',data.realms||{}],
        ['subregion',data.subrealms||{}],
        ['bioregion',data.bioregions||{}]
    ];
    for(const [level,entries] of defs){
        for(const rawKey of Object.keys(entries)){
            const key=level==='bioregion'?normalizeOneEarthCode(rawKey):String(rawKey).toLowerCase();
            const oldSet=new Set(units.filter(unit=>enclosureGeographicQualification(unit,level,key)?.qualifies)
                .map(geographicLogicalCellKey));
            const newSet=new Set((indexed[level].get(key)||[])
                .filter(unit=>enclosureGeographicQualification(unit,level,key)?.qualifies)
                .map(geographicLogicalCellKey));
            if(oldSet.size!==newSet.size||[...oldSet].some(k=>!newSet.has(k)))
                mismatches.push({level,key,old:oldSet.size,indexed:newSet.size});
        }
    }
    activeGeographicAnimalIndex=null;
    activeGeographicResidentCache=null;
    activeGeographicQualificationCache=null;
    return {ok:mismatches.length===0,mismatches};
}

function geographicAnimalRegionCodes(animal){
    const entry=inventoryEntryForAnimal(animal)||{};
    return Array.isArray(entry.wild_regions)
        ? entry.wild_regions.map(normalizeOneEarthCode).filter(Boolean)
        : [];
}
function geographicAnimalSpeciesKey(animal){
    const entry=inventoryEntryForAnimal(animal)||{};
    return String(entry.scientific_name||entry.scientificName||animal?.scientific_name||
        animal?.fileName||animal?.filename||animal?.name||'').trim().toLowerCase();
}

function geographicTierCandidateScore(group,level){
    const identity={level,key:group?.theme?.geographicKey};
    const species=new Set();
    let endemicCells=0;
    for(const unit of group?.qualifyingEnclosures||[]){
        let cellEndemic=false;
        for(const animal of animalsInGeographicExhibit(unit)){
            if(!geographicAnimalIsDiagnostic(animal,identity))continue;
            cellEndemic=true;
            const key=geographicAnimalSpeciesKey(animal);
            if(key)species.add(key);
        }
        if(cellEndemic)endemicCells++;
    }
    return {
        endemicSpecies:species.size,
        endemicCells,
        support:Number(group?._support)||0,
        cells:(group?.qualifyingEnclosures||[]).length,
        key:String(group?.theme?.geographicKey||'')
    };
}
function compareGeographicTierCandidates(a,b,level){
    const A=geographicTierCandidateScore(a,level),B=geographicTierCandidateScore(b,level);
    // Narrow tiers prefer the strongest endemic identity. Realms have no endemic
    // requirement, so support/footprint decide ambiguous broad-range cells.
    if(level!=='realm'){
        const endemic=B.endemicSpecies-A.endemicSpecies || B.endemicCells-A.endemicCells;
        if(endemic)return endemic;
    }
    return B.support-A.support || B.cells-A.cells || A.key.localeCompare(B.key);
}
function geographicResolveExclusiveTier(groups,level){
    if(!Array.isArray(groups)||groups.length<2)return groups||[];

    // A logical enclosure cell can belong to exactly one Area at a given
    // geographic tier. Cross-tier nesting remains valid: realm -> subregion ->
    // bioregion. This resolves ownership per cell rather than deleting an entire
    // otherwise-valid Area because one edge cell overlaps another candidate.
    const candidatesByCell=new Map();
    for(const group of groups){
        for(const unit of group.qualifyingEnclosures||[]){
            const cell=geographicLogicalCellKey(unit);
            if(!candidatesByCell.has(cell))candidatesByCell.set(cell,[]);
            candidatesByCell.get(cell).push(group);
        }
    }
    const ownedByGroup=new Map(groups.map(group=>[group,[]]));
    for(const [cell,candidates] of candidatesByCell.entries()){
        candidates.sort((a,b)=>compareGeographicTierCandidates(a,b,level));
        const winner=candidates[0];
        const unit=(winner.qualifyingEnclosures||[]).find(u=>geographicLogicalCellKey(u)===cell);
        if(unit)ownedByGroup.get(winner).push(unit);
    }

    const resolved=[];
    for(const group of groups){
        const owned=ownedByGroup.get(group)||[];
        if(owned.length<(group._minimum||4))continue;
        // Ownership can split one candidate into disconnected islands. Each
        // surviving Area must independently meet the normal minimum size.
        for(const component of geographicConnectedComponents(owned)){
            if(component.length<(group._minimum||4))continue;
            resolved.push({...group,
                enclosures:[...component],
                qualifyingEnclosures:[...component],
                infillEnclosures:[],
                _support:component.reduce((sum,u)=>sum+geographicCandidateSupport(
                    u,{key:group?.theme?.geographicKey,entry:group?._geoEntry},level),0)
            });
        }
    }
    return resolved;
}

function generatedGeographicAreaGroups(){
    const data=trueAreaNamesData;if(!data)return [];
    const geographySignature=areaRenderStateSignature();
    if(state.gameMode!=='true' &&
       classicGeneratedGeographyCache.signature===geographySignature &&
       Array.isArray(classicGeneratedGeographyCache.groups)){
        return classicGeneratedGeographyCache.groups;
    }
    // Geography asks for the same exhibit residents hundreds/thousands of times
    // while resolving candidates. Build one O(n animals) index for this pass.
    activeGeographicAnimalIndex=buildGeographicAnimalIndex();
    activeGeographicResidentCache=new Map();
    activeGeographicQualificationCache=new Map();
    activeAnimalGeographicMatchCache=persistentAnimalGeographicMatchCache;
    activeGeographicCandidateKeys=buildActiveGeographicCandidateKeys();
    const units=geographicLogicalExhibits(),all=[];
    activeGeographicAdjacencyIndex=buildGeographicAdjacencyIndex(units);
    activeGeographicCandidateUnitIndex=buildGeographicCandidateUnitIndex(units);

    // Realm is the broadest generated tier. Every tier owns its logical cells
    // exclusively, while different tiers may nest over the same cells.
    const realmCandidates=geographicCandidateComponents(units,'realm',data.realms||{},4);
    all.push(...geographicResolveExclusiveTier(realmCandidates,'realm'));

    const resolvedRealms=all.filter(g=>g?.theme?.geographicLevel==='realm');

    const filterChildToValidParent=(groups,parentGroups,parentLevel)=>{
        const parentCellsByKey=new Map();
        for(const parent of parentGroups){
            const key=String(parent?.theme?.geographicKey||'').toLowerCase();
            if(!key)continue;
            if(!parentCellsByKey.has(key))parentCellsByKey.set(key,new Set());
            const cells=parentCellsByKey.get(key);
            for(const unit of parent.qualifyingEnclosures||parent.enclosures||[]){
                cells.add(geographicLogicalCellKey(unit));
            }
        }
        const filtered=[];
        for(const group of groups){
            const childIdentity={
                level:group?.theme?.geographicLevel,
                key:group?.theme?.geographicKey
            };
            const hierarchy=geographicIdentityHierarchy(childIdentity);
            const requiredParent=String(hierarchy?.[parentLevel]||'').toLowerCase();
            const allowed=parentCellsByKey.get(requiredParent);
            if(!requiredParent||!allowed)continue;
            const owned=(group.qualifyingEnclosures||[]).filter(unit=>
                allowed.has(geographicLogicalCellKey(unit))
            );
            if(owned.length<(group._minimum||4))continue;
            for(const component of geographicConnectedComponents(owned)){
                if(component.length<(group._minimum||4))continue;
                filtered.push({...group,
                    enclosures:[...component],
                    qualifyingEnclosures:[...component],
                    infillEnclosures:[]
                });
            }
        }
        return filtered;
    };

    // A Subregion may only occupy cells that are already owned by its actual
    // OneEarth Realm. Physical overlap with some other Realm is irrelevant.
    const subCandidates=geographicCandidateComponents(units,'subregion',data.subrealms||{},4);
    const resolvedSubs=filterChildToValidParent(
        geographicResolveExclusiveTier(subCandidates,'subregion'),
        resolvedRealms,
        'realm'
    );
    all.push(...resolvedSubs);

    // Likewise a Bioregion may only occupy cells belonging to its actual
    // OneEarth Subregion. This guarantees one valid Realm -> Subregion ->
    // Bioregion lineage for every nested logical cell.
    const bioCandidates=geographicCandidateComponents(units,'bioregion',data.bioregions||{},4);
    const resolvedBios=filterChildToValidParent(
        geographicResolveExclusiveTier(bioCandidates,'bioregion'),
        resolvedSubs,
        'subregion'
    );
    all.push(...resolvedBios);

    // Baseline rendering uses the exact qualifying cells. No visual infill,
    // ownership partition or whole-card expansion is allowed.
    for(const g of all){
        g.infillEnclosures=[];
        g.enclosures=[...(g.qualifyingEnclosures||[])];
    }

    // Realm Areas represent broad faunal membership. They do not need an endemic
    // anchor: purity is enough. Subregions and bioregions are narrower identities,
    // so they still require at least one endemic species before range species can
    // support the generated Area.
    const hasRequiredGeographicAnchor=group=>{
        const level=group?.theme?.geographicLevel;
        const key=group?.theme?.geographicKey;
        if(!level||!key||level==='realm')return true;
        const identity={level,key};
        for(const unit of group.qualifyingEnclosures||group.enclosures||[]){
            for(const animal of animalsInGeographicExhibit(unit)){
                if(geographicAnimalIsDiagnostic(animal,identity))return true;
            }
        }
        return false;
    };

    // Keep the generated pipeline deliberately small: qualification,
    // connectivity, exclusive same-tier ownership, then the level-appropriate
    // anchor.
    let displayed=all.filter(hasRequiredGeographicAnchor);

    // Do not draw a broader geographic Area when one immediate child tier has
    // exactly the same logical-cell footprint. The narrower identity contains
    // all of the information in that footprint, so rendering both only creates
    // duplicate borders/labels (realm -> subregion, subregion -> bioregion).
    // Partial children remain nested normally inside their larger parent.
    const tierRank={realm:0,subregion:1,bioregion:2};
    const footprintKey=group=>(group?.qualifyingEnclosures||group?.enclosures||[])
        .map(geographicLogicalCellKey).filter(Boolean).sort().join('|');
    const footprintsByTier=new Map();
    for(const group of displayed){
        const level=group?.theme?.geographicLevel;
        const rank=tierRank[level];
        if(rank==null)continue;
        if(!footprintsByTier.has(rank))footprintsByTier.set(rank,new Set());
        footprintsByTier.get(rank).add(footprintKey(group));
    }
    displayed=displayed.filter(group=>{
        const rank=tierRank[group?.theme?.geographicLevel];
        if(rank==null||rank>=2)return true;
        const footprint=footprintKey(group);
        return !footprintsByTier.get(rank+1)?.has(footprint);
    });

    // Generated Areas are fully derived from the current zoo. There is no
    // historical membership or retention step in the baseline architecture.
    activeGeographicAnimalIndex=null;
    activeGeographicResidentCache=null;
    activeGeographicQualificationCache=null;
    activeGeographicCandidateKeys=null;
    activeGeographicAdjacencyIndex=null;
    activeGeographicCandidateUnitIndex=null;
    activeAnimalGeographicMatchCache=null;
    // Defensive bound for long development sessions where geography data may
    // be hot-reloaded repeatedly. Clearing only affects speed, never results.
    if(persistentAnimalGeographicMatchCache.size>50000)
        persistentAnimalGeographicMatchCache.clear();
    if(state.gameMode!=='true'){
        classicGeneratedGeographyCache={
            signature:geographySignature,
            groups:displayed
        };
    }
    return displayed;
}

function loadOneEarthBioregionsGeoJSON(){
    if(!oneEarthBioregionsGeoJSONPromise){
        oneEarthBioregionsGeoJSONPromise=fetch(ONE_EARTH_BIOREGIONS_GEOJSON_URL)
            .then(r=>r.ok?r.json():null)
            .catch(()=>null);
    }
    return oneEarthBioregionsGeoJSONPromise;
}
async function loadOneEarthBioregionsForCodes(regionKeys){
    const wanted=[...new Set([...regionKeys].map(normalizeOneEarthCode)
        .filter(code=>/^(?:NT|NA|PA|AT|IM|AU|OC|AN)\d+$/.test(code)))];
    if(!wanted.length)return null;

    // Prefer the local official download. If it is absent, malformed, or its
    // schema changes, ask the public One Earth ArcGIS layer for only the
    // bioregions this animal needs.
    const local=await loadOneEarthBioregionsGeoJSON();
    const localMatches=(local?.features||[]).filter(f=>wanted.includes(oneEarthFeatureCode(f)));
    const found=new Set(localMatches.map(oneEarthFeatureCode).filter(Boolean));
    const missing=wanted.filter(code=>!found.has(code));
    if(!missing.length)return {type:'FeatureCollection',features:localMatches};

    // Use the same loader for animal and Area maps, but never let one missing
    // local bioregion leave either UI on “Loading map…” indefinitely. Fetch only
    // the missing codes in small batches and put a finite bound on each request.
    const remote=[];
    for(let offset=0;offset<missing.length;offset+=12){
        const batch=missing.slice(offset,offset+12);
        const where=batch.map(code=>`BIOREGIO_1 LIKE '%(${code})%'`).join(' OR ');
        const params=new URLSearchParams({
            where,
            outFields:'BIOREGION_,BIOREGIO_1',
            returnGeometry:'true',
            outSR:'4326',
            f:'geojson'
        });
        const controller=new AbortController();
        const timer=setTimeout(()=>controller.abort(),5000);
        try{
            const response=await fetch(`${ONE_EARTH_BIOREGIONS_ARCGIS_URL}?${params}`,{signal:controller.signal,cache:'default'});
            if(!response.ok)throw new Error(`One Earth ArcGIS HTTP ${response.status}`);
            const collection=await response.json();
            remote.push(...(collection?.features||[]));
        }catch(error){
            console.warn('Could not load missing One Earth bioregion geometry:',batch.join(', '),error);
        }finally{
            clearTimeout(timer);
        }
    }
    const merged=[...localMatches,...remote];
    return merged.length?{type:'FeatureCollection',features:merged}:null;
}


function animalMarineRegionKeys(animal,record=null){
    const source=record||inventoryEntryForAnimal(animal);
    return [...new Set((Array.isArray(source?.marine_regions)?source.marine_regions:[])
        .map(v=>String(v||'').trim().toUpperCase())
        .filter(v=>/^MEOW-E\d{3}$/.test(v)))];
}
function animalPelagicRegionKeys(animal,record=null){
    const source=record||inventoryEntryForAnimal(animal);
    return [...new Set((Array.isArray(source?.pelagic_regions)?source.pelagic_regions:[])
        .map(v=>String(v||'').trim().toUpperCase())
        .filter(v=>/^PPOW-P\d{2}$/.test(v)))];
}
function marineRegionLabel(code){
    const key=String(code||'').trim().toUpperCase();
    return MARINE_MEOW_ECOREGIONS[key]?.name||MARINE_PPOW_PROVINCES[key]?.name||key;
}
function normalizeMarineName(value){
    return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
        .replace(/[–—]/g,'-').replace(/\s+/g,' ').trim().toLowerCase();
}
// Cache MEOW by canonical ecoregion, not only by the exact requested set.
const marineMeowFeatureCache=new Map();
const marineMeowBatchPromises=new Map();

async function fetchMarineGeoJSON(url,timeoutMs=5000){
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),timeoutMs);
    try{
        const response=await fetch(url,{signal:controller.signal,cache:'default'});
        if(!response.ok)throw new Error(`HTTP ${response.status}`);
        const collection=await response.json();
        if(!collection||!Array.isArray(collection.features))throw new Error('Marine geography response is not a FeatureCollection.');
        return collection;
    }finally{clearTimeout(timer);}
}
async function loadMeowEcoregionsForCodes(codes){
    const wanted=[...new Set((codes||[]).map(v=>String(v||'').toUpperCase()).filter(Boolean))].sort();
    if(!wanted.length)return {type:'FeatureCollection',features:[]};

    const missing=wanted.filter(code=>!marineMeowFeatureCache.has(code));
    const batches=[];
    for(let offset=0;offset<missing.length;offset+=24)batches.push(missing.slice(offset,offset+24));

    // Wide-ranging marine species (especially dolphins) can require most of the
    // MEOW catalogue. Waiting for every 24-region request serially made their map
    // appear permanently stuck on “Loading map…”. Run the independent batches in
    // parallel, and let an individual failed batch degrade gracefully instead of
    // aborting the entire animal map.
    await Promise.all(batches.map(async batch=>{
        const batchKey=batch.join('|');
        let promise=marineMeowBatchPromises.get(batchKey);
        if(!promise){
            promise=(async()=>{
                const names=batch.map(code=>MARINE_MEOW_ECOREGIONS[code]?.name).filter(Boolean);
                if(!names.length)return;
                const codeByName=new Map(batch.map(code=>[
                    normalizeMarineName(MARINE_MEOW_ECOREGIONS[code]?.name),code
                ]));
                const escaped=names.map(name=>`'${String(name).replace(/'/g,"''")}'`);
                const params=new URLSearchParams({
                    where:`ECOREGION IN (${escaped.join(',')})`,
                    outFields:'ECO_CODE,ECOREGION,PROVINCE,REALM',
                    returnGeometry:'true',outSR:'4326',f:'geojson'
                });
                const collection=await fetchMarineGeoJSON(`${ANIMAL_INFO_MEOW_ARCGIS_URL}?${params}`,5000);
                for(const feature of collection.features||[]){
                    const code=codeByName.get(normalizeMarineName(feature?.properties?.ECOREGION));
                    if(!code)continue;
                    feature.properties=feature.properties||{};
                    feature.properties.ZOO_CURATOR_MEOW_ID=code;
                    marineMeowFeatureCache.set(code,feature);
                }
            })()
                .catch(error=>console.warn(`Could not load MEOW batch ${batchKey}:`,error))
                .finally(()=>marineMeowBatchPromises.delete(batchKey));
            marineMeowBatchPromises.set(batchKey,promise);
        }
        await promise;
    }));

    return {
        type:'FeatureCollection',
        features:wanted.map(code=>marineMeowFeatureCache.get(code)).filter(Boolean)
    };
}
async function loadPpowProvincesGeoJSON(){
    if(marinePpowGeoJSONPromise)return marinePpowGeoJSONPromise;
    marinePpowGeoJSONPromise=(async()=>{
        try{
            const response=await fetch(ANIMAL_INFO_PPOW_WFS_URL,{cache:'default'});
            if(!response.ok)throw new Error(`HTTP ${response.status}`);
            const collection=await response.json();
            if(!collection||!Array.isArray(collection.features))throw new Error('Local PPOW GeoJSON is not a FeatureCollection.');
            return collection;
        }catch(error){
            marinePpowGeoJSONPromise=null;
            console.warn('Could not load local PPOW geometry:',error);
            return {type:'FeatureCollection',features:[]};
        }
    })();
    return marinePpowGeoJSONPromise;
}
function ppowFeatureCode(feature){
    return String(feature?.properties?.id||'').toUpperCase();
}

function animalWildRegionKeys(animal){
    const record=inventoryEntryForAnimal(animal);
    const explicit=Array.isArray(record?.wild_regions) ? record.wild_regions : [];
    if(explicit.length){
        return [...new Set(explicit.map(v=>String(v).trim().toLowerCase()).filter(Boolean))];
    }
    // Migration fallback: today's subregion tags keep working until each
    // species is deliberately moved to factual wild_regions.
    return animalInfoRegionKeys(animal);
}
function factualRegionMeta(regionKey){
    const key=String(regionKey||'').trim().toLowerCase();
    const meta=ZOO_GEOGRAPHY.factual_regions[key];
    return meta ? {key,...meta} : {key,label:animalInfoRegionLabel(key),zoo_region:null,continent:null};
}
function zooRegionMeta(regionKey){
    const key=String(regionKey||'').trim().toLowerCase();
    const meta=ZOO_GEOGRAPHY.zoo_regions[key];
    return meta ? {key,...meta} : null;
}
function collapsedFullSubrealms(regionKeys){
    const keys=new Set([...regionKeys].map(v=>String(v).toLowerCase()));
    const collapsed=new Map();
    for(const [parentKey,parent] of Object.entries(ZOO_GEOGRAPHY.zoo_regions)){
        const canonicalMembers=(parent?.bioregions||[]).map(v=>String(v).toLowerCase()).filter(Boolean);
        if(!canonicalMembers.length)continue;
        // Strict rule: collapse only when EVERY canonical member is explicitly
        // present. Never infer/add a missing member from majority coverage.
        if(canonicalMembers.every(code=>keys.has(code))){
            collapsed.set(parentKey,new Set(canonicalMembers));
        }
    }
    return collapsed;
}
function geographyParentForFactualRegion(regionKey){
    const factual=factualRegionMeta(regionKey);
    return factual.zoo_region ? zooRegionMeta(factual.zoo_region) : null;
}


