      {d:Math.abs(y-(b.y+b.h)),u:b.w+b.h+(b.w-Math.max(0,Math.min(b.w,x-b.x)))},
      {d:Math.abs(x-b.x),u:2*b.w+b.h+(b.h-Math.max(0,Math.min(b.h,y-b.y)))}
