    const groundCols=Math.max(1,Math.round(bounds.w/TRUE_ENC_CELL_W)),groundRows=Math.max(1,Math.round(bounds.h/TRUE_ENC_CELL_H));
    const parcelDepth=trueLandExpansionParcelCells();

