            if(!perimeterGround.has(trueBuilderCellKey(col,row-1)))addEdge(col,row,'top',x,y,w,h);
            if(!perimeterGround.has(trueBuilderCellKey(col+1,row)))addEdge(col,row,'right',x,y,w,h);
