            enclosureSizes:(state.enclosures||[]).filter(trueEnclosureIsCurrentBackstage).map(e=>trueBuiltWorldCells(e).length),
            freeConnectorCell:b.backstageFreeCell||null,
            publicFrontageCells:(()=>{const p=new Set(b.startingGroundsCells||[]);return (b.backstageCells||[]).filter(k=>{const [c,r]=String(k).split(',').map(Number);return [[1,0],[-1,0],[0,1],[0,-1]].some(([dc,dr])=>p.has(trueBuilderCellKey(c+dc,r+dr)));}).length;})(),
            connectorTouchesOpenPublic:(()=>{if(!b.backstageFreeCell)return false;const [c,r]=String(b.backstageFreeCell).split(',').map(Number),p=new Set(b.startingGroundsCells||[]),occ=trueEnclosureSpatialIndex().occupied;return [[1,0],[-1,0],[0,1],[0,-1]].some(([dc,dr])=>{const k=trueBuilderCellKey(c+dc,r+dr);return p.has(k)&&!occ.has(k);});})(),
