let trueMapToolMountFrame=0;
function trueMountExistingMapToolButtons(){
    const rail=document.getElementById('trueMapToolRail');
    if(!rail)return;
    const buttons=[
        document.getElementById('trueEnclosureBuilderButton'),
        document.getElementById('trueDecorationToolButton'),
        document.getElementById('areaToolButton')
    ];
    for(const el of buttons){
        if(!el)continue;
        if(el.parentElement!==rail)rail.appendChild(el);
        const exact={
            position:'relative',left:'auto',right:'auto',top:'auto',bottom:'auto',
            width:'56px',height:'56px','min-width':'56px','min-height':'56px',
            'max-width':'56px','max-height':'56px','inline-size':'56px','block-size':'56px',
            'min-inline-size':'56px','max-inline-size':'56px','min-block-size':'56px','max-block-size':'56px',
            'aspect-ratio':'1 / 1',margin:'0',padding:'7px','box-sizing':'border-box',
            display:'grid','place-items':'center'
        };
        for(const [prop,value] of Object.entries(exact))el.style.setProperty(prop,value,'important');
    }
    trueRefreshMapToolIcons();
}
function trueScheduleMapToolMount(){
    if(trueMapToolMountFrame)return;
    trueMapToolMountFrame=requestAnimationFrame(()=>{
        trueMapToolMountFrame=0;
        trueMountExistingMapToolButtons();
    });
}
if(!window.__trueMapToolMountObserver){
    window.__trueMapToolMountObserver=new MutationObserver(mutations=>{
        for(const mutation of mutations){
            for(const node of mutation.addedNodes||[]){
                if(node?.nodeType!==1)continue;
                if(['areaToolButton','trueDecorationToolButton','trueEnclosureBuilderButton'].includes(node.id)
                   || node.querySelector?.('#areaToolButton,#trueDecorationToolButton,#trueEnclosureBuilderButton')){
                    trueScheduleMapToolMount();
                    return;
                }
            }
        }
    });
    window.__trueMapToolMountObserver.observe(document.body,{childList:true,subtree:true});
}
