    'zooLocation',
    'zooType',
    'manualZooNameOverrideType',
    'realZooPlayerRecordName',
    'areaLabelPositions',
    'customAreas',
    'handcraftedAreaEvolution',
    'areaEvolutionBaselineSpecies',
    'suppressedGeneratedGeographicAreas',
    'suppressedGeneratedGeographicAreaSpecies',
