function multiplayerCursorTarget(){
    const viewed=multiplayerEffectiveViewedLocalPlayerId();
    if(!viewed)return null;
    const own=localClassicMatch?.activePlayerId;
    if(viewed===own){
        const t=localMultiplayerBrowserTransport;
        const players=t?.serverPlayers||[];
        return players.find(p=>String(p.playerId)===String(t?.serverPlayerId)) ||
            players.find(p=>Number(p.seat)===Number(t?.serverSeat)) || null;
    }
    return multiplayerServerPlayerForLocalId(viewed);
}
function sendMultiplayerCursorFromPointer(event){
    const channel=localMultiplayerBrowserChannel,t=localMultiplayerBrowserTransport;
    if(!channel?.serverBacked||!t?.serverAuthenticated||!localClassicMatch||!zooCanvas||!zooBoard)return;
    const nowMs=performance.now();if(nowMs-multiplayerCursorLastSentAt<50)return; // <=20 Hz
    const boardRect=zooBoard.getBoundingClientRect();
    if(event.clientX<boardRect.left||event.clientX>boardRect.right||event.clientY<boardRect.top||event.clientY>boardRect.bottom)return;
    // Cursor identity is the authenticated socket, while viewTargetPlayerId is
    // only the zoo currently rendered in this browser. Keeping these separate
    // makes owner<->visitor routing symmetric and independent of subscription ACKs.
    const viewTarget=multiplayerCursorTarget();if(!viewTarget)return;
    const rect=zooCanvas.getBoundingClientRect(),zoom=Math.max(.01,Number(state.zoom)||1);
    const x=(event.clientX-rect.left)/zoom,y=(event.clientY-rect.top)/zoom;
    multiplayerCursorLastSentAt=nowMs;
    try{channel.postMessage({protocol:MULTIPLAYER_SERVER_PROTOCOL,type:'cursor',viewTargetPlayerId:viewTarget.playerId,x,y,moving:true});}catch(_){}
}
function sendMultiplayerCursorLeave(){
    const channel=localMultiplayerBrowserChannel,t=localMultiplayerBrowserTransport;
    if(!channel?.serverBacked||!t?.serverAuthenticated)return;
    const viewTarget=multiplayerCursorTarget();if(!viewTarget)return;
    try{channel.postMessage({protocol:MULTIPLAYER_SERVER_PROTOCOL,type:'cursor',viewTargetPlayerId:viewTarget.playerId,x:0,y:0,moving:false});}catch(_){}
}
window.addEventListener('pointermove',sendMultiplayerCursorFromPointer,{passive:true});
zooBoard?.addEventListener('pointerleave',sendMultiplayerCursorLeave,{passive:true});
zooBoard?.addEventListener('scroll',()=>{if(!multiplayerCursorRaf&&multiplayerRemoteCursors.size)multiplayerCursorRaf=requestAnimationFrame(renderMultiplayerRemoteCursors);},{passive:true});
const MULTIPLAYER_SERVER_PROTOCOL='zoo-curator-server-v2';
const MULTIPLAYER_SERVER_IDENTITY_KEY='zoo-curator-server-identities-v1';
const multiplayerServerPendingActions=new Map();
let multiplayerPublicTradeListings=[];
let selectedMultiplayerPublicListingPlayerId=null;
let selectedHumanTradeProposalId=null;
const pendingHumanTradeActionIds=new Set();
function serverAuthoritativeMultiplayerActive(){
    const t=localMultiplayerBrowserTransport;
    return !!(t?.serverBacked&&t.serverAuthenticated&&localMultiplayerBrowserChannel?.postServerMessage);
}
function resolveMultiplayerServerAction(message){
    const requestId=String(message?.requestId||'');
    if(!requestId)return false;
    const pending=multiplayerServerPendingActions.get(requestId);
    if(!pending)return false;
    // Only terminal authoritative responses may consume a waiter. Require the
    // action field as well as the request ID so unrelated protocol packets can
    // never complete an in-flight gameplay operation.
    if(message?.type!=='action-committed'&&message?.type!=='action-rejected')return false;
    if(String(message?.action||'')!==String(pending.type))return false;
    clearTimeout(pending.timeout);
    multiplayerServerPendingActions.delete(requestId);
    pending.resolve(cloneForSave(message));
    return true;
}
function sendMultiplayerServerAction(type,payload={}){
    const t=localMultiplayerBrowserTransport;
    const channel=localMultiplayerBrowserChannel;
    if(!serverAuthoritativeMultiplayerActive())
        return Promise.resolve({type:'action-rejected',action:type,code:'SERVER_NOT_AUTHENTICATED'});
    const requestId=`${t.serverPlayerId||'player'}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
    const promise=new Promise(resolve=>{
        const timeout=setTimeout(()=>{
            if(!multiplayerServerPendingActions.has(requestId))return;
            multiplayerServerPendingActions.delete(requestId);
            resolve({type:'action-rejected',action:type,code:'SERVER_TIMEOUT',requestId});
        },7000);
        multiplayerServerPendingActions.set(requestId,{resolve,timeout,type});
    });
    channel.postServerMessage({type,requestId,...payload});
    t.sent++;t.lastMessageType=type;
    return promise;
}


const SERVER_HUMAN_TRADE_ACTIONS=new Set([
    'send-human-trade-offer','accept-human-trade','claim-human-trade',
    'decline-human-trade','cancel-human-trade'
]);
async function authorizeHumanTradeWithServer(type,payload={}){
    if(!serverAuthoritativeMultiplayerActive())return {ok:true,legacy:true};
    const operation={
        'send-human-trade-offer':'offer',
        'accept-human-trade':'accept',
        'claim-human-trade':'claim',
        'decline-human-trade':'decline',
        'cancel-human-trade':'cancel'
    }[type];
    if(!operation)return {ok:true,legacy:true};
    const wire={operation};
    if(operation==='offer'){
        const requestedLocalId=payload.requestedPlayerId;
        const requestedServerPlayer=multiplayerServerPlayerForLocalId(requestedLocalId);
        const requestedServerPlayerId=payload.requestedServerPlayerId||
            requestedServerPlayer?.playerId||null;
        if(!requestedServerPlayerId)
            return {ok:false,reason:'trade-target-not-connected'};
        wire.tradeId=payload.tradeId;
        wire.toPlayerId=requestedServerPlayerId;
        wire.offeredAnimalId=payload.offeredAnimalId;
        if(payload.offeredAnimalIdentity)
            wire.offeredAnimalIdentity=cloneForSave(payload.offeredAnimalIdentity);
        wire.requestedAnimalId=payload.requestedAnimalId;
        if(payload.requestedAnimalIdentity)
            wire.requestedAnimalIdentity=cloneForSave(payload.requestedAnimalIdentity);
        // Transfer IDs are deliberately omitted. The authoritative server
        // allocates them atomically only if/when this proposal is accepted.
    }else{
        wire.tradeId=payload.offerId;
        if((operation==='accept'||operation==='claim')&&payload.destination)wire.destination=payload.destination;
    }
    const response=await sendMultiplayerServerAction('human-trade',wire);
    if(response?.type!=='action-committed'||response?.action!=='human-trade'){
        if(response?.code==='REQUESTED_ANIMAL_NOT_OWNED'){
            multiplayerDiagnostic?.('human-trade-requested-animal-ownership-mismatch',{
                requestedLocalId:payload.requestedPlayerId,
                requestedServerPlayerId:wire.toPlayerId,
                requestedAnimalId:wire.requestedAnimalId,
                requestedAnimalIdentity:cloneForSave(wire.requestedAnimalIdentity||null)
            });
        }
        return {ok:false,reason:response?.code||'server-trade-rejected'};
    }
    return {ok:true,response};
}


function multiplayerLocalPlayerIdForServerId(serverPlayerId){
    const wanted=String(serverPlayerId||'');
    if(!wanted)return null;
    const transport=localMultiplayerBrowserTransport;
    if(wanted===String(transport?.serverPlayerId||'')&&Number(transport?.serverSeat)>0)
        return `player-${Number(transport.serverSeat)}`;
    const serverPlayer=(transport?.serverPlayers||[])
        .find(p=>String(p?.playerId||'')===wanted);
    return serverPlayer?.seat?`player-${Number(serverPlayer.seat)}`:null;
}
function normaliseAuthoritativeHumanTradeForLocalUI(trade){
    if(!trade)return trade;
    const copy=cloneForSave(trade);
    copy.fromServerPlayerId=trade.fromPlayerId;
    copy.toServerPlayerId=trade.toPlayerId;
    copy.fromPlayerId=multiplayerLocalPlayerIdForServerId(trade.fromPlayerId)||trade.fromPlayerId;
    copy.toPlayerId=multiplayerLocalPlayerIdForServerId(trade.toPlayerId)||trade.toPlayerId;
    return copy;
}

function clearOrphanedHumanTradeDragVisuals(){
    // Human-trade authority can replace/import the zoo while pointer-up and the
    // server transaction are crossing the wire. The real card is then already
    // in its authoritative enclosure, but an old DOM drag clone can survive
    // outside renderZoo() and look like a frozen duplicate. Never remove a live
    // local drag; only clean detached transaction ghosts.
    if(!state.drag){
        for(const el of document.querySelectorAll('.dragging-animal:not(.multiplayer-live-animal-drag)'))
            el.remove();
    }
    // A completed ownership transaction also invalidates any spectator drag
    // visual for the transferred card. A lost/late `ended` packet must not
    // leave that old owner's card floating over the new owner's zoo.
    clearMultiplayerRemoteAnimalDrags?.();
}

function applyAuthoritativeHumanTradeMessage(message){
    if(!localClassicMatch||message?.action!=='human-trade'||message?.type!=='action-committed')return false;
    const incoming=normaliseAuthoritativeHumanTradeForLocalUI(message.trade);
    if(!incoming?.id)return false;
    if(incoming.status==='accepted-awaiting-sender-claim'||incoming.status==='completed')
        clearOrphanedHumanTradeDragVisuals();

    if(!Array.isArray(localClassicMatch.pendingPlayerTrades))
        localClassicMatch.pendingPlayerTrades=[];
    let offer=localClassicMatch.pendingPlayerTrades.find(o=>String(o?.id)===String(incoming.id));
    if(!offer){
        offer={id:incoming.id};
        localClassicMatch.pendingPlayerTrades.push(offer);
    }else{
        const knownTradeUpdatedAt=Math.max(0,Number(offer.updatedAt)||0);
        const incomingTradeUpdatedAt=Math.max(0,Number(incoming.updatedAt)||0);
        // Trade packets have their own durable ordering independent of zoo
        // revisions. Reconnect recovery and a live transaction can cross on the
        // socket; never let an older pending/accepted packet resurrect a trade
        // after a newer invalid/declined/completed transition was already seen.
        if(incomingTradeUpdatedAt<knownTradeUpdatedAt){
            multiplayerDiagnostic('human-trade-state-stale-dropped',{
                tradeId:incoming.id,status:incoming.status,
                updatedAt:incomingTradeUpdatedAt,highestAcceptedUpdatedAt:knownTradeUpdatedAt
            });
            return false;
        }
        if(incomingTradeUpdatedAt===knownTradeUpdatedAt){
            const rank={
                pending:1,'accepted-awaiting-sender-claim':2,
                declined:3,cancelled:3,invalid:3,accepted:4,completed:4
            };
            if((rank[incoming.status]||0)<(rank[offer.status]||0)){
                multiplayerDiagnostic('human-trade-state-regression-dropped',{
                    tradeId:incoming.id,status:incoming.status,knownStatus:offer.status,
                    updatedAt:incomingTradeUpdatedAt
                });
                return false;
            }
        }
    }
    Object.assign(offer,cloneForSave(incoming));
    if(message.recovered===true)offer.recoveredFromServer=true;
    // The visit-selected request is only a draft. Once the server accepts the
    // real proposal, do not let that draft reappear underneath it.
    if(incoming.status==='pending'){
        if(incoming.fromPlayerId===localClassicMatch.activePlayerId)
            clearLocalHumanTradeDraft(incoming.fromPlayerId);
        if(incoming.toPlayerId===localClassicMatch.activePlayerId &&
           !selectedHumanTradeProposalId)
            selectedHumanTradeProposalId=incoming.id;
    }

    // The server response already contains the exact durable zoo revisions
    // produced by the transaction. Keep replicas current without asking the
    // browser host to replay ownership mutations. Record only updates that pass
    // the monotonic revision guard; later trade UI must never read a raw stale
    // zooUpdates payload that this loop deliberately rejected.
    const acceptedTradeZooUpdates=new Map();
    for(const update of (Array.isArray(message.zooUpdates)?message.zooUpdates:[])){
        const localUpdatePlayerId=multiplayerLocalPlayerIdForServerId(update.playerId);
        const player=localClassicMatch.players?.[localUpdatePlayerId];
        const transport=localMultiplayerBrowserTransport;
        const updateRevision=Math.max(0,Number(update.revision)||0);
        if(!(transport?.serverZooRevisionByPlayer instanceof Map) && transport)
            transport.serverZooRevisionByPlayer=new Map(transport.serverZooRevisionByPlayer||[]);
        const serverPlayerKey=String(update.playerId||'');
        const knownTransportRevision=Math.max(
            0,Number(transport?.serverZooRevisionByPlayer?.get(serverPlayerKey))||0
        );
        const knownPlayerRevision=Math.max(0,Number(player?.lastServerZooRevision)||0);
        const knownRevision=Math.max(knownTransportRevision,knownPlayerRevision);
        if(updateRevision<knownRevision){
            multiplayerDiagnostic('human-trade-zoo-update-stale-dropped',{
                tradeId:incoming.id,playerId:serverPlayerKey,
                revision:updateRevision,highestAcceptedRevision:knownRevision
            });
            continue;
        }
        if(player&&update.zoo){
            acceptedTradeZooUpdates.set(serverPlayerKey,update);
            player.snapshot=cloneForSave(update.zoo);
            player.lastServerZooRevision=Math.max(knownPlayerRevision,updateRevision);
            if(updateRevision>knownTransportRevision)
                transport?.serverZooRevisionByPlayer?.set(serverPlayerKey,updateRevision);
            if(String(update.playerId)===String(transport?.serverPlayerId)){
                transport.durableZooRevision=Math.max(
                    Math.max(0,Number(transport.durableZooRevision)||0),
                    updateRevision
                );
                transport.durableOwnZooSnapshot=cloneForSave(update.zoo);
                transport.durableZooQueuedSnapshot=null;
                transport.durableZooQueuedSignature='';
                // Do NOT clear durableZooCommitPending here. If an ordinary
                // zoo-state commit was already sent, its ACK/rejection is still
                // in flight and remains the only event allowed to settle that
                // request. The authoritative trade revision makes an older CAS
                // commit stale; its rejection closes the pending request.
                localMultiplayerBrowserTransport.durableZooQueuedSnapshot=null;
                localMultiplayerBrowserTransport.durableZooQueuedSignature='';
                try{
                    localMultiplayerBrowserTransport.durableZooLastRequestedSignature=JSON.stringify(update.zoo);
                }catch(_){}
            }
        }
    }

    // If this transaction changed the zoo currently owned/rendered by this
    // browser, apply that authoritative snapshot immediately. Merely updating
    // localClassicMatch.players[].snapshot is not enough: `state` would still
    // contain the pre-trade animals until a later visit/reload.
    const ownServerId=String(localMultiplayerBrowserTransport?.serverPlayerId||'');
    const ownUpdate=(message.zooUpdates||[]).find(
        u=>String(u?.playerId||'')===ownServerId
    );
    const ownUpdateRevision=Math.max(0,Number(ownUpdate?.revision)||0);
    const latestOwnRevision=Math.max(
        0,Number(localMultiplayerBrowserTransport?.durableZooRevision)||0
    );
    if(ownUpdate?.zoo && ownUpdateRevision>=latestOwnRevision &&
       localClassicMatch.activePlayerId===multiplayerLocalPlayerIdForServerId(ownUpdate.playerId) &&
       (!localClassicMatch.viewingPlayerId ||
        localClassicMatch.viewingPlayerId===localClassicMatch.activePlayerId)){
        const authoritativeOwnZoo=cloneForSave(ownUpdate.zoo);
        const authoritativeOwnRevision=Math.max(0,Number(ownUpdate.revision)||0);
        const importKey=`${String(incoming.id)}:${String(incoming.status)}:${authoritativeOwnRevision}`;
        const transportNow=localMultiplayerBrowserTransport;
        if(!transportNow.authoritativeHumanTradeImportKeys)
            transportNow.authoritativeHumanTradeImportKeys=new Set();
        if(!transportNow.authoritativeHumanTradeImportKeys.has(importKey)){
            transportNow.authoritativeHumanTradeImportKeys.add(importKey);
            enqueueMicrotask(async()=>{
            const transport=localMultiplayerBrowserTransport;
            // The action packet and zoo-state packet can arrive back-to-back.
            // Never let a queued import of revision N overwrite N+1.
            if(Math.max(0,Number(transport?.durableZooRevision)||0)>authoritativeOwnRevision){
                transport?.authoritativeHumanTradeImportKeys?.delete(importKey);
                return;
            }
            autoResumeWriteSuppressed=true;
            try{await importGameState(authoritativeOwnZoo,{deferRender:false});}
            finally{autoResumeWriteSuppressed=false;}
            // importGameState can yield. If newer authority arrived while it
            // was importing, immediately restore the newest durable snapshot.
            if(Math.max(0,Number(transport?.durableZooRevision)||0)>authoritativeOwnRevision){
                const latest=transport?.durableOwnZooSnapshot;
                if(latest?.state){
                    autoResumeWriteSuppressed=true;
                    try{await importGameState(cloneForSave(latest),{deferRender:false});}
                    finally{autoResumeWriteSuppressed=false;}
                }
                transport?.authoritativeHumanTradeImportKeys?.delete(importKey);
                return;
            }
            const ownedIds=new Set((state.animals||[]).map(a=>String(a?.id)));
            if(state.outgoingOffer&&!ownedIds.has(String(state.outgoingOffer.id))){
                state.outgoingOffer=null;
                state.tradeOffers=[];
                state.selectedTradeOpponent=null;
            }
            if(Array.isArray(state.exchange))
                state.exchange=state.exchange.map(a=>a&&!ownedIds.has(String(a.id))?null:a);
            if(state.result&&!ownedIds.has(String(state.result.id)))state.result=null;
            // Old/mixed-version snapshots can still contain an autonomous AI
            // request that caches a player card already transferred by the
            // authoritative human trade. Mirror the server's exact-ID cleanup
            // so that stale AI offer cannot reappear after import/reconnect.
            if(state.autonomousTradeOffer){
                const aiPlayerIds=[
                    state.autonomousTradeOffer.outgoingId,
                    state.autonomousTradeOffer.playerAnimalId,
                    state.autonomousTradeOffer.outgoing?.id
                ].filter(v=>v!=null&&String(v)!=='');
                if(aiPlayerIds.some(id=>!ownedIds.has(String(id))))
                    state.autonomousTradeOffer=null;
            }
            // importGameState also restores the snapshot's multiplayer-adjacent
            // transient UI. Re-assert the server trade object after that import
            // so an older zoo snapshot cannot resurrect a pending/cancelled
            // proposal or hide an accepted sender-claim card.
            if(!Array.isArray(localClassicMatch.pendingPlayerTrades))
                localClassicMatch.pendingPlayerTrades=[];
            let liveOffer=localClassicMatch.pendingPlayerTrades.find(
                o=>String(o?.id)===String(incoming.id)
            );
            if(!liveOffer){
                liveOffer={id:incoming.id};
                localClassicMatch.pendingPlayerTrades.push(liveOffer);
            }
            const preservedClaim=offer.senderClaimAnimal?cloneForSave(offer.senderClaimAnimal):null;
            Object.assign(liveOffer,cloneForSave(incoming));
            if(preservedClaim&&incoming.status==='accepted-awaiting-sender-claim')
                liveOffer.senderClaimAnimal=preservedClaim;
            if(incoming.status==='completed'||incoming.status==='declined'||
               incoming.status==='cancelled'||incoming.status==='invalid')
                liveOffer.senderClaimAnimal=null;

            clearOrphanedZooSlotReservations?.();
            refreshDrawAvailabilityState?.();
            localClassicMatch.players[localClassicMatch.activePlayerId].snapshot=cloneForSave(exportCurrentGameState());
            clearOrphanedHumanTradeDragVisuals();
            renderTrade?.();
            renderVisitedZooQuickTabs?.();
            transport?.authoritativeHumanTradeImportKeys?.delete(importKey);
        });
        }
    }

    if(incoming.status==='accepted-awaiting-sender-claim'||
       incoming.status==='completed'||incoming.status==='declined'||
       incoming.status==='cancelled'||incoming.status==='invalid'){
        pendingHumanTradeActionIds.delete(`accept:${incoming.id}`);
        pendingHumanTradeActionIds.delete(`claim:${incoming.id}`);
    }

    if(incoming.status==='accepted-awaiting-sender-claim'){
        const acceptedSenderUpdate=acceptedTradeZooUpdates.get(String(incoming.fromServerPlayerId||''));
        // Never reconstruct a claim card from a cached player snapshot. That
        // snapshot can predate the authoritative accept and may still contain
        // the old animal ID/ownership. The accepted trade packet is the only
        // authority for the newly allocated transfer ID.
        const transferred=(acceptedSenderUpdate?.zoo?.state?.animals||[]).find(
            a=>String(a?.id)===String(incoming.requestedTransferId)
        );
        if(transferred)offer.senderClaimAnimal=cloneForSave(transferred);
        else if(!offer.senderClaimAnimal)offer.senderClaimAnimal=null;
    }else if(incoming.status==='completed'){
        offer.senderClaimAnimal=null;
        if(String(selectedHumanTradeProposalId||'')===String(incoming.id))
            selectedHumanTradeProposalId=null;
        resumeAITradingAfterHumanTrade?.();
    }else if(incoming.status==='declined'||incoming.status==='cancelled'||incoming.status==='invalid'){
        offer.senderClaimAnimal=null;
        if(String(selectedHumanTradeProposalId||'')===String(incoming.id))
            selectedHumanTradeProposalId=null;
        // A server invalidation may arrive while this exact proposal card is
        // being dragged. Drop only that transaction ghost; never disturb a
        // normal animal drag or a different simultaneous proposal.
        if((state.drag?.type==='direct-human-trade-result'||
            state.drag?.type==='direct-human-trade-sender-claim')&&
           String(state.drag?.humanTradeOfferId||'')===String(incoming.id)){
            state.drag.image?.remove?.();
            state.drag=null;
        }
        resumeAITradingAfterHumanTrade?.();
    }

    localClassicMatch.revision=Math.max(
        Number(localClassicMatch.revision)||0,
        Number(message.revision)||0
    );
    pruneTerminalDirectHumanTrades?.();
    renderTrade?.();
    renderVisitedZooQuickTabs?.();
    return true;
}

function sanitizeTransientExchangeState(snapshot){
    if(!snapshot?.state)return snapshot;
    snapshot.state.exchange=[null,null];
    snapshot.state.result=null;
    snapshot.state.exchangeGlowFocusKey=null;
    return snapshot;
}

function commitOwnZooStateToServer(snapshot=null,options={}){
    const t=localMultiplayerBrowserTransport;
    const channel=localMultiplayerBrowserChannel;
    if(!serverAuthoritativeMultiplayerActive()||!channel?.postServerMessage)return false;
    // Direct callers must obey the same reconnect firewall as the debounced
    // scheduler. Until the first durable own-zoo snapshot arrives, local resume
    // state is not authoritative and must never be committed.
    if(t.serverReturning===true&&!t.durableOwnZooSnapshot)return false;
    if(t.awaitingAuthoritativeZooCorrection===true)return false;
    // Last persistence firewall: even a direct caller may not publish a real/AI
    // zoo visit as this player's authoritative zoo.
    if(realZooVisitTransitionActive||state.visitingZoo)return false;
    const activeId=localClassicMatch?.activePlayerId;
    if(!activeId||t.playerId!==activeId)return false;
    const zoo=cloneForSave(snapshot||exportCurrentGameState());
    let signature=String(options?.scheduledSignature||'');
    if(!signature){try{signature=JSON.stringify(zoo);}catch(_){}}
    if(t.durableZooCommitTimer){
        clearTimeout(t.durableZooCommitTimer);
        t.durableZooCommitTimer=null;
        t.durableZooScheduledSnapshot=null;
        t.durableZooScheduledSignature='';
    }
    if(signature)t.durableZooLastRequestedSignature=signature;

    // Coalesce while a commit is awaiting its authoritative revision. Sending
    // multiple snapshots against the same base revision creates avoidable CAS
    // failures and was a source of trade/update races.
    if(t.durableZooCommitPending){
        t.durableZooQueuedSnapshot=zoo;
        t.durableZooQueuedSignature=signature;
        return true;
    }
    t.durableZooCommitPending=true;
    t.durableZooCommitBaseRevision=Math.max(0,Number(t.durableZooRevision)||0);
    channel.postServerMessage({
        type:'zoo-state-commit',
        baseRevision:t.durableZooCommitBaseRevision,
        zoo
    });
    t.sent++;t.lastMessageType='zoo-state-commit';
    return true;
}
function flushQueuedOwnZooStateCommit(){
    const t=localMultiplayerBrowserTransport;
    if(!t||t.durableZooCommitPending)return false;
    const queued=t.durableZooQueuedSnapshot;
    const queuedSignature=t.durableZooQueuedSignature||'';
    t.durableZooQueuedSnapshot=null;
    t.durableZooQueuedSignature='';
    return queued?commitOwnZooStateToServer(queued,{scheduledSignature:queuedSignature}):false;
}
function settleDurableZooCommitWaiters(ok=true){
    const t=localMultiplayerBrowserTransport;
    if(!t)return;
    const waiters=Array.isArray(t.durableZooCommitWaiters)?t.durableZooCommitWaiters.splice(0):[];
    for(const resolve of waiters){try{resolve(ok);}catch(_){}}
}
function reconcileLiveOwnZooPlacementFromDurable(zoo){
    if(!zoo?.state||!Array.isArray(zoo.state.animals)||!Array.isArray(state.animals))return false;
    if(localClassicMatch?.viewingPlayerId&&
       localClassicMatch.viewingPlayerId!==localClassicMatch.activePlayerId)return false;
    if(state.drag||state.exchange?.some(Boolean)||state.result)return false;

    const durableById=new Map(zoo.state.animals.map(a=>[String(a?.id),a]));
    const liveIds=new Set(state.animals.map(a=>String(a?.id)));
    if(durableById.size!==liveIds.size||[...liveIds].some(id=>!durableById.has(id)))return false;

    // An ordinary zoo-state ACK is the server's normalized version of the exact
    // snapshot this browser submitted. Until now we stored that normalized zoo
    // only in the seat snapshot; the live `state` kept its older placement /
    // reservation metadata. Visiting another zoo and returning appeared to fix
    // Draw because returnToActiveLocalClassicZoo() re-imported this stored copy.
    // Reconcile the capacity-relevant fields immediately instead.
    let changed=false;
    for(const live of state.animals){
        const durable=durableById.get(String(live.id));
        for(const key of ['enclosureId','slotIndex','reservedEnclosureId','reservedSlotIndex']){
            const next=durable?.[key]??null;
            if((live[key]??null)!==next){live[key]=next;changed=true;}
        }
    }
    if(changed){
        clearOrphanedZooSlotReservations();
        updateDiscoveredCategoryLevels?.();
    }
    refreshDrawAvailabilityState?.();
    return changed;
}
async function awaitDurableZooCommitIdle(timeoutMs=5000){
    const t=localMultiplayerBrowserTransport;
    if(!serverAuthoritativeMultiplayerActive()||!t)return true;
    const deadline=Date.now()+Math.max(250,Number(timeoutMs)||5000);

    // A debounced snapshot is just as real as an in-flight one. Promote it now
    // so a trade/listing cannot overtake local changes that were waiting for
    // the normal commit timer.
    if(t.durableZooCommitTimer){
        clearTimeout(t.durableZooCommitTimer);
        t.durableZooCommitTimer=null;
        const scheduled=t.durableZooScheduledSnapshot;
        const signature=t.durableZooScheduledSignature||'';
        t.durableZooScheduledSnapshot=null;
        t.durableZooScheduledSignature='';
        if(scheduled)commitOwnZooStateToServer(scheduled,{scheduledSignature:signature});
    }

    while(true){
        // ACK handling normally schedules this flush in a microtask. Do it
        // synchronously at the authority boundary so the waiter continuation
        // can never overtake a queued second snapshot.
        if(!t.durableZooCommitPending&&t.durableZooQueuedSnapshot)
            flushQueuedOwnZooStateCommit();

        if(!t.durableZooCommitPending&&!t.durableZooQueuedSnapshot)
            return true;

        const remaining=deadline-Date.now();
        if(remaining<=0)return false;
        const ok=await new Promise(resolve=>{
            if(!Array.isArray(t.durableZooCommitWaiters))t.durableZooCommitWaiters=[];
            let done=false,timer=null;
            const finish=value=>{
                if(done)return;
                done=true;
                if(timer!==null)clearTimeout(timer);
                // A timeout must unregister itself. Otherwise every stalled
                // authority barrier leaves a dead closure behind until some
                // unrelated future zoo-state ACK happens to drain the array.
                const index=t.durableZooCommitWaiters.indexOf(finish);
                if(index>=0)t.durableZooCommitWaiters.splice(index,1);
                resolve(value);
            };
            t.durableZooCommitWaiters.push(finish);
            timer=setTimeout(()=>finish(false),Math.max(1,remaining));
        });
        if(!ok)return false;
        // Loop: the completed commit may have exposed another queued snapshot.
    }
}


function readMultiplayerServerIdentity(matchId){
    try{
        const all=JSON.parse(localStorage.getItem(MULTIPLAYER_SERVER_IDENTITY_KEY)||'{}');
        const value=all?.[String(matchId||'')];
        return value&&value.playerId&&value.reconnectToken?value:null;
    }catch(_){return null;}
}
function writeMultiplayerServerIdentity(matchId,identity){
    if(!matchId||!identity?.playerId||!identity?.reconnectToken)return false;
    try{
        const all=JSON.parse(localStorage.getItem(MULTIPLAYER_SERVER_IDENTITY_KEY)||'{}');
        all[String(matchId)]={playerId:String(identity.playerId),reconnectToken:String(identity.reconnectToken),seat:Number(identity.seat)||null};
        localStorage.setItem(MULTIPLAYER_SERVER_IDENTITY_KEY,JSON.stringify(all));
        return true;
    }catch(_){return false;}
}
function setLocalMultiplayerExternalChannelFactory(factory=null){
    localMultiplayerExternalChannelFactory=typeof factory==='function'?factory:null;
    return !!localMultiplayerExternalChannelFactory;
}
function configuredMultiplayerRelayUrl(){
    try{return String(localStorage.getItem(MULTIPLAYER_RELAY_URL_KEY)||DEFAULT_MULTIPLAYER_RELAY_URL).trim();}
    catch(_){return DEFAULT_MULTIPLAYER_RELAY_URL;}
}

function normaliseMultiplayerRelayUrl(value){
    const raw=String(value||'').trim();
    if(!raw)return '';
    try{
        const url=new URL(raw);
        if(url.protocol!=='ws:'&&url.protocol!=='wss:')return '';
        url.hash='';
        return url.toString().replace(/\/$/,'');
    }catch(_){return '';}
}
function createWebSocketMultiplayerChannelFactory(relayUrl){
    const base=normaliseMultiplayerRelayUrl(relayUrl);
    if(!base)throw new Error('Invalid multiplayer server address.');
    return async matchId=>{
        if(typeof WebSocket!=='function')throw new Error('WebSocket is not supported by this browser.');
        const socketUrl=new URL(base);
        socketUrl.searchParams.set('matchId',String(matchId||''));
        const socket=new WebSocket(socketUrl.toString());
        const queued=[];
        const inboundQueue=[];
        let handler=null,closed=false,superseded=false;
        const deliver=data=>{
            if(handler)handler({data});
            else inboundQueue.push(data);
        };
        const channel={
            serverBacked:true,
            serverIdentity:null,
            serverProgression:null,
            postMessage(data){
                if(closed)return;
                // Multiplayer snapshots contain Sets/Maps (reward ledgers, Areas,
                // collection state, etc.). Plain JSON.stringify turns those into
                // {}, which can make a peer re-award milestones after the next
                // authoritative import. Use the same lossless wire shape as saves.
                const encoded=JSON.stringify(serialiseSpecial(data));
                if(socket.readyState===WebSocket.OPEN)socket.send(encoded);
                else if(socket.readyState===WebSocket.CONNECTING)queued.push(encoded);
            },
            postServerMessage(data){
                if(closed)return false;
                const message={...data,protocol:MULTIPLAYER_SERVER_PROTOCOL};
                multiplayerDiagnostic('server-message-sent',{
                    type:message.type||null,requestId:message.requestId||null,
                    baseRevision:Number(message.baseRevision)||null,
                    hasZoo:!!message.zoo
                });
                const encoded=JSON.stringify(serialiseSpecial(message));
                if(socket.readyState===WebSocket.OPEN)socket.send(encoded);
                else if(socket.readyState===WebSocket.CONNECTING)queued.push(encoded);
                return true;
            },
            close(){closed=true;queued.length=0;inboundQueue.length=0;try{socket.close();}catch(_){}},
            get onmessage(){return handler;},
            set onmessage(fn){
                handler=typeof fn==='function'?fn:null;
                if(handler){
                    for(const data of inboundQueue.splice(0))handler({data});
                }
            }
        };
        // Attach the message listener before sending the v2 hello. A fast local
        // server can answer hello with server-welcome immediately; attaching
        // this only after the open promise resolved created a small race where
        // the authentication packet could be lost before the channel existed.
        socket.addEventListener('message',event=>{
            try{
                const message=deserialiseSpecial(JSON.parse(event.data));
                if(message?.protocol===MULTIPLAYER_SERVER_PROTOCOL&&message?.type==='server-superseded')
                    superseded=true;
                deliver(message);
            }catch(error){console.warn('Ignored invalid multiplayer server message:',error);}
        });
        await new Promise((resolve,reject)=>{
            const timer=setTimeout(()=>{
                try{socket.close();}catch(_){}
                reject(new Error('Multiplayer server connection timed out.'));
            },7000);
            socket.addEventListener('open',()=>{
                clearTimeout(timer);
                multiplayerDiagnostic('websocket-open',{url:socketUrl.origin});
                for(const message of queued.splice(0))socket.send(message);
                const savedIdentity=readMultiplayerServerIdentity(matchId);
                const activeIdentity=String(localClassicMatch?.activePlayerId||'');
                const seatMatch=/^player-(\d+)$/.exec(activeIdentity);
                const desiredSeat=seatMatch?Number(seatMatch[1]):null;
                const isProvisionalJoin=/^joining-/.test(activeIdentity);
                // A fresh manual Join must not silently reuse an old token.
                // Automatic reload recovery, however, intentionally enters
                // join() through a provisional joining-* shell. Recognise the
                // persisted active peer session so that path still presents its
                // reconnect token and reclaims the existing durable seat.
                const activeSession=readActiveMultiplayerSession?.();
                const explicitPeerReconnect=!!(
                    isProvisionalJoin&&savedIdentity&&
                    activeSession?.role==='peer'&&
                    String(activeSession?.matchId||'')===String(matchId||'')
                );
                const reconnectIdentity=(!isProvisionalJoin||explicitPeerReconnect)&&savedIdentity
                    ? savedIdentity : null;
                socket.send(JSON.stringify({
                    protocol:MULTIPLAYER_SERVER_PROTOCOL,
                    type:'hello',
                    playerId:reconnectIdentity?.playerId||null,
                    reconnectToken:reconnectIdentity?.reconnectToken||null,
                    desiredSeat
                }));
                resolve();
            },{once:true});
            socket.addEventListener('error',()=>{
                clearTimeout(timer);
                multiplayerDiagnostic('websocket-error',{readyState:socket.readyState});
                reject(new Error('Could not connect to multiplayer server.'));
            },{once:true});
        });
        socket.addEventListener('close',event=>{
            multiplayerDiagnostic('websocket-close',{code:event?.code||0,reason:event?.reason||'',wasClean:event?.wasClean===true,superseded});
            closed=true;
            queued.length=0;
            if(!superseded)deliver({
                protocol:MULTIPLAYER_SERVER_PROTOCOL,
                type:'server-disconnected',
                matchId:String(matchId||'')
            });
        });
        return channel;
    };
}
function configureWebSocketMultiplayer(relayUrl){
    const normalised=normaliseMultiplayerRelayUrl(relayUrl);
    if(!normalised){
        setLocalMultiplayerExternalChannelFactory(null);
        try{localStorage.removeItem(MULTIPLAYER_RELAY_URL_KEY);}catch(_){}
        return false;
    }
    try{localStorage.setItem(MULTIPLAYER_RELAY_URL_KEY,normalised);}catch(_){}
    setLocalMultiplayerExternalChannelFactory(createWebSocketMultiplayerChannelFactory(normalised));
    return true;
}
const savedMultiplayerRelayUrl=configuredMultiplayerRelayUrl();
if(savedMultiplayerRelayUrl)configureWebSocketMultiplayer(savedMultiplayerRelayUrl);
async function createLocalMultiplayerChannel(matchId){
    if(localMultiplayerExternalChannelFactory){
        try{
            const channel=await localMultiplayerExternalChannelFactory(String(matchId));
            if(channel?.postMessage&&channel?.close)return channel;
        }catch(error){
            console.error('Multiplayer external transport failed:',error);
            return null;
        }
    }
    if(typeof BroadcastChannel==='function')
        return new BroadcastChannel(multiplayerBrowserChannelName(matchId));
    return null;
}

function captureBrowserPeerCamera(){
    const t=localMultiplayerBrowserTransport;
    if(!t||t.role!=='peer'||!t.peerCameraInitialised||!zooBoard)return;
    t.peerCamera={
        scrollLeft:zooBoard.scrollLeft,
        scrollTop:zooBoard.scrollTop,
        zoom:Number(state.zoom)||1
    };
}
zooBoard?.addEventListener('scroll',captureBrowserPeerCamera,{passive:true});
zooBoard?.addEventListener('wheel',()=>requestAnimationFrame(captureBrowserPeerCamera),{passive:true});
window.addEventListener('pointerup',()=>requestAnimationFrame(captureBrowserPeerCamera),{passive:true});
let localMultiplayerBrowserSyncSequence=0;

// Multiplayer join diagnostics. Deliberately keep zoo snapshots, reconnect
// tokens and animal inventories out of this log: it is meant to be safe to
// paste into a bug report.
const multiplayerDiagnosticLog=[];
function multiplayerDiagnostic(event,details={}){
    const entry={
        at:new Date().toISOString(),
        event:String(event||'event'),
        role:localMultiplayerBrowserTransport?.role||null,
        matchId:localMultiplayerBrowserTransport?.matchId||localClassicMatch?.matchId||null,
        localPlayerId:localClassicMatch?.activePlayerId||null,
        serverPlayerId:localMultiplayerBrowserTransport?.serverPlayerId||null,
        serverSeat:localMultiplayerBrowserTransport?.serverSeat||null,
        authenticated:localMultiplayerBrowserTransport?.serverAuthenticated===true,
        ...details
    };
    multiplayerDiagnosticLog.push(entry);
    if(multiplayerDiagnosticLog.length>250)multiplayerDiagnosticLog.splice(0,multiplayerDiagnosticLog.length-250);
    console.log('[Zoo Curator Multiplayer]',entry.event,entry);
    return entry;
}
function zooMultiplayerDiagnostics(){
    const t=localMultiplayerBrowserTransport;
    const players=(t?.serverPlayers||[]).map(p=>({
        playerId:String(p?.playerId||''),
        seat:Number(p?.seat)||null,
        connected:p?.connected!==false,
        zooName:p?.zooName||null,
        hasZoo:Boolean(
            localClassicMatch?.players?.[`player-${Number(p?.seat)}`]?.snapshot ||
            localMultiplayerPeerReplica?.players?.[`player-${Number(p?.seat)}`]?.snapshot ||
            (Number(p?.seat)===Number(t?.serverSeat) && t?.durableOwnZooSnapshot)
        )
    }));
    const localPlayers=Object.fromEntries(Object.entries(localClassicMatch?.players||{}).map(([id,p])=>[
        id,{connected:p?.connected!==false,hasSnapshot:!!p?.snapshot,
            zooName:p?.snapshot?.state?.zooName||p?.snapshot?.zooName||null}
    ]));
    const report={
        generatedAt:new Date().toISOString(),
        transport:t?{
            role:t.role,matchId:t.matchId,playerId:t.playerId,
            serverBacked:t.serverBacked===true,serverAuthenticated:t.serverAuthenticated===true,
            serverDisconnected:t.serverDisconnected===true,serverSuperseded:t.serverSuperseded===true,
            serverPlayerId:t.serverPlayerId||null,serverSeat:t.serverSeat||null,
            serverRevision:Number(t.serverRevision)||0,
            sent:Number(t.sent)||0,received:Number(t.received)||0,
            lastMessageType:t.lastMessageType||null,
            pendingPreSeatSync:!!t.pendingPreSeatSync,
            durableZooRevision:Number(t.durableZooRevision)||0,
            durableZooCommitPending:t.durableZooCommitPending===true,
            hasDurableOwnZoo:!!t.durableOwnZooSnapshot
        }:null,
        match:localClassicMatch?{
            matchId:localClassicMatch.matchId,activePlayerId:localClassicMatch.activePlayerId,
            turnPlayerId:localClassicMatch.turnPlayerId,
            awaitingLocalZooSetup:localClassicMatch.awaitingLocalZooSetup===true,
            playerIds:[...(localClassicMatch.playerIds||[])],
            players:localPlayers
        }:null,
        serverPlayers:players,
        peerReplica:localMultiplayerPeerReplica?{
            playerId:localMultiplayerPeerReplica.playerId,
            revision:localMultiplayerPeerReplica.revision,
            receivedPackets:localMultiplayerPeerReplica.receivedPackets,
            playerIds:[...(localMultiplayerPeerReplica.playerIds||[])],
            snapshotSeats:Object.fromEntries(Object.entries(localMultiplayerPeerReplica.players||{})
                .map(([id,p])=>[id,!!p?.snapshot]))
        }:null,
        pendingBrowserActions:[...localMultiplayerPendingActions.entries()].map(([id,p])=>({id,type:p.type})),
        pendingServerActions:[...multiplayerServerPendingActions.entries()].map(([id,p])=>({id,type:p.type})),
        recentEvents:multiplayerDiagnosticLog.slice(-80)
    };
    console.log('[Zoo Curator Multiplayer] DIAGNOSTIC REPORT');
    console.log(report);
    console.table(players);
    console.table(report.recentEvents);
    return report;
}
window.zooMultiplayerDiagnostics=zooMultiplayerDiagnostics;
window.copyZooMultiplayerDiagnostics=async function(){
    const text=JSON.stringify(zooMultiplayerDiagnostics(),null,2);
    try{
        await navigator.clipboard.writeText(text);
        console.log('[Zoo Curator Multiplayer] Diagnostic report copied to clipboard.');
        return text;
    }catch(error){
        console.warn('[Zoo Curator Multiplayer] Could not copy automatically; use zooMultiplayerDiagnostics() instead.',error);
        return text;
    }
};

let localMultiplayerPeerApplyChain=Promise.resolve();
const localMultiplayerPendingActions=new Map();
let localMultiplayerTransportGeneration=0;
let localMultiplayerReconnectTimer=null;
let localMultiplayerReconnectAttempt=0;
function cancelAutomaticMultiplayerReconnect(){
    if(localMultiplayerReconnectTimer){clearTimeout(localMultiplayerReconnectTimer);localMultiplayerReconnectTimer=null;}
    localMultiplayerReconnectAttempt=0;
}
function scheduleAutomaticMultiplayerReconnect(transport){
    if(!transport?.serverBacked||transport.serverSuperseded||!localClassicMatch)return false;
    if(localMultiplayerReconnectTimer)return true;
    const matchId=transport.matchId;
    const role=transport.role;
    const playerId=transport.playerId;
    const attempt=++localMultiplayerReconnectAttempt;
    const delay=Math.min(10000,1000*Math.pow(2,Math.min(3,attempt-1)));
    localMultiplayerReconnectTimer=setTimeout(async()=>{
        localMultiplayerReconnectTimer=null;
        if(!localClassicMatch||transport.serverSuperseded)return;
        const ok=await enableLocalMultiplayerBrowserTransport({role,playerId,matchId});
        if(!ok){
            scheduleAutomaticMultiplayerReconnect({
                serverBacked:true,serverSuperseded:false,role,playerId,matchId
            });
        }
    },delay);
    return true;
}
function multiplayerBrowserChannelName(matchId){return `zoo-curator-classic:${String(matchId||'local')}`;}
function closeLocalMultiplayerBrowserTransport({preserveReconnect=false}={}){
    if(!preserveReconnect)cancelAutomaticMultiplayerReconnect();
    localMultiplayerTransportGeneration++;
    // Detach future peer sync work. In-flight async work is invalidated by the
    // transport-generation/channel guards in the sync handler.
    localMultiplayerPeerApplyChain=Promise.resolve();
    // Never leave the previous host channel captured by the authoritative
    // outbound sink. Without this, reconnecting or switching to peer mode can
    // keep sending snapshots into a closed/stale channel.
    setLocalMultiplayerOutboundSink(null);
    try{localMultiplayerBrowserChannel?.close?.();}catch(_){}
    for(const [id,pending] of localMultiplayerPendingActions){
        clearTimeout(pending.timeout);
        pending.resolve({ok:false,reason:'transport-closed',actionId:id});
    }
    localMultiplayerPendingActions.clear();
    for(const [id,pending] of multiplayerServerPendingActions){
        clearTimeout(pending.timeout);
        pending.resolve({type:'action-rejected',action:pending.type,code:'TRANSPORT_CLOSED',requestId:id});
    }
    multiplayerServerPendingActions.clear();
    clearMultiplayerRemoteCursors();
    localMultiplayerBrowserChannel=null;localMultiplayerBrowserTransport=null;
}
function announceLocalMultiplayerLeave(){
    const transport=localMultiplayerBrowserTransport;
    const channel=localMultiplayerBrowserChannel;
    if(!transport||!channel)return false;
    try{
        channel.postMessage({
            protocol:'zoo-curator-browser-transport-v1',
            matchId:transport.matchId,
            senderPlayerId:transport.playerId,
            type:'leave',
            hostLeaving:transport.role==='host'
        });
        return true;
    }catch(_){return false;}
}
function getLocalMultiplayerBrowserTransportSummary(){
    return localMultiplayerBrowserTransport?cloneForSave(localMultiplayerBrowserTransport):null;
}
function ensureLocalClassicMatchId(){
    if(!localClassicMatch)return null;
    if(!localClassicMatch.matchId)localClassicMatch.matchId=`match-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
    return localClassicMatch.matchId;
}
async function enableLocalMultiplayerBrowserTransport({role='host',playerId=null,matchId=null}={}){
    if(!localClassicMatch)return false;
    closeLocalMultiplayerBrowserTransport({preserveReconnect:true});
    if(localMultiplayerReconnectTimer){clearTimeout(localMultiplayerReconnectTimer);localMultiplayerReconnectTimer=null;}
    const generation=++localMultiplayerTransportGeneration;
    const resolvedMatchId=matchId||ensureLocalClassicMatchId();
    const resolvedPlayerId=playerId||localClassicMatch.activePlayerId;
    multiplayerDiagnostic('transport-opening',{requestedRole:role,requestedPlayerId:resolvedPlayerId});
    const channel=await createLocalMultiplayerChannel(resolvedMatchId);
    if(!channel){
        multiplayerDiagnostic('transport-open-failed',{requestedRole:role,requestedPlayerId:resolvedPlayerId});
        return false;
    }
    multiplayerDiagnostic('transport-channel-created',{requestedRole:role,requestedPlayerId:resolvedPlayerId,serverBacked:channel.serverBacked===true});
    // A second Host/Join click may have started while an async external
    // transport was opening. Only the newest attempt may become active.
    if(generation!==localMultiplayerTransportGeneration){
        try{channel.close?.();}catch(_){}
        return false;
    }
    localMultiplayerBrowserChannel=channel;
    localMultiplayerBrowserTransport={
        protocol:'zoo-curator-browser-transport-v1',role,matchId:resolvedMatchId,
        playerId:resolvedPlayerId,connectedAt:Date.now(),sent:0,received:0,lastMessageType:null,
        peerSeats:role==='host'?{}:null,
        lastAppliedSyncSequence:0,peerCameraInitialised:false,peerCamera:null,
        serverBacked:channel.serverBacked===true,
        serverAuthenticated:false,serverPlayerId:null,serverSeat:null,serverReturning:false,
        serverDisconnected:false,serverSuperseded:false,
        serverRevision:0,serverProgressionRevision:0,serverProgression:null,
        serverViewTargetPlayerId:null,serverViewSubscriptionPending:false,serverViewSubscriptionSequence:0,
        serverProgressionInitSent:false,
        durableZooRevision:0,
        // Highest durable zoo revision accepted for every server player. This is
        // separate from our own CAS revision because viewer/reconnect/action
        // packets can independently carry snapshots for several players.
        serverZooRevisionByPlayer:new Map(),appliedAuthoritativeOwnActionZooRevisions:new Set(),
        durableZooCommitPending:false,durableZooCommitBaseRevision:0,durableZooQueuedSnapshot:null,
        durableZooQueuedSignature:'',durableZooCommitWaiters:[],
        durableZooCommitTimer:null,durableZooScheduledSnapshot:null,durableZooScheduledSignature:'',
        durableZooLastRequestedSignature:'',durableOwnZooSnapshot:null,
        awaitingAuthoritativeZooCorrection:false,lastImportedViewedZooSignature:''
    };
    channel.onmessage=async event=>{
        // Ignore late events from a channel that has already been replaced.
        if(channel!==localMultiplayerBrowserChannel)return;
        const transport=localMultiplayerBrowserTransport;
        const message=event?.data;
        if(!transport||!message)return;

        // New authenticated server protocol runs alongside the legacy browser
        // relay while gameplay actions are migrated one by one.
        if(message.protocol===MULTIPLAYER_SERVER_PROTOCOL){
            transport.received++;
            transport.lastMessageType=message.type;
            multiplayerDiagnostic('server-message',{
                type:message.type||null,
                playerId:message.playerId||null,
                seat:Number(message.seat)||null,
                revision:Number(message.revision)||0,
                playerCount:Array.isArray(message.players)?message.players.length:null,
                hasZoo:!!message.zoo,
                action:message.action||null,
                code:message.code||null
            });
            if(message.type==='server-welcome'){
                channel.serverIdentity={
                    playerId:String(message.playerId||''),
                    reconnectToken:String(message.reconnectToken||''),
                    seat:Number(message.seat)||null
                };
                transport.serverPlayerId=channel.serverIdentity.playerId;
                transport.serverSeat=channel.serverIdentity.seat;
                transport.serverRevision=Number(message.revision)||0;
                transport.serverAuthenticated=true;
                transport.serverDisconnected=false;
                // Authentication alone does not mean the durable zoo has been
                // restored yet. Keep the reload fallback until this connection
                // receives its first authoritative own zoo-state.
                localMultiplayerReconnectAttempt=0;
                transport.serverSuperseded=false;
                transport.serverReturning=message.returning===true;
                if(transport.durableZooCommitPending)settleDurableZooCommitWaiters(false);
                transport.durableZooCommitPending=false;
                transport.durableZooQueuedSnapshot=null;
                transport.durableZooQueuedSignature='';
                if(transport.durableZooCommitTimer)clearTimeout(transport.durableZooCommitTimer);
                transport.durableZooCommitTimer=null;
                transport.durableZooScheduledSnapshot=null;
                transport.durableZooScheduledSignature='';
                transport.durableZooLastRequestedSignature='';
                transport.serverPlayers=cloneForSave(message.players||[]);
                const localSeat=multiplayerSeatForLocalPlayerId(localClassicMatch?.activePlayerId);
                const authoritativeLocalId=transport.serverSeat?`player-${Number(transport.serverSeat)}`:null;
                if(authoritativeLocalId&&localClassicMatch){
                    const previousLocalId=localClassicMatch.activePlayerId;
                    if(previousLocalId!==authoritativeLocalId){
                        console.warn(`Server seat ${transport.serverSeat} differs from local identity ${previousLocalId}; remapping local player to ${authoritativeLocalId}.`);
                        const previous=localClassicMatch.players?.[previousLocalId];
                        if(!localClassicMatch.players)localClassicMatch.players={};
                        if(!localClassicMatch.players[authoritativeLocalId]&&previous)
                            localClassicMatch.players[authoritativeLocalId]=previous;
                        if(/^joining-/.test(String(previousLocalId||''))){
                            delete localClassicMatch.players[previousLocalId];
                            if(Array.isArray(localClassicMatch.playerIds))
                                localClassicMatch.playerIds=localClassicMatch.playerIds.filter(id=>id!==previousLocalId);
                        }
                        if(!localClassicMatch.playerIds.includes(authoritativeLocalId))
                            localClassicMatch.playerIds.push(authoritativeLocalId);
                        localClassicMatch.activePlayerId=authoritativeLocalId;
                        transport.playerId=authoritativeLocalId;
                    }
                }
                reconcileLocalMultiplayerRosterFromServerPlayers(transport.serverPlayers);
                if(role==='peer'&&transport.serverSeat){
                    // With server-backed seat assignment there is no legacy
                    // seat-assignment packet. Bind the peer replica directly to
                    // the authenticated local player id.
                    const authenticatedLocalId=`player-${Number(transport.serverSeat)}`;
                    if(localMultiplayerPeerReplica)
                        localMultiplayerPeerReplica.playerId=authenticatedLocalId;
                }
                multiplayerDiagnostic('server-welcome-applied',{
                    assignedPlayerId:transport.serverPlayerId,
                    assignedSeat:transport.serverSeat,
                    returning:transport.serverReturning===true,
                    roster:(transport.serverPlayers||[]).map(p=>({
                        playerId:p?.playerId||null,seat:Number(p?.seat)||null,connected:p?.connected!==false
                    }))
                });
                if(transport.role==='peer'&&transport.serverSeat&&transport.serverReturning!==true){
                    const authenticatedLocalId=`player-${Number(transport.serverSeat)}`;
                    const ownSnapshot=localClassicMatch?.players?.[authenticatedLocalId]?.snapshot;
                    if(localClassicMatch&&!ownSnapshot){
                        localClassicMatch.activePlayerId=authenticatedLocalId;
                        transport.playerId=authenticatedLocalId;
                        localClassicMatch.awaitingLocalZooSetup=true;
                        pendingMultiplayerSetup={
                            gameMode:localClassicMatch.rules?.gameMode==='true'?'true':'classic',
                            turnMode:localClassicMatch.rules?.turnMode==='simultaneous'?'simultaneous':'alternating',
                            activeCategories:[...(localClassicMatch.rules?.activeCategories||Object.keys(FOLDERS))]
                        };
                        queueMicrotask(()=>{
                            if(localMultiplayerBrowserTransport!==transport||
                               !localClassicMatch?.awaitingLocalZooSetup)return;
                            const menu=ensureGenerateZooUI();
                            menu?.classList.add('multiplayer-join-zoo-setup');
                            openGenerateZooMenu();
                            const select=menu?.querySelector?.('#newZooGameMode');
                            if(select){
                                select.value=pendingMultiplayerSetup.gameMode;
                                select.disabled=true;
                            }
                            const cancel=menu?.querySelector?.('#generateZooCancel');
                            if(cancel){
                                cancel.disabled=true;
                                cancel.title='Create your zoo to join this multiplayer game.';
                            }
                            multiplayerDiagnostic('join-setup-opened-after-authentication',{
                                seat:transport.serverSeat,
                                playerId:authenticatedLocalId
                            });
                        });
                    }
                }
                if(transport.role==='peer'&&transport.serverSeat){
                    clearTimeout(transport._joinSetupWatchdog);
                    transport._joinSetupWatchdog=setTimeout(()=>{
                        if(localClassicMatch?.awaitingLocalZooSetup &&
                           !localClassicMatch?.players?.[`player-${transport.serverSeat}`]?.snapshot){
                            multiplayerDiagnostic('join-setup-stalled',{
                                seat:transport.serverSeat,
                                replicaHasSeat:!!localMultiplayerPeerReplica?.players?.[`player-${transport.serverSeat}`],
                                replicaPlayerIds:[...(localMultiplayerPeerReplica?.playerIds||[])],
                                serverPlayerCount:(transport.serverPlayers||[]).length
                            });
                            console.warn('[Zoo Curator Multiplayer] Join setup is still waiting after authentication. Run zooMultiplayerDiagnostics().');
                        }
                    },4000);
                }
                writeMultiplayerServerIdentity(resolvedMatchId,channel.serverIdentity);
                if(role==='peer'&&transport.pendingPreSeatSync){
                    const deferredSync=transport.pendingPreSeatSync;
                    transport.pendingPreSeatSync=null;
                    queueMicrotask(()=>{
                        if(channel===localMultiplayerBrowserChannel&&channel.onmessage)
                            channel.onmessage({data:deferredSync});
                    });
                }
                queueMicrotask(()=>sendMultiplayerLiveViewSubscription());
                // Existing matches replay progression immediately after welcome.
                // Give that packet one event-loop turn before seat 1 attempts
                // create-once initialization of a brand-new match.
                setTimeout(()=>{
                    if(channel===localMultiplayerBrowserChannel)
                        initialiseAuthoritativeMultiplayerProgressionIfHost();
                },0);
            }else if(message.type==='zoo-state'){
                multiplayerDiagnostic('zoo-state-received',{
                    playerId:message.playerId||null,revision:Number(message.revision)||0,
                    commitAck:message.commitAck===true,authoritativeCorrection:message.authoritativeCorrection===true,
                    zooName:message.zoo?.state?.zooName||message.zoo?.zooName||null,
                    enclosureCount:Array.isArray(message.zoo?.state?.enclosures)?message.zoo.state.enclosures.length:null,
                    animalCount:Array.isArray(message.zoo?.state?.animals)?message.zoo.state.animals.length:null
                });
                const serverPlayerId=String(message.playerId||'');
                const ownServerId=String(transport.serverPlayerId||'');
                const liveViewSequence=Math.max(0,Number(message.liveViewSubscriptionSequence)||0);
                // A subscription snapshot is valid only for the exact view
                // request that produced it. Without this check, P2 -> P3 ->
                // Return could receive P2's delayed initial snapshot after the
                // browser had already moved on. Replica revisions may still be
                // useful for ordinary broadcasts, but a stale subscription
                // bootstrap must be completely side-effect free.
                if(liveViewSequence&&
                   liveViewSequence!==Number(transport.serverViewSubscriptionSequence||0)){
                    multiplayerDiagnostic('live-view-zoo-state-stale-dropped',{
                        playerId:serverPlayerId,
                        subscriptionSequence:liveViewSequence,
                        currentSubscriptionSequence:Number(transport.serverViewSubscriptionSequence)||0
                    });
                    return;
                }
                const zoo=message.zoo;
                const zooRevision=Math.max(0,Number(message.revision)||0);
                if(!(transport.serverZooRevisionByPlayer instanceof Map))
                    transport.serverZooRevisionByPlayer=new Map(transport.serverZooRevisionByPlayer||[]);
                const highestAcceptedZooRevision=Math.max(
                    0,Number(transport.serverZooRevisionByPlayer.get(serverPlayerId))||0
                );
                // Never let a reconnect replay, action broadcast or old live-view
                // snapshot replace a newer durable zoo already accepted for this
                // player. Equal revisions are allowed because the owner's
                // commitAck/correction flags can carry important control state.
                if(zooRevision<highestAcceptedZooRevision){
                    multiplayerDiagnostic('zoo-state-stale-dropped',{
                        playerId:serverPlayerId,revision:zooRevision,
                        highestAcceptedRevision:highestAcceptedZooRevision
                    });
                    return;
                }
                if(zooRevision>highestAcceptedZooRevision)
                    transport.serverZooRevisionByPlayer.set(serverPlayerId,zooRevision);
                if(zoo&&typeof zoo==='object'&&!Array.isArray(zoo)){
                    const serverPlayer=transport.serverPlayers?.find(p=>String(p?.playerId||'')===serverPlayerId);
                    const localTargetId=serverPlayerId===String(transport.serverPlayerId||'')&&Number(transport.serverSeat)>0
                        ? `player-${Number(transport.serverSeat)}`
                        : (serverPlayer?.seat?`player-${Number(serverPlayer.seat)}`:null);
                    if(localTargetId&&localClassicMatch?.players?.[localTargetId])
                        localClassicMatch.players[localTargetId].snapshot=cloneForSave(zoo);
                    if(localTargetId&&localMultiplayerPeerReplica?.players?.[localTargetId])
                        localMultiplayerPeerReplica.players[localTargetId].snapshot=cloneForSave(zoo);
                }
                if(serverPlayerId===ownServerId&&zoo&&typeof zoo==='object'&&!Array.isArray(zoo)){
                    // The durable owned zoo has now crossed the wire; the local
                    // reload fallback is no longer needed.
                    transport.reconnectFallbackMatch=null;
                    transport.durableZooRevision=Math.max(
                        Math.max(0,Number(transport.durableZooRevision)||0),
                        zooRevision
                    );
                    if(message.authoritativeCorrection===true)transport.awaitingAuthoritativeZooCorrection=false;
                    transport.durableOwnZooSnapshot=cloneForSave(zoo);
                    const ownPlayer=localClassicMatch?.players?.[transport.playerId];
                    if(ownPlayer)ownPlayer.snapshot=cloneForSave(zoo);
                    try{transport.durableZooLastRequestedSignature=JSON.stringify(zoo);}catch(_){}
                    if(message.commitAck===true){
                        transport.durableZooCommitPending=false;
                        transport.durableZooCommitBaseRevision=zooRevision;
                        settleDurableZooCommitWaiters(true);
                        // If there is no newer local snapshot waiting, make the
                        // live zoo agree with the normalized durable placement
                        // immediately. This is the refresh that previously only
                        // happened accidentally after visiting another zoo.
                        if(!transport.durableZooQueuedSnapshot &&
                           !transport.durableZooScheduledSnapshot)
                            reconcileLiveOwnZooPlacementFromDurable(zoo);
                        queueMicrotask(()=>flushQueuedOwnZooStateCommit());
                    }else if(message.authoritativeTrade===true){
                        // A server transaction advanced the durable zoo while a
                        // normal snapshot may still be in flight. The stale
                        // commit will be rejected by CAS; don't let its queued
                        // pre-trade copy overwrite the authoritative result.
                        transport.durableZooQueuedSnapshot=null;
                        transport.durableZooQueuedSignature='';
                    }
                    // Only force a full own-zoo restore for an authenticated reconnect.
                    // Viewer zoo-state packets remain display data and must never overwrite
                    // the local player's zoo.
                    if(!(transport.appliedAuthoritativeOwnActionZooRevisions instanceof Set))
                        transport.appliedAuthoritativeOwnActionZooRevisions=
                            new Set(transport.appliedAuthoritativeOwnActionZooRevisions||[]);
                    const redundantOwnActionEcho=(
                        (message.authoritativeDraw===true||
                         message.authoritativeExchange===true||
                         message.authoritativeMove===true) &&
                        zooRevision>0 &&
                        transport.appliedAuthoritativeOwnActionZooRevisions.has(zooRevision)
                    );
                    if(redundantOwnActionEcho)
                        transport.appliedAuthoritativeOwnActionZooRevisions.delete(zooRevision);
                    if((transport.serverReturning===true||message.authoritativeTrade===true||message.authoritativeDraw===true||message.authoritativeExchange===true||message.authoritativeCorrection===true)&&
                       !redundantOwnActionEcho&&!localClassicMatch?.viewingPlayerId){
                        // The server owns gameplay state, never this browser's camera.
                        const localCamera={
                            zoom:Number(state.zoom)||1,
                            scrollLeft:zooBoard?.scrollLeft||0,
                            scrollTop:zooBoard?.scrollTop||0
                        };
                        const authoritativeImport=cloneForSave(zoo);
                        if(authoritativeImport?.view)delete authoritativeImport.view;
                        autoResumeWriteSuppressed=true;
                        try{
                            await importGameState(authoritativeImport,{deferRender:false});
                        }finally{autoResumeWriteSuppressed=false;}
                        state.zoom=localCamera.zoom;
                        document.documentElement.style.setProperty('--zoo-zoom',state.zoom);
                        await new Promise(resolve=>requestAnimationFrame(resolve));
                        if(zooBoard){
                            const maxLeft=Math.max(0,zooBoard.scrollWidth-zooBoard.clientWidth);
                            const maxTop=Math.max(0,zooBoard.scrollHeight-zooBoard.clientHeight);
                            zooBoard.scrollLeft=Math.max(0,Math.min(maxLeft,localCamera.scrollLeft));
                            zooBoard.scrollTop=Math.max(0,Math.min(maxTop,localCamera.scrollTop));
                        }
                        if(localClassicMatch?.activePlayerId===transport.playerId){
                            syncActiveZooIntoLocalMatch();
                            try{
                                transport.lastImportedOwnSnapshotSignature=JSON.stringify(
                                    localClassicMatch.players?.[transport.playerId]?.snapshot||zoo
                                );
                            }catch(_){}
                        }
                        transport.serverReturning=false;
                        renderVisitedZooQuickTabs();
                        renderTrade();
                    }
                }
                if(serverPlayerId!==ownServerId&&zoo&&typeof zoo==='object'&&!Array.isArray(zoo)){
                    const serverPlayer=transport.serverPlayers?.find(p=>String(p?.playerId||'')===serverPlayerId);
                    const localTargetId=serverPlayer?.seat?`player-${Number(serverPlayer.seat)}`:null;
                    if(localTargetId&&String(localClassicMatch?.viewingPlayerId||'')===localTargetId&&
                       message.authoritativeMove===true&&message.animalId!=null&&message.destination){
                        // High-frequency ordinary relocation: the visitor is
                        // already looking at this zoo, so update the one card in
                        // place. Full importGameState caused a visible flicker,
                        // rebuilt every enclosure and disturbed live drag/cursor
                        // presentation for a move that changes only two fields.
                        const moved=(state.animals||[]).find(a=>String(a?.id)===String(message.animalId));
                        const enclosure=(state.enclosures||[]).find(e=>
                            String(e?.id)===String(message.destination?.enclosureId));
                        const slotIndex=Number(message.destination?.slotIndex);
                        if(moved&&enclosure&&getAllSlots(enclosure).includes(slotIndex)){
                            moved.enclosureId=enclosure.id;
                            moved.slotIndex=slotIndex;
                            renderAll();
                            try{transport.lastImportedViewedZooSignature=JSON.stringify(zoo);}catch(_){}
                        }
                    }else if(localTargetId&&String(localClassicMatch?.viewingPlayerId||'')===localTargetId){
                        let signature='';
                        try{signature=JSON.stringify(zoo);}catch(_){}
                        if(!signature||transport.lastImportedViewedZooSignature!==signature){
                            const savedView={zoom:state.zoom,scrollLeft:zooBoard?.scrollLeft||0,scrollTop:zooBoard?.scrollTop||0};
                            const viewedImport=cloneForSave(zoo);
                            if(viewedImport?.view)delete viewedImport.view;
                            autoResumeWriteSuppressed=true;
                            try{
                                await importGameState(viewedImport,{deferRender:false});
                                invalidateMultiplayerViewedZooAreaCaches();
                                renderAll(false);
                            }finally{autoResumeWriteSuppressed=false;}
                            transport.lastImportedViewedZooSignature=signature;
                            state.zoom=savedView.zoom;
                            document.documentElement.style.setProperty('--zoo-zoom',state.zoom);
                            requestAnimationFrame(()=>{
                                if(zooBoard){
                                    zooBoard.scrollLeft=savedView.scrollLeft;
                                    zooBoard.scrollTop=savedView.scrollTop;
                                }
                            });
                            renderVisitedZooQuickTabs();
                            renderTrade();
                        }
                    }
                }
            }else if(message.type==='zoo-state-rejected'){
                const currentRevision=Math.max(0,Number(message.currentRevision)||0);
                transport.durableZooRevision=currentRevision;
                transport.durableZooCommitPending=false;
                transport.durableZooCommitBaseRevision=currentRevision;
                transport.durableZooQueuedSnapshot=null;
                transport.durableZooQueuedSignature='';
                // A second local edit may already be sitting in the debounce
                // timer behind the rejected commit. It was produced from the
                // same now-stale authority base, so discard it as well rather
                // than letting its timer fire during/after correction.
                if(transport.durableZooCommitTimer)clearTimeout(transport.durableZooCommitTimer);
                transport.durableZooCommitTimer=null;
                transport.durableZooScheduledSnapshot=null;
                transport.durableZooScheduledSignature='';
                transport.durableZooLastRequestedSignature='';
                transport.awaitingAuthoritativeZooCorrection=true;
                settleDurableZooCommitWaiters(false);
                console.warn('Durable multiplayer zoo state rejected:',message.code||'unknown');
            }else if(message.type==='live-view-subscribed'){
                const ackSequence=Number(message.subscriptionSequence)||0;
                if(!ackSequence||ackSequence===Number(transport.serverViewSubscriptionSequence)){
                    const nextViewTarget=message.targetPlayerId?String(message.targetPlayerId):null;
                    if(nextViewTarget!==transport.serverViewTargetPlayerId)
                        transport.lastImportedViewedZooSignature='';
                    transport.serverViewTargetPlayerId=nextViewTarget;
                    transport.serverViewSubscriptionPending=false;
                }
            }else if(message.type==='trade-listings'){
                multiplayerPublicTradeListings=Array.isArray(message.listings)?cloneForSave(message.listings):[];
                reconcilePublicTradeProposalsWithListings();
                if(selectedMultiplayerPublicListingPlayerId &&
                   !multiplayerPublicTradeListings.some(x=>String(x?.playerId)===String(selectedMultiplayerPublicListingPlayerId)))
                    selectedMultiplayerPublicListingPlayerId=null;
                renderTrade?.();
            }else if(message.type==='progression-state'){
                const incomingProgressionRevision=Math.max(0,Number(message.revision)||0);
                const currentProgressionRevision=Math.max(0,Number(transport.serverProgressionRevision)||0);
                if(incomingProgressionRevision>=currentProgressionRevision){
                    channel.serverProgression=cloneForSave(message);
                    transport.serverProgression=cloneForSave(message);
                    transport.serverProgressionRevision=incomingProgressionRevision;
                    transport.serverProgressionInitSent=true;
                    // The server owns each seat's action turn. Apply it to the
                    // local zoo immediately, including a brand-new P2 before its
                    // first action, rather than waiting for Draw/Exchange to make
                    // the browser snapshot converge incidentally.
                    const authoritativeActionTurn=Math.max(1,Number(message.actionTurn)||1);
                    const ownLocalId=transport.serverSeat?`player-${Number(transport.serverSeat)}`:null;
                    const ownPlayer=ownLocalId?localClassicMatch?.players?.[ownLocalId]:null;
                    if(ownPlayer?.snapshot?.state)
                        ownPlayer.snapshot.state.turn=authoritativeActionTurn;
                    if(ownLocalId&&localClassicMatch?.activePlayerId===ownLocalId&&!localClassicMatch?.viewingPlayerId)
                        state.turn=authoritativeActionTurn;
                    // Only an accepted authoritative progression snapshot should
                    // trigger availability work. An older packet has no state to
                    // contribute and must be completely side-effect free.
                    queueMicrotask(()=>{
                        if(channel===localMultiplayerBrowserChannel){
                            renderTurn?.();
                            refreshDrawAvailabilityState?.();
                        }
                    });
                }
            }else if(message.type==='server-presence'){
                const previousServerPlayers=Array.isArray(transport.serverPlayers)?transport.serverPlayers:[];
                const previousConnectedIds=new Set(previousServerPlayers.filter(p=>p?.connected!==false).map(p=>String(p.playerId||'')));
                transport.serverPlayers=cloneForSave(message.players||[]);
                if(previousServerPlayers.length){
                    for(const player of transport.serverPlayers.filter(p=>p?.connected!==false)){
                        const playerId=String(player?.playerId||'');
                        if(playerId&&!previousConnectedIds.has(playerId)&&playerId!==String(transport.serverPlayerId||'')){
                            pushMultiplayerActivity('presence',{
                                playerId,key:`presence:${playerId}:${Number(message.revision)||0}`,
                                text:`${multiplayerActivityPlayerName(playerId)} joined the match.`
                            });
                        }
                    }
                }
                reconcileLocalMultiplayerRosterFromServerPlayers(transport.serverPlayers);
                // Presence is part of trade availability: a disconnected player
                // cannot leave a public animal card stranded on the trade board.
                renderTrade?.();
                if(localMultiplayerPeerReplica){
                    if(!localMultiplayerPeerReplica.players)localMultiplayerPeerReplica.players={};
                    if(!Array.isArray(localMultiplayerPeerReplica.playerIds))localMultiplayerPeerReplica.playerIds=[];
                    for(const serverPlayer of transport.serverPlayers||[]){
                        const localId=multiplayerLocalPlayerIdForServerId(serverPlayer?.playerId);
                        if(!localId)continue;
                        if(!localMultiplayerPeerReplica.players[localId]){
                            localMultiplayerPeerReplica.players[localId]={snapshot:null,connected:serverPlayer?.connected!==false,reconnectToken:null};
                        }else{
                            localMultiplayerPeerReplica.players[localId].connected=serverPlayer?.connected!==false;
                        }
                        if(!localMultiplayerPeerReplica.playerIds.includes(localId))localMultiplayerPeerReplica.playerIds.push(localId);
                    }
                    localMultiplayerPeerReplica.playerIds.sort((a,b)=>{
                        const seat=id=>Number(/^player-(\d+)$/.exec(String(id||''))?.[1])||Number.MAX_SAFE_INTEGER;
                        return seat(a)-seat(b);
                    });
                }
                multiplayerDiagnostic('server-presence-applied',{
                    roster:(transport.serverPlayers||[]).map(p=>({
                        playerId:p?.playerId||null,seat:Number(p?.seat)||null,connected:p?.connected!==false
                    })),
                    localSeats:Object.fromEntries(Object.entries(localClassicMatch?.players||{}).map(([id,p])=>[id,!!p?.snapshot]))
                });
                transport.serverRevision=Math.max(Number(transport.serverRevision)||0,Number(message.revision)||0);
                renderVisitedZooQuickTabs?.();
                queueMicrotask(()=>sendMultiplayerLiveViewSubscription());
                if(role==='host'){
                    // On server-backed multiplayer the old browser hello/seat handshake
                    // is intentionally disabled. Presence is now the authoritative join
                    // signal: when a newly connected authenticated peer appears, send
                    // the full host snapshot that lets it finish joining.
                    const ownServerId=String(transport.serverPlayerId||'');
                    const newlyConnectedPeer=transport.serverPlayers.some(p=>
                        p?.connected!==false &&
                        String(p.playerId||'')!==ownServerId &&
                        !previousConnectedIds.has(String(p.playerId||''))
                    );
                    if(newlyConnectedPeer&&channel.serverBacked!==true)queueMicrotask(()=>{
                        if(channel===localMultiplayerBrowserChannel&&localMultiplayerBrowserTransport?.role==='host')
                            emitLocalMultiplayerSync('server-peer-joined');
                    });
                }
            }else if(message.type==='multiplayer-activity'){
                receiveRelayedMultiplayerActivity(message);
            }else if(message.type==='cursor'){
                receiveMultiplayerCursor(message);
            }else if(message.type==='live-layout'){
                receiveMultiplayerLiveLayout(message);
            }else if(message.type==='action-rejected'&&message.action==='progression-init'){
                // progression-init is fire-and-forget, so handle its recovery
                // before the generic authoritative action branch below.
                transport.serverProgressionInitSent=false;
                transport.lastServerAction=cloneForSave(message);
                console.warn('Authoritative progression initialisation rejected:',
                    message.code||'unknown');
                if(message.code!=='HOST_ONLY'&&message.code!=='INVALID_LEVEL1_DECK'){
                    setTimeout(()=>{
                        if(channel===localMultiplayerBrowserChannel&&
                           localMultiplayerBrowserTransport===transport&&
                           transport.serverAuthenticated&&Number(transport.serverSeat)===1&&
                           !transport.serverProgression)
                            initialiseAuthoritativeMultiplayerProgressionIfHost();
                    },250);
                }
            }else if(message.type==='action-committed'||message.type==='action-rejected'){
                transport.lastServerAction=cloneForSave(message);
                if(message.type==='action-committed'){
                    recordAuthoritativeMultiplayerActivity(message);
                    relayAuthoritativeMultiplayerActivity(message);
                }
                if(message.type==='action-committed'&&message.action==='human-trade')
                    applyAuthoritativeHumanTradeMessage(message);
                if(message.type==='action-committed'&&
                   (message.action==='draw-level1'||message.action==='exchange')&&
                   Number.isFinite(Number(message.revision)))
                    transport.serverProgressionRevision=Math.max(
                        Number(transport.serverProgressionRevision)||0,
                        Number(message.revision)
                    );
                resolveMultiplayerServerAction(message);
                // A committed/rejected server action closes an asynchronous
                // availability boundary. Do not wait for the user to click the
                // visually stale deck before restoring its enabled appearance.
                queueMicrotask(()=>{
                    if(channel===localMultiplayerBrowserChannel)
                        refreshDrawAvailabilityState?.();
                });
            }else if(message.type==='server-superseded'){
                transport.serverAuthenticated=false;
                transport.serverDisconnected=true;
                transport.serverSuperseded=true;
                cancelAutomaticMultiplayerReconnect();
                clearMultiplayerRemoteCursors();
                setLocalMultiplayerOutboundSink(null);
                showGameNotice?.('This multiplayer player reconnected in another tab or window. This connection is now read-only.');
            }else if(message.type==='server-disconnected'){
                if(transport.serverSuperseded)return;
                if(transport.serverAuthenticated){
                    transport.serverAuthenticated=false;
                    transport.serverDisconnected=true;
                    if(transport.reconnectFallbackMatch&&
                       /^joining-/.test(String(localClassicMatch?.activePlayerId||''))){
                        const fallback=cloneForSave(transport.reconnectFallbackMatch);
                        localClassicMatch=fallback;
                        localClassicMatch.viewingPlayerId=null;
                        transport.playerId=localClassicMatch.activePlayerId;
                        renderVisitedZooQuickTabs?.();
                    }
                    clearMultiplayerRemoteCursors();
                    setLocalMultiplayerOutboundSink(null);
                    showGameNotice?.('Multiplayer server connection lost. Your zoo is preserved; reconnecting automatically…');
                    scheduleAutomaticMultiplayerReconnect(transport);
                }
            }else if(message.type==='server-error'){
                transport.serverError=cloneForSave(message);
                console.warn('Multiplayer server error:',message.code||message.message||'unknown');
                if(role==='peer'&&!transport.serverAuthenticated){
                    const reason=String(message.message||message.code||'Could not join multiplayer game.');
                    const reconnectFallback=transport.reconnectFallbackMatch
                        ? cloneForSave(transport.reconnectFallbackMatch) : null;
                    queueMicrotask(()=>{
                        if(channel!==localMultiplayerBrowserChannel)return;
                        closeLocalMultiplayerBrowserTransport({preserveReconnect:!!reconnectFallback});
                        if(reconnectFallback){
                            // An automatic reload reconnect can fail after the
                            // WebSocket itself opened (bad network/server auth).
                            // Do not throw away the already-restored P2 zoo just
                            // because join() had returned before authentication.
                            localClassicMatch=reconnectFallback;
                            localClassicMatch.viewingPlayerId=null;
                            localMultiplayerPeerReplica=null;
                            renderVisitedZooQuickTabs?.();
                        }else{
                            if(localClassicMatch&&/^joining-/.test(String(localClassicMatch.activePlayerId||''))){
                                localClassicMatch=null;
                                localMultiplayerPeerReplica=null;
                                renderVisitedZooQuickTabs?.();
                            }
                            clearActiveMultiplayerSession?.();
                        }
                        updateMultiplayerHeaderButtonState?.();
                        showGameNotice?.(`Could not join multiplayer game: ${reason}`);
                    });
                }
            }
            updateMultiplayerHeaderButtonState?.();
            return;
        }

        if(message.protocol!=='zoo-curator-browser-transport-v1'||
           message.matchId!==resolvedMatchId||message.senderPlayerId===transport.playerId)return;
        transport.received++;
        transport.lastMessageType=message.type;
        if(message.type==='seat-assignment'&&role==='peer'){
            if(message.targetPlayerId!==transport.playerId)return;
            const assignedId=String(message.assignedPlayerId||'').trim();
            if(!assignedId)return;
            transport.playerId=assignedId;
            localClassicMatch.activePlayerId=assignedId;
            if(localMultiplayerPeerReplica)localMultiplayerPeerReplica.playerId=assignedId;
            if(message.reconnectToken)writeLocalMultiplayerReconnectIdentity(resolvedMatchId,assignedId,message.reconnectToken);
            transport.lastMessageType='seat-assignment';
            // A relay normally preserves the host's seat-assignment -> sync
            // ordering, but don't make joining depend on that timing. If a sync
            // reached us while the provisional joining-* id was still active,
            // replay the newest deferred packet now that this tab owns a seat.
            const deferredSync=transport.pendingPreSeatSync;
            transport.pendingPreSeatSync=null;
            if(deferredSync)queueMicrotask(()=>{
                if(channel===localMultiplayerBrowserChannel&&channel.onmessage)
                    channel.onmessage({data:deferredSync});
            });
        }else if(message.type==='action'&&role==='host'){
            const hostSeat=resolvedPlayerId;
            const result=await applyLocalMultiplayerActionEnvelope(cloneForSave(message.action));
            if(localClassicMatch?.activePlayerId!==hostSeat){
                await restoreBrowserHostSeatAfterRemoteAction(hostSeat);
            }
            // A remote Classic action is executed against the peer's seat on
            // the browser host. Server-backed peer sync deliberately refuses to
            // overwrite that peer's OWN zoo with host snapshots, so an accepted
            // private AI trade would otherwise disappear before P2 could commit
            // it to SQLite. Return the exact post-action owner snapshot directly
            // to the action initiator; only that authenticated owner may persist it.
            const actionOwnerId=String(message.action?.playerId||'');
            const ownerSnapshot=result?.ok&&actionOwnerId
                ? cloneForSave(localClassicMatch?.players?.[actionOwnerId]?.snapshot||null)
                : null;
            channel.postMessage({protocol:'zoo-curator-browser-transport-v1',matchId:resolvedMatchId,
                senderPlayerId:resolvedPlayerId,type:'action-result',actionId:message.action?.id,result:cloneForSave(result),
                ownerPlayerId:actionOwnerId||null,ownerSnapshot,
                turnPlayerId:localClassicMatch?.turnPlayerId||null,revision:localClassicMatch?.revision??null});
            emitLocalMultiplayerSync('browser-action');
        }else if(message.type==='turn-state'&&role==='peer'){
            // Turn-state is a tiny immediate UI hint, not a replacement for a
            // full authoritative snapshot. Do NOT advance lastAppliedSyncSequence
            // here: doing so could make the subsequent full sync look stale and
            // leave P2 with the old zoo/trade/layout state.
            if(localMultiplayerPeerReplica)localMultiplayerPeerReplica.turnPlayerId=message.turnPlayerId;
            if(localClassicMatch){
                localClassicMatch.turnPlayerId=message.turnPlayerId;
                const revision=Number(message.revision);
                if(Number.isFinite(revision))localClassicMatch.revision=Math.max(localClassicMatch.revision||0,revision);
                renderVisitedZooQuickTabs();renderTrade();
            }
        }else if(message.type==='action-result'&&role==='peer'){
            localMultiplayerBrowserTransport.lastActionResult=cloneForSave(message.result||null);

            // For successful remote Classic mutations (notably AI trade
            // acceptance), install the host-executed owner snapshot before the
            // action promise resolves. Normal server-backed sync intentionally
            // preserves our durable own snapshot and therefore cannot carry
            // this mutation back to us.
            const pending=localMultiplayerPendingActions.get(message.actionId);
            const returnedOwnSnapshot=
                // Only Classic gameplay mutations use the authoritative-return
                // bridge. Registration has its own durable initial-zoo commit
                // immediately after the host ACK; intercepting it here made the
                // join path try to persist the new zoo twice and could turn a
                // successful host registration into "host could not register".
                pending?.type==='classic-game-action' &&
                message.result?.ok===true &&
                String(message.ownerPlayerId||'')===String(transport.playerId||'') &&
                message.ownerSnapshot?.state
                    ? cloneForSave(message.ownerSnapshot) : null;
            let resolvedActionResult=cloneForSave(message.result||{ok:false,reason:'empty-result'});
            if(returnedOwnSnapshot){
                if(localClassicMatch?.players?.[transport.playerId])
                    localClassicMatch.players[transport.playerId].snapshot=cloneForSave(returnedOwnSnapshot);
                if(!localClassicMatch?.viewingPlayerId&&!state.visitingZoo){
                    const imported=cloneForSave(returnedOwnSnapshot);
                    if(imported?.view)delete imported.view;
                    autoResumeWriteSuppressed=true;
                    try{
                        await importGameState(imported,{deferRender:false});
                        const signature=JSON.stringify(returnedOwnSnapshot);
                        transport.lastImportedOwnSnapshotSignature=signature;
                    }finally{autoResumeWriteSuppressed=false;}
                }
                // P2 is the only browser authorised to persist P2's zoo. A host
                // success is not a completed trade until that owner snapshot is
                // durably accepted by the server. Do not tell the drag handler
                // "accepted" while SQLite is still on the pre-trade zoo.
                const commitStarted=commitOwnZooStateToServer(returnedOwnSnapshot);
                const durableAccepted=commitStarted&&await awaitDurableZooCommitIdle(5000);
                if(!durableAccepted){
                    resolvedActionResult={ok:false,reason:'zoo-state-sync'};
                    console.warn('Multiplayer action could not persist the returned owner zoo.');

                    // A rejected/stalled CAS may already have supplied the last
                    // authoritative durable snapshot. Restore it immediately so
                    // the incoming AI card cannot remain visible as a phantom
                    // successful trade.
                    if(transport.durableOwnZooSnapshot?.state&&!localClassicMatch?.viewingPlayerId&&!state.visitingZoo){
                        const correction=cloneForSave(transport.durableOwnZooSnapshot);
                        if(correction?.view)delete correction.view;
                        autoResumeWriteSuppressed=true;
                        try{await importGameState(correction,{deferRender:false});}
                        finally{autoResumeWriteSuppressed=false;}
                        if(localClassicMatch?.players?.[transport.playerId])
                            localClassicMatch.players[transport.playerId].snapshot=cloneForSave(transport.durableOwnZooSnapshot);
                    }
                }
            }

            if(pending){
                clearTimeout(pending.timeout);
                localMultiplayerPendingActions.delete(message.actionId);
                pending.resolve(resolvedActionResult);
            }
            if(message.result?.ok===false){
                console.warn('Multiplayer action rejected by host:',message.result.reason||'unknown');
                // Restore authoritative offer/exchange controls after a rejected
                // optimistic drag rather than leaving the peer UI stranded.
                renderAll();renderVisitedZooQuickTabs();
            }
            if(message.turnPlayerId&&localClassicMatch){
                localClassicMatch.turnPlayerId=message.turnPlayerId;
                if(localMultiplayerPeerReplica)localMultiplayerPeerReplica.turnPlayerId=message.turnPlayerId;
                const revision=Number(message.revision);
                if(Number.isFinite(revision))localClassicMatch.revision=Math.max(localClassicMatch.revision||0,revision);
                renderVisitedZooQuickTabs();renderTrade();
            }
        }else if(message.type==='leave'){
            if(message.hostLeaving&&role==='peer'){
                // The authoritative host is gone, so this peer can no longer
                // perform a valid multiplayer action. Leave cleanly rather
                // than showing a connected but dead match.
                closeLocalMultiplayerBrowserTransport();
                disableLocalMultiplayerPeerSimulation();
                localClassicMatch=null;
                pendingMultiplayerSetup={
                    gameMode:'classic',
                    turnMode:'simultaneous',
                    activeCategories:[...state.activeCategories]
                };
                renderVisitedZooQuickTabs();
                renderTrade();
                updateMultiplayerHeaderButtonState();
                showGameNotice(uiText('The host left the multiplayer game.'));
            }else if(role==='host'){
                const leavingId=String(message.senderPlayerId||''),player=localClassicMatch?.players?.[leavingId];
                if(player&&leavingId!=='player-1'){
                    player.connected=false;
                    if(transport.peerSeats)for(const [p,id] of Object.entries(transport.peerSeats))if(id===leavingId)delete transport.peerSeats[p];
                    if(localClassicMatch.turnPlayerId===leavingId&&!localClassicUsesSimultaneousTurns()){
                        const next=nextConnectedRegisteredMultiplayerPlayer(leavingId);if(next)localClassicMatch.turnPlayerId=next;
                    }
                    if(localClassicMatch.viewingPlayerId===leavingId){
                        localClassicMatch.viewingPlayerId=null;
                        const own=localClassicMatch.players?.[localClassicMatch.activePlayerId]?.snapshot;
                        if(own)importGameState(own).catch(error=>console.error('Could not return from disconnected multiplayer zoo:',error));
                    }
                    localClassicMatch.revision++;recordLocalMultiplayerEvent('player-disconnected',{playerId:leavingId});
                    renderVisitedZooQuickTabs();renderTrade();scheduleLocalMultiplayerSync('player-disconnected');
                }
                showGameNotice(uiText('A player disconnected from the multiplayer game.'));
            }
        }else if(message.type==='sync'&&role==='peer'){
            if(channel.serverBacked===true&&!transport.serverAuthenticated){
                transport.pendingPreSeatSync=cloneForSave(message);
                return;
            }
            if(channel.serverBacked!==true&&String(transport.playerId||'').startsWith('joining-')){
                transport.pendingPreSeatSync=cloneForSave(message);
                return;
            }
            const packet=cloneForSave(message.packet);
            const isServerReplay=message.serverReplay===true;
            const sequence=isServerReplay?0:(Number(packet?.transportSequence)||0);
            const syncGeneration=localMultiplayerTransportGeneration;
            const syncChannel=channel;
            localMultiplayerPeerApplyChain=localMultiplayerPeerApplyChain.then(async()=>{
                const before=localMultiplayerBrowserTransport;
                if(syncGeneration!==localMultiplayerTransportGeneration ||
                   syncChannel!==localMultiplayerBrowserChannel ||
                   !before||before.role!=='peer')return;
                if(sequence&&sequence<=before.lastAppliedSyncSequence)return;
                if(isServerReplay&&before.lastAppliedSyncSequence>0)return;
                const applied=await applyLocalMultiplayerSyncPacketToReplica(packet);
                // importGameState is asynchronous. The user may have left the
                // match while it was awaiting assets/rendering.
                const after=localMultiplayerBrowserTransport;
                if(syncGeneration!==localMultiplayerTransportGeneration ||
                   syncChannel!==localMultiplayerBrowserChannel ||
                   !after||after.role!=='peer')return;
                if(applied&&sequence)after.lastAppliedSyncSequence=sequence;
            }).catch(error=>console.error('Multiplayer peer sync failed:',error));
        }else if(message.type==='hello'&&role==='host'){
            // The authenticated multiplayer server owns player identity and seat
            // allocation. The old browser-relay hello handshake must never create
            // pending seats on a server-backed channel; doing so races server-welcome
            // and produces phantom Player 2 / Player 3 tabs.
            if(channel.serverBacked===true)return;
            const provisionalId=String(message.senderPlayerId||'');
            let assignedId=transport.peerSeats?.[provisionalId];
            const reconnectId=String(message.reconnectPlayerId||''),token=String(message.reconnectToken||'');
            const reconnectPlayer=localClassicMatch.players?.[reconnectId];
            if(!assignedId&&reconnectId&&token&&reconnectPlayer?.reconnectToken===token&&reconnectPlayer.connected===false){
                assignedId=reconnectId;reconnectPlayer.connected=true;transport.peerSeats[provisionalId]=assignedId;
                localClassicMatch.revision++;recordLocalMultiplayerEvent('player-reconnected',{playerId:assignedId});
            }
            if(!assignedId){assignedId=nextLocalMultiplayerPlayerId();transport.peerSeats[provisionalId]=assignedId;addPendingLocalMultiplayerSeat(assignedId);}
            const player=localClassicMatch.players?.[assignedId];
            if(player&&!player.reconnectToken)player.reconnectToken=createLocalMultiplayerReconnectToken();
            channel.postMessage({
                protocol:'zoo-curator-browser-transport-v1',matchId:resolvedMatchId,
                senderPlayerId:resolvedPlayerId,type:'seat-assignment',
                targetPlayerId:provisionalId,assignedPlayerId:assignedId,reconnectToken:player?.reconnectToken||null
            });
            const helloPacket=getLocalMultiplayerSyncPacket(null);
            helloPacket.transportSequence=++localMultiplayerBrowserSyncSequence;
            channel.postMessage({protocol:'zoo-curator-browser-transport-v1',matchId:resolvedMatchId,
                senderPlayerId:resolvedPlayerId,type:'sync',packet:cloneForSave(helloPacket)});
        }
    };
    if(role==='host'){
        setLocalMultiplayerOutboundSink(packet=>{
            packet.transportSequence=++localMultiplayerBrowserSyncSequence;
            channel.postMessage({protocol:'zoo-curator-browser-transport-v1',matchId:resolvedMatchId,
                senderPlayerId:resolvedPlayerId,type:'sync',packet:cloneForSave(packet)});
            localMultiplayerBrowserTransport.sent++;
        });
    }else{
        createLocalMultiplayerPeerReplica(resolvedPlayerId);
        // Legacy browser-relay channels still need their own seat handshake.
        // Server-backed WebSockets get the authoritative seat from server-welcome,
        // so sending this second hello would create a duplicate pending player.
        if(channel.serverBacked!==true){
            const reconnectIdentity=readLocalMultiplayerReconnectIdentity(resolvedMatchId);
            channel.postMessage({protocol:'zoo-curator-browser-transport-v1',matchId:resolvedMatchId,
                senderPlayerId:resolvedPlayerId,type:'hello',
                reconnectPlayerId:reconnectIdentity?.playerId||null,reconnectToken:reconnectIdentity?.token||null});
            localMultiplayerBrowserTransport.sent++;
        }
    }
    return true;
}
function broadcastAuthoritativeMultiplayerTurn(){
    const t=localMultiplayerBrowserTransport;
    if(!t||t.role!=='host'||!localMultiplayerBrowserChannel||!localClassicMatch)return false;
    const sequence=++localMultiplayerBrowserSyncSequence;
    localMultiplayerBrowserChannel.postMessage({
        protocol:'zoo-curator-browser-transport-v1',matchId:t.matchId,
        senderPlayerId:t.playerId,type:'turn-state',sequence,
        revision:localClassicMatch.revision,turnPlayerId:localClassicMatch.turnPlayerId
    });
    t.sent++;t.lastMessageType='turn-state';
    return true;
}
function sendLocalMultiplayerBrowserAction(type,payload={}){
    const t=localMultiplayerBrowserTransport;
    if(!t||t.role!=='peer'||!localMultiplayerBrowserChannel)
        return Promise.resolve({ok:false,reason:'transport'});
    const action=createLocalMultiplayerActionEnvelope(t.playerId,type,payload);
    action.baseRevision=localMultiplayerPeerReplica?.revision??action.baseRevision;
    const promise=new Promise(resolve=>{
        const timeout=setTimeout(()=>{
            if(!localMultiplayerPendingActions.has(action.id))return;
            localMultiplayerPendingActions.delete(action.id);
            multiplayerDiagnostic('browser-action-timeout',{actionId:action.id,actionType:type});
            resolve({ok:false,reason:'timeout',actionId:action.id});
        },5000);
        localMultiplayerPendingActions.set(action.id,{resolve,timeout,type});
    });
    multiplayerDiagnostic('browser-action-sent',{
        actionId:action.id,actionType:type,
        hasSnapshot:!!payload?.snapshot,
        snapshotZooName:payload?.snapshot?.state?.zooName||null
    });
    localMultiplayerBrowserChannel.postMessage({protocol:'zoo-curator-browser-transport-v1',
        matchId:t.matchId,senderPlayerId:t.playerId,type:'action',action:cloneForSave(action)});
    t.sent++;t.lastMessageType='action';
    return promise;
}

async function hostCurrentLocalMultiplayerInBrowser(){
    if(!localClassicMatch)return false;
    const matchId=ensureLocalClassicMatchId();
    const ok=await enableLocalMultiplayerBrowserTransport({
        role:'host',playerId:'player-1',matchId
    });
    if(ok){
        emitLocalMultiplayerSync('browser-host-start');
        updateMultiplayerHeaderButtonState();
        writeActiveMultiplayerSession(matchId,'host');
    }
    return ok?matchId:false;
}
async function joinLocalMultiplayerInBrowser(matchId,playerId=null){
    if(!matchId)return false;
    const requestedMatchId=String(matchId);
    const activeTransport=localMultiplayerBrowserTransport;
    if(activeTransport&&localClassicMatch){
        const sameMatch=String(activeTransport.matchId||'')===requestedMatchId;
        const roleLabel=activeTransport.role==='host'?'hosting':'connected to';
        showGameNotice?.(sameMatch
            ? `This browser is already ${roleLabel} that multiplayer game.`
            : 'Leave the current multiplayer game before joining another one.');
        return false;
    }
    const previousMatch=localClassicMatch;
    // The peer needs a temporary shell only until the host/server response
    // supplies the authoritative player snapshots.
    const provisionalPlayerId=playerId||`joining-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
    localClassicMatch={
        mode:'classic-multiplayer',matchId:requestedMatchId,
        playerIds:[],activePlayerId:provisionalPlayerId,
        turnPlayerId:'player-1',viewingPlayerId:null,revision:-1,rules:null,
        players:{},
        awaitingLocalZooSetup:true,
        pendingPlayerTrades:[],tradeDrafts:{},events:[],nextEventSequence:1
    };
    const ok=await enableLocalMultiplayerBrowserTransport({
        role:'peer',playerId:provisionalPlayerId,matchId:requestedMatchId
    });
    if(!ok){
        localClassicMatch=previousMatch;
        renderVisitedZooQuickTabs();
    }
    if(ok)writeActiveMultiplayerSession(requestedMatchId,'peer');
    updateMultiplayerHeaderButtonState();
    return ok;
}

function ensureMultiplayerLobbyOverlay(){
    let overlay=document.getElementById('multiplayerLobbyOverlay');
    if(overlay)return overlay;
    overlay=document.createElement('div');
    overlay.id='multiplayerLobbyOverlay';
    overlay.className='game-options-overlay';
    overlay.innerHTML=`<div class="game-options-modal multiplayer-setup-modal" style="max-width:520px">
        <h2>Multiplayer</h2>
        <p>Configure the shared game, then host it or join an existing match.</p>
        <div class="advanced-game-rules">
            <label class="trade-frequency-option">
                <span>Gamemode</span>
                <select id="multiplayerGameMode">
                    <option value="classic">Classic</option>
                    <option value="true" disabled>True (coming soon)</option>
                </select>
            </label>
            <label class="trade-frequency-option">
                <span>Turns</span>
                <select id="multiplayerTurnMode">
                    <option value="alternating">Alternating</option>
                    <option value="simultaneous" selected>Simultaneous</option>
                </select>
            </label>
            <div class="advanced-options-note">Alternating shares one turn order. Simultaneous lets every zoo progress independently in real time.</div>
            <label class="trade-frequency-option">
                <span>Multiplayer server</span>
                <input class="multiplayer-server-url" autocomplete="off" spellcheck="false"
                    placeholder="wss://multiplayer.zoocurator.nl">
            </label>
            <div class="advanced-options-note">Uses the Zoo Curator multiplayer server by default. You can still enter another ws:// or wss:// relay address for testing.</div>
            <label class="trade-frequency-option">
                <span>Match code</span>
                <input class="multiplayer-match-code" autocomplete="off" spellcheck="false">
            </label>
            <div class="advanced-options-title" style="margin-top:12px">ANIMAL CATEGORIES</div>
            <button type="button" id="multiplayerCategoriesButton">Animal Categories</button>
            <div id="multiplayerCategoryPanel" class="category-option-list" hidden></div>
            <div class="advanced-options-note">Deselected categories are disabled for both players for the whole match.</div>
        </div>
        <div class="multiplayer-lobby-status advanced-options-note" style="margin-top:10px"></div>
        <div class="options-actions" style="flex-wrap:wrap">
            <button type="button" class="multiplayer-host-button">Create Multiplayer Game</button>
            <button type="button" class="multiplayer-join-button">Join Existing Game</button>
            <span style="flex:1 1 auto"></span>
            <button type="button" class="multiplayer-close-button">Continue</button>
        </div>
    </div>`;
    document.body.appendChild(overlay);
    const input=overlay.querySelector('.multiplayer-match-code');
    const serverUrl=overlay.querySelector('.multiplayer-server-url');
    const status=overlay.querySelector('.multiplayer-lobby-status');
    const mode=overlay.querySelector('#multiplayerGameMode');
    const turnMode=overlay.querySelector('#multiplayerTurnMode');
    if(serverUrl&&!serverUrl.value)serverUrl.value=configuredMultiplayerRelayUrl();
    const panel=overlay.querySelector('#multiplayerCategoryPanel');
    for(const category of Object.keys(FOLDERS).sort((a,b)=>a.localeCompare(b))){
        const label=document.createElement('label');
        label.className='category-option multiplayer-category-option';
        label.innerHTML=`<input type="checkbox" value="${category}" checked><span class="category-option-colour"></span><span>${category}</span>`;
        label.querySelector('.category-option-colour').style.background=state.categoryColours[category]||CATEGORY_COLOURS[category];
        panel.appendChild(label);
    }
    overlay.querySelector('#multiplayerCategoriesButton').onclick=()=>{panel.hidden=!panel.hidden;};
    const selectedCategories=()=>[...panel.querySelectorAll('input[type="checkbox"]:checked')].map(cb=>cb.value);
    const saveSetup=()=>{
        if(multiplayerCategoriesLocked()){
            pendingMultiplayerSetup=cloneForSave(localClassicMatch.rules);
            return true;
        }
        const categories=selectedCategories();
        if(!categories.length){showGameNotice(uiText('At least one animal category must remain enabled.'));return false;}
        pendingMultiplayerSetup={
            gameMode:mode.value==='true'?'true':'classic',
            turnMode:turnMode?.value==='simultaneous'?'simultaneous':'alternating',
            activeCategories:categories
        };
        return true;
    };
    overlay.querySelector('.multiplayer-host-button').onclick=async()=>{
        if(localClassicMatch){
            status.textContent=`Already in multiplayer · ${localClassicMatch.matchId||'match active'}`;
            return;
        }
        // Multiplayer now starts from the zoo already on screen, so its
        // gamemode is authoritative rather than an independent lobby choice.
        mode.value=state.gameMode==='true'?'true':'classic';
        if(!saveSetup())return;
        const requestedServer=String(serverUrl?.value||'').trim();
        if(requestedServer&&!normaliseMultiplayerRelayUrl(requestedServer)){
            status.textContent='Enter a valid ws:// or wss:// multiplayer server address.';
            return;
        }
        configureWebSocketMultiplayer(requestedServer);
        overlay.dataset.multiplayerIntent='host';
        status.textContent=requestedServer
            ? 'Creating match and connecting to multiplayer server…'
            : 'Creating local multiplayer match…';
        try{
            await startConfiguredLocalTwoPlayerClassicMatch({
                playerOneSnapshot:exportCurrentGameState(),
                country:state.zooCountry||'',
                startingSize:Number(state.gameOptions?.startingCollectionSize)||20,
                gameMode:state.gameMode==='true'?'true':'classic',
                activeCategories:[...state.activeCategories]
            });
            const hostedMatchId=await hostCurrentLocalMultiplayerInBrowser();
            if(!hostedMatchId)throw new Error('Could not start multiplayer transport.');
            input.value=hostedMatchId;
            status.textContent=`Hosting · ${hostedMatchId}`;
            overlay._syncSetup?.();
        }catch(error){
            console.error('Could not create multiplayer game:',error);
            if(localClassicMatch)destroyLocalClassicMatchContainer();
            status.textContent='Could not create multiplayer game.';
        }
    };
    overlay.querySelector('.multiplayer-join-button').onclick=async()=>{
        const id=input.value.trim();
        if(!id){status.textContent='Enter a match code first.';return;}
        const requestedServer=String(serverUrl?.value||'').trim();
        if(requestedServer&&!normaliseMultiplayerRelayUrl(requestedServer)){
            status.textContent='Enter a valid ws:// or wss:// multiplayer server address.';
            return;
        }
        configureWebSocketMultiplayer(requestedServer);
        status.textContent=requestedServer?'Connecting to multiplayer server…':'Joining local match…';
        const ok=await joinLocalMultiplayerInBrowser(id);
        if(ok){
            overlay.dataset.multiplayerIntent='join';
            status.textContent=requestedServer
                ? 'Connected to multiplayer server. Waiting for the host’s zoo and shared settings…'
                : 'Connected locally. Waiting for the host’s zoo and shared settings…';
        }else status.textContent=requestedServer
            ? 'Could not connect to that multiplayer server or match.'
            : 'Could not join local multiplayer transport.';
    };
    const close=()=>{
        if(!saveSetup())return;
        overlay.classList.remove('visible');
        overlay.setAttribute('aria-hidden','true');
        const parent=document.getElementById('generateZooOverlay');
        if(parent&&overlay.dataset.returnToNewZoo==='true'&&overlay.dataset.multiplayerIntent!=='join'){
            const select=parent.querySelector('#newZooGameMode');
            if(select)select.value='multiplayer';
            parent.classList.add('visible');
        }
        overlay.dataset.returnToNewZoo='false';
    };
    overlay.querySelector('.multiplayer-close-button').onclick=close;
    overlay.addEventListener('pointerdown',event=>{if(event.target===overlay)close();});
    overlay._syncSetup=()=>{
        const locked=multiplayerCategoriesLocked();
        const source=locked?localClassicMatch.rules:pendingMultiplayerSetup;
        mode.value=locked
            ? (source?.gameMode==='true'?'true':'classic')
            : (state.gameMode==='true'?'true':'classic');
        mode.disabled=true;
        if(turnMode){
            turnMode.value=source?.turnMode==='simultaneous'?'simultaneous':'alternating';
            turnMode.disabled=locked;
        }
        const allowed=new Set(source?.activeCategories||Object.keys(FOLDERS));
        for(const cb of panel.querySelectorAll('input[type="checkbox"]')){
            cb.checked=allowed.has(cb.value);
            cb.disabled=locked;
            cb.closest('.category-option')?.classList.toggle('multiplayer-locked',locked);
        }
        overlay.querySelector('#multiplayerCategoriesButton').disabled=locked;
        if(serverUrl&&!serverUrl.value)serverUrl.value=configuredMultiplayerRelayUrl();
        panel.hidden=true;
    };
    return overlay;
}
function openMultiplayerSetupMenu(newZooOverlay=null,newZooGameModeSelect=null){
    const overlay=ensureMultiplayerLobbyOverlay();
    overlay.dataset.multiplayerIntent='';
    overlay.dataset.returnToNewZoo=newZooOverlay?'true':'false';
    overlay._syncSetup?.();
    if(newZooOverlay)newZooOverlay.classList.remove('visible');
    if(newZooGameModeSelect)newZooGameModeSelect.value='multiplayer';
    const input=overlay.querySelector('.multiplayer-match-code');
    const status=overlay.querySelector('.multiplayer-lobby-status');
    if(localClassicMatch?.matchId)input.value=localClassicMatch.matchId;
    const t=localMultiplayerBrowserTransport;
    status.textContent=t
        ? `${t.role==='host'?'Hosting':'Connected'} · ${t.matchId}`
        : 'Configure multiplayer for the zoo currently open.';
    overlay.classList.add('visible');overlay.setAttribute('aria-hidden','false');
    return true;
}
function openMultiplayerLobby(){return openMultiplayerSetupMenu();}

// Bidirectional action envelopes: the same authority boundary a remote client
// will use. The local peer simulator serializes through it now.
let localMultiplayerActionSequence=1;
const localMultiplayerProcessedActionIds=new Set();
function createLocalMultiplayerActionEnvelope(playerId,type,payload={}){
    return {protocol:'zoo-curator-classic-multiplayer-action-v1',
        id:`${playerId}:${localMultiplayerActionSequence++}`,playerId:String(playerId||''),
        type:String(type||''),baseRevision:localClassicMatch?.revision??-1,payload:cloneForSave(payload)};
}
function validateLocalMultiplayerActionEnvelope(action){
    if(!localClassicMatch||action?.protocol!=='zoo-curator-classic-multiplayer-action-v1')return {ok:false,reason:'protocol'};
    if(!localClassicMatch.players?.[action.playerId])return {ok:false,reason:'player'};
    if(localMultiplayerProcessedActionIds.has(action.id))return {ok:false,reason:'duplicate'};
    const base=Number(action.baseRevision);
    if(!Number.isFinite(base)||base>localClassicMatch.revision)return {ok:false,reason:'future-revision'};
    if(localClassicMatch.revision-base>25)return {ok:false,reason:'stale-revision'};
    return {ok:true};
}
async function applyLocalMultiplayerActionEnvelope(action){
    const valid=validateLocalMultiplayerActionEnvelope(action);
    if(!valid.ok)return {ok:false,reason:valid.reason};
    // Human trades in server-backed matches are committed by the durable server
    // and applied by applyAuthoritativeHumanTradeMessage(). Replaying the same
    // operation through this legacy browser-authority executor can double-move
    // cards, reject against the already-mutated zoo, or overwrite a newer
    // durable snapshot.
    if(serverAuthoritativeMultiplayerActive()&&SERVER_HUMAN_TRADE_ACTIONS.has(action.type))
        return {ok:false,reason:'server-authority-required'};
    localMultiplayerProcessedActionIds.add(action.id);
    if(localMultiplayerProcessedActionIds.size>500){
        const keep=[...localMultiplayerProcessedActionIds].slice(-250);
        localMultiplayerProcessedActionIds.clear();keep.forEach(id=>localMultiplayerProcessedActionIds.add(id));
    }
    if(action.type==='request-seat'){
        if(localClassicMatch.activePlayerId!==action.playerId)await switchLocalClassicMatchPlayer(action.playerId);
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='claim-human-trade'){
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const offer=pendingDirectHumanTrades().find(o=>
            o.id===action.payload?.offerId&&
            directHumanTradeHasParticipant(o,action.playerId)&&
            o.fromPlayerId===action.playerId&&
            o.status==='accepted-awaiting-sender-claim'
        );
        if(!offer||!offer.senderClaimAnimal)return {ok:false,reason:'offer'};
        const destination=multiplayerDestinationFromWire(action.payload?.destination);
        if(!destination)return {ok:false,reason:'destination'};
        const incoming=offer.senderClaimAnimal;
        const authoritativeTransferId=String(offer.requestedTransferId??incoming?.id??'');
        const hasOtherDuplicate=(state.animals||[]).some(a=>
            animalCardKey(a)===animalCardKey(incoming) &&
            !(serverAuthoritativeMultiplayerActive()&&
              authoritativeTransferId&&String(a?.id)===authoritativeTransferId)
        );
        if(hasOtherDuplicate){
            return {ok:false,reason:'duplicate-species'};
        }
        if(!canPlace(incoming,destination.enclosure,destination.slotIndex)){
            return {ok:false,reason:'illegal-placement'};
        }

        const liveCopy=cloneForSave(incoming);
        liveCopy.enclosureId=destination.enclosure.id;
        liveCopy.slotIndex=destination.slotIndex;
        state.animals.push(liveCopy);
        repairLoadedNextId();

        offer.senderClaimAnimal=null;
        offer.status='accepted';
        offer.claimedRevision=++localClassicMatch.revision;
        syncActiveZooIntoLocalMatch();
        recordLocalMultiplayerEvent('trade-completed',{
            offerId:offer.id,fromPlayerId:offer.fromPlayerId,toPlayerId:offer.toPlayerId,
            revision:localClassicMatch.revision
        });
        renderAll();
        resumeAITradingAfterHumanTrade();
        commitClassicTurn();
        renderVisitedZooQuickTabs();
        commitOwnZooStateToServer(exportCurrentGameState());
        persistHumanTradeBoundary('human-trade-completed');
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='accept-human-trade'){
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const offer=pendingDirectHumanTrades().find(o=>
            o.id===action.payload?.offerId&&directHumanTradeHasParticipant(o,action.playerId)&&o.toPlayerId===action.playerId&&o.status==='pending'
        );
        if(!offer)return {ok:false,reason:'offer'};
        const destination=multiplayerDestinationFromWire(action.payload?.destination);
        if(!destination)return {ok:false,reason:'destination'};
        const incoming=directTradeAnimal(offer.fromPlayerId,offer.offeredAnimalId);
        if(!incoming||!canPlace(incoming,destination.enclosure,destination.slotIndex)){
            return {ok:false,reason:'illegal-placement'};
        }
        const accepted=await acceptDirectHumanTradeOffer(
            offer.id,destination,{skipActiveSync:false}
        );
        return accepted
            ? {ok:true,revision:localClassicMatch.revision}
            : {ok:false,reason:'accept-rejected'};
    }
    if(action.type==='send-human-trade-offer'){
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const draft=localHumanTradeDraft(action.playerId);
        const offered=(state.animals||[]).find(a=>String(a.id)===String(action.payload?.offeredAnimalId));
        const requested=draft?.requestedPlayerId?directTradeAnimal(draft.requestedPlayerId,draft.requestedAnimalId):null;
        if(!draft?.requestedPlayerId||!requested||!offered)return {ok:false,reason:'trade-draft'};
        const softlockReason=humanTradeSoftlockReason(
            action.playerId,offered,draft.requestedPlayerId,requested
        );
        if(softlockReason)return {ok:false,reason:'no-legal-post-trade-placement'};
        const offeredKey=animalCardKey(offered),requestedKey=animalCardKey(requested);
        const fromOthers=(state.animals||[]).filter(a=>String(a.id)!==String(offered.id));
        const targetAnimals=localClassicMatch.players[draft.requestedPlayerId]?.snapshot?.state?.animals||[];
        if(offeredKey===requestedKey||
           fromOthers.some(a=>animalCardKey(a)===requestedKey)||
           targetAnimals.some(a=>String(a.id)!==String(requested.id)&&animalCardKey(a)===offeredKey)){
            return {ok:false,reason:'duplicate-species'};
        }
        const offer={
            id:String(action.payload?.tradeId||`player-trade-${Date.now()}-${Math.random().toString(36).slice(2,7)}`),
            fromPlayerId:action.playerId,toPlayerId:draft.requestedPlayerId,
            offeredAnimalId:offered.id,requestedAnimalId:requested.id,
            offeredTransferId:action.payload?.offeredTransferId??nextDirectTradeAnimalId(localClassicMatch.players[draft.requestedPlayerId]?.snapshot),
            requestedTransferId:action.payload?.requestedTransferId??nextDirectTradeAnimalId(localClassicMatch.players[action.playerId]?.snapshot),
            status:'pending',createdRevision:localClassicMatch.revision
        };
        pendingDirectHumanTrades().push(offer);
        clearLocalHumanTradeDraft(action.playerId);
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('trade-offered',{
            offerId:offer.id,fromPlayerId:offer.fromPlayerId,toPlayerId:offer.toPlayerId
        });
        renderTrade();renderVisitedZooQuickTabs();
        persistHumanTradeBoundary('human-trade-offered');
        return {ok:true,revision:localClassicMatch.revision,offerId:offer.id};
    }
    if(action.type==='cancel-human-trade-draft'){
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const draft=localHumanTradeDraft(action.playerId);
        if(!draft?.requestedPlayerId||!draft?.requestedAnimalId)return {ok:false,reason:'trade-draft'};
        clearLocalHumanTradeDraft(action.playerId);
        localClassicMatch.revision++;
        resumeAITradingAfterHumanTrade();
        recordLocalMultiplayerEvent('trade-draft-cancelled',{playerId:action.playerId});
        renderTrade();renderVisitedZooQuickTabs();
        persistHumanTradeBoundary('human-trade-draft-cancelled');
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='stage-human-trade-request'){
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const requestedPlayerId=String(action.payload?.requestedPlayerId||'');
        const requestedAnimalId=action.payload?.requestedAnimalId;
        if(requestedPlayerId===action.playerId||!localClassicMatch.players?.[requestedPlayerId])return {ok:false,reason:'target-player'};
        const requested=directTradeAnimal(requestedPlayerId,requestedAnimalId);
        if(!requested)return {ok:false,reason:'requested-animal'};
        const ownAnimals=localClassicMatch.players[action.playerId]?.snapshot?.state?.animals||[];
        if(ownAnimals.some(a=>animalCardKey(a)===animalCardKey(requested)))return {ok:false,reason:'duplicate-species'};
        const draft=localHumanTradeDraft(action.playerId);
        draft.requestedPlayerId=requestedPlayerId;
        draft.requestedServerPlayerId=action.payload?.requestedServerPlayerId||
            multiplayerServerPlayerForLocalId(requestedPlayerId)?.playerId||null;
        draft.requestedAnimalId=requestedAnimalId;
        draft.requestedAnimalIdentity=cloneForSave(action.payload?.requestedAnimalIdentity||null);
        cancelAITradingForHumanTrade();
        syncActiveZooIntoLocalMatch();
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('trade-draft-staged',{playerId:action.playerId,requestedPlayerId,requestedAnimalId});
        renderTrade();
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='move-animal'){
        // Layout edits are free actions: validate ownership and destination,
        // but deliberately do not require progression-turn ownership.
        if(localClassicMatch.activePlayerId!==action.playerId){
            const switched=localMultiplayerBrowserTransport?.role==='host'
                ? await loadBrowserAuthoritySeat(action.playerId)
                : await switchLocalClassicMatchPlayer(action.playerId);
            if(!switched)return {ok:false,reason:'seat'};
        }
        const animal=(state.animals||[]).find(a=>String(a.id)===String(action.payload?.animalId));
        const destination=multiplayerDestinationFromWire(action.payload?.destination);
        if(!animal||!destination)return {ok:false,reason:'move-target'};

        // In single-player, putting a card in Your Offer immediately reserves
        // its former slot, and that vacancy can be moved around by rearranging
        // other animals. P2 previously had that state only in its own browser,
        // so the host still saw the offered card physically occupying the slot
        // and rejected otherwise legal relocation as "illegal-placement".
        const outgoingId=action.payload?.outgoingOfferId;
        if(outgoingId!=null){
            const outgoing=(state.animals||[]).find(a=>String(a.id)===String(outgoingId));
            if(!outgoing)return {ok:false,reason:'outgoing-offer'};
            if(!state.outgoingOffer||String(state.outgoingOffer.id)!==String(outgoing.id)){
                state.outgoingOffer=outgoing;
                if(outgoing.enclosureId!=null&&outgoing.slotIndex!=null){
                    reserveAnimalZooSlot(outgoing,outgoing.enclosureId,outgoing.slotIndex);
                    outgoing.enclosureId=null;outgoing.slotIndex=null;
                }
            }
        }

        if(!canPlace(animal,destination.enclosure,destination.slotIndex))return {ok:false,reason:'illegal-placement'};
        const old={enclosureId:animal.enclosureId,slotIndex:animal.slotIndex};
        if(!placeAnimal(animal,destination.enclosure,destination.slotIndex))return {ok:false,reason:'placement'};
        localClassicMatch.revision++;
        syncActiveZooIntoLocalMatch();
        recordLocalMultiplayerEvent('animal-moved',{
            playerId:action.playerId,animalId:animal.id,from:old,
            to:multiplayerDestinationToWire(destination)
        });
        checkEnclosure10Unlock();renderAll();
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='classic-turn-action'){
        if(!localClassicUsesSimultaneousTurns()&&localClassicMatch.turnPlayerId!==action.playerId)return {ok:false,reason:'turn-owner'};
        const requested=action.payload?.action||{};
        if(![CLASSIC_GAME_ACTION.DRAW_LEVEL_1,CLASSIC_GAME_ACTION.COMPLETE_EXCHANGE,CLASSIC_GAME_ACTION.ACCEPT_TRADE].includes(requested.type)){
            return {ok:false,reason:'classic-action'};
        }
        const beforeRevision=localClassicMatch.revision;
        const result=await runAuthoritativeClassicActionForPlayer(action.playerId,{
            type:requested.type,
            destinationWire:requested.destination||null,
            autoPlace:!!requested.autoPlace,
            prepared:requested.prepared||null
        });
        if(!result)return {ok:false,reason:'action-rejected'};
        recordLocalMultiplayerEvent('classic-action-committed',{
            playerId:action.playerId,actionType:requested.type,
            fromRevision:beforeRevision,toRevision:localClassicMatch.revision
        });
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='replace-player-zoo'){
        const player=localClassicMatch.players?.[action.playerId];
        const snapshot=action.payload?.snapshot;
        if(!player?.snapshot||!snapshot?.state)return {ok:false,reason:'player-zoo'};

        const replacement=cloneForSave(snapshot);
        const previousTurn=Number(player.snapshot?.state?.turn)||1;
        replacement.state.turn=Math.max(previousTurn,Number(replacement.state.turn)||1);
        replacement.state.gameMode=localClassicMatch.rules?.gameMode==='true'?'true':'classic';
        replacement.state.sandboxMode=false;
        replacement.state.activeCategories=[
            ...(localClassicMatch.rules?.activeCategories||replacement.state.activeCategories||[])
        ];
        player.snapshot=replacement;
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('player-zoo-reset',{
            playerId:action.playerId,
            turn:replacement.state.turn
        });
        renderVisitedZooQuickTabs();
        scheduleLocalMultiplayerSync('player-zoo-reset');
        return {ok:true,revision:localClassicMatch.revision,turn:replacement.state.turn};
    }
    if(action.type==='register-player-zoo'){
        const player=localClassicMatch.players?.[action.playerId];
        const snapshot=action.payload?.snapshot;
        if(!player||!snapshot?.state)return {ok:false,reason:'player-zoo'};
        if(player.snapshot)return {ok:true,revision:localClassicMatch.revision,turn:Number(player.snapshot.state?.turn)||1,alreadyRegistered:true};
        const registered=cloneForSave(snapshot);
        const hostSnapshot=localClassicMatch.players?.['player-1']?.snapshot;
        const liveHostTurn=(localMultiplayerBrowserTransport?.role==='host' &&
            localClassicMatch.activePlayerId==='player-1' &&
            !localClassicMatch.viewingPlayerId)
            ? Number(state.turn)||1
            : 0;
        // Simultaneous multiplayer has independent per-player action turns.
        // A newly joined zoo therefore starts on its own generated turn instead
        // of inheriting P1's current turn. The server progression row uses the
        // same per-player model (new seats begin at actionTurn 1). Keeping these
        // aligned also means the durable zoo committed just before registration
        // cannot later restore an older turn than the browser-host snapshot.
        const joinTurn=localClassicUsesSimultaneousTurns()
            ? Math.max(1,Number(registered.state.turn)||1)
            : Math.max(
                liveHostTurn,
                Number(hostSnapshot?.state?.turn)||1,
                Number(registered.state.turn)||1
            );
        registered.state.turn=joinTurn;
        registered.state.gameMode=localClassicMatch.rules?.gameMode==='true'?'true':'classic';
        registered.state.sandboxMode=false;
        registered.state.activeCategories=[...(localClassicMatch.rules?.activeCategories||registered.state.activeCategories||[])];
        player.snapshot=registered;
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('player-zoo-registered',{
            playerId:action.playerId,turn:joinTurn
        });
        renderVisitedZooQuickTabs();
        scheduleLocalMultiplayerSync('player-zoo-registered');
        return {ok:true,revision:localClassicMatch.revision,turn:joinTurn};
    }
    if(action.type==='rename-zoo'){
        const player=localClassicMatch.players?.[action.playerId];
        const identity=action.payload?.identity;
        const newName=String(identity?.zooName||'').trim();
        if(!player?.snapshot||!newName)return {ok:false,reason:'rename'};
        const snapState=player.snapshot.state||(player.snapshot.state={});
        for(const key of ['zooName','zooCountry','zooProvince','zooLocation','zooType','manualZooNameOverrideType']){
            if(identity[key]!=null)snapState[key]=String(identity[key]);
        }
        if(localClassicMatch.activePlayerId===action.playerId&&!localClassicMatch.viewingPlayerId){
            for(const key of ['zooName','zooCountry','zooProvince','zooLocation','zooType','manualZooNameOverrideType'])
                state[key]=snapState[key];
        }
        localClassicMatch.revision++;
        recordLocalMultiplayerEvent('zoo-renamed',{playerId:action.playerId,zooName:newName});
        renderVisitedZooQuickTabs();
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='decline-human-trade'){
        const offer=pendingDirectHumanTrades().find(o=>o.id===action.payload?.offerId&&directHumanTradeHasParticipant(o,action.playerId)&&o.toPlayerId===action.playerId&&o.status==='pending');
        if(!offer)return {ok:false,reason:'offer'};
        declineDirectHumanTradeOffer(offer.id,action.playerId);
        recordLocalMultiplayerEvent('trade-declined',{offerId:offer.id,playerId:action.playerId});
        persistHumanTradeBoundary('human-trade-declined');
        return {ok:true,revision:localClassicMatch.revision};
    }
    if(action.type==='cancel-human-trade'){
        const offer=pendingDirectHumanTrades().find(o=>o.id===action.payload?.offerId&&directHumanTradeHasParticipant(o,action.playerId)&&o.fromPlayerId===action.playerId&&o.status==='pending');
        if(!offer)return {ok:false,reason:'offer'};
        offer.status='cancelled';offer.cancelledRevision=++localClassicMatch.revision;
        resumeAITradingAfterHumanTrade();
        recordLocalMultiplayerEvent('trade-cancelled',{offerId:offer.id,playerId:action.playerId});
        renderTrade();renderVisitedZooQuickTabs();
        persistHumanTradeBoundary('human-trade-cancelled');
        return {ok:true,revision:localClassicMatch.revision};
    }
    return {ok:false,reason:'unsupported-action'};
}

function multiplayerTradeDestinationToWireAfterOutgoing(destination,incoming,outgoingId){
    if(!destination?.enclosure||destination.slotIndex==null)return null;
    const slotIndex=Number(destination.slotIndex);
    if(!Number.isInteger(slotIndex)||!getAllSlots(destination.enclosure).includes(slotIndex))return null;
    const wire={enclosureId:destination.enclosure.id,slotIndex};
    const outgoing=(state.animals||[]).find(a=>String(a?.id)===String(outgoingId));
    if(!incoming){wire.clientPlacementValidated=false;return wire;}
    if(!outgoing){
        wire.clientPlacementValidated=canPlace(incoming,destination.enclosure,slotIndex)===true;
        return wire;
    }
    const saved={
        enclosureId:outgoing.enclosureId,slotIndex:outgoing.slotIndex,
        reservedEnclosureId:outgoing.reservedEnclosureId,reservedSlotIndex:outgoing.reservedSlotIndex
    };
    try{
        // Evaluate the exact post-trade board: the outgoing card and any slot
        // reservation belonging to it no longer occupy the zoo.
        outgoing.enclosureId=null;outgoing.slotIndex=null;
        outgoing.reservedEnclosureId=null;outgoing.reservedSlotIndex=null;
        wire.clientPlacementValidated=canPlace(incoming,destination.enclosure,slotIndex)===true;
    }finally{
        outgoing.enclosureId=saved.enclosureId;outgoing.slotIndex=saved.slotIndex;
        outgoing.reservedEnclosureId=saved.reservedEnclosureId;
        outgoing.reservedSlotIndex=saved.reservedSlotIndex;
    }
    return wire;
}

function multiplayerDestinationToWire(destination,animal=null){
    if(!destination?.enclosure||destination.slotIndex==null)return null;
    const slotIndex=Number(destination.slotIndex);
    if(!Number.isInteger(slotIndex)||!getAllSlots(destination.enclosure).includes(slotIndex))return null;
    const wire={enclosureId:destination.enclosure.id,slotIndex};
    // The browser owns the full JSON-backed compatibility graph. Include the
    // result of that exact local rule check so the server can fail closed on
    // placements that were never validated by the game client.
    if(animal)wire.clientPlacementValidated=canPlace(animal,destination.enclosure,slotIndex)===true;
    return wire;
}
function multiplayerDestinationFromWire(payload){
    if(!payload||payload.enclosureId==null||payload.slotIndex==null)return null;
    const enclosure=(state.enclosures||[]).find(e=>String(e.id)===String(payload.enclosureId));
    if(!enclosure)return null;
    const slotIndex=Number(payload.slotIndex);
    if(!Number.isInteger(slotIndex)||!getAllSlots(enclosure).includes(slotIndex))return null;
    return {enclosure,slotIndex};
}
async function loadBrowserAuthoritySeat(playerId){
    if(!localClassicMatch?.players?.[playerId]?.snapshot)return false;
    if(localClassicMatch.activePlayerId===playerId)return true;
    syncActiveZooIntoLocalMatch();
    localClassicMatch.activePlayerId=playerId;
    autoResumeWriteSuppressed=true;
    try{
        await importGameState(cloneForSave(localClassicMatch.players[playerId].snapshot),{deferRender:true});
        return true;
    }finally{autoResumeWriteSuppressed=false;}
}

async function restoreBrowserHostSeatAfterRemoteAction(previousPlayerId){
    if(!localClassicMatch||localMultiplayerBrowserTransport?.role!=='host')return false;
    if(!previousPlayerId||localClassicMatch.activePlayerId===previousPlayerId)return true;
    // First preserve the remote seat exactly as authority just mutated it.
    syncActiveZooIntoLocalMatch();
    const target=localClassicMatch.players?.[previousPlayerId];
    if(!target?.snapshot)return false;
    localClassicMatch.activePlayerId=previousPlayerId;
    autoResumeWriteSuppressed=true;
    try{
        await importGameState(cloneForSave(target.snapshot),{deferRender:false});
        createZooNameEditor();
        renderVisitedZooQuickTabs();renderTrade();
        renderExchange();refreshDrawAvailabilityState();
        const camera=localMultiplayerBrowserTransport?.hostAuthorityCamera;
        if(camera&&zooBoard){
            state.zoom=Number(camera.zoom)||1;
            document.documentElement.style.setProperty('--zoo-zoom',state.zoom);
            await new Promise(resolve=>requestAnimationFrame(resolve));
            const maxLeft=Math.max(0,zooBoard.scrollWidth-zooBoard.clientWidth);
            const maxTop=Math.max(0,zooBoard.scrollHeight-zooBoard.clientHeight);
            zooBoard.scrollLeft=Math.max(0,Math.min(maxLeft,Number(camera.scrollLeft)||0));
            zooBoard.scrollTop=Math.max(0,Math.min(maxTop,Number(camera.scrollTop)||0));
        }
        if(localMultiplayerBrowserTransport)delete localMultiplayerBrowserTransport.hostAuthorityCamera;
        return true;
    }finally{autoResumeWriteSuppressed=false;}
}

function applyAuthoritativePreparedClassicState(requested){
    const prepared=requested?.prepared;
    if(!prepared||typeof prepared!=='object')return true;

    if(requested.type===CLASSIC_GAME_ACTION.COMPLETE_EXCHANGE){
        const ids=Array.isArray(prepared.exchangeAnimalIds)?prepared.exchangeAnimalIds:[];
        if(ids.length!==2)return false;
        const selected=ids.map(id=>(state.animals||[]).find(a=>String(a.id)===String(id)));
        if(selected.some(a=>!a))return false;
        if(selected[0].category!==selected[1].category||selected[0].level!==selected[1].level)return false;
        const result=prepared.exchangeResult;
        if(!result||
           result.category!==selected[0].category||
           Number(result.level)!==Number(selected[0].level)+1)return false;
        const allowed=availableNextLevelFiles(selected[0].category,selected[0].level)
            .map(cleanFilename);
        if(!allowed.includes(cleanFilename(result.filename)))return false;
        state.exchange=selected;
        for(const animal of selected){
            if(animal.enclosureId!=null&&animal.slotIndex!=null){
                reserveAnimalZooSlot(animal,animal.enclosureId,animal.slotIndex);
                animal.enclosureId=null;animal.slotIndex=null;
            }
        }
        state.result={
            category:result.category,level:Number(result.level),
            filename:cleanFilename(result.filename)
        };
        state.result.readyPromise=preloadAnimalAsset(state.result);
    }

    if(requested.type===CLASSIC_GAME_ACTION.ACCEPT_TRADE){
        if(prepared.outgoingOfferId==null)return false;
        const outgoing=(state.animals||[]).find(a=>String(a.id)===String(prepared.outgoingOfferId));
        if(!outgoing)return false;
        state.outgoingOffer=outgoing;
        state.selectedTradeOpponent=prepared.selectedTradeOpponent??state.selectedTradeOpponent;

        // The remote browser may have generated/selected an AI offer after the
        // last authoritative snapshot. Reconstruct the exact incoming card the
        // player actually accepted instead of assuming the host independently
        // has the same selectedTradeOffer().
        const wireIncoming=prepared.aiIncoming;
        if(wireIncoming){
            const opponentIndex=Number(wireIncoming.opponentIndex);
            const candidate={
                id:wireIncoming.id??null,
                category:wireIncoming.category,
                level:Number(wireIncoming.level),
                filename:cleanFilename(wireIncoming.filename),
                enclosureId:null,slotIndex:null
            };
            const validProfile=state.opponentProfiles?.[opponentIndex];
            if(!validProfile)return false;
            const stock=state.opponentTradeStocks?.[opponentIndex]||[];
            const stockMatch=stock.find(a=>
                animalCardKey(a)===animalCardKey(candidate) ||
                (candidate.id!=null&&String(a.id)===String(candidate.id))
            );
            if(!stockMatch)return false;
            const incoming=stockMatch;
            if(prepared.autonomousAI){
                if(!state.autonomousTradeOffer ||
                   state.autonomousTradeOffer.opponentIndex!==opponentIndex ||
                   animalCardKey(state.autonomousTradeOffer.animal)!==animalCardKey(incoming)){
                    state.autonomousTradeOffer={
                        opponentIndex,animal:incoming,
                        expiresTurn:Math.max(state.turn+1,Number(state.autonomousTradeOffer?.expiresTurn)||state.turn+1)
                    };
                }
                state.selectedTradeOpponent=opponentIndex;
            }else{
                state.tradeOffers=[{opponentIndex,animal:incoming}];
                state.selectedTradeOpponent=opponentIndex;
            }
        }
        // Recreate the local "card moved into Your Offer" state on authority.
        // Merely assigning outgoingOffer left the same animal visibly in its
        // enclosure, so accepting an AI offer temporarily rendered a duplicate.
        if(outgoing.enclosureId!=null&&outgoing.slotIndex!=null){
            reserveAnimalZooSlot(outgoing,outgoing.enclosureId,outgoing.slotIndex);
            outgoing.enclosureId=null;outgoing.slotIndex=null;
        }
    }
    return true;
}

async function runAuthoritativeClassicActionForPlayer(playerId,classicAction){
    if(!localClassicMatch?.players?.[playerId])return false;
    if(!localClassicUsesSimultaneousTurns()&&localClassicMatch.turnPlayerId!==playerId)return false;

    const hostSeat=localMultiplayerBrowserTransport?.role==='host'
        ? localMultiplayerBrowserTransport.playerId
        : null;
    if(hostSeat && localClassicMatch.activePlayerId===hostSeat && zooBoard){
        localMultiplayerBrowserTransport.hostAuthorityCamera={
            scrollLeft:zooBoard.scrollLeft||0,
            scrollTop:zooBoard.scrollTop||0,
            zoom:Number(state.zoom)||1
        };
    }
    if(localClassicMatch.activePlayerId!==playerId){
        const switched=hostSeat
            ? await loadBrowserAuthoritySeat(playerId)
            : await switchLocalClassicMatchPlayer(playerId);
        if(!switched)return false;
    }
    const action={...classicAction};
    const preparedRollback = action.type===CLASSIC_GAME_ACTION.ACCEPT_TRADE ? {
        outgoingOffer:state.outgoingOffer,
        selectedTradeOpponent:state.selectedTradeOpponent,
        tradeOffers:cloneForSave(state.tradeOffers||[]),
        autonomousTradeOffer:cloneForSave(state.autonomousTradeOffer),
        animals:(state.animals||[]).map(a=>({
            id:a.id,enclosureId:a.enclosureId,slotIndex:a.slotIndex,
            reservedEnclosureId:a.reservedEnclosureId,reservedSlotIndex:a.reservedSlotIndex
        }))
    } : null;
    if(!applyAuthoritativePreparedClassicState(action)){
        if(hostSeat)await restoreBrowserHostSeatAfterRemoteAction(hostSeat);
        return false;
    }
    if(action.type===CLASSIC_GAME_ACTION.ACCEPT_TRADE&&action.prepared?.frozenAITradeOffer){
        action.frozenAITradeOffer=cloneForSave(action.prepared.frozenAITradeOffer);
        action.frozenAIAutonomous=Boolean(action.prepared.autonomousAI);
    }
    delete action.prepared;
    if(action.destinationWire){
        action.destination=multiplayerDestinationFromWire(action.destinationWire);
        delete action.destinationWire;
        if(!action.destination){
            if(hostSeat)await restoreBrowserHostSeatAfterRemoteAction(hostSeat);
            return false;
        }
    }
    performClassicGameAction.authorityExecuting=true;
    try{
        const result=await performClassicGameAction(action);
        if(!result&&preparedRollback){
            state.outgoingOffer=preparedRollback.outgoingOffer;
            state.selectedTradeOpponent=preparedRollback.selectedTradeOpponent;
            state.tradeOffers=preparedRollback.tradeOffers;
            state.autonomousTradeOffer=preparedRollback.autonomousTradeOffer;
            const positions=new Map(preparedRollback.animals.map(p=>[String(p.id),p]));
            for(const animal of state.animals||[]){
                const p=positions.get(String(animal.id));if(!p)continue;
                animal.enclosureId=p.enclosureId;animal.slotIndex=p.slotIndex;
                if(p.reservedEnclosureId==null)delete animal.reservedEnclosureId;else animal.reservedEnclosureId=p.reservedEnclosureId;
                if(p.reservedSlotIndex==null)delete animal.reservedSlotIndex;else animal.reservedSlotIndex=p.reservedSlotIndex;
            }
            clearOrphanedZooSlotReservations();
            renderAll();
            refreshDrawAvailabilityState();
        }
        // commitClassicTurn() has already changed the authoritative turn owner.
        // Save the remote zoo, then put the host UI back on its own seat without
        // altering turnPlayerId. Previously the host stayed on Player 2 after
        // executing Player 2's network action, making both tabs appear to be
        // waiting for "the other" player.
        if(hostSeat)await restoreBrowserHostSeatAfterRemoteAction(hostSeat);
        return result;
    }finally{
        performClassicGameAction.authorityExecuting=false;
        if(hostSeat&&localClassicMatch?.activePlayerId!==hostSeat){
            await restoreBrowserHostSeatAfterRemoteAction(hostSeat);
        }
    }
}

async function dispatchLocalMultiplayerAction(playerId,type,payload={}){
    if(SERVER_HUMAN_TRADE_ACTIONS.has(type)&&serverAuthoritativeMultiplayerActive()){
        // A human-trade transaction must start from the latest durable zoo
        // revision. Otherwise a just-moved/listed card can still be sitting in
        // a queued ordinary zoo commit while the trade reaches SQLite first.
        // Serialize that boundary rather than letting the later stale-CAS
        // correction fight an already accepted ownership transfer.
        const durableReady=await awaitDurableZooCommitIdle(5000);
        if(!durableReady){
            // Do not deadlock a server-authoritative human trade behind a stale
            // browser zoo-commit flag. This was reproducible on P2: the trade
            // placement itself was valid, but a previous durable commit never
            // reached the local idle state and the client rejected the drop
            // before the server was even allowed to validate it.
            //
            // The server is the authority for ownership, listing validity and
            // destination placement. Let it make the decision. If a pending
            // pre-trade snapshot later arrives, its old CAS revision is rejected
            // and the authoritative trade zoo wins.
            console.warn('Human trade proceeding with server validation after durable zoo sync timeout.');
        }
        const authorized=await authorizeHumanTradeWithServer(type,payload);
        if(!authorized.ok){
            if((type==='accept-human-trade'||type==='claim-human-trade')&&
               (authorized.reason==='TRADE_NOT_PENDING'||authorized.reason==='TRADE_NOT_AWAITING_CLAIM')){
                multiplayerDiagnostic('human-trade-duplicate-action-rejected',{
                    type,offerId:payload.offerId,reason:authorized.reason
                });
            }
            return authorized;
        }
        // The websocket event handler normally applies this same authoritative
        // packet, but the action promise can resolve before that handler's
        // queued zoo import/render finishes. Apply the transaction to the local
        // trade ledger now as an idempotent operation so accept/claim UI cannot
        // remain one state behind until another server message arrives.
        applyAuthoritativeHumanTradeMessage(authorized.response);
        // Server + SQLite are the authority. Do not replay the same trade
        // through the browser-host action envelope.
        return {
            ok:true,
            authoritative:true,
            revision:Number(authorized.response?.revision)||0,
            trade:cloneForSave(authorized.response?.trade||null)
        };
    }
    if(localMultiplayerBrowserTransport?.role==='peer' &&
       localMultiplayerBrowserTransport.playerId===playerId){
        return sendLocalMultiplayerBrowserAction(type,payload);
    }
    const envelope=createLocalMultiplayerActionEnvelope(playerId,type,payload);
    return applyLocalMultiplayerActionEnvelope(cloneForSave(envelope));
}
async function simulateLocalPeerAction(type,payload={}){
    const playerId=localMultiplayerPeerReplica?.playerId;
    if(!playerId)return {ok:false,reason:'no-peer'};
    return applyLocalMultiplayerActionEnvelope(cloneForSave(createLocalMultiplayerActionEnvelope(playerId,type,payload)));
}
async function sendLocalMultiplayerAnimalMove(playerId,animalId,destination){
    if(serverAuthoritativeMultiplayerActive()&&
       playerId===localClassicMatch?.activePlayerId){
        const movingAnimal=(state.animals||[]).find(a=>String(a?.id)===String(animalId));
        const wireDestination=multiplayerDestinationToWire(destination,movingAnimal);
        const t=localMultiplayerBrowserTransport;

        // Layout edits (especially enclosure moves) are persisted through the
        // debounced whole-zoo CAS stream. Do not let a server-authoritative
        // animal move overtake one of those commits: the destination enclosure
        // may not exist at its new position on the server yet, and the action
        // itself advances the durable revision. That race previously produced
        // a stale-commit rejection/correction immediately after an otherwise
        // valid drag, disproportionately affecting P2.
        if(!await awaitDurableZooCommitIdle()){
            console.warn('Multiplayer animal move paused because the durable zoo is still synchronising.');
            if(t?.durableOwnZooSnapshot?.state){
                autoResumeWriteSuppressed=true;
                try{await importGameState(cloneForSave(t.durableOwnZooSnapshot),{deferRender:false});}
                finally{autoResumeWriteSuppressed=false;}
                syncActiveZooIntoLocalMatch();
            }else renderAll();
            return {ok:false,reason:'zoo-sync'};
        }

        const response=await sendMultiplayerServerAction('move-animal',{
            animalId,destination:wireDestination
        });
        if(response?.type!=='action-committed'||response?.action!=='move-animal'){
            if(response?.code)console.warn('Multiplayer animal move rejected:',response.code);
            // The card was left optimistically at the drop target. A rejection
            // must restore the last server-authoritative zoo, not merely render
            // the optimistic local state again.
            if(t?.durableOwnZooSnapshot?.state){
                autoResumeWriteSuppressed=true;
                try{await importGameState(cloneForSave(t.durableOwnZooSnapshot),{deferRender:false});}
                finally{autoResumeWriteSuppressed=false;}
                syncActiveZooIntoLocalMatch();
            }else renderAll();
            return {ok:false,reason:response?.code||'move-rejected'};
        }
        if(String(response.playerId||'')!==String(t?.serverPlayerId||'')||
           !response.zoo?.state)return {ok:false,reason:'move-response'};

        noteAuthoritativeOwnZooRevision(response.zooRevision);
        t.durableOwnZooSnapshot=cloneForSave(response.zoo);
        t.durableZooQueuedSnapshot=null;t.durableZooQueuedSignature='';

        // The player already sees the valid optimistic drop. Do not tear down
        // and rebuild the whole zoo after every ordinary relocation. Reconcile
        // only the authoritative destination and stored seat snapshot.
        const live=(state.animals||[]).find(a=>String(a?.id)===String(animalId));
        if(live&&response.destination){
            live.enclosureId=response.destination.enclosureId;
            live.slotIndex=Number(response.destination.slotIndex);
        }
        if(localClassicMatch?.players?.[playerId])
            localClassicMatch.players[playerId].snapshot=cloneForSave(response.zoo);
        renderVisitedZooQuickTabs();
        return {ok:true,authoritative:true,revision:t.durableZooRevision};
    }
    return dispatchLocalMultiplayerAction(playerId,'move-animal',{
        animalId,
        destination:multiplayerDestinationToWire(destination),
        outgoingOfferId:state.outgoingOffer?.id??null
    });
}

function localHumanTradeDraft(playerId=localClassicMatch?.activePlayerId){
    if(!localClassicMatch||!playerId)return null;
    if(!localClassicMatch.tradeDrafts||typeof localClassicMatch.tradeDrafts!=='object')localClassicMatch.tradeDrafts={};
    if(!localClassicMatch.tradeDrafts[playerId])localClassicMatch.tradeDrafts[playerId]={requestedAnimalId:null,requestedPlayerId:null};
    return localClassicMatch.tradeDrafts[playerId];
}
function clearLocalHumanTradeDraft(playerId=localClassicMatch?.activePlayerId){
    if(localClassicMatch?.tradeDrafts&&playerId)delete localClassicMatch.tradeDrafts[playerId];
}
function viewingOtherHumanPlayerZoo(){
    return !!(localClassicMatch?.viewingPlayerId &&
        localClassicMatch.viewingPlayerId!==localClassicMatch.activePlayerId);
}

function invalidateMultiplayerViewedZooAreaCaches(){
    stableConnectedAreaGroups=null;
    stableConnectedAreaGroupsSignature='';
    renderedConnectedAreaGroups=null;
    renderedConnectedAreaGroupsSignature='';
    generatedModernGeographicAreas=[];
    invalidateConnectedAreaReconciliation();
}
function captureMultiplayerPlayerView(playerId){
    if(!localClassicMatch||!playerId||!zooBoard)return;
    if(!localClassicMatch.playerViewState||typeof localClassicMatch.playerViewState!=='object')
        localClassicMatch.playerViewState={};
    localClassicMatch.playerViewState[playerId]={
        zoom:Number(state.zoom)||1,
        left:Number(zooBoard.scrollLeft)||0,
        top:Number(zooBoard.scrollTop)||0
    };
}
function restoreMultiplayerPlayerView(playerId,{fallbackToFit=true}={}){
    const view=localClassicMatch?.playerViewState?.[playerId];
    if(!view){
        if(fallbackToFit)centerInitialView();
        return;
    }
    state.zoom=Math.max(currentZoomMin(),Math.min(ZOOM_MAX,Number(view.zoom)||1));
    document.documentElement.style.setProperty('--zoo-zoom',state.zoom);
    requestAnimationFrame(()=>{
        if(!zooBoard)return;
        const maxLeft=Math.max(0,zooBoard.scrollWidth-zooBoard.clientWidth);
        const maxTop=Math.max(0,zooBoard.scrollHeight-zooBoard.clientHeight);
        zooBoard.scrollLeft=Math.max(0,Math.min(maxLeft,Number(view.left)||0));
        zooBoard.scrollTop=Math.max(0,Math.min(maxTop,Number(view.top)||0));
    });
}

async function visitLocalClassicMatchPlayer(playerId){
    if(!localClassicMatch?.players?.[playerId]?.snapshot)return false;
    const ownerId=localClassicMatch.activePlayerId;
    if(playerId===ownerId){
        if(state.visitingZoo)await returnFromZooVisit();
        return returnToActiveLocalClassicZoo();
    }
    // AI/real-zoo visits use a separate visitPlayerSnapshot. If we switch
    // directly from one of those views to another human zoo, state still holds
    // the AI zoo. Syncing that state into the multiplayer owner slot corrupts
    // the owner's snapshot and makes Return load the AI zoo. Restore the real
    // player zoo before entering the human-player visit layer.
    if(state.visitingZoo)await returnFromZooVisit();
    const wasViewingHuman=!!localClassicMatch.viewingPlayerId;
    const currentlyRenderedPlayerId=localClassicMatch.viewingPlayerId||ownerId;
    captureMultiplayerPlayerView(currentlyRenderedPlayerId);
    if(!wasViewingHuman)syncActiveZooIntoLocalMatch();
    const target=localClassicMatch.players[playerId];
    // Capture the owner's private AI-trade state only when leaving their own
    // zoo. Switching directly P2 -> P3 must not replace it with P2's state.
    if(!wasViewingHuman&&!localClassicMatch.privateVisitState){
        localClassicMatch.privateVisitState={
            autonomousTradeOffer:cloneForSave(state.autonomousTradeOffer||null),
            tradeOffers:cloneForSave(state.tradeOffers||[]),
            selectedTradeOpponent:state.selectedTradeOpponent,
            outgoingOffer:cloneForSave(state.outgoingOffer||null),
            nextAutonomousOfferTurn:state.nextAutonomousOfferTurn
        };
    }
    localClassicMatch.viewingPlayerId=playerId;
    sendMultiplayerLiveViewSubscription();
    clearMultiplayerRemoteCursors();
    clearCompatibilityHoverImmediately();
    clearTradeEligibleGlow();
    removeActionHintOverlay();
    clearYellowExchangeHintOverlays();
    setExchangeEligibilityHover(false);
    autoResumeWriteSuppressed=true;
    try{
        const visitSnapshot=cloneForSave(target.snapshot);
        if(visitSnapshot?.view)delete visitSnapshot.view;
        await importGameState(visitSnapshot,{deferRender:false});
        invalidateMultiplayerViewedZooAreaCaches();
        renderAll(false);
        restoreMultiplayerPlayerView(playerId);
        createZooNameEditor();
        renderVisitedZooQuickTabs();renderTrade();
        renderExchange();refreshDrawAvailabilityState();
        showHumanZooVisitReturnButton();
        return true;
    }finally{autoResumeWriteSuppressed=false;}
}
async function returnToActiveLocalClassicZoo(){
    if(!localClassicMatch)return false;
    const ownerId=localClassicMatch.activePlayerId;
    const target=localClassicMatch.players?.[ownerId];
    if(!target?.snapshot)return false;
    if(localClassicMatch.viewingPlayerId)
        captureMultiplayerPlayerView(localClassicMatch.viewingPlayerId);
    localClassicMatch.viewingPlayerId=null;
    sendMultiplayerLiveViewSubscription();
    clearMultiplayerRemoteCursors();
    autoResumeWriteSuppressed=true;
    try{
        await importGameState(cloneForSave(target.snapshot),{deferRender:false});
        const privateVisitState=localClassicMatch.privateVisitState;
        if(privateVisitState){
            if(!humanTradeBlocksAITrading()){
                state.autonomousTradeOffer=cloneForSave(privateVisitState.autonomousTradeOffer);
                state.tradeOffers=cloneForSave(privateVisitState.tradeOffers||[]);
                state.selectedTradeOpponent=privateVisitState.selectedTradeOpponent;
                state.outgoingOffer=cloneForSave(privateVisitState.outgoingOffer);
                state.nextAutonomousOfferTurn=privateVisitState.nextAutonomousOfferTurn;
            }else{
                cancelAITradingForHumanTrade();
            }
            delete localClassicMatch.privateVisitState;
        }
        invalidateMultiplayerViewedZooAreaCaches();
        renderAll(false);
        restoreMultiplayerPlayerView(ownerId);
        createZooNameEditor();
        renderVisitedZooQuickTabs();renderTrade();
        hideZooVisitReturnButton();
        return true;
    }finally{autoResumeWriteSuppressed=false;}
}

async function switchLocalClassicMatchPlayer(playerId, { deferRender = false } = {}) {
    if (!localClassicMatch || !localClassicMatch.players?.[playerId]) return false;
    if (playerId === localClassicMatch.activePlayerId) {
        renderVisitedZooQuickTabs();
        return true;
    }

    if(localClassicMatch.viewingPlayerId)await returnToActiveLocalClassicZoo();
    syncActiveZooIntoLocalMatch();
    const previousPlayerId = localClassicMatch.activePlayerId;
    const target = localClassicMatch.players[playerId];
    if (!target.snapshot) return false;

    // Mark the target active before import. importGameState() renders, and
    // rendering can refresh/synchronise multiplayer UI. Keeping the old player
    // active until after import allowed the target zoo to overwrite its snapshot.
    localClassicMatch.activePlayerId = playerId;
    autoResumeWriteSuppressed = true;
    try {
        await importGameState(cloneForSave(target.snapshot), { deferRender });
        localClassicMatch.revision++;
        if (!deferRender) {
            // Camera/pan is UI state rather than part of a player's zoo snapshot.
            // Re-centre after visiting the other human zoo so a correctly
            // generated zoo cannot appear as an empty board off-screen.
            centerInitialView();
        }
        renderVisitedZooQuickTabs();
        return true;
    } catch (error) {
        localClassicMatch.activePlayerId = previousPlayerId;
        throw error;
    } finally {
        autoResumeWriteSuppressed = false;
    }
}

function destroyLocalClassicMatchContainer() {
    if (!localClassicMatch) return false;
    syncActiveZooIntoLocalMatch();
    closeLocalMultiplayerBrowserTransport();
    disableLocalMultiplayerPeerSimulation();

    // Multiplayer trade state is session UI, never part of the single-player
    // zoo. Clear it at the same boundary that destroys the match so stale
    // public listings/proposals cannot survive into a newly generated solo zoo.
    multiplayerPublicTradeListings=[];
    selectedMultiplayerPublicListingPlayerId=null;
    selectedHumanTradeProposalId=null;
    multiplayerTradeListingPublishGeneration=0;
    pendingHumanTradeActionIds.clear?.();
    clearDirectHumanTradeActions?.();
    state.autonomousTradeOffer=null;
    state.tradeOffers=[];
    state.selectedTradeOpponent=null;
    state.outgoingOffer=null;
    document.getElementById('tradeCapacityBlockNotice')?.remove();

    localClassicMatch = null;
    pendingMultiplayerZooReset=false;
    hideZooVisitReturnButton();
    pendingMultiplayerSetup={
        gameMode:'classic',
        turnMode:'simultaneous',
        activeCategories:[...state.activeCategories]
    };
    renderVisitedZooQuickTabs();
    renderTrade?.();
    updateMultiplayerHeaderButtonState();
    return true;
}

// V2.22.78 — first playable local two-player prototype helpers. These are
// intentionally development-facing for one more validation pass; no public
// New Zoo menu option is exposed yet.
function getLocalClassicMatchSummary() {
    if (!localClassicMatch) return null;
    syncActiveZooIntoLocalMatch();
    return {
        mode: localClassicMatch.mode,
        activePlayerId: localClassicMatch.activePlayerId,
        turnPlayerId: localClassicMatch.turnPlayerId,
        playerIds: [...localClassicMatch.playerIds],
        revision: localClassicMatch.revision,
        peerSync: getLocalMultiplayerPeerSummary(),
        browserTransport: getLocalMultiplayerBrowserTransportSummary(),
        players: Object.fromEntries(localClassicMatch.playerIds.map(id => [id, {
            seeded: !!localClassicMatch.players?.[id]?.snapshot,
            zooName: localClassicMatch.players?.[id]?.snapshot?.state?.zooName || null,
            turn: localClassicMatch.players?.[id]?.snapshot?.state?.turn ?? null
        }]))
    };
}

async function startConfiguredLocalTwoPlayerClassicMatch({
    playerOneSnapshot = null,
    country = '',
    startingSize = 20,
    gameMode = 'classic',
    activeCategories = null
} = {}) {
    if (!playerOneSnapshot) playerOneSnapshot = exportCurrentGameState();
    const requestedCategories=Object.keys(FOLDERS).filter(category=>
        (activeCategories||Object.keys(FOLDERS)).includes(category)
    );
    if(!requestedCategories.length)requestedCategories.push(...Object.keys(FOLDERS));

    // Hosting starts from the zoo already on screen. Player 2 is deliberately
    // only a vacant seat: their zoo is created on their own client after join.
    localClassicMatch=null;
    renderVisitedZooQuickTabs();
    const multiplayerGameMode=gameMode==='true'?'true':'classic';
    createLocalClassicMatchContainer();
    localClassicMatch.players['player-1'].snapshot=cloneForSave(playerOneSnapshot);
    localClassicMatch.activePlayerId='player-1';
    localClassicMatch.turnPlayerId='player-1';
    localClassicMatch.revision=0;
    localClassicMatch.rules={
        gameMode:multiplayerGameMode,
        turnMode:pendingMultiplayerSetup?.turnMode==='simultaneous'?'simultaneous':'alternating',
        activeCategories:[...requestedCategories]
    };
    pendingMultiplayerSetup=cloneForSave(localClassicMatch.rules);
    applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
    syncActiveZooIntoLocalMatch();
    renderVisitedZooQuickTabs();
    writeAutoResumeSnapshot(true);
    return getLocalClassicMatchSummary();
}

async function startLocalTwoPlayerClassicPrototype() {
    // Start from the currently open Classic zoo. Player 2 receives an independent
    // snapshot, proving isolation without changing the public New Zoo workflow.
    // The next UI pass will create/configure both zoos through the multiplayer menu.
    if (state.sandboxMode || state.gameMode === 'true') {
        console.warn('Local two-player prototype currently requires a Classic zoo.');
        return false;
    }
    if (localClassicMatch) destroyLocalClassicMatchContainer();
    createLocalClassicMatchContainer();
    seedLocalClassicMatchPlayer('player-2', exportCurrentGameState());
    localClassicMatch.activePlayerId = 'player-1';
    localClassicMatch.turnPlayerId = 'player-1';
    localClassicMatch.revision = 0;
    enableLocalMultiplayerPeerSimulation('player-2');
    renderVisitedZooQuickTabs();
    return getLocalClassicMatchSummary();
}

function clearAutoResumeSnapshot() {
    try {
        localStorage.removeItem(AUTO_RESUME_STORAGE_KEY);
    } catch (error) {
        console.warn('Could not clear automatic resume snapshot:', error);
    }
    lastAutoResumeTurn = null;
}

function multiplayerOwnedGameStateForResume() {
    // A human-zoo visit temporarily imports the OTHER player's zoo into the
    // global `state` object. Auto-resume must never persist that presentation
    // state as this browser's owned zoo, otherwise refreshing while spectating
    // can make the peer reconnect as a copy of the zoo they were viewing.
    if (localClassicMatch?.viewingPlayerId &&
        localClassicMatch.viewingPlayerId !== localClassicMatch.activePlayerId) {
        const owned = localClassicMatch.players?.[localClassicMatch.activePlayerId]?.snapshot;
        if (owned?.state) return compactPortableGameSnapshot(owned);
    }
    return exportCurrentGameState({ compactHistory:true });
}

function compactLocalMatchForPersistence(match) {
    if(!match)return null;
    const copy=cloneForSave(match);
    for(const player of Object.values(copy.players||{})){
        if(player?.snapshot?.state)player.snapshot=compactPortableGameSnapshot(player.snapshot);
    }
    return copy;
}

function writeAutoResumeSnapshot(force = false) {
    if (
        !state.loaded ||
        autoResumeWriteSuppressed ||
        state.suppressHistoryCapture ||
        state.historyViewTurn !== null
    ) return false;

    const resumeGame = multiplayerOwnedGameStateForResume();
    const resumeTurn = Number(resumeGame?.state?.turn);
    const turn = Number.isFinite(resumeTurn) ? resumeTurn : (Number(state.turn) || 0);
    if (!force && lastAutoResumeTurn === turn) return false;

    try {
        const record = {
            formatVersion: AUTO_RESUME_FORMAT_VERSION,
            gameVersion: ZOO_CURATOR_VERSION,
            savedAt: new Date().toISOString(),
            turn,
            zooName: resumeGame?.state?.zooName || state.zooName,
            game: serialiseSpecial(resumeGame),
            // Multiplayer lives above ordinary zoo state, so persist the
            // complete match container separately. Without this, refresh
            // restored only whichever zoo happened to be open.
            localClassicMatch: localClassicMatch
                ? serialiseSpecial(compactLocalMatchForPersistence(getLocalClassicMatchSnapshot()))
                : null
        };

        localStorage.setItem(
            AUTO_RESUME_STORAGE_KEY,
            JSON.stringify(record)
        );
        lastAutoResumeTurn = turn;
        return true;
    } catch (error) {
        // Automatic resume must never interrupt gameplay if storage is
        // unavailable/full/private-mode restricted.
        console.warn('Could not update automatic resume snapshot:', error);
        return false;
    }
}

function persistCurrentCameraForReload() {
    // The reconnect breadcrumb is session state, not camera state. Persist it
    // even while visiting another zoo or viewing history; the old early return
    // could otherwise make a perfectly valid P2 session look abandoned on
    // reload from a visited zoo.
    if(localMultiplayerBrowserTransport&&localClassicMatch){
        const transport=localMultiplayerBrowserTransport;
        if(transport.role==='host'&&!state.visitingZoo&&state.historyViewTurn===null)
            syncActiveZooIntoLocalMatch();
        if(transport.matchId&&(transport.role==='host'||transport.role==='peer'))
            writeActiveMultiplayerSession(transport.matchId,transport.role);
    }

    // Camera movement is deliberately not a game turn. Only persist the current
    // camera when it belongs to the owned live zoo. Multiplayer auto-resume
    // snapshots written elsewhere already use multiplayerOwnedGameStateForResume
    // and therefore cannot turn a visited zoo into the player's own zoo.
    if (!state.loaded || state.visitingZoo || state.historyViewTurn !== null) return;
    writeAutoResumeSnapshot(true);
}

window.addEventListener('pagehide', persistCurrentCameraForReload);
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') persistCurrentCameraForReload();
});

function readAutoResumeSnapshot() {
    try {
        const raw = localStorage.getItem(AUTO_RESUME_STORAGE_KEY);
        if (!raw) return null;

        const record = JSON.parse(raw);
        if (!record || !record.game) return null;

        return {
            ...record,
            game: deserialiseSpecial(record.game),
            localClassicMatch: record.localClassicMatch
                ? deserialiseSpecial(record.localClassicMatch)
                : null
        };
    } catch (error) {
        console.warn('Automatic resume snapshot is invalid:', error);
        clearAutoResumeSnapshot();
        return null;
    }
}

function zooNameNeedsRepair(value) {
    if (typeof value !== 'string') return true;
    const name = value.trim();
    if (!name) return true;

    const placeholder = name.toLowerCase().replace(/\s+/g, ' ');
    return (
        placeholder === 'loading zoo...' ||
        placeholder === 'loading zoo…' ||
        placeholder === 'loading zoo' ||
        placeholder === 'loading...'
    );
}

function repairLoadedZooName() {
    if (!zooNameNeedsRepair(state.zooName)) return false;

    const pool = buildZooNamePool(state.zooNamesData);
    state.zooName = pool.length
        ? randomItem(pool)
        : randomItem([
            'Riverside Zoo',
            'Forest Wildlife Park',
            'Lakeside Zoo',
            'Highland Wildlife Park',
            'Meadowlands Zoo',
            'Coastal Animal Park'
        ]);

    return true;
}

function restoreAutoResumeSnapshot() {
    const record = readAutoResumeSnapshot();
    if (!record) return false;

    try {
        autoResumeWriteSuppressed = true;
        importGameState(record.game, { deferRender: true });

        if(['classic-multiplayer','classic-two-player'].includes(record.localClassicMatch?.mode)){
            localClassicMatch=cloneForSave(record.localClassicMatch);
            localClassicMatch.mode='classic-multiplayer';
            if(!Array.isArray(localClassicMatch.playerIds)||localClassicMatch.playerIds.length<1){
                throw new Error('Saved multiplayer match has invalid player seats.');
            }
            localClassicMatch.viewingPlayerId=null;
            localClassicMatch.events=Array.isArray(localClassicMatch.events)?localClassicMatch.events:[];
            localClassicMatch.tradeDrafts=localClassicMatch.tradeDrafts||{};
            localClassicMatch.pendingPlayerTrades=Array.isArray(localClassicMatch.pendingPlayerTrades)?localClassicMatch.pendingPlayerTrades:[];
            localClassicMatch.nextEventSequence=Number(localClassicMatch.nextEventSequence)||1;
            for(const [playerId,player] of Object.entries(localClassicMatch.players||{})){
                if(!player)continue;
                if(typeof player.connected!=='boolean')player.connected=playerId==='player-1';
                if(!player.reconnectToken&&playerId!=='player-1')
                    player.reconnectToken=createLocalMultiplayerReconnectToken();
            }
            if(localClassicMatch.players?.['player-1'])
                localClassicMatch.players['player-1'].connected=true;
            if(!localClassicMatch.rules){
                localClassicMatch.rules={
                    gameMode:state.gameMode==='true'?'true':'classic',
                    turnMode:'alternating',
                    activeCategories:[...state.activeCategories]
                };
            }
            if(localClassicMatch.rules?.activeCategories){
                const restoredCategories=Object.keys(FOLDERS).filter(category=>
                    localClassicMatch.rules.activeCategories.includes(category)
                );
                localClassicMatch.rules.activeCategories=restoredCategories.length
                    ? restoredCategories
                    : Object.keys(FOLDERS);
                localClassicMatch.rules.gameMode=
                    localClassicMatch.rules.gameMode==='true'?'true':'classic';
                localClassicMatch.rules.turnMode=
                    localClassicMatch.rules.turnMode==='simultaneous'?'simultaneous':'alternating';
                pendingMultiplayerSetup=cloneForSave(localClassicMatch.rules);
                applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
            }

            // The auto-resume `game` field in older builds could contain the
            // remote human zoo that happened to be on screen at refresh time.
            // The match container already knows which seat this browser owns;
            // make that seat authoritative before any call can synchronise the
            // global state back into the match. This also repairs those older
            // contaminated resume records on their next successful reconnect.
            const resumeOwner=localClassicMatch.players?.[localClassicMatch.activePlayerId]?.snapshot;
            if(resumeOwner?.state){
                importGameState(cloneForSave(resumeOwner),{deferRender:true});
                if(localClassicMatch.rules?.activeCategories)
                    applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
            }
            syncActiveZooIntoLocalMatch();
            // A restored network match is reconnected after startup. Do not
            // enable the legacy same-tab peer simulator here: it can consume
            // authoritative syncs and mutate the restored match before the
            // real transport is back online.
            disableLocalMultiplayerPeerSimulation();
        }

        // zoocurator.nl has its own localStorage, separate from localhost.
        // An older production auto-resume snapshot can therefore contain the
        // old header placeholder ("Loading zoo...") even when localhost is
        // perfectly clean. Never let that stale UI placeholder become a saved
        // zoo name.
        const repairedZooName = repairLoadedZooName();
        if (repairedZooName) {
            createZooNameEditor();
        }

        lastAutoResumeTurn = Number(record.turn) || Number(state.turn) || 0;
        return true;
    } catch (error) {
        console.warn('Could not restore automatic resume snapshot:', error);
        clearAutoResumeSnapshot();
        return false;
    } finally {
        autoResumeWriteSuppressed = false;
    }
}

function normaliseLoadedCollection(value, kind = 'Set') {
    // Older saves, JSON round-trips and saves made by versions before a field
    // existed can leave Set/Map state as arrays, plain objects or undefined.
    if (kind === 'Map') {
        if (value instanceof Map) return value;
        if (Array.isArray(value)) return new Map(value);
        if (value && typeof value === 'object') {
            if (value.__zooType === 'Map') {
                return new Map(value.entries || []);
            }
            return new Map(Object.entries(value));
        }
        return new Map();
    }

    if (value instanceof Set) return value;
    if (Array.isArray(value)) return new Set(value);
    if (value && typeof value === 'object') {
        if (value.__zooType === 'Set') {
            return new Set(value.values || []);
        }
        return new Set(
            Object.entries(value)
                .filter(([, enabled]) => Boolean(enabled))
                .map(([key]) => key)
        );
    }
    return new Set();
}

function normaliseLoadedGameCollections() {
    const setKeys = [
        'activeCategories',
        'playerLevelsSeen',
        'enclosureRewards',
        'glowingEnclosureIds',
        'suppressedExchangeGlowIds',
        'exchangeGlowReturnIds',
        'exchangeGlowContinueIds',
        'discoveredCategoryLevels',
        'acquiredLevel2Categories',
        'awardedLevel2Milestones',
        'awardedProgressMilestones',
        'progressionGlowPinnedKeys',
        'realZooTradeDirtyZoos'
    ];

    for (const key of setKeys) {
        state[key] = normaliseLoadedCollection(state[key], 'Set');
    }

    // Plain-object fallbacks stringify object keys. A few legacy Set fields
    // contain numeric ids/levels, so convert those values back before runtime
    // code performs numeric .has()/.delete() checks. Modern tagged Set saves
    // already contain numbers and pass through unchanged.
    for (const key of ['playerLevelsSeen', 'suppressedExchangeGlowIds']) {
        state[key] = new Set(
            [...state[key]].map(value => {
                const numeric = Number(value);
                return Number.isFinite(numeric) ? numeric : value;
            })
        );
    }

    // Portable saves store real-zoo holdings as differences from the static
    // catalogue baseline. Expand them once on load; runtime trading still sees
    // the same complete Map it used before this save-format optimization.
    state.realZooSessionHoldings = decodePortableRealZooSessionHoldings(state.realZooSessionHoldings);

    // Collection and lineage use compact string-table payloads in new saves.
    // Expand them before the ordinary Map normalization/relink pass; legacy Map
    // and plain-object saves continue through their original migration path.
    state.collectionRecords = decodePortableCollectionRecords(state.collectionRecords);
    state.animalLineage = decodePortableAnimalLineage(state.animalLineage);

    const mapKeys = [
        'lastExchangeGroupCounts',
        'animalLineage',
        'tradeOfferCache',
        'assetPreloadPromises'
    ];

    for (const key of mapKeys) {
        state[key] = normaliseLoadedCollection(state[key], 'Map');
    }

    // Older/plain-JSON saves can represent a Map as an object. Object keys
    // are always strings, so an animal-lineage entry for id 12 becomes "12".
    // Runtime lineage uses numeric animal ids; normalise those keys now so the
    // relink pass below finds and preserves the existing provenance record
    // instead of creating a second blank numeric record beside it.
    if (state.animalLineage instanceof Map) {
        const normalisedLineage = new Map();
        for (const [key, record] of state.animalLineage.entries()) {
            const numericKey = Number(key);
            const lineageKey = Number.isFinite(numericKey) ? numericKey : key;
            normalisedLineage.set(lineageKey, record);
        }
        state.animalLineage = normalisedLineage;
    }
}


function relinkSandboxLooseAnimals() {
    const byId = new Map((state.animals || []).map(animal => [animal.id, animal]));
    const relinked = [];
    const seenIds = new Set();

    for (const loose of state.sandboxLooseAnimals || []) {
        if (!loose || loose.id == null || seenIds.has(loose.id)) continue;

        let canonical = byId.get(loose.id);
        if (!canonical) {
            canonical = loose;
            state.animals.push(canonical);
            byId.set(canonical.id, canonical);
        }

        if (Number.isFinite(Number(loose.x))) canonical.x = Number(loose.x);
        if (Number.isFinite(Number(loose.y))) canonical.y = Number(loose.y);
        canonical.sandboxLoose = true;
        canonical.enclosureId = null;
        canonical.slotIndex = null;

        relinked.push(canonical);
        seenIds.add(canonical.id);
    }

    state.sandboxLooseAnimals = relinked;
    return byId;
}

function relinkLoadedPlayerReferences() {
    const byId = relinkSandboxLooseAnimals();
    if (!(state.animalLineage instanceof Map)) state.animalLineage = new Map();
    state.collectionRecords = normaliseLoadedCollection(state.collectionRecords, 'Map');
    state.collectionCohabitationActive = normaliseLoadedCollection(state.collectionCohabitationActive, 'Map');
    state.collectionActiveLevel = Math.min(5, Math.max(1, Number(state.collectionActiveLevel) || 1));
    for (const animal of state.animals) {
        if (!state.animalLineage.has(animal.id)) {
            ensureAnimalLineage(animal, state.zooName || 'Your Zoo');
        }
    }
    state.exchange = (state.exchange || [null, null])
        .map(animal => animal ? (byId.get(animal.id) || animal) : null);
    if (state.outgoingOffer) {
        state.outgoingOffer =
            byId.get(state.outgoingOffer.id) || state.outgoingOffer;
    }
}

function repairLoadedNextId() {
    // `nextId` is shared by player animals, enclosures and simulated opponent
    // animals. Older/manual saves can contain a stale or missing counter even
    // though those entities (or their historical lineage/trade records) still
    // use higher ids. Reusing one of those ids would merge unrelated lineage
    // and trade-history references, so advance the counter beyond every known
    // numeric id without otherwise rewriting the loaded save.
    let highestId = 0;
    const noteId = value => {
        const numeric = Number(value);
        if (Number.isInteger(numeric) && numeric > highestId) highestId = numeric;
    };
    const noteAnimal = animal => {
        if (animal && typeof animal === 'object') noteId(animal.id);
    };

    for (const animal of state.animals || []) noteAnimal(animal);
    for (const animal of state.sandboxLooseAnimals || []) noteAnimal(animal);
    for (const enclosure of state.enclosures || []) noteId(enclosure?.id);
    for (const stock of state.opponentTradeStocks || []) {
        for (const animal of stock || []) noteAnimal(animal);
    }
    for (const animal of state.exchange || []) noteAnimal(animal);
    noteAnimal(state.result);
    noteAnimal(state.outgoingOffer);

    if (state.animalLineage instanceof Map) {
        for (const [key, record] of state.animalLineage.entries()) {
            noteId(key);
            noteId(record?.animalId);
        }
    }
    for (const trade of state.tradeHistory || []) {
        noteId(trade?.outgoingId);
        noteId(trade?.incomingId);
    }

    const loadedNextId = Number(state.nextId);
    const safeNextId = highestId + 1;
    state.nextId = Number.isInteger(loadedNextId) && loadedNextId > highestId
        ? loadedNextId
        : safeNextId;
}

function resetTransientStateForImport() {
    // None of these values belongs to a saved zoo. They describe in-flight
    // input, preloads, hover effects or short-lived glow timers from the
    // currently open game. Letting them survive a Load can make the restored
    // zoo inherit visual/input state or promises created for another zoo.
    state.nextDrawSpec = null;
    state.nextDrawReadyPromise = null;
    state.drawCommitInProgress = false;
    state.assetPreloadPromises = new Map();

    // Enclosure reward glows are purely visual and time-based. Never carry
    // them across a Load: their cleanup timers and start timestamps are not
    // persistent, so restoring only the glowing IDs can otherwise leave a
    // freshly loaded enclosure glowing indefinitely.
    state.glowingEnclosureIds = new Set();
    state.newEnclosureGlowStartedAt = new Map();

    state.drag = null;
    state.pan = null;
    state.lastHoveredAnimal = null;
    if (state.compatibilityIntentTimer) clearTimeout(state.compatibilityIntentTimer);
    if (state.compatibilityAnimalHoverTimer) clearTimeout(state.compatibilityAnimalHoverTimer);
    if (state.compatibilityHoveredSlotTimer) clearTimeout(state.compatibilityHoveredSlotTimer);
    state.compatibilityIntentTimer = null;
    state.compatibilityAnimalHoverTimer = null;
    state.compatibilityHoveredSlotTimer = null;
    state.compatibilityIntentAnimalId = null;
    state.compatibilityIntentActiveAnimal = null;

    state.exchangeGlowFocusKey = null;
    state.outgoingOfferHoverSuppressesExchangeGlow = false;
    state.outgoingOfferTradeHoverActive = false;
    state.exchangeEligibilityHoverActive = false;
    state.exchangeGlowReturnUntil = 0;
    state.exchangeGlowReturnIds = new Set();
    state.exchangeGlowDragStartedAt = 0;
    state.exchangeGlowContinueIds = new Set();
    state.exchangeGlowContinueStartedAt = 0;
    state.exchangeGlowContinueUntil = 0;

    state.previewHoveredAnimalId = null;
    if (state.previewHideTimer) clearTimeout(state.previewHideTimer);
    if (state.previewIntentTimer) clearTimeout(state.previewIntentTimer);
    state.previewHideTimer = null;
    state.previewIntentTimer = null;
    state.previewIntentAnimalId = null;
    state.previewWikiAnimalId = null;
    // Invalidate requests started by the zoo being replaced. Never reset this
    // token to zero: an older asynchronous response could otherwise reuse the
    // same token as the first request in the newly loaded zoo and be accepted.
    state.previewWikiRequestToken = (Number(state.previewWikiRequestToken) || 0) + 1;
    state.previewScientificName = '';
    state.previewZtlAnimalId = null;
    state.previewZtlScientificName = '';
    state.previewZtlRequestToken = (Number(state.previewZtlRequestToken) || 0) + 1;

    // Module-level UI timers are transient too. They live outside `state`, so
    // resetting the saved zoo alone cannot invalidate them. Cancel callbacks
    // created by the zoo being replaced before they can act on the new DOM.
    clearTimeout(tradeEligibleGlowHideTimer);
    tradeEligibleGlowHideTimer = null;
    tradeEligibleGlowActive = false;
    tradeEligibleGlowWorkToken++;

    clearTimeout(categoryProgressHoverTimer);
    categoryProgressHoverTimer = null;

    clearTimeout(yellowExchangeHintTimer);
    yellowExchangeHintTimer = null;
    clearTimeout(actionHintTimer);
    actionHintTimer = null;
    clearTimeout(actionHintRepeatTimer);
    actionHintRepeatTimer = null;

    clearTimeout(opponentInfoHideTimer);
    opponentInfoHideTimer = null;
    clearTimeout(opponentInfoFadeTimer);
    opponentInfoFadeTimer = null;
    clearTimeout(opponentInfoShowTimer);
    opponentInfoShowTimer = null;

    clearTimeout(tradeAnimalLockTimer);
    tradeAnimalLockTimer = null;
    tradeAnimalHoverKey = null;
    tradeAnimalLockedKey = null;

    // True creates its calendar/activity panel dynamically inside the shared
    // header. Remove mode-owned DOM whenever a zoo/save is being replaced.
    // If the incoming game is also True, renderAll() recreates it immediately;
    // Classic/Sandbox therefore cannot inherit a stale True panel or have their
    // action controls pushed sideways by it.
    document.getElementById('trueSimulationPanel')?.remove();
    document.getElementById('trueMarketplaceOverlay')?.remove();
    document.getElementById('truePopulationSelectorBackdrop')?.remove();
}

function importGameState(saveData, { deferRender = false } = {}) {
    lifetimeCollectionLastMergeSignature='';
    if (!saveData || !saveData.state) {
        throw new Error(uiText('This save file does not contain a valid Zoo Curator game.'));
    }

    // A full import replaces the physical zoo, not merely a few state fields.
    // Never let geometry/geography caches from the previously rendered zoo
    // survive a multiplayer visit, return-home import, reconnect correction or
    // save load. Two different zoos can legitimately share the same revision
    // and object counts, which made the old task-shape shortcut reuse the wrong
    // detailed signature and generated Area result.
    areaSignatureTaskCache=null;
    areaSignatureTaskShape='';
    areaSignatureTaskCacheScheduled=false;
    invalidateClassicGeneratedGeography();
    geographicAdjacencyGeometryCache={signature:null,index:null};
    activeGeographicAnimalIndex=null;
    activeGeographicResidentCache=null;
    activeGeographicCandidateUnitIndex=null;

    // Named saves written by the old plain-JSON path flattened every Set/Map to
    // an empty object. Remember that corruption before cloneForSave/normalisers
    // turn it into an indistinguishable empty runtime collection.
    const legacyFlattenedCollection = key => {
        const value = saveData.state?.[key];
        return value && typeof value === 'object' && !Array.isArray(value) &&
            !(value instanceof Set) && !(value instanceof Map) &&
            value.__zooType == null && Object.keys(value).length === 0;
    };
    const legacyProgressRewardsFlattened =
        legacyFlattenedCollection('awardedProgressMilestones');
    const legacyGeneratedAreasFlattened =
        legacyFlattenedCollection('generatedAreaMembership');
    const rebuildLegacyGeneratedAreas = legacyGeneratedAreasFlattened;

    exitHistoryView(false);
    state.suppressHistoryCapture = true;

    // Reset all non-persistent/in-flight state before replacing the saved zoo.
    // A fresh prepared draw and any hover/preview state will be rebuilt from
    // the restored game rather than inherited from the game being replaced.
    resetTransientStateForImport();

    // V220.51 removes the old Hand subsystem. Older saves may still contain
    // one or more pending hand-card references; remember their ids solely for
    // one-time migration after the normal zoo state has been restored.
    const legacyHandIds = new Set(
        Array.isArray(saveData.state.hand)
            ? saveData.state.hand.map(animal => Number(animal?.id)).filter(Number.isFinite)
            : []
    );

    for (const key of SAVE_STATE_KEYS) {
        if (Object.prototype.hasOwnProperty.call(saveData.state, key)) {
            state[key] = cloneForSave(saveData.state[key]);
        } else {
            // The save genuinely has no value for this field (typically
            // because it was created before the field existed). Never retain
            // the corresponding value from the game we are replacing.
            state[key] = cloneForSave(SAVE_STATE_DEFAULTS[key]);
        }
    }

    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'zooType')) {
        state.zooType = inferZooTypeFromAnyGeneratedName(state.zooName);
    }
    state.zooType = normaliseZooTypes(state.zooType)[0];

    state.sandboxMode = Boolean(state.sandboxMode);
    // Backward-compatible migration: saves from before True mode had only the
    // Sandbox boolean. They therefore load exactly as Classic or Sandbox did.
    if (!['classic', 'true', 'sandbox'].includes(state.gameMode)) {
        state.gameMode = state.sandboxMode ? 'sandbox' : 'classic';
    }
    if (state.sandboxMode) state.gameMode = 'sandbox';
    if (state.gameMode === 'true') {
        normaliseTrueCalendarState();
        normaliseTrueDecorations();
        // V229.1 migration: older True saves predate enclosure populations. Give
        // every existing species card a small neutral founder population while
        // leaving Classic/Sandbox save objects completely untouched.
        for (const animal of state.animals || []) normaliseTrueAnimalPopulation(animal);
        requestAnimationFrame(()=>refreshTrueDecorationVisuals());
    }
    if (!Array.isArray(state.sandboxLooseAnimals)) state.sandboxLooseAnimals = [];
    state.turnHistory = decodePortableTurnHistory(saveData.turnHistory || []);
    if(Array.isArray(state.turnHistory)){
        const byTurn=new Map();
        for(const snapshot of state.turnHistory){
            const turn=Number(snapshot?.turn);
            // Turn history is read-only convenience data, not authoritative zoo
            // state. Ignore malformed legacy checkpoints rather than allowing an
            // undefined turn or missing zoo arrays to break history controls/load.
            if(!Number.isFinite(turn))continue;
            if(!Array.isArray(snapshot?.enclosures)||!Array.isArray(snapshot?.animals))continue;
            snapshot.turn=turn;
            byTurn.set(turn,snapshot);
        }
        state.turnHistory=[...byTurn.entries()]
            .sort((a,b)=>a[0]-b[0])
            .map(([,snapshot])=>snapshot);
    }else{
        state.turnHistory=[];
    }
    state.historyViewTurn = null;
    state.historyLiveView = null;
    state.drag = null;
    state.pan = null;

    // repair collection types before any render/update function can call
    // .has(), .add(), spread syntax, .entries(), etc. This keeps older saves
    // compatible with newer state fields such as progressionGlowPinnedKeys.
    normaliseLoadedGameCollections();

    // Recovery for named saves written by builds that stored Set/Map values
    // with plain JSON.stringify. In those saves activeCategories became {},
    // which normalises to an empty Set and makes every draw look illegal.
    // An intentionally category-restricted multiplayer game restores its rules
    // separately, so an empty ordinary save is never a meaningful category set.
    if (!state.activeCategories.size) {
        state.activeCategories = new Set(Object.keys(FOLDERS));
    }

    // Do NOT replay years of progression rewards when loading a save whose
    // awarded-milestone Set was destroyed by the old JSON writer. The animals
    // already encode which milestones have been passed; mark those milestones
    // as historically awarded without creating any enclosure cards.
    if (legacyProgressRewardsFlattened) {
        state.awardedProgressMilestones = progressionRewardKeysForMilestones(
            state.gameOptions?.enclosureRewardMilestones || []
        );
        state.awardedLevel2Milestones = new Set(
            [...state.awardedProgressMilestones]
                .map(key => String(key).split('|'))
                .filter(([levelText]) => Number(levelText) === 2)
                .map(([, milestoneText]) => Number(milestoneText))
        );
    }

    // A loaded zoo must never inherit generated-Area reconciliation from the
    // zoo that happened to be open before it. Old lossy saves have no retained
    // Area maps, so force a clean derivation from their surviving animals,
    // enclosure positions and geographic/tag data on the first render.
    invalidateConnectedAreaReconciliation();
    renderedConnectedAreaGroups = [];
    renderedConnectedAreaGroupsSignature = '';
    stableConnectedAreaGroups = [];
    stableConnectedAreaGroupsSignature = '';
    generatedModernGeographicAreas = [];
    if (legacyGeneratedAreasFlattened) {
        state.generatedAreaMembership = new Map();
    
        // The old lossy named-save writer also exposed a second legacy failure:
        // mature zoos could retain valid card coordinates with entire empty grid
        // columns/rows between occupied columns/rows. Classic gameplay cannot
        // create those disconnected holes, and generated Areas depend on physical
        // adjacency. Compact ONLY this unmistakably corrupted legacy-save shape.
        //
        // Preserve every enclosure id, card number, animal enclosureId/slotIndex
        // and the relative ordering of rows/columns; only remove wholly empty
        // grid bands. That restores the topology without inventing/reassigning
        // animals or enclosure cards.
        const legacyEnclosures = Array.isArray(state.enclosures) ? state.enclosures : [];
        if (legacyEnclosures.length > 1) {
            const stepX = ENCLOSURE_W + ENCLOSURE_GAP;
            const stepY = ENCLOSURE_H + ENCLOSURE_GAP;
            const xs = [...new Set(legacyEnclosures.map(e => Number(e?.x)).filter(Number.isFinite))]
                .sort((a,b) => a-b);
            const ys = [...new Set(legacyEnclosures.map(e => Number(e?.y)).filter(Number.isFinite))]
                .sort((a,b) => a-b);

            const hasGridSizedGap = values => values.some(
                (value,index) => index > 0 &&
                    value - values[index-1] > Math.max(stepX, stepY) * 1.45
            );

            if (hasGridSizedGap(xs) || hasGridSizedGap(ys)) {
                const originX = xs[0];
                const originY = ys[0];
                const xIndex = new Map(xs.map((value,index) => [value,index]));
                const yIndex = new Map(ys.map((value,index) => [value,index]));

                for (const enclosure of legacyEnclosures) {
                    const xi = xIndex.get(Number(enclosure.x));
                    const yi = yIndex.get(Number(enclosure.y));
                    if (Number.isInteger(xi)) enclosure.x = originX + xi * stepX;
                    if (Number.isInteger(yi)) enclosure.y = originY + yi * stepY;
                }

                // Geometry changed, so Area recognition must see the repaired
                // connected footprint rather than any pre-import cache.
                state.areaPlacementRevision = (Number(state.areaPlacementRevision) || 0) + 1;
                invalidateConnectedAreaReconciliation();
                renderedConnectedAreaGroups = [];
                renderedConnectedAreaGroupsSignature = '';
                stableConnectedAreaGroups = [];
                stableConnectedAreaGroupsSignature = '';
                generatedModernGeographicAreas = [];
            }
        }
    }

    if(!state.sandboxMode)ensureLifetimePlaythroughId();
    relinkLoadedPlayerReferences();
    repairLoadedNextId();

    // One-time compatibility migration for pre-V220.51 saves. Modern gameplay
    // never creates an unplaced owned animal: draw, upgrade and incoming-trade
    // actions commit only after a legal destination is known.
    for (const id of legacyHandIds) {
        const animal = state.animals.find(item => Number(item?.id) === id);
        if (!animal || animal.enclosureId != null) continue;
        const destination = randomEligibleDestinationForAnimal(animal);
        if (destination) {
            placeAnimal(animal, destination.enclosure, destination.slotIndex);
        } else {
            console.warn(`Legacy hand card ${id} could not be auto-placed; leaving save unchanged for that card.`);
        }
    }

    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'zooProvince')) {
        state.zooProvince = zooSetupProvinceForLocation(
            state.zooCountry,
            state.zooLocation
        );
    }
    if (!Object.prototype.hasOwnProperty.call(saveData.state, 'highestZooPrestige')) {
        state.highestZooPrestige = (state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo)
            ? visibleZooPrestige()
            : currentZooPrestige();
    }
    updateHighestZooPrestige();

    document.documentElement.style.setProperty('--zoo-zoom', state.zoom);
    document.body.classList.remove('history-viewing');

    // The colour scheme is part of saved state, but the header/theme UI is
    // created before auto-resume is restored during startup. Re-apply it here
    // immediately after every import so body[data-zoo-colour-scheme], the
    // header/menus and the map all switch atomically to the restored scheme.
    // This also fixes ordinary Save/Load imports, not only page reloads.
    applyZooColourScheme();

    if (deferRender) {
        // Startup will perform the first render once, after restoration is
        // complete. Avoid rebuilding the entire zoo invisibly and scheduling a
        // second history capture before the loading screen is removed.
        state.suppressHistoryCapture = false;
        if (saveData.view) {
            state.pendingRestoredView = {
                scrollLeft: Number(saveData.view.scrollLeft) || 0,
                scrollTop: Number(saveData.view.scrollTop) || 0
            };
        }
        return;
    }

    renderAll();

    // Old named saves lost the Maps that say which generated Areas were already
    // established. After the repaired enclosure topology has rendered once,
    // run the existing Area generator again against the live zoo. This is a
    // one-shot migration only; healthy saves retain their stored memberships.
    if (rebuildLegacyGeneratedAreas && state.gameOptions?.autoGeneratedAreasZones !== false) {
        invalidateConnectedAreaReconciliation();
        try {
            generatedGeographicAreaGroups();
        } catch (error) {
            console.warn('Legacy generated-Area reconstruction could not complete:', error);
        }
    }

    requestAnimationFrame(() => {
        if (saveData.view) {
            const left=Math.max(0,Number(saveData.view.scrollLeft)||0);
            const top=Math.max(0,Number(saveData.view.scrollTop)||0);
            zooBoard.scrollLeft=left;
            zooBoard.scrollTop=top;
            requestAnimationFrame(() => {
                if (Math.abs(zooBoard.scrollLeft-left)>1) zooBoard.scrollLeft=left;
                if (Math.abs(zooBoard.scrollTop-top)>1) zooBoard.scrollTop=top;
            });
        }
        state.suppressHistoryCapture = false;
        captureTurnSnapshot();
        updateHistoryControls();
    });
}

function loadSaveSlots() {
    try {
        const parsed = deserialiseSpecial(
            JSON.parse(localStorage.getItem(SAVE_STORAGE_KEY) || '[]')
        );
        return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
        console.warn('Could not read saved games:', error);
        return [];
    }
}

function writeSaveSlots(slots) {
    // Named saves contain Sets and Maps (active categories, generated Areas,
    // collection/progression state, etc.). Plain JSON.stringify turns those
    // collections into {}, silently corrupting the save. Use the same tagged
    // representation as auto-resume so a named save is a lossless snapshot.
    localStorage.setItem(SAVE_STORAGE_KEY, JSON.stringify(serialiseSpecial(slots)));
}

function realZooTemplateSlug(name) {
    return String(name || 'real-zoo')
        .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
        .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'real-zoo';
}

// Canonical generated layouts remain in one large file. A very small registry of
// deliberately handcrafted zoo layouts can bypass that file without modifying it.
// Add future curated layouts here; each file is fetched once at real-zoo startup,
// so we avoid the old "try a JSON file for every zoo" 404 storm.
const REAL_ZOO_HANDCRAFTED_LAYOUT_FILES = [
    'assets/layouts/koninklijke-burgers-zoo.json'
];

let REAL_ZOO_HANDCRAFTED_LAYOUTS = new Map();
let REAL_ZOO_PREGENERATED_LAYOUTS = new Map();

function loadHandcraftedRealZooLayouts() {
    return Promise.all(
        REAL_ZOO_HANDCRAFTED_LAYOUT_FILES.map(path =>
            fetch(path, { cache:'default' })
                .then(response => {
                    if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
                    return response.json();
                })
                .then(layout => ({ path, layout }))
                .catch(error => {
                    console.warn('Could not load handcrafted real-zoo layout:', error);
                    return null;
                })
        )
    ).then(results => {
        const map = new Map();
        for (const result of results) {
            const layout = result?.layout;
            const key = realZooTemplateKey(layout?.zoo?.name || layout?.zooName || '');
            if (key && Array.isArray(layout?.enclosures) && layout.enclosures.length) {
                map.set(key, layout);
            } else if (result) {
                console.warn(`Ignoring invalid handcrafted real-zoo layout: ${result.path}`);
            }
        }
        REAL_ZOO_HANDCRAFTED_LAYOUTS = map;
        REAL_ZOO_PRESTIGE_CACHE = new WeakMap();
        return map;
    });
}

function loadPregeneratedRealZooLayouts() {
    const path = 'pregenerated_real_zoo_layouts.json';
    const pregeneratedPromise = fetch(path, { cache:'no-store' })
        .then(response => response.ok ? response.json() : { layouts:[] })
        .then(data => {
            const layouts = Array.isArray(data) ? data : (Array.isArray(data?.layouts) ? data.layouts : []);
            const map = new Map();
            for (const layout of layouts) {
                const key = realZooTemplateKey(layout?.zoo?.name || layout?.zooName || '');
                if (key && Array.isArray(layout?.enclosures) && layout.enclosures.length) map.set(key, layout);
            }
            REAL_ZOO_PREGENERATED_LAYOUTS = map;
            return map;
        })
        .catch(error => {
            console.warn('Could not load pregenerated real-zoo layouts:', error);
            REAL_ZOO_PREGENERATED_LAYOUTS = new Map();
            return REAL_ZOO_PREGENERATED_LAYOUTS;
        });

    // Both layers are ready before callers receive the existing loader promise.
    return Promise.all([loadHandcraftedRealZooLayouts(), pregeneratedPromise])
        .then(([, pregenerated]) => {
            REAL_ZOO_PRESTIGE_CACHE = new WeakMap();
            auditRealZooPregeneratedPrestigeCoverage();
            return pregenerated;
        });
}


function realZooPregeneratedPrestigeCoverage() {
    const records=Array.isArray(state.realZooData?.zoos)?state.realZooData.zoos:[];
    const missing=[],invalid=[];
    for(const record of records){
        const layout=pregeneratedRealZooLayout(record);
        const summary=layout?.prestige || record?.layout_prestige || null;
        if(!summary){missing.push(record?.name||'Unnamed zoo');continue;}
        if(!Number.isFinite(Number(summary.current))){
            invalid.push(record?.name||'Unnamed zoo');
        }
    }
    return {total:records.length,valid:Math.max(0,records.length-missing.length-invalid.length),missing,invalid};
}
function auditRealZooPregeneratedPrestigeCoverage() {
    const coverage=realZooPregeneratedPrestigeCoverage();
    if(coverage.missing.length||coverage.invalid.length){
        console.warn(
            `Real-zoo prestige coverage incomplete: ${coverage.valid}/${coverage.total} have a valid pregenerated current prestige.`,
            {missing:coverage.missing,invalid:coverage.invalid}
        );
    }else if(coverage.total){
        console.info(`Real-zoo prestige coverage: ${coverage.valid}/${coverage.total} current prestige summaries ready at startup.`);
    }
    return coverage;
}

function handcraftedRealZooLayout(recordOrName) {
    const key = realZooTemplateKey(recordOrName);
    return key ? REAL_ZOO_HANDCRAFTED_LAYOUTS.get(key) || null : null;
}

function pregeneratedRealZooLayout(recordOrName) {
    const key = realZooTemplateKey(recordOrName);
    return key ? REAL_ZOO_PREGENERATED_LAYOUTS.get(key) || null : null;
}

function authoritativeRealZooLayout(record) {
    // Strict separation of concerns:
    // local authoring override -> shipped handcrafted layout ->
    // canonical pregenerated layout -> procedural fallback.
    return localRealZooTemplate(record) ||
        handcraftedRealZooLayout(record) ||
        pregeneratedRealZooLayout(record) ||
        null;
}

function loadLocalRealZooTemplates() {
    try {
        const parsed = JSON.parse(localStorage.getItem(REAL_ZOO_TEMPLATE_STORAGE_KEY) || '{}');
        return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (error) {
        console.warn('Could not read real-zoo layout templates:', error);
        return {};
    }
}

function realZooTemplateKey(recordOrName) {
    return normaliseGeographyPart(typeof recordOrName === 'string' ? recordOrName : recordOrName?.name || '');
}

function localRealZooTemplate(recordOrName) {
    const key = realZooTemplateKey(recordOrName);
    return key ? loadLocalRealZooTemplates()[key] || null : null;
}

function saveLocalRealZooTemplate(record, template) {
    const key = realZooTemplateKey(record);
    if (!key) throw new Error('The real zoo has no usable name.');
    const templates = loadLocalRealZooTemplates();
    templates[key] = template;
    localStorage.setItem(REAL_ZOO_TEMPLATE_STORAGE_KEY, JSON.stringify(templates));
}

function templateSpeciesName(value) {
    return animalDatabaseKey(typeof value === 'string' ? value : animalDisplayName(value));
}

function realZooTemplateSpeciesDiff(record) {
    const actual = new Map();
    for (const animal of state.animals || []) {
        const name = animalDisplayName(animal);
        const key = templateSpeciesName(name);
        if (key && !actual.has(key)) actual.set(key, name);
    }
    const expected = new Map();
    for (const raw of record?.animals || []) {
        const spec = realZooAnimalSpecByName(raw);
        const display = spec ? animalDisplayName(spec) : String(raw || '').trim();
        const key = templateSpeciesName(display);
        if (key && !expected.has(key)) expected.set(key, display);
    }
    return {
        missing: [...expected].filter(([key]) => !actual.has(key)).map(([,name]) => name).sort(),
        added: [...actual].filter(([key]) => !expected.has(key)).map(([,name]) => name).sort()
    };
}

function editDistance(a, b) {
    a = String(a || ''); b = String(b || '');
    const prev = Array.from({length:b.length+1}, (_,i)=>i);
    for (let i=1;i<=a.length;i++) {
        let diagonal = prev[0]; prev[0] = i;
        for (let j=1;j<=b.length;j++) {
            const old = prev[j];
            prev[j] = Math.min(prev[j]+1, prev[j-1]+1, diagonal + (a[i-1]===b[j-1]?0:1));
            diagonal = old;
        }
    }
    return prev[b.length];
}

function matchSandboxZooToRealZoo() {
    const records = (state.realZooData?.zoos || []).filter(record => record?.name);
    if (!records.length) return { record:null, exact:false, score:0 };
    const wanted = normaliseGeographyPart(state.zooName || '');
    const exact = records.find(record => normaliseGeographyPart(record.name) === wanted);
    if (exact) return { record:exact, exact:true, score:1 };
    let best = null, bestScore = -1;
    for (const record of records) {
        const candidate = normaliseGeographyPart(record.name);
        const longest = Math.max(wanted.length, candidate.length, 1);
        let score = 1 - editDistance(wanted, candidate) / longest;
        if (wanted && candidate && (wanted.includes(candidate) || candidate.includes(wanted))) score = Math.max(score, .84);
        if (score > bestScore) { best = record; bestScore = score; }
    }
    return { record:best, exact:false, score:bestScore };
}

function buildRealZooLayoutTemplate(record) {
    // Capture current reconciled membership, not stale membership from before
    // the most recent animal/enclosure change.
    connectedEnclosureThemeGroups();
    const enclosureIds = new Set((state.enclosures || []).map(enclosure => enclosure.id));
    const membership = {};
    for (const [key, ids] of state.generatedAreaMembership instanceof Map ? state.generatedAreaMembership : []) {
        membership[key] = [...ids].filter(id => enclosureIds.has(id));
    }
    return {
        format: 'ZooCuratorRealZooLayout',
        version: REAL_ZOO_TEMPLATE_FORMAT_VERSION,
        zoo: { name: record.name, country: record.country || '', province: record.province || '' },
        createdAt: new Date().toISOString(),
        enclosures: cloneForSave(state.enclosures || []),
        animals: (state.animals || []).map(animal => ({
            name: animalDisplayName(animal),
            enclosureId: animal.enclosureId ?? null,
            slotIndex: animal.slotIndex ?? null
        })),
        customAreas: cloneForSave(state.customAreas || []),
        generatedAreaMembership: membership,
        generatedAreaOverrides: Object.fromEntries(state.generatedAreaOverrides instanceof Map ? state.generatedAreaOverrides : []),
        areaLabelPositions: Object.fromEntries(state.areaLabelPositions instanceof Map ? state.areaLabelPositions : []),
        suppressedGeneratedAreas: Object.fromEntries(state.suppressedGeneratedAreas instanceof Map ? state.suppressedGeneratedAreas : []),
        prestige: (() => {
            const b=zooPrestigeBreakdown();
            return {
                original:Math.ceil(b.base),
                current:Math.ceil(b.current),
                identity_bonus_percent:Number(b.identityPercent)||0,
                area_bonus_percent:Number(b.areaBonusPercent)||0,
                combination_bonus_percent:Number(b.combinationUnits)||0,
                curation_bonus_percent:Number(b.curationPercent)||0,
                husbandry_penalty_percent:Number(b.husbandryPenaltyPercent)||0,
                total_modifier_percent:
                    (Number(b.identityPercent)||0)+(Number(b.areaBonusPercent)||0)+
                    (Number(b.combinationUnits)||0)+(Number(b.curationPercent)||0)-
                    (Number(b.husbandryPenaltyPercent)||0)
            };
        })()
    };
}

function canonicaliseProceduralRealZooGridSpacing(){
    const enclosures=Array.isArray(state.enclosures)?state.enclosures:[];
    if(enclosures.length<2)return false;
    const stepX=ENCLOSURE_W+ENCLOSURE_GAP;
    const stepY=ENCLOSURE_H+ENCLOSURE_GAP;
    const xs=[...new Set(enclosures.map(e=>Number(e.x)).filter(Number.isFinite))].sort((a,b)=>a-b);
    const ys=[...new Set(enclosures.map(e=>Number(e.y)).filter(Number.isFinite))].sort((a,b)=>a-b);
    if(!xs.length||!ys.length)return false;

    // Procedural real zoos are generated on an integer grid. Recover that grid
    // from the smallest observed pitch, then rewrite it using the exact Classic
    // startup pitch. Unlike rank-compaction, this preserves intentional empty
    // grid columns/rows in irregular silhouettes.
    const positiveDeltas=values=>values.slice(1)
        .map((value,index)=>value-values[index])
        .filter(delta=>Number.isFinite(delta)&&delta>1);
    const xDeltas=positiveDeltas(xs),yDeltas=positiveDeltas(ys);
    const sourceStepX=xDeltas.length?Math.min(...xDeltas):stepX;
    const sourceStepY=yDeltas.length?Math.min(...yDeltas):stepY;
    const originX=xs[0],originY=ys[0];

    let changed=false;
    for(const enclosure of enclosures){
        const gx=Math.round((Number(enclosure.x)-originX)/sourceStepX);
        const gy=Math.round((Number(enclosure.y)-originY)/sourceStepY);
        const x=originX+gx*stepX;
        const y=originY+gy*stepY;
        if(Math.abs(Number(enclosure.x)-x)>.01||Math.abs(Number(enclosure.y)-y)>.01)changed=true;
        enclosure.x=x;
        enclosure.y=y;
    }
    if(changed){
        state.areaPlacementRevision=(Number(state.areaPlacementRevision)||0)+1;
        invalidateConnectedAreaReconciliation();
        renderedConnectedAreaGroups=[];
        renderedConnectedAreaGroupsSignature='';
        stableConnectedAreaGroups=[];
        stableConnectedAreaGroupsSignature='';
        generatedModernGeographicAreas=[];
    }
    return changed;
}

// Batch-regenerate the canonical real-zoo layout file from the CURRENT opponent
// database. This intentionally ignores the previously shipped pregenerated map,
// while still honoring local/handcrafted layouts (for example Burgers), so an
// old 41-zoo cache can never prevent newly added opponents from being generated.
async function pregenerateAllRealZooLayouts() {
    const records = (state.realZooData?.zoos || []).filter(record => record?.name && Array.isArray(record.animals) && record.animals.length);
    if (!records.length) throw new Error('No real-zoo opponent records are loaded.');

    const previousPregenerated = REAL_ZOO_PREGENERATED_LAYOUTS;
    const layouts = [];
    const failures = [];
    REAL_ZOO_PREGENERATED_LAYOUTS = new Map();
    REAL_ZOO_PRESTIGE_CACHE = new WeakMap();

    try {
        for (let index = 0; index < records.length; index++) {
            const record = records[index];
            try {
                const usesAuthoredLayout=Boolean(
                    handcraftedRealZooLayout(record)||localRealZooTemplate(record)
                );
                createRealZooFromRecord(record, { sandboxMode:false });
                // Pregenerated procedural zoos must use the exact same physical
                // card pitch as ordinary Classic generation. Authored templates
                // deliberately retain their hand-positioned coordinates.
                // Procedural coordinates are already emitted on the canonical Classic grid.
                // Force reconciliation before capture so generated Areas and the
                // prestige summary describe exactly what opening this zoo shows.
                connectedEnclosureThemeGroups();
                const layout = buildRealZooLayoutTemplate(record);
                layout._pregeneration = {
                    status: 'regenerated-v2.43.21',
                    generator: usesAuthoredLayout
                        ? 'authoritative-handcrafted-layout'
                        : 'naturalistic-thematic-districts',
                    source_trade_id: record.trade_id ?? null,
                    source_holding_count: record.animals.length,
                    generated_at: new Date().toISOString()
                };
                layouts.push(layout);
            } catch (error) {
                console.error(`Pregeneration failed for ${record.name}:`, error);
                failures.push({ name:record.name, trade_id:record.trade_id ?? null, error:String(error?.message || error) });
            }
            if ((index + 1) % 5 === 0) {
                console.log(`Pregenerated ${index + 1}/${records.length} real zoos…`);
                await new Promise(resolve => setTimeout(resolve, 0));
            }
        }
    } finally {
        // Do not restore the stale pregenerated map after a successful developer
        // regeneration. Install every newly generated layout immediately so the
        // current localhost/session uses the same geometry and prestige that is
        // written to the downloaded JSON. Preserve an old entry only for a zoo
        // whose regeneration failed.
        const generatedMap=new Map();
        for(const layout of layouts){
            const key=realZooTemplateKey(layout?.zoo?.name || layout?.zooName || '');
            if(key)generatedMap.set(key,layout);
        }
        for(const [key,layout] of previousPregenerated){
            if(!generatedMap.has(key))generatedMap.set(key,layout);
        }
        REAL_ZOO_PREGENERATED_LAYOUTS = generatedMap;
        REAL_ZOO_PRESTIGE_CACHE = new WeakMap();
        state.tradeOfferCache?.clear?.();
        if(document.getElementById('realZooDirectoryOverlay')?.style.display==='flex'){
            renderRealZooDirectory();
        }
    }

    const payload = {
        format: 'ZooCuratorPregeneratedRealZooLayouts',
        version: 2,
        game_version: ZOO_CURATOR_VERSION,
        generatedAt: new Date().toISOString(),
        sourceZooCount: records.length,
        layoutCount: layouts.length,
        failureCount: failures.length,
        failures,
        layouts
    };
    const blob = new Blob([JSON.stringify(payload, null, 2) + '\n'], { type:'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'pregenerated_real_zoo_layouts.json';
    document.body.appendChild(link); link.click(); link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    console.log(`Finished pregenerating ${layouts.length}/${records.length} real zoos.`, failures.length ? failures : 'No failures.');
    return payload;
}
window.pregenerateAllRealZooLayouts = pregenerateAllRealZooLayouts;

function downloadRealZooLayoutTemplate(template) {
    const blob = new Blob([JSON.stringify(template, null, 2) + '\n'], { type:'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${realZooTemplateSlug(template?.zoo?.name)}.json`;
    document.body.appendChild(link); link.click(); link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// ============================================================
// GAME-NATIVE DIALOGS
//
// Never use browser alert()/confirm()/prompt() for Zoo Curator UI. Apart from
// breaking visual consistency, browsers can permanently suppress those dialogs
// for a site. This Promise-based modal is owned by the game and therefore also
// remains usable when native browser pop-ups are disabled.
// ============================================================
function ensureGameDialogUI() {
    let overlay = document.getElementById('zooGameDialogOverlay');
    if (overlay) return overlay;

    const style = document.createElement('style');
    style.id = 'zooGameDialogStyles';
    style.textContent = `
        .zoo-game-dialog-overlay{position:fixed;inset:0;z-index:120000;display:none;align-items:center;justify-content:center;padding:18px;background:rgba(34,30,22,.34);backdrop-filter:blur(1px)}
        .zoo-game-dialog-overlay.visible{display:flex}
        .zoo-game-dialog{box-sizing:border-box;width:min(460px,calc(100vw - 28px));max-height:min(78vh,720px);overflow:auto;padding:16px 18px 14px;background:#eee3c4;color:#554a38;border:1px solid #9d8e6e;border-radius:8px;box-shadow:0 10px 34px rgba(0,0,0,.32);font:600 13px/1.4 Arial,sans-serif}
        .zoo-game-dialog h2{margin:0 0 10px;font-size:18px;color:#514633}
        .zoo-game-dialog-message{white-space:pre-wrap;font-weight:500;overflow-wrap:anywhere}
        .zoo-game-dialog-input{box-sizing:border-box;width:100%;margin-top:12px;padding:8px 9px;background:#fffdf7;color:#40392e;border:1px solid #9d8e6e;border-radius:4px;font:600 13px Arial,sans-serif;outline:none}
        .zoo-game-dialog-input:focus{box-shadow:0 0 0 2px rgba(142,119,68,.22)}
        .zoo-game-dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:15px}
        .zoo-game-dialog button{padding:6px 12px;background:#fffaf0;color:#514633;border:1px solid #9d8e6e;border-radius:4px;font:700 12px Arial,sans-serif;cursor:pointer}
        .zoo-game-dialog button:hover{background:#f8efd9}
        body.zoo-dark-mode .zoo-game-dialog{background:#302f2b;color:#eee6d3;border-color:#706a5d}
        body.zoo-dark-mode .zoo-game-dialog h2{color:#f2ead8}
        body.zoo-dark-mode .zoo-game-dialog-input,body.zoo-dark-mode .zoo-game-dialog button{background:#22211f;color:#eee6d3;border-color:#706a5d}
    `;
    document.head.appendChild(style);

    overlay = document.createElement('div');
    overlay.id = 'zooGameDialogOverlay';
    overlay.className = 'zoo-game-dialog-overlay';
    overlay.innerHTML = `<div class="zoo-game-dialog" role="dialog" aria-modal="true" aria-labelledby="zooGameDialogTitle"><h2 id="zooGameDialogTitle"></h2><div class="zoo-game-dialog-message"></div><input class="zoo-game-dialog-input" type="text"><div class="zoo-game-dialog-actions"><button type="button" data-dialog-cancel>Cancel</button><button type="button" data-dialog-confirm>OK</button></div></div>`;
    document.body.appendChild(overlay);
    return overlay;
}

function showGameDialog({ title='Zoo Curator', message='', inputValue=null, confirmLabel='OK', cancelLabel='Cancel', showCancel=false }={}) {
    const overlay = ensureGameDialogUI();
    const titleEl = overlay.querySelector('#zooGameDialogTitle');
    const messageEl = overlay.querySelector('.zoo-game-dialog-message');
    const input = overlay.querySelector('.zoo-game-dialog-input');
    const confirmButton = overlay.querySelector('[data-dialog-confirm]');
    const cancelButton = overlay.querySelector('[data-dialog-cancel]');
    titleEl.textContent = title;
    messageEl.textContent = String(message ?? '');
    confirmButton.textContent = confirmLabel;
    cancelButton.textContent = cancelLabel;
    cancelButton.hidden = !showCancel;
    input.hidden = inputValue === null;
    if (inputValue !== null) input.value = String(inputValue ?? '');
    overlay.classList.add('visible');

    return new Promise(resolve => {
        let settled = false;
        const finish = value => {
            if (settled) return;
            settled = true;
            overlay.classList.remove('visible');
            confirmButton.removeEventListener('click', onConfirm);
            cancelButton.removeEventListener('click', onCancel);
            overlay.removeEventListener('pointerdown', onBackdrop);
            document.removeEventListener('keydown', onKey);
            resolve(value);
        };
        const onConfirm = () => finish(inputValue === null ? true : input.value);
        const onCancel = () => finish(inputValue === null ? false : null);
        const onBackdrop = event => { if (event.target === overlay && showCancel) onCancel(); };
        const onKey = event => {
            if (event.key === 'Escape' && showCancel) { event.preventDefault(); onCancel(); }
            else if (event.key === 'Enter' && (!input.hidden || document.activeElement !== cancelButton)) { event.preventDefault(); onConfirm(); }
        };
        confirmButton.addEventListener('click', onConfirm);
        cancelButton.addEventListener('click', onCancel);
        overlay.addEventListener('pointerdown', onBackdrop);
        document.addEventListener('keydown', onKey);
        requestAnimationFrame(() => (input.hidden ? confirmButton : input).focus());
    });
}
function showGameNotice(message, title='Zoo Curator') {
    return showGameDialog({ title, message, confirmLabel:'OK' });
}
function showGameConfirm(message, options={}) {
    return showGameDialog({ title:options.title || 'Zoo Curator', message, confirmLabel:options.confirmLabel || 'OK', cancelLabel:options.cancelLabel || 'Cancel', showCancel:true });
}
function showGamePrompt(message, defaultValue='', options={}) {
    return showGameDialog({ title:options.title || 'Zoo Curator', message, inputValue:defaultValue, confirmLabel:options.confirmLabel || 'OK', cancelLabel:options.cancelLabel || 'Cancel', showCancel:true });
}

async function saveRealZooTemplate() {
    if (!state.sandboxMode) {
        showGameNotice('Real zoo templates can only be created from Sandbox mode.');
        return false;
    }
    if (state.realZooDataLoadState !== 'ready') {
        showGameNotice('The real zoo database is still loading. Try again when it has finished.');
        return false;
    }
    const match = matchSandboxZooToRealZoo();
    if (!match.record) {
        showGameNotice(`Could not match “${state.zooName || 'Unnamed Zoo'}” to a real zoo.`);
        return false;
    }
    if (!match.exact) {
        const suggestion = match.record.name;
        const confidence = Math.round(Math.max(0, match.score) * 100);
        if (!(await showGameConfirm(`The zoo name “${state.zooName || 'Unnamed Zoo'}” is not an exact match.\n\nI think this is supposed to be:\n${suggestion}\n\nName similarity: ${confidence}%\n\nSave the template for ${suggestion}?`))) return false;
    }
    const diff = realZooTemplateSpeciesDiff(match.record);
    if (diff.missing.length || diff.added.length) {
        const lines = [`Species mismatch for ${match.record.name}:`];
        if (diff.missing.length) lines.push(`\nMissing from this Sandbox zoo (${diff.missing.length}):\n• ${diff.missing.join('\n• ')}`);
        if (diff.added.length) lines.push(`\nAdded/not in the real-zoo record (${diff.added.length}):\n• ${diff.added.join('\n• ')}`);
        lines.push('\nThe template can still be saved. Missing species will simply have no saved placement; added species will be ignored when this template is used for the real zoo.\n\nSave anyway?');
        if (!(await showGameConfirm(lines.join('\n')))) return false;
    }
    const template = buildRealZooLayoutTemplate(match.record);
    try {
        saveLocalRealZooTemplate(match.record, template);
        downloadRealZooLayoutTemplate(template);
    } catch (error) {
        console.error(error);
        showGameNotice(`Could not save the real zoo template:\n\n${error.message}`);
        return false;
    }
    showGameNotice(`Saved real zoo template for ${match.record.name}.\n\nIt is stored separately from save games in this browser, so deleting the save game will not delete the template. A JSON copy has also been downloaded for assets/data/layouts/${realZooTemplateSlug(match.record.name)}.json.`);
    return true;
}

function applyRealZooLayoutTemplate(record, template) {
    if (!template || !Array.isArray(template.enclosures) || !template.enclosures.length) return false;
    const oldToNew = new Map();
    const newEnclosures = template.enclosures.map(source => {
        const id = state.nextId++;
        oldToNew.set(source.id, id);
        return { ...cloneForSave(source), id };
    });
    const animalsByName = new Map();
    for (const animal of state.animals || []) {
        const key = templateSpeciesName(animal);
        if (!animalsByName.has(key)) animalsByName.set(key, []);
        animalsByName.get(key).push(animal);
        animal.enclosureId = null; animal.slotIndex = null;
    }
    for (const saved of template.animals || []) {
        const animal = animalsByName.get(templateSpeciesName(saved.name))?.shift();
        const enclosureId = oldToNew.get(saved.enclosureId);
        if (!animal || enclosureId == null) continue;
        animal.enclosureId = enclosureId;
        animal.slotIndex = Number.isInteger(saved.slotIndex) ? saved.slotIndex : null;
    }
    state.enclosures = ensureGeneratedEnclosureRotations(newEnclosures);
    state.customAreas = (template.customAreas || []).map(area => ({
        ...cloneForSave(area),
        enclosureIds: (area.enclosureIds || []).map(id => oldToNew.get(id)).filter(id => id != null)
    })).filter(area => area.enclosureIds.length);
    state.handcraftedAreaEvolution = state.customAreas.length > 0;
    state.areaEvolutionBaselineSpecies = state.handcraftedAreaEvolution
        ? (state.animals || []).map(animal => animalDisplayName(animal))
        : [];
    state.generatedAreaMembership = new Map(Object.entries(template.generatedAreaMembership || {}).map(([key,ids]) => [key, new Set((ids || []).map(id => oldToNew.get(id)).filter(id => id != null))]));
    state.generatedAreaOverrides = new Map(Object.entries(template.generatedAreaOverrides || {}));
    state.areaLabelPositions = new Map(Object.entries(template.areaLabelPositions || {}));
    state.suppressedGeneratedAreas = new Map(Object.entries(template.suppressedGeneratedAreas || {}));
    return true;
}

async function saveCurrentGame(slotId = null, options = {}) {
    if (state.historyViewTurn !== null) {
        showGameNotice(uiText('Return to the current turn before saving the game.'));
        return;
    }

    captureTurnSnapshot();

    const slots = loadSaveSlots();
    let existingIndex = slotId
        ? slots.findIndex(slot => slot.id === slotId)
        : -1;

    let name = existingIndex >= 0
        ? slots[existingIndex].name
        : `Save ${slots.length + 1}`;

    const entered = await showGamePrompt(uiText('Name this save game:'), name, { title:'Save Game', confirmLabel:'Save' });
    if (entered === null) return;

    name = entered.trim() || name;

    const record = {
        id: existingIndex >= 0
            ? slots[existingIndex].id
            : `save-${Date.now()}-${classicGameRandom().toString(36).slice(2, 8)}`,
        name,
        zooName: state.zooName,
        turn: state.sandboxMode ? '∞' : state.turn,
        animalCount: state.animals.length,
        enclosureCount: state.enclosures.length,
        savedAt: new Date().toISOString(),
        game: exportCurrentGameState({ compactHistory:true })
    };

    if (existingIndex >= 0) {
        slots[existingIndex] = record;
    } else {
        if (slots.length >= MAX_SAVE_SLOTS) {
            showGameNotice(`You can keep up to ${MAX_SAVE_SLOTS} saved games. Delete or overwrite one first.`);
            return;
        }
        slots.unshift(record);
    }

    try {
        writeSaveSlots(slots);
        renderSaveSlots();
        if (options.alsoRealZooTemplate) await saveRealZooTemplate();
    } catch (error) {
        console.error(error);
        showGameNotice(
            'The browser could not store this save. Its local storage may be full. ' +
            'Delete an older save and try again.'
        );
    }
}

async function loadSavedGame(slotId) {
    const record = loadSaveSlots().find(slot => slot.id === slotId);
    if (!record) return;

    const ok = await showGameConfirm(
        `Load “${record.name}”?\n\nYour current unsaved game will be replaced.`,
        { title:'Load Game', confirmLabel:'Load' }
    );
    if (!ok) return;

    // Loading is transactional from the player's point of view. importGameState()
    // necessarily mutates the live state while migrating/relinking a save, so
    // keep one exact snapshot of the currently running zoo. If any later import
    // step rejects the selected save, restore this snapshot before reporting the
    // error instead of leaving a half-imported zoo on screen.
    const previousGame = exportCurrentGameState();

    try {
        lastAutoResumeTurn = null;
        importGameState(record.game);
        // Make the manually loaded game the browser's new resume point.
        requestAnimationFrame(() => writeAutoResumeSnapshot(true));
        closeSaveLoadMenu();
    } catch (error) {
        console.error(error);

        try {
            importGameState(previousGame);
        } catch (rollbackError) {
            // A snapshot produced by this running build should always be
            // importable. Keep both errors visible in the console if an
            // unexpected runtime failure prevents rollback.
            console.error('Could not restore the game after failed Load:', rollbackError);
        }

        showGameNotice(`Could not load this save:\n\n${error.message}\n\nYour current game has been kept.`);
    }
}

async function deleteSavedGame(slotId) {
    const slots = loadSaveSlots();
    const record = slots.find(slot => slot.id === slotId);
    if (!record) return;
    if (!(await showGameConfirm(`Delete “${record.name}”?`, { title:'Delete Save', confirmLabel:'Delete' }))) return;

    writeSaveSlots(slots.filter(slot => slot.id !== slotId));
    renderSaveSlots();
}

function saveFileSlug(value) {
    return String(value || 'Zoo-Curator-Save')
        .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '') || 'Zoo-Curator-Save';
}


function normaliseImportedSavePayload(raw) {
    const decoded = deserialiseSpecial(raw);

    // Current single-save download format.
    if (decoded?.format === 'ZooCuratorSave' && decoded.save?.game) {
        return decoded.save;
    }

    // Also accept a raw named-save record.
    if (decoded?.game?.state) {
        return decoded;
    }

    // Accept a raw exported game snapshot and wrap it as a named save.
    if (decoded?.state && Array.isArray(decoded.state.enclosures) && Array.isArray(decoded.state.animals)) {
        return {
            id: `import-${Date.now()}`,
            name: decoded.state.zooName || 'Imported Zoo',
            zooName: decoded.state.zooName || 'Imported Zoo',
            turn: decoded.state.sandboxMode ? '∞' : decoded.state.turn,
            animalCount: decoded.state.animals.length,
            enclosureCount: decoded.state.enclosures.length,
            savedAt: new Date().toISOString(),
            game: decoded
        };
    }

    // Older "all saves" exports were arrays. Importing a file should be
    // deterministic: accept it only when it contains exactly one usable save.
    if (Array.isArray(decoded)) {
        const usable = decoded.filter(item => item?.game?.state);
        if (usable.length === 1) return usable[0];
        if (usable.length > 1) {
            throw new Error('This file contains multiple Zoo Curator saves. Please import a single-zoo save file.');
        }
    }

    throw new Error('This is not a recognised Zoo Curator save file.');
}

async function loadImportedSaveDirectly(record, reason='') {
    const previousGame=exportCurrentGameState();
    try {
        lastAutoResumeTurn=null;
        importGameState(record.game);
        requestAnimationFrame(()=>writeAutoResumeSnapshot(true));
        closeSaveLoadMenu();
        const suffix=reason ? ` ${reason}` : '';
        await showGameNotice(`Loaded ${record.zooName || record.name || 'imported zoo'}.${suffix}`);
        return true;
    } catch(error) {
        console.error(error);
        try{importGameState(previousGame);}catch(rollbackError){
            console.error('Could not restore the game after failed imported-save load:',rollbackError);
        }
        await showGameNotice(`Could not load this save:\n\n${error?.message || 'Unknown error'}`);
        return false;
    }
}

async function importSaveFile(file) {
    if (!file) return false;
    let raw;
    try {
        raw = JSON.parse(await file.text());
    } catch (error) {
        showGameNotice('Could not read that save file. Zoo Curator save files must contain valid JSON.');
        return false;
    }

    let record;
    try {
        record = normaliseImportedSavePayload(raw);
    } catch (error) {
        showGameNotice(error?.message || 'That file is not a recognised Zoo Curator save.');
        return false;
    }

    // Validate the minimum portable game shape before writing anything into
    // browser storage. Old lossy saves are intentionally allowed through:
    // importGameState contains the one-time Set/Map/layout/Area migrations.
    const game = record?.game;
    if (!game?.state || !Array.isArray(game.state.enclosures) || !Array.isArray(game.state.animals)) {
        showGameNotice('That save is incomplete: its zoo enclosure/animal state is missing.');
        return false;
    }

    const compactBytes=new Blob([JSON.stringify(serialiseSpecial(record))]).size;
    const DIRECT_IMPORT_THRESHOLD_BYTES=3.5*1024*1024;
    if(compactBytes>DIRECT_IMPORT_THRESHOLD_BYTES){
        return loadImportedSaveDirectly(
            record,
            'This save is too large for reliable browser save storage, so it was loaded directly.'
        );
    }

    const slots = loadSaveSlots();
    const imported = cloneForSave(record);
    imported.id = `save-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    imported.name = imported.name || imported.zooName || game.state.zooName || 'Imported Zoo';
    imported.zooName = imported.zooName || game.state.zooName || imported.name;
    imported.turn = game.state.sandboxMode ? '∞' : (game.state.turn ?? imported.turn ?? 1);
    imported.animalCount = game.state.animals.length;
    imported.enclosureCount = game.state.enclosures.length;
    imported.savedAt = new Date().toISOString();
    imported.importedFromFile = file.name || 'Zoo Curator save';

    slots.unshift(imported);
    try {
        writeSaveSlots(slots);
        renderSaveSlots();
        await showGameNotice(`Imported ${imported.zooName}. You can now load it from Saved Games.`);
        return true;
    } catch (error) {
        // Safari/iOS localStorage is relatively small and a portable zoo can be
        // larger than the remaining quota. Importing the file itself must still
        // work: load it directly rather than failing silently after file selection.
        console.warn('Could not persist imported save; loading it directly instead:', error);
        return loadImportedSaveDirectly(
            imported,
            'The browser did not have enough local save storage to keep an additional copy.'
        );
    }
}

function chooseSaveFileToImport() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,.txt,application/json,text/plain';
    // Do not use display:none/hidden here. iOS Safari can ignore a synthetic
    // click on a hidden file input even when it originates from a user gesture.
    // Keep it mounted and focusable by the picker while visually off-screen.
    input.style.cssText = 'position:fixed;left:-10000px;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
    document.body.appendChild(input);
    input.addEventListener('change', async () => {
        try {
            await importSaveFile(input.files?.[0]);
        } finally {
            input.remove();
        }
    }, { once:true });
    input.addEventListener('cancel', () => input.remove(), { once:true });
    input.click();
}

function downloadSaveRecord(record) {
    if (!record?.game) return false;
    const payload = {
        format: 'ZooCuratorSave',
        version: 1,
        game_version: typeof ZOO_CURATOR_VERSION !== 'undefined' ? ZOO_CURATOR_VERSION : null,
        exportedAt: new Date().toISOString(),
        save: record
    };
    // Downloads must preserve the same Set/Map values as browser saves.
    const blob = new Blob([JSON.stringify(serialiseSpecial(payload), null, 2) + '\n'], { type:'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const date = new Date().toISOString().slice(0, 10);
    link.download = `ZooCurator_${saveFileSlug(record.zooName || record.name)}_${date}.json`;
    document.body.appendChild(link);
    // Keep the Blob URL alive well beyond the synthetic click. Mobile Safari
    // may hand the download to another process after the click returns; revoking
    // it after one second can therefore produce an apparent no-op.
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
    return true;
}

function downloadSavedGame(slotId) {
    const record = loadSaveSlots().find(slot => slot.id === slotId);
    if (!record) {
        showGameNotice('That saved game could not be found.');
        return;
    }
    downloadSaveRecord(record);
}

function downloadCurrentGame() {
    if (state.historyViewTurn !== null) {
        showGameNotice(uiText('Return to the current turn before downloading the save file.'));
        return;
    }
    captureTurnSnapshot();
    const record = {
        id: `export-${Date.now()}`,
        name: state.zooName || 'Zoo Curator Save',
        zooName: state.zooName,
        turn: state.sandboxMode ? '∞' : state.turn,
        animalCount: state.animals.length,
        enclosureCount: state.enclosures.length,
        savedAt: new Date().toISOString(),
        game: exportCurrentGameState()
    };
    downloadSaveRecord(record);
}

function formatSaveDate(iso) {
    try {
        return new Intl.DateTimeFormat(undefined, {
            dateStyle: 'medium',
            timeStyle: 'short'
        }).format(new Date(iso));
    } catch {
        return iso || '';
    }
}

function renderSaveSlots() {
    const list = document.getElementById('saveSlotList');
    if (!list) return;

    const slots = loadSaveSlots();
    list.innerHTML = '';

    if (!slots.length) {
        const empty = document.createElement('div');
        empty.className = 'save-empty';
        empty.textContent = 'No saved games yet.';
        list.appendChild(empty);
        return;
    }

    for (const slot of slots) {
        const row = document.createElement('div');
        row.className = 'save-slot';
        row.innerHTML = `
            <div class="save-slot-info">
                <strong></strong>
                <span class="save-slot-zoo"></span>
                <span class="save-slot-meta"></span>
            </div>
            <div class="save-slot-actions">
                <button type="button" data-action="load">Load</button>
                <button type="button" data-action="download">Download</button>
                <button type="button" data-action="overwrite">Overwrite</button>
                <button type="button" data-action="delete">Delete</button>
            </div>
        `;

        row.querySelector('strong').textContent = slot.name;
        row.querySelector('.save-slot-zoo').textContent =
            `${slot.zooName || 'Unnamed Zoo'} — Turn ${slot.turn || 1}`;
        row.querySelector('.save-slot-meta').textContent =
            `${slot.animalCount || 0} animals · ${slot.enclosureCount || 0} enclosure cards · ${formatSaveDate(slot.savedAt)}`;

        row.querySelector('[data-action="load"]').addEventListener(
            'click', () => loadSavedGame(slot.id)
        );
        row.querySelector('[data-action="download"]').addEventListener(
            'click', () => downloadSavedGame(slot.id)
        );
        row.querySelector('[data-action="overwrite"]').addEventListener(
            'click', () => saveCurrentGame(slot.id)
        );
        row.querySelector('[data-action="delete"]').addEventListener(
            'click', () => deleteSavedGame(slot.id)
        );

        list.appendChild(row);
    }
    queueDocumentLocalisation();
}

function openSaveLoadMenu() {
    if (state.historyViewTurn !== null) return;
    pauseAllHintGlowsForMenu();
    renderSaveSlots();
    const templateButton = document.getElementById('saveRealZooTemplate');
    if (templateButton) templateButton.hidden = !state.sandboxMode;
    document.getElementById('saveLoadOverlay')?.classList.add('visible');
}

function closeSaveLoadMenu() {
    document.getElementById('saveLoadOverlay')?.classList.remove('visible');
    resumeHintGlowsAfterMenu();
}

function normalizePrimaryHeaderControlOrder(){
    const headerLeft=document.getElementById('headerLeft');
    if(!headerLeft)return;
    const saveLoad=document.getElementById('saveLoadButton');
    const newGame=document.getElementById('newGameButton');
    const multiplayerRow=document.getElementById('multiplayerSettingsHeaderRow');
    if(!saveLoad||!newGame||!multiplayerRow)return;

    let stack=document.getElementById('primaryHeaderControlStack');
    if(!stack){
        stack=document.createElement('div');
        stack.id='primaryHeaderControlStack';
        stack.className='primary-header-control-stack';
    }
    // Re-append every time so DOM order itself exactly matches the intended
    // visual order, regardless of earlier legacy insertion rules.
    stack.append(saveLoad);
    stack.append(newGame);
    stack.append(multiplayerRow);
    if(stack.parentNode!==headerLeft){
        headerLeft.insertBefore(stack,headerLeft.firstChild||null);
    }else if(headerLeft.firstChild!==stack){
        headerLeft.insertBefore(stack,headerLeft.firstChild);
    }
}

function ensureSaveLoadUI() {
    if (document.getElementById('saveLoadButton')) return;

    const headerLeft = document.getElementById('headerLeft');
    const optionsButton = document.getElementById('gameOptionsButton');
    const turnDisplay = document.getElementById('turnOrder');

    const button = document.createElement('button');
    button.id = 'saveLoadButton';
    button.type = 'button';
    button.className = 'save-load-button';
    button.textContent = 'Save / Load Game';

    if (headerLeft) {
        // Game Options now lives inside #multiplayerSettingsHeaderRow, so it is
        // no longer a direct child of #headerLeft. insertBefore() may only use
        // a reference node owned by the same parent. Prefer New Game so the
        // existing desktop order remains Save/Load -> New Game -> Multiplayer/Settings.
        const newGameButton = document.getElementById('newGameButton');
        const multiplayerRow = document.getElementById('multiplayerSettingsHeaderRow');
        const candidates = [newGameButton, multiplayerRow, optionsButton, turnDisplay, headerLeft.firstChild];
        const anchor = candidates.find(node => node?.parentNode === headerLeft) || null;
        if (anchor) headerLeft.insertBefore(button, anchor);
        else headerLeft.appendChild(button);
    }

    const overlay = document.createElement('div');
    overlay.id = 'saveLoadOverlay';
    overlay.className = 'save-load-overlay';
    overlay.innerHTML = `
        <div class="save-load-modal">
            <h2>Save / Load Game</h2>
            <p>Saved games are stored in this browser. Each save also keeps its turn-history viewer.</p>
            <div id="saveSlotList" class="save-slot-list"></div>
            <div class="save-load-footer">
                <span style="flex:1 1 auto;"></span>
                <button type="button" id="saveRealZooTemplate" hidden>Save Real Zoo Template</button>
                <button type="button" id="importSaveFile">Import Save File</button>
                <button type="button" id="downloadCurrentGame">Download Current Zoo</button>
                <button type="button" id="saveCurrentGame">Save Current Game</button>
                <button type="button" id="closeSaveLoad">Close</button>
            </div>
        </div>
    `;
    document.body.appendChild(overlay);

    button.addEventListener('click', openSaveLoadMenu);
    overlay.querySelector('#importSaveFile').addEventListener(
        'click', chooseSaveFileToImport
    );
    overlay.querySelector('#downloadCurrentGame').addEventListener(
        'click', downloadCurrentGame
    );
    overlay.querySelector('#saveCurrentGame').addEventListener(
        'click', () => saveCurrentGame()
    );
    overlay.querySelector('#saveRealZooTemplate').addEventListener(
        'click', () => saveCurrentGame(null, { alsoRealZooTemplate:true })
    );
    overlay.querySelector('#closeSaveLoad').addEventListener(
        'click', closeSaveLoadMenu
    );
    overlay.addEventListener('pointerdown', event => {
        if (event.target === overlay) closeSaveLoadMenu();
    });
    normalizePrimaryHeaderControlOrder();
}


function ensureMobileSettingsHub() {
    if (document.getElementById('mobileSettingsButton')) return;

    // This control is phone-only. Desktop keeps the full Save / Load,
    // New Game and Game Options buttons and must never show the cog.
    if (!window.matchMedia('(max-width: 700px)').matches) return;

    const headerLeft = document.getElementById('headerLeft');
    if (!headerLeft) return;

    const button = document.createElement('button');
    button.id = 'mobileSettingsButton';
    button.type = 'button';
    button.className = 'mobile-settings-button';
    button.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20"><path fill="currentColor" d="M19.14 12.94a7.8 7.8 0 0 0 .05-.94 7.8 7.8 0 0 0-.05-.94l2.03-1.58-1.92-3.32-2.39.96a7.3 7.3 0 0 0-1.63-.95L14.87 3h-3.84l-.36 3.17c-.58.24-1.12.56-1.63.95l-2.39-.96-1.92 3.32 2.03 1.58a7.8 7.8 0 0 0-.05.94c0 .32.02.63.05.94l-2.03 1.58 1.92 3.32 2.39-.96c.5.39 1.05.71 1.63.95l.36 3.17h3.84l.36-3.17c.58-.24 1.12-.56 1.63-.95l2.39.96 1.92-3.32-2.03-1.58ZM12.95 15.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7Z"/></svg>`;
    button.title = 'Settings';
    button.setAttribute('aria-label', 'Settings');
    headerLeft.appendChild(button);

    const overlay = document.createElement('div');
    overlay.id = 'mobileSettingsOverlay';
    overlay.className = 'mobile-settings-overlay';
    overlay.innerHTML = `
        <div class="mobile-settings-menu" role="dialog" aria-label="Settings">
            <button type="button" data-mobile-menu="save">Save / Load Game</button>
            <button type="button" data-mobile-menu="new">New Game</button>
            <button type="button" data-mobile-menu="options">Game Options</button>
            <button type="button" data-mobile-menu="history">Trade History</button>
        </div>
    `;
    document.body.appendChild(overlay);

    const close = () => overlay.classList.remove('visible');
    const open = () => {
        if (state.historyViewTurn !== null) return;
        pauseAllHintGlowsForMenu();
        overlay.classList.add('visible');
    };
    const closeAndResume = () => {
        close();
        resumeHintGlowsAfterMenu();
    };

    button.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        if (overlay.classList.contains('visible')) closeAndResume();
        else open();
    });

    overlay.addEventListener('pointerdown', event => {
        if (event.target === overlay) closeAndResume();
    });

    overlay.querySelector('[data-mobile-menu="save"]').addEventListener('click', () => {
        close();
        openSaveLoadMenu();
    });
    overlay.querySelector('[data-mobile-menu="new"]').addEventListener('click', () => {
        close();
        resumeHintGlowsAfterMenu();
        requestNewGame();
    });
    overlay.querySelector('[data-mobile-menu="options"]').addEventListener('click', () => {
        close();
        document.getElementById('gameOptionsButton')?.click();
    });
    overlay.querySelector('[data-mobile-menu="history"]').addEventListener('click', () => {
        close();
        openTradeHistoryMenu();
    });
}


