let pendingMultiplayerZooReset=false;

function showMultiplayerToast(message){
    let toast=document.getElementById('multiplayerToast');
    if(!toast){
        toast=document.createElement('div');
        toast.id='multiplayerToast';
        toast.className='multiplayer-toast';
        document.body.appendChild(toast);
    }
    toast.textContent=String(message||'');
    toast.classList.add('visible');
    clearTimeout(showMultiplayerToast._timer);
    showMultiplayerToast._timer=setTimeout(()=>toast.classList.remove('visible'),1800);
}

async function copyCurrentMultiplayerCode(){
    const code=String(localClassicMatch?.matchId||localMultiplayerBrowserTransport?.matchId||'').trim();
    if(!code)return false;
    let copied=false;
    try{
        await navigator.clipboard.writeText(code);
        copied=true;
    }catch(_){
        try{
            const input=document.createElement('textarea');
            input.value=code;
            input.style.position='fixed';
            input.style.opacity='0';
            document.body.appendChild(input);
            input.select();
            copied=document.execCommand('copy');
            input.remove();
        }catch(__){}
    }
    showMultiplayerToast(copied?'Multiplayer code copied.':`Multiplayer code: ${code}`);
    return copied;
}

function updateMultiplayerHeaderButtonState(){
    const button=document.getElementById('multiplayerHeaderButton');
    if(!button)return;
    const active=!!localClassicMatch;
    button.classList.toggle('is-session-active',active);
    button.title=active?'Multiplayer active — click to copy server code':'Multiplayer';
    button.setAttribute('aria-label',active?'Copy multiplayer code':'Multiplayer');
}

async function handleMultiplayerHeaderButton(){
    if(localClassicMatch){
        await copyCurrentMultiplayerCode();
        return;
    }
    openMultiplayerSetupMenu();
}

function submitCurrentMultiplayerAction(type,payload={}){
    const transport=localMultiplayerBrowserTransport;
    if(transport?.role==='host'){
        return dispatchLocalMultiplayerAction(
            localClassicMatch?.activePlayerId||transport.playerId,type,payload
        );
    }
    return sendLocalMultiplayerBrowserAction(type,payload);
}

function ensureGameOptionsUI() {
    if (document.getElementById('gameOptionsButton')) return;

    const button = document.createElement('button');
    button.id = 'gameOptionsButton';
    button.type = 'button';
    button.textContent = '⚙';
    button.title = 'Game Options';
    button.setAttribute('aria-label','Game Options');
    button.className = 'game-options-button header-settings-button';
    const headerLeft = document.getElementById('headerLeft');
    const turnDisplay = document.getElementById('turnOrder');
    if (headerLeft) {
        const newGameButton = document.createElement('button');
        newGameButton.id = 'newGameButton';
        newGameButton.type = 'button';
        newGameButton.textContent = 'New Game';
        newGameButton.className = 'game-options-button';
        newGameButton.addEventListener('click', requestNewGame);

        const multiplayerButton=document.createElement('button');
        multiplayerButton.id='multiplayerHeaderButton';
        multiplayerButton.type='button';
        multiplayerButton.textContent='Multiplayer';
        multiplayerButton.className='game-options-button multiplayer-header-button';
        multiplayerButton.addEventListener('click',handleMultiplayerHeaderButton);

        const multiplayerSettingsRow=document.createElement('div');
        multiplayerSettingsRow.id='multiplayerSettingsHeaderRow';
        multiplayerSettingsRow.className='multiplayer-settings-header-row';
        multiplayerSettingsRow.append(multiplayerButton,button);
        queueMicrotask(updateMultiplayerHeaderButtonState);

        // turnOrder is not guaranteed to be a direct child of #headerLeft.
        // insertBefore throws when the reference node belongs to a descendant
        // wrapper instead. Use it only when it is an actual child.
        const anchor=turnDisplay?.parentNode===headerLeft
            ? turnDisplay
            : headerLeft.firstChild;
        if(anchor){
            headerLeft.insertBefore(newGameButton,anchor);
            headerLeft.insertBefore(multiplayerSettingsRow,anchor);
        }else{
            headerLeft.append(newGameButton,multiplayerSettingsRow);
        }
    }

    const overlay = document.createElement('div');
    overlay.id = 'gameOptionsOverlay';
    overlay.className = 'game-options-overlay';
    overlay.innerHTML = `
        <div class="game-options-modal">
            <h2>Game Options</h2>
            <p>Choose gameplay preferences and which animal categories may appear.</p>

            <div class="advanced-game-rules" id="advancedGameRules">
                <label class="glow-option">
                    <span>Eligibility glows</span>
                    <input id="optEligibilityGlows" type="checkbox" checked>
                </label>
                <div class="advanced-options-note">Shows yellow upgrade-ready glows and blue trade-interest glows.</div>
                <label class="dark-mode-option">
                    <span>Dark mode</span>
                    <input id="optDarkMode" type="checkbox">
                </label>
                <div class="advanced-options-note">Uses a darker interface while keeping animal and enclosure artwork unchanged.</div>
                <label><span>Zoomed animal card</span><input id="optAnimalPreview" type="checkbox" checked></label>
                <div class="advanced-options-note">Shows the enlarged animal card when hovering or selecting an animal.</div>
                <label><span>Limit animal combinations</span><input id="optAnimalCombinations" type="checkbox" checked></label>
                <div class="advanced-options-note">When disabled, any species may share a multi-animal exhibit regardless of combination data.</div>
                <label><span>Minimum exhibit size</span><input id="optMinimumExhibitSize" type="checkbox" checked></label>
                <div class="advanced-options-note">When disabled, animal size requirements and their husbandry penalties are ignored.</div>
                <label><span>Auto-generated Areas &amp; Zones</span><input id="optAutoGeneratedAreasZones" type="checkbox" checked></label>
                <div class="advanced-options-note">Automatically recognises and rewards geographic Areas, habitat Zones and specialist groupings. Manual Areas remain available when disabled.</div>
                <label><span>Language</span><select id="optAnimalLanguage"><option value="en">English</option><option value="nl">Nederlands</option></select></label>
                <div class="advanced-options-note">Dutch translation covers all animal cards, card categories, menus and on-screen interface text.</div>
                <label class="reward-milestones-option">
                    <span>New enclosure reward milestones</span>
                    <input id="optRewardMilestones" type="text" placeholder="1, 2, 3, 4, 6, 9">
                </label>
                <label>
                    <span>Opponent zoos</span>
                    <select id="optOpponentMode">
                        <option value="fictional">Fictional opponents</option>
                        <option value="real">Real zoo opponents</option>
                    </select>
                </label>
                <label class="trade-frequency-option">
                    <span>Trade offer frequency: <strong id="optTradeFrequencyValue">50%</strong></span>
                    <input id="optTradeFrequency" type="range" min="0" max="100" step="1" value="50">
                </label>
                <div class="advanced-options-note">
                    Trade offer frequency affects both offers made in response to your outgoing card
                    and spontaneous offers made by opponents. 50% is the standard setting.
                </div>
                <div class="advanced-options-note">
                    Milestones are the distinct category counts at each level that award a new enclosure.
                    These settings are saved in this browser and apply when the zoo is regenerated.
                </div>
            </div>

            <div class="advanced-options-title">ANIMAL CATEGORIES</div>
            <div id="categoryOptionList" class="category-option-list"></div>

            <div class="options-actions">
                <button type="button" id="resetGameOptionsChanges">Reset Changes</button>
                <span style="flex:1 1 auto;"></span>
                <button type="button" id="cancelGameOptions">Cancel</button>
                <button type="button" id="applyGameOptions">Apply</button>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    applyDarkMode();

    const list = overlay.querySelector('#categoryOptionList');
    const eligibilityGlowsInput = overlay.querySelector('#optEligibilityGlows');
    const animalLanguageInput = overlay.querySelector('#optAnimalLanguage');
    const darkModeInput = overlay.querySelector('#optDarkMode');
    const animalPreviewInput = overlay.querySelector('#optAnimalPreview');
    // Turning this preference off is immediate: dismiss any preview that is
    // already visible instead of waiting for the Game Options Apply button.
    animalPreviewInput.addEventListener('change', () => {
        if (!animalPreviewInput.checked) {
            cancelHoverPreviewIntent();
            hideHoverPreview(true);
        }
    });

    const animalCombinationsInput = overlay.querySelector('#optAnimalCombinations');
    const minimumExhibitSizeInput = overlay.querySelector('#optMinimumExhibitSize');
    const autoGeneratedAreasZonesInput = overlay.querySelector('#optAutoGeneratedAreasZones');
    const milestonesInput = overlay.querySelector('#optRewardMilestones');
    const opponentModeInput = overlay.querySelector('#optOpponentMode');
    const tradeFrequencyInput = overlay.querySelector('#optTradeFrequency');
    const tradeFrequencyValue = overlay.querySelector('#optTradeFrequencyValue');
    tradeFrequencyInput.addEventListener('input', () => {
        tradeFrequencyValue.textContent = `${Math.round(Number(tradeFrequencyInput.value))}%`;
    });

    for (const category of Object.keys(FOLDERS).sort((a, b) => a.localeCompare(b))) {
        const label = document.createElement('label');
        label.className = 'category-option';
        label.innerHTML = `<input type="checkbox" value="${category}"><span class="category-option-colour"></span><span>${category}</span>`;
        label.querySelector('.category-option-colour').style.background =
            state.categoryColours[category] || CATEGORY_COLOURS[category];
        list.appendChild(label);
    }

    function syncInputs() {
        eligibilityGlowsInput.checked = state.gameOptions.showEligibilityGlows !== false;
        animalLanguageInput.value = state.gameOptions.animalLanguage === 'nl' ? 'nl' : 'en';
        darkModeInput.checked = state.gameOptions.darkMode === true;
        animalPreviewInput.checked = state.gameOptions.showAnimalPreview !== false;
        animalCombinationsInput.checked = state.gameOptions.enforceAnimalCombinations !== false;
        minimumExhibitSizeInput.checked = state.gameOptions.enforceMinimumExhibitSize !== false;
        autoGeneratedAreasZonesInput.checked = state.gameOptions.autoGeneratedAreasZones !== false;
        milestonesInput.value = state.gameOptions.enclosureRewardMilestones.join(', ');
        opponentModeInput.value = state.gameOptions.opponentMode;
        tradeFrequencyInput.value = state.gameOptions.tradeOfferFrequency;
        tradeFrequencyValue.textContent = `${Math.round(state.gameOptions.tradeOfferFrequency)}%`;
        const locked=multiplayerCategoriesLocked();
        for (const cb of list.querySelectorAll('input[type="checkbox"]')) {
            cb.checked = state.activeCategories.has(cb.value);
            cb.disabled=locked;
            cb.closest('.category-option')?.classList.toggle('multiplayer-locked',locked);
            cb.title=locked?'Animal categories are fixed by this multiplayer match.':'';
        }
    }

    function open() {
        pauseAllHintGlowsForMenu();
        syncInputs();
        overlay.classList.add('visible');
    }

    function close() {
        overlay.classList.remove('visible');
        resumeHintGlowsAfterMenu();
    }

    button.addEventListener('click', open);
    overlay.querySelector('#cancelGameOptions').addEventListener('click', close);

    overlay.querySelector('#resetGameOptionsChanges').addEventListener('click', () => {
        // Restore the standard/default option values in the menu only.
        // The player can still Cancel, or press Apply to commit them.
        eligibilityGlowsInput.checked = true;
        animalLanguageInput.value = 'en';
        darkModeInput.checked = false;
        animalPreviewInput.checked = true;
        animalCombinationsInput.checked = true;
        minimumExhibitSizeInput.checked = true;
        autoGeneratedAreasZonesInput.checked = true;
        milestonesInput.value = DEFAULT_GAME_OPTIONS.enclosureRewardMilestones.join(', ');
        opponentModeInput.value = 'real';
        tradeFrequencyInput.value = 50;
        tradeFrequencyValue.textContent = '50%';

        if(!multiplayerCategoriesLocked()){
            for (const cb of list.querySelectorAll('input[type="checkbox"]')) cb.checked = true;
        }else{
            for (const cb of list.querySelectorAll('input[type="checkbox"]'))
                cb.checked=state.activeCategories.has(cb.value);
        }

    });

    overlay.addEventListener('pointerdown', event => {
        if (event.target === overlay) close();
    });

    overlay.querySelector('#applyGameOptions').addEventListener('click', async () => {
        const selected = [...list.querySelectorAll('input[type="checkbox"]:checked')]
            .map(cb => cb.value);

        if (!selected.length) {
            showGameNotice(uiText('At least one animal category must remain enabled.'));
            return;
        }

        const showEligibilityGlows = eligibilityGlowsInput.checked;
        const animalLanguage = animalLanguageInput.value === 'nl' ? 'nl' : 'en';
        const darkMode = darkModeInput.checked;
        const showAnimalPreview = animalPreviewInput.checked;
        const enforceAnimalCombinations = animalCombinationsInput.checked;
        const enforceMinimumExhibitSize = minimumExhibitSizeInput.checked;
        const autoGeneratedAreasZones = autoGeneratedAreasZonesInput.checked;
        const milestones = normalizeRewardMilestones(milestonesInput.value);
        const opponentMode = opponentModeInput.value === 'real' ? 'real' : 'fictional';
        const tradeOfferFrequency = Math.max(
            0,
            Math.min(100, Math.round(Number(tradeFrequencyInput.value)))
        );

        const effectiveSelected=multiplayerCategoriesLocked()
            ? [...state.activeCategories]
            : selected;
        const categoriesSame =
            effectiveSelected.length === state.activeCategories.size &&
            effectiveSelected.every(category => state.activeCategories.has(category));
        const rulesSame =
            showEligibilityGlows === (state.gameOptions.showEligibilityGlows !== false) &&
            animalLanguage === (state.gameOptions.animalLanguage === 'nl' ? 'nl' : 'en') &&
            darkMode === (state.gameOptions.darkMode === true) &&
            showAnimalPreview === (state.gameOptions.showAnimalPreview !== false) &&
            enforceAnimalCombinations === (state.gameOptions.enforceAnimalCombinations !== false) &&
            enforceMinimumExhibitSize === (state.gameOptions.enforceMinimumExhibitSize !== false) &&
            autoGeneratedAreasZones === (state.gameOptions.autoGeneratedAreasZones !== false) &&
            milestones.join(',') === state.gameOptions.enclosureRewardMilestones.join(',') &&
            opponentMode === state.gameOptions.opponentMode &&
            tradeOfferFrequency === state.gameOptions.tradeOfferFrequency;

        if (categoriesSame && rulesSame) {
            close();
            return;
        }

        const milestonesChanged =
            milestones.join(',') !== state.gameOptions.enclosureRewardMilestones.join(',');
        let applyMilestonesRetroactively = false;

        if (milestonesChanged) {
            const oldAwardedCount = (state.awardedProgressMilestones || new Set()).size;
            const expectedCount = progressionRewardKeysForMilestones(milestones).size;
            const difference = expectedCount - oldAwardedCount;

            if (difference !== 0) {
                const actionText = difference > 0
                    ? `This would immediately add ${difference} enclosure card${difference===1?'':'s'} to your current zoo.`
                    : `This would immediately remove ${-difference} enclosure card${difference===-1?'':'s'} from your current zoo, using completely empty enclosures only.`;

                applyMilestonesRetroactively = await showGameConfirm(
                    `The new enclosure milestones change rewards your current zoo would already have earned.

` +
                    `${actionText}

` +
                    `OK = Recalculate the current zoo now
` +
                    `Cancel = Use the new milestones from this point onward`
                );
            }
        }

        if(!multiplayerCategoriesLocked()) state.activeCategories = new Set(selected);
        else applyMultiplayerCategoryRules(localClassicMatch.rules.activeCategories);
        state.gameOptions.showEligibilityGlows = showEligibilityGlows;
        state.gameOptions.animalLanguage = animalLanguage;
        state.gameOptions.darkMode = darkMode;
        state.gameOptions.showAnimalPreview = showAnimalPreview;
        state.gameOptions.enforceAnimalCombinations = enforceAnimalCombinations;
        state.gameOptions.enforceMinimumExhibitSize = enforceMinimumExhibitSize;
        const autoGeneratedAreasZonesChanged =
            autoGeneratedAreasZones !== (state.gameOptions.autoGeneratedAreasZones !== false);
        state.gameOptions.autoGeneratedAreasZones = autoGeneratedAreasZones;
        if(autoGeneratedAreasZonesChanged){
            invalidateConnectedAreaReconciliation();
            renderedConnectedAreaGroups=null;
            renderedConnectedAreaGroupsSignature='';
            stableConnectedAreaGroups=null;
            stableConnectedAreaGroupsSignature='';
            generatedModernGeographicAreas=[];
        }
        if (!showAnimalPreview) {
            cancelHoverPreviewIntent();
            hideHoverPreview(true);
        }
        applyDarkMode(darkMode);
        setTimeout(localizeDocument, 0);
        state.gameOptions.enclosureRewardMilestones = milestones;
        if (milestonesChanged) {
            applyMilestonesToCurrentZoo(milestones, applyMilestonesRetroactively);
        }
        state.gameOptions.opponentMode = opponentMode;
        state.gameOptions.tradeOfferFrequency = tradeOfferFrequency;
        saveGameOptions();

        assignOpponentProfiles();
        renderAll();

        close();
    });
}

function ensurePrestigeBreakdownPopup() {
    let popup = document.getElementById('prestigeBreakdownPopup');
    if (popup) return popup;
    popup = document.createElement('div');
    popup.id = 'prestigeBreakdownPopup';
    popup.style.cssText = 'position:fixed;display:none;z-index:10060;max-width:340px;padding:11px 13px;background:rgba(25,25,25,.97);color:white;border:1px solid rgba(255,255,255,.3);border-radius:8px;box-shadow:0 8px 28px rgba(0,0,0,.45);font-size:12px;line-height:1.45;pointer-events:none;white-space:pre-line;';
    document.body.appendChild(popup);
    return popup;
}
function positionSmallPopup(popup, anchor) {
    const r=anchor.getBoundingClientRect(), pr=popup.getBoundingClientRect();
    let left=Math.min(innerWidth-pr.width-8,r.right+8); if(left<8)left=8;
    let top=Math.min(innerHeight-pr.height-8,r.top); if(top<8)top=8;
    popup.style.left=`${left}px`; popup.style.top=`${top}px`;
}
function prestigeBreakdownText(b) {
    const diff=Math.ceil(b.current)-Math.ceil(b.base), sign=diff>0?'+':'';
    const lines=[`Current prestige: ${Math.ceil(b.current)}`,`Collection prestige: ${Math.ceil(b.base)} (raw ${Math.ceil(b.rawBase ?? b.base)})`,`Difference: ${sign}${diff}`];
    if(b.identityPercent) lines.push(`Collection identity: +${Math.round(b.identityBonus)} (${b.identityPercent}%)`);
    if(b.areaBonusPercent) {
        const d=b.areaDetails||{};
        lines.push(`Areas / speciality exhibits: +${Math.round(b.areaBonus)} (${Number(b.areaBonusPercent.toFixed(2))}% of base)`);
        if(d.recognisedPercent) lines.push(`  Recognised areas: ${Number(d.recognisedPercent.toFixed(2))}%`);
        if(d.customPercent) lines.push(`  Custom areas: ${Number(d.customPercent.toFixed(2))}%`);
    }
    if(b.combinationUnits) lines.push(`Mixed exhibits: +${Math.round(b.combinationBonus)} (${b.combinationUnits}% of base)`);
    if(b.curationPercent) lines.push(`Curation: +${Math.round(b.curationBonus)} (${b.curationPercent}%; ${Math.round((b.curationRatio||0)*100)}% of animals in recognised areas)`);
    if(b.husbandryPenaltyPercent) lines.push(`Husbandry penalty: −${Math.round(b.husbandryPenalty)} (${b.husbandryPenaltyPercent}%)`);
    return lines.join('\n');
}
function unbindPrestigeBreakdownHover(node){
    if(!node)return;
    if(node._prestigeHoverEnter)node.removeEventListener('mouseenter',node._prestigeHoverEnter);
    if(node._prestigeHoverLeave)node.removeEventListener('mouseleave',node._prestigeHoverLeave);
    node._prestigeHoverEnter=null;node._prestigeHoverLeave=null;
    delete node.dataset.prestigeHoverBound;
    node.style.cursor='';
    const p=document.getElementById('prestigeBreakdownPopup');if(p)p.style.display='none';
}
function bindPrestigeBreakdownHover(node, provider) {
    if(!node || node.dataset.prestigeHoverBound==='1') return;
    node.dataset.prestigeHoverBound='1'; node.style.cursor='help';
    node._prestigeHoverEnter=()=>{const p=ensurePrestigeBreakdownPopup();p.textContent=prestigeBreakdownText(provider());p.style.display='block';positionSmallPopup(p,node);};
    node._prestigeHoverLeave=()=>{const p=document.getElementById('prestigeBreakdownPopup');if(p)p.style.display='none';};
    node.addEventListener('mouseenter',node._prestigeHoverEnter);
    node.addEventListener('mouseleave',node._prestigeHoverLeave);
}
function bindTruePrestigeTestingHover(node){
    if(!node||node.dataset.truePrestigeTestingHover==='1')return;
    node.dataset.truePrestigeTestingHover='1';
    let inside=false;
    const hide=()=>{const p=document.getElementById('prestigeBreakdownPopup');if(p)p.style.display='none';};
    const show=e=>{
        if(!inside||!e.ctrlKey){hide();return;}
        const b=zooPrestigeBreakdown();
        const p=ensurePrestigeBreakdownPopup();
        p.textContent=`VISIBLE / PUBLIC PRESTIGE: ${visibleZooPrestige()}\nUNDERLYING CURRENT PRESTIGE: ${trueUnderlyingPrestige()}\n\n${prestigeBreakdownText(b)}\n\nTesting view · release Ctrl to hide`;
        p.style.display='block';positionSmallPopup(p,node);
    };
    node.addEventListener('mouseenter',e=>{inside=true;show(e);});
    node.addEventListener('mousemove',show);
    node.addEventListener('mouseleave',()=>{inside=false;hide();});
    // Ctrl can be pressed/released while the pointer remains stationary.
    node._truePrestigeKeyHandler=e=>{
        if(!inside)return;
        if(e.key==='Control'){
            if(e.type==='keydown')show({ctrlKey:true});
            else hide();
        }
    };
    window.addEventListener('keydown',node._truePrestigeKeyHandler);
    window.addEventListener('keyup',node._truePrestigeKeyHandler);
}

// ============================================================
// REAL ZOO OPPONENTS
// ============================================================
function isRealOpponentMode() {
    return state.gameOptions.opponentMode === 'real';
}

const ZOO_PRESTIGE_BY_LEVEL = Object.freeze({ 1: 1, 2: 4, 3: 12, 4: 36, 5: 144 });
const REAL_ZOO_ANIMAL_SPEC_CACHE = new Map();
let REAL_ZOO_PRESTIGE_CACHE = new WeakMap();
const REAL_ZOO_TRADE_SPEC_CACHE = new WeakMap();
let realZooAnimalSpecCacheReady = false;

// same province, adjacent domestic, adjacent foreign, farther domestic,
// farther Europe. Rows are smoothly interpolated between prestige anchors.
// Early-game locality is intentionally dominant: same-province is the largest
// single band, and farther-domestic already outweighs adjacent-foreign around
// the starting trade-access prestige. Do not invert those two bands.
const REAL_ZOO_GEOGRAPHY_PRESTIGE_CURVE = Object.freeze([
    { prestige: 8,   weights: [70, 20, 10, 0, 0] },
    { prestige: 25,  weights: [60, 25, 12, 8, 2] },
    { prestige: 70,  weights: [50, 28, 16, 18, 8] },
    { prestige: 160, weights: [40, 28, 20, 24, 14] },
    { prestige: 350, weights: [32, 26, 22, 24, 18] },
    { prestige: 700, weights: [22, 21, 20, 21, 20] }
]);

function diminishedCategoryPrestige(raw) {
    const value = Math.max(0, Number(raw) || 0);
    return Math.min(value, 200)
        + Math.max(0, Math.min(value - 200, 200)) * 0.50
        + Math.max(0, Math.min(value - 400, 200)) * 0.25
        + Math.max(0, value - 600) * 0.10;
}
function collectionPrestigeDetails() {
    const rawByCategory = new Map();
    const speciesByCategory = new Map();
    for (const animal of state.animals || []) {
        if (!animal || animal.enclosureId === null) continue;
        const category = animal.category || 'Other';
        rawByCategory.set(category, (rawByCategory.get(category) || 0) + (ZOO_PRESTIGE_BY_LEVEL[Number(animal.level)] || 0));
        if (!speciesByCategory.has(category)) speciesByCategory.set(category, new Set());
        speciesByCategory.get(category).add(animalDatabaseKey(animal.filename));
    }
    const raw = [...rawByCategory.values()].reduce((a,b)=>a+b,0);
    const adjustedByCategory = new Map([...rawByCategory].map(([category,value]) => [category,diminishedCategoryPrestige(value)]));
    const adjusted = [...adjustedByCategory.values()].reduce((a,b)=>a+b,0);
    let dominantCategory = null, dominantRaw = 0;
    for (const [category,value] of rawByCategory) if (value > dominantRaw) { dominantCategory=category; dominantRaw=value; }
    const share = raw > 0 ? dominantRaw / raw : 0;
    const dominantSpecies = dominantCategory ? (speciesByCategory.get(dominantCategory)?.size || 0) : 0;
    // A specialist identity must have genuine depth; a tiny collection cannot
    // earn a large percentage simply because all of its cards share a category.
    const depthQualified = dominantRaw >= 150 && dominantSpecies >= 8;
    let identityPercent = 0;
    if (depthQualified) {
        if (share >= .80) identityPercent = 40;
        else if (share >= .70) identityPercent = 30;
        else if (share >= .55) identityPercent = 20;
        else if (share >= .40) identityPercent = 10;
    }
    return { raw, adjusted, rawByCategory, adjustedByCategory, dominantCategory, share, dominantSpecies, identityPercent };
}
function baseZooPrestige() {
    return collectionPrestigeDetails().adjusted;
}

// Area prestige rewards structure, but recognised game-generated Areas/Houses
// are deliberately worth much more than arbitrary player labels. All values are
// percentage points of BASE prestige; they never compound with one another.
function prestigeAreaBonusDetails() {
    const recognisedGroups = mergeCompletelyOverlappingAreaGroups(connectedEnclosureThemeGroups());
    const recognised = [];
    const recognisedSignatures = new Set();
    let recognisedPercent = 0;

    for (const group of recognisedGroups) {
        const count = new Set(group.enclosures.map(e => e.id)).size;
        if (!count) continue;
        const sig = areaMembershipSignature(group);
        recognisedSignatures.add(sig);
        // A normal two-card recognised Area keeps the old 5% value. Larger
        // Areas gain +1 percentage point per additional enclosure. Very large
        // coherent Areas continue to be rewarded through 15 cards, where the
        // recognised-Area bonus caps at 18% of BASE prestige.
        const percent = Math.min(18, 5 + Math.max(0, count - 2));
        recognisedPercent += percent;
        recognised.push({ title: group.theme?.title || 'Recognised area', count, percent, signature: sig });
    }

    const custom = [];
    let customPercent = 0;
    for (const area of state.customAreas || []) {
        const ids = [...new Set((area.enclosureIds || []).filter(id => state.enclosures.some(e => e.id === id)))];
        if (!ids.length) continue;
        const sig = ids.sort((a,b)=>a-b).join(',');
        // A custom Area that exactly duplicates a recognised Area is presentation
        // only and earns no second bonus for the same footprint.
        if (recognisedSignatures.has(sig)) continue;
        // Custom Areas earn a modest size-sensitive reward: 1% for the first
        // enclosure +0.25% for each extra enclosure, capped at 2.5% per Area.
        const percent = Math.min(2.5, 1 + Math.max(0, ids.length - 1) * 0.25);
        customPercent += percent;
        custom.push({ title: String(area.name || '').trim() || 'Custom area', count: ids.length, percent, signature: sig });
    }
    const tagPercent = 0;

    // Prevent nested/overlapping geography from multiplying prestige without
    // bound. Continents and named regions together cap at +30%; habitat/facility
    // presentation has its own +30% cap. Specials are handled as recognised
    // presentation but remain inside the overall presentation ceiling.
    let geographyPercent = 0, habitatPercent = 0, specialPercent = 0;
    for (const item of recognised) {
        const source = recognisedGroups.find(group => areaMembershipSignature(group) === item.signature);
        const layer = source?.theme?.layer || 'special';
        if (layer === 'geography' || layer === 'subregion') geographyPercent += item.percent;
        else if (layer === 'habitat' || layer === 'facility') habitatPercent += item.percent;
        else specialPercent += item.percent;
    }
    geographyPercent = Math.min(30, geographyPercent);
    habitatPercent = Math.min(30, habitatPercent);
    specialPercent = Math.min(40, specialPercent);
    recognisedPercent = geographyPercent + habitatPercent + specialPercent;
    const totalPercent = Math.min(100, recognisedPercent + customPercent);
    return {
        recognised, custom, tagLocations: 0,
        recognisedPercent, geographyPercent, habitatPercent, specialPercent,
        customPercent, tagPercent, totalPercent
    };
}


function prestigeCombinationBonusUnits() {
    let units = 0;
    for (const enclosure of state.enclosures || []) {
        for (const group of getGroups(enclosure)) {
            const occupants = animalsInEnclosureGroup(enclosure, group, null, false);
            if (occupants.length < 2) continue;
            const species = new Set(occupants.map(animal => animalDatabaseKey(animal.filename)));
            if (species.size < 2 || !animalsFormCompatibilityChain(occupants)) continue;
            units += occupants.length >= 4 ? 5 : occupants.length === 3 ? 3 : 1;
        }
    }
    return units;
}

function zooPrestigeBreakdown() {
    const collection = collectionPrestigeDetails();
    const base = collection.adjusted;
    const identityPercent = collection.identityPercent;
    const identityBonus = base * identityPercent * 0.01;
    const areaDetails = prestigeAreaBonusDetails();
    const areaCount = areaDetails.recognised.length + areaDetails.custom.length;
    const areaBonusPercent = areaDetails.totalPercent;
    const combinationUnits = Math.min(25, prestigeCombinationBonusUnits());
    const problems = allHusbandryProblems();
    const husbandryPenaltyPercent = problems.some(p => p.severe) ? 50 : problems.length ? 25 : 0;
    const areaBonus = base * areaBonusPercent * 0.01;
    const combinationBonus = base * combinationUnits * 0.01;

    // Curation is layout-derived: reward the proportion of the collection that
    // actually sits in a recognised >=2-card area/house. Standalone placement
    // does not count. This lets a carefully organised specialist compete with a
    // broad collection without hard-coding bonuses for named zoos.
    const recognisedGroups = mergeCompletelyOverlappingAreaGroups(connectedEnclosureThemeGroups());
    const curatedEnclosures = new Set(recognisedGroups.flatMap(group => group.enclosures.map(e => e.id)));
    const placedAnimals = (state.animals || []).filter(a => a && a.enclosureId !== null);
    const curatedAnimals = placedAnimals.filter(a => curatedEnclosures.has(a.enclosureId)).length;
    const curationRatio = placedAnimals.length ? curatedAnimals / placedAnimals.length : 0;
    const curationPercent = curationRatio >= .85 ? 15 : curationRatio >= .70 ? 10 : curationRatio >= .50 ? 6 : curationRatio >= .25 ? 3 : 0;
    const curationBonus = base * curationPercent * 0.01;

    const husbandryPenalty = base * husbandryPenaltyPercent * 0.01;
    const current = Math.max(0, base + identityBonus + areaBonus + combinationBonus + curationBonus - husbandryPenalty);
    return { base, rawBase: collection.raw, collection, current, identityPercent, identityBonus, areaCount, areaDetails, areaBonusPercent, areaBonus, combinationUnits, combinationBonus, curationRatio, curationPercent, curationBonus, husbandryPenaltyPercent, husbandryPenalty, problems };
}

function currentZooPrestige() {
    // Prestige is always presented/used as a whole number, rounded UP.
    return Math.ceil(Math.max(0, zooPrestigeBreakdown().current));
}

function trueUnderlyingPrestige(){
    return currentZooPrestige();
}
function normaliseTruePublicPrestige(){
    const underlying=trueUnderlyingPrestige();
    if(state.truePublicPrestige==null||state.truePublicPrestige===''||!Number.isFinite(Number(state.truePublicPrestige))||
       (Number(state.truePublicPrestige)<=0&&underlying>0)){
        // Seed new games, and repair older True saves that persisted the broken
        // zero public-prestige value. From here the visible value can lag normally.
        state.truePublicPrestige=underlying;
        state.truePublicPrestigeLastDate=normaliseTrueCalendarState().date;
    }
    state.truePublicPrestige=Math.max(0,Number(state.truePublicPrestige)||0);
    state.trueGuestAttendanceDays=(state.trueGuestAttendanceDays&&typeof state.trueGuestAttendanceDays==='object'&&!Array.isArray(state.trueGuestAttendanceDays))
        ?state.trueGuestAttendanceDays:{};
    return state.truePublicPrestige;
}
function visibleZooPrestige(){
    if(state.gameMode!=='true'||state.sandboxMode||state.visitingZoo)return currentZooPrestige();
    return Math.max(0,Math.round(normaliseTruePublicPrestige()));
}
function trueGuestAttendanceRawVariation(date){
    // Triangular-ish deterministic noise: most days stay near normal while
    // +/-15% remains possible but uncommon.
    const a=seededRoll(`guest-attendance-a|${state.zooName}|${date}`).roll;
    const b=seededRoll(`guest-attendance-b|${state.zooName}|${date}`).roll;
    return ((a+b)-1)*.15;
}
function trueGuestPreviousDate(date){
    const d=trueDateObject(date);d.setUTCDate(d.getUTCDate()-1);return trueDateString(d);
}
function trueGuestAttendanceVariation(date=normaliseTrueCalendarState().date){
    // Give attendance mild weather/word-of-mouth persistence: 70% of today's
    // own signal plus 30% of yesterday's. It remains deterministic by zoo/date,
    // so reloads never reroll a day and the range stays bounded to +/-15%.
    const today=trueGuestAttendanceRawVariation(date);
    const yesterday=trueGuestAttendanceRawVariation(trueGuestPreviousDate(date));
    return Math.max(.85,Math.min(1.15,1+today*.70+yesterday*.30));
}
function trueGuestAttendanceTargetForDate(date=normaliseTrueCalendarState().date){
    state.trueGuestAttendanceDays=(state.trueGuestAttendanceDays&&typeof state.trueGuestAttendanceDays==='object'&&!Array.isArray(state.trueGuestAttendanceDays))
        ?state.trueGuestAttendanceDays:{};
    if(Number.isFinite(Number(state.trueGuestAttendanceDays[date])))return Number(state.trueGuestAttendanceDays[date]);
    const underlying=trueUnderlyingPrestige();
    // Snapshot today's demand on first access. Zoo changes later in the same
    // day affect tomorrow's attendance rather than retroactively rerolling today.
    const eventAttendance=trueEventModifierProduct('attendance-multiplier',{date});
    const target=Math.max(0,Math.round(underlying*trueGuestAttendanceVariation(date)*eventAttendance));
    state.trueGuestAttendanceDays[date]=target;
    // Keep only recent cached days.
    const keys=Object.keys(state.trueGuestAttendanceDays).sort();
    while(keys.length>45)delete state.trueGuestAttendanceDays[keys.shift()];
    return target;
}
function trueApplyPublicPrestigeForCompletedDay(date,entered,target){
    if(state.gameMode!=='true'||state.sandboxMode||state.visitingZoo)return visibleZooPrestige();
    const underlying=trueUnderlyingPrestige();
    let shown=normaliseTruePublicPrestige();
    const gap=underlying-shown;
    if(Math.abs(gap)<.01){
        state.truePublicPrestige=underlying;
        if(state.trueEnclosureBuilder)trueEnclosureCellCapacity?.();
        trueEvaluateLandExpansionUnlocks?.();
        refreshTrueEnclosureCapacityBadge?.();
        return visibleZooPrestige();
    }
    const expected=Math.max(1,Number(target)||trueGuestAttendanceTargetForDate(date)||1);
    const exposure=Math.max(0,Math.min(1.35,(Number(entered)||0)/expected));
    // Visitor exposure controls how quickly public reputation discovers the
    // hidden target. Rising reputation travels a little faster than decline.
    // Publicity/press events can change how quickly the outside world catches up
    // with the zoo's underlying quality without changing that underlying prestige.
    const publicityCatchup=trueEventModifierProduct('public-prestige-catchup-multiplier',{date});
    const rate=(gap>0?.16:.11)*exposure*publicityCatchup;
    let move=gap*rate;
    if(exposure>0&&Math.abs(move)<.35)move=Math.sign(gap)*Math.min(Math.abs(gap),.35);
    shown+=move;
    if((gap>0&&shown>underlying)||(gap<0&&shown<underlying))shown=underlying;
    state.truePublicPrestige=shown;
    state.truePublicPrestigeLastDate=String(date||'');
    if(state.trueEnclosureBuilder)trueEnclosureCellCapacity?.();
    trueEvaluateLandExpansionUnlocks?.();
    refreshTrueEnclosureCapacityBadge?.();
    return visibleZooPrestige();
}

function updateHighestZooPrestige() {
    const prestige=(state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo)
        ?visibleZooPrestige()
        :currentZooPrestige();
    state.highestZooPrestige = Math.max(Number(state.highestZooPrestige) || 0, prestige);
    return state.highestZooPrestige;
}

// Trading gets a temporary early-game prestige head start so a new zoo has a
// useful pool of potential partners immediately. The boost starts at 150 and
// is gradually replaced by earned prestige, disappearing completely at 500.
// This value is ONLY for real-zoo trade matching; displayed/actual prestige
// and every other prestige-dependent system continue to use the real value.
function playerTradeAccessPrestige(actualPrestige = currentZooPrestige()) {
    const actual = Math.max(0, Number(actualPrestige) || 0);
    const STARTING_TRADE_PRESTIGE = 150;
    const FULL_CONVERGENCE_PRESTIGE = 500;

    if (actual >= FULL_CONVERGENCE_PRESTIGE) return actual;

    const remainingStarterBoost = STARTING_TRADE_PRESTIGE *
        (1 - actual / FULL_CONVERGENCE_PRESTIGE);
    return actual + remainingStarterBoost;
}

function interpolatedPrestigeWeights(curve, prestige = currentZooPrestige()) {
    if (prestige <= curve[0].prestige) return [...curve[0].weights];
    const last = curve[curve.length - 1];
    if (prestige >= last.prestige) return [...last.weights];

    for (let i = 1; i < curve.length; i++) {
        const upper = curve[i];
        if (prestige > upper.prestige) continue;
        const lower = curve[i - 1];
        const span = upper.prestige - lower.prestige;
        const fraction = span > 0 ? (prestige - lower.prestige) / span : 0;
        return lower.weights.map((weight, index) =>
            weight + (upper.weights[index] - weight) * fraction
        );
    }
    return [...last.weights];
}

function realZooRecordsAvailable() {
    // Trade partner prestige/proximity selection must use the same complete
    // startup prestige layer as All Zoos. Do not seed a cache from transient
    // animal-base fallback values while layouts are still loading.
    if(state.realZooDataLoadState!=='ready') return [];
    const playerSource = realZooHoldingKey(state.realZooPlayerRecordName || '');
    return (state.realZooData?.zoos || []).filter(zoo =>
        Array.isArray(zoo.animals) && zoo.animals.length &&
        (!playerSource || realZooHoldingKey(zoo) !== playerSource)
    );
}

// return only real zoos that can possibly participate in a trade for
// this outgoing card. The expensive holdings/category/level scan was done
// offline and embedded in real_zoo_opponents.json. Dynamic rules are still checked later.
function realZooRecordsAvailableForTrade(wantedAnimal) {
    const index = state.realZooTradeIndex;
    if (!wantedAnimal || !index || !state.realZooRecordByStaticId?.size) {
        return realZooRecordsAvailable();
    }

    // the embedded index contains only the Turn-0 shortlist for this outgoing
    // category/level. It never replaces current zoo holdings. Any zoo whose
    // holdings changed during this game is merged back into the shortlist and
    // is then checked against its live session holdings by realZooCanTradeFor()
    // and realZooTradeAnimals(). This keeps Trade History/current-collection
    // popups fully dynamic while preserving the fast static starting index.
    const key = `${wantedAnimal.category}|${Number(wantedAnimal.level) || 0}`;
    const ids = index.candidates_by_outgoing?.[key] || [];
    const records = ids
        .map(id => state.realZooRecordByStaticId.get(Number(id)))
        .filter(record => record && Array.isArray(record.animals) && record.animals.length);

    const seen = new Set(records.map(record => realZooHoldingKey(record)));
    for (const dirtyName of state.realZooTradeDirtyZoos || []) {
        if (seen.has(dirtyName)) continue;
        const record = (state.realZooData?.zoos || []).find(item =>
            realZooHoldingKey(item) === dirtyName
        );
        if (record) {
            records.push(record);
            seen.add(dirtyName);
        }
    }
    return records;
}

function normaliseGeographyPart(value) {
    return String(value || '')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function provinceGraphKey(country, province) {
    return `${String(country || '').trim()}|${String(province || '').trim()}`;
}

function resolveProvinceGraphKey(country, province) {
    const exact = provinceGraphKey(country, province);
    const graph = state.provinceConnections?.provinces || {};
    if (graph[exact]) return exact;

    const aliases = state.provinceConnections?.aliases || {};
    if (aliases[exact] && graph[aliases[exact]]) return aliases[exact];

    const wantedCountry = normaliseGeographyPart(country);
    const wantedProvince = normaliseGeographyPart(province);
    const normalisedAlias = Object.entries(aliases).find(([alias]) => {
        const split = String(alias).split('|');
        return normaliseGeographyPart(split.shift()) === wantedCountry &&
            normaliseGeographyPart(split.join('|')) === wantedProvince;
    });
    if (normalisedAlias && graph[normalisedAlias[1]]) return normalisedAlias[1];

    return Object.keys(graph).find(key => {
        const node = graph[key] || {};
        return normaliseGeographyPart(node.country) === wantedCountry &&
            normaliseGeographyPart(node.province) === wantedProvince;
    }) || '';
}

function provinceGraphDistance(fromCountry, fromProvince, toCountry, toProvince) {
    const from = resolveProvinceGraphKey(fromCountry, fromProvince);
    const to = resolveProvinceGraphKey(toCountry, toProvince);
    if (!from || !to) return Number.POSITIVE_INFINITY;
    if (from === to) return 0;

    const cacheKey = `${from}->${to}`;
    if (state.provinceDistanceCache.has(cacheKey)) {
        return state.provinceDistanceCache.get(cacheKey);
    }

    const graph = state.provinceConnections?.provinces || {};
    const queue = [{ key: from, distance: 0 }];
    const visited = new Set([from]);
    while (queue.length) {
        const current = queue.shift();
        for (const neighbour of graph[current.key]?.neighbours || []) {
            if (visited.has(neighbour) || !graph[neighbour]) continue;
            const distance = current.distance + 1;
            if (neighbour === to) {
                state.provinceDistanceCache.set(cacheKey, distance);
                state.provinceDistanceCache.set(`${to}->${from}`, distance);
                return distance;
            }
            visited.add(neighbour);
            queue.push({ key: neighbour, distance });
        }
    }
    state.provinceDistanceCache.set(cacheKey, Number.POSITIVE_INFINITY);
    return Number.POSITIVE_INFINITY;
}

function realZooGeographyBand(record) {
    const sameCountry = normaliseGeographyPart(record?.country) ===
        normaliseGeographyPart(state.zooCountry);
    const playerProvinceKey = resolveProvinceGraphKey(
        state.zooCountry,
        state.zooProvince
    );
    const recordProvinceKey = resolveProvinceGraphKey(
        record?.country,
        record?.province
    );
    const sameProvince = sameCountry && playerProvinceKey &&
        playerProvinceKey === recordProvinceKey;
    if (sameProvince) return 0;

    const distance = provinceGraphDistance(
        state.zooCountry,
        state.zooProvince,
        record?.country,
        record?.province
    );
    if (distance === 1) return sameCountry ? 1 : 2;
    return sameCountry ? 3 : 4;
}

function realZooRelationshipLabel(record) {
    if (!record?.country) return '';
    const sameCountry = normaliseGeographyPart(record.country) ===
        normaliseGeographyPart(state.zooCountry);
    if (!sameCountry) return 'Foreign';

    const playerProvince = resolveProvinceGraphKey(state.zooCountry, state.zooProvince);
    const zooProvince = resolveProvinceGraphKey(record.country, record.province);
    const sameProvince = playerProvince && zooProvince
        ? playerProvince === zooProvince
        : Boolean(record.province && state.zooProvince) &&
            normaliseGeographyPart(record.province) === normaliseGeographyPart(state.zooProvince);
    if (sameProvince) return 'Local';
    return 'National';
}

function realZooLocationLines(record, includeRelationship = false) {
    if (!record) return [];
    const relationship = includeRelationship
        ? realZooRelationshipLabel(record)
        : '';
    const lines = [
        `Country: ${record.country || 'Unknown'}`,
        `Province: ${record.province || 'Unknown'}${relationship ? ` (${relationship})` : ''}`
    ];
    return lines;
}

function weightedIndex(weights, roll = Math.random()) {
    const safe = weights.map(weight => Math.max(0, Number(weight) || 0));
    const total = safe.reduce((sum, weight) => sum + weight, 0);
    if (total <= 0) return -1;
    let cursor = Math.max(0, Math.min(0.999999999, roll)) * total;
    for (let index = 0; index < safe.length; index++) {
        cursor -= safe[index];
        if (cursor < 0) return index;
    }
    return safe.length - 1;
}

function ensureRealZooAnimalSpecCache() {
    if (realZooAnimalSpecCacheReady) return;
    REAL_ZOO_ANIMAL_SPEC_CACHE.clear();
    for (const category of Object.keys(FOLDERS)) {
        for (let level = 1; level <= 5; level++) {
            for (const filename of levelFiles(category, level)) {
                const key = String(filename || '')
                    .replace(/\.png$/i, '')
                    .trim()
                    .toLowerCase();
                if (!key || REAL_ZOO_ANIMAL_SPEC_CACHE.has(key)) continue;
                REAL_ZOO_ANIMAL_SPEC_CACHE.set(key, { category, level, filename });
            }
        }
    }
    realZooAnimalSpecCacheReady = true;
}

function realZooAnimalSpecByName(name) {
    ensureRealZooAnimalSpecCache();
    const wanted = String(name || '').replace(/\.png$/i, '').trim().toLowerCase();
    return wanted ? REAL_ZOO_ANIMAL_SPEC_CACHE.get(wanted) || null : null;
}

function realZooAnimalLevelByName(name) {
    return Number(realZooAnimalSpecByName(name)?.level) || 0;
}

function realZooOriginalPrestige(record) {
    if (!record || typeof record !== 'object') return 0;
    return (Array.isArray(record.animals) ? record.animals : []).reduce((total,name)=>
        total + (ZOO_PRESTIGE_BY_LEVEL[realZooAnimalLevelByName(name)] || 0), 0);
}
function realZooStartingPrestige(record) {
    if (!record || typeof record !== 'object') return 0;
    // Gameplay "Original" means the zoo's prestige at world start, after its
    // pregenerated layout, Areas, combinations, identity and curation modifiers
    // have all been applied. Keep this baseline frozen even after the zoo is
    // visited or its holdings change through trades.
    const pregenerated=pregeneratedRealZooLayout(record);
    const starting=Number(pregenerated?.prestige?.current);
    if(Number.isFinite(starting))return Math.ceil(Math.max(0,starting));
    // Legacy/custom layouts without a pregenerated prestige summary retain the
    // old animal-base fallback rather than inventing a starting score.
    return realZooOriginalPrestige(record);
}

function realZooStoredPrestigeSummary(record) {
    // A materialised/visited zoo has the newest exact score. Prefer that over
    // the static template so All Zoos reflects current prestige after changes.
    const liveKey=realZooVisitLayoutKey(record);
    const exactLive=liveKey ? realZooLivePrestige.get(liveKey) : null;
    if(exactLive && Number.isFinite(Number(exactLive.current))) return exactLive;
    const live=liveKey ? (realZooVisitLayouts.get(liveKey) || (state.gameMode==='true' ? trueWorldZooState(record,{create:false})?.liveLayout : null)) : null;
    if(live?.prestige) return live.prestige;
    // Handcrafted committed/local templates override the one-time generated
    // base layout. Pregenerated records written by the offline generator carry
    // the same prestige summary inside pregenerated_layout.prestige.
    const layout = authoritativeRealZooLayout(record);
    // A handcrafted/local layout may intentionally override geometry without a
    // freshly generated prestige summary. Never let that hide the canonical
    // pregenerated current score that is available from game start.
    const pregenerated = pregeneratedRealZooLayout(record);
    const candidates=[layout?.prestige,pregenerated?.prestige,record?.layout_prestige];
    return candidates.find(summary=>summary&&Number.isFinite(Number(summary.current)))||null;
}
function realZooPrestige(record) {
    if (!record || typeof record !== 'object') return 0;
    // While this exact zoo is open, the rendered state contains the authoritative
    // live layout and modifiers. Never substitute its static database prestige.
    if (state.visitingZoo && realZooVisitLayoutKey(record)===realZooVisitLayoutKey(state.visitingZoo.name)) return currentZooPrestige();
    const original = realZooOriginalPrestige(record);
    const currentNames = realZooSessionAnimalNames(record);
    const holdingsChanged = currentNames.length !== (record.animals || []).length ||
        currentNames.some((name,index) => templateSpeciesName(name) !== templateSpeciesName(record.animals?.[index]));
    const summary = realZooStoredPrestigeSummary(record);
    // Before an opponent's holdings change, its canonical layout score is exact.
    // After trading, preserve the canonical layout percentage modifiers while
    // applying them to the new animal base until that zoo is next materialised.
    const currentBase = currentNames.reduce((total,name)=> total + (ZOO_PRESTIGE_BY_LEVEL[realZooAnimalLevelByName(name)] || 0), 0);
    if (summary) {
        if (!holdingsChanged && Number.isFinite(Number(summary.current))) return Math.ceil(Math.max(0,Number(summary.current)));
        const pct=Number.isFinite(Number(summary.total_modifier_percent))
            ? Number(summary.total_modifier_percent)
            : (Number(summary.identity_bonus_percent)||0)+(Number(summary.area_bonus_percent)||0)+
              (Number(summary.combination_bonus_percent)||0)+(Number(summary.curation_bonus_percent)||0)-
              (Number(summary.husbandry_penalty_percent)||0);
        return Math.ceil(Math.max(0,currentBase*(1+pct/100)));
    }
    return Math.ceil(Math.max(0,currentBase));
}
function realZooPrestigeBreakdown(record) {
    const originalBase=realZooOriginalPrestige(record);
    const currentBase=realZooSessionAnimalNames(record).reduce((total,name)=>
        total+(ZOO_PRESTIGE_BY_LEVEL[realZooAnimalLevelByName(name)]||0),0);
    const current=realZooPrestige(record), summary=realZooStoredPrestigeSummary(record)||{};
    const areaBonusPercent=Number(summary.area_bonus_percent)||0, combinationUnits=Number(summary.combination_bonus_percent)||0, husbandryPenaltyPercent=Number(summary.husbandry_penalty_percent)||0;
    return {base:currentBase,originalBase,current,areaCount:0,areaBonusPercent,areaBonus:currentBase*areaBonusPercent*.01,combinationUnits,combinationBonus:currentBase*combinationUnits*.01,husbandryPenaltyPercent,husbandryPenalty:currentBase*husbandryPenaltyPercent*.01,problems:[]};
}

function realZooPrestigeWindow(
    actualPrestige = currentZooPrestige(),
    accessPrestige = playerTradeAccessPrestige(actualPrestige)
) {
    const actual = Math.max(0, Number(actualPrestige) || 0);
    const access = Math.max(actual, Number(accessPrestige) || 0);

    // The early-game trade boost expands the TOP of the normal prestige range;
    // it must not shift the entire range upward. The lower edge therefore stays
    // anchored to the player's real prestige, while the upper edge benefits
    // from the temporary access boost. Once actual prestige reaches 500 the
    // boost is gone and this naturally becomes the old symmetric window again.
    const lowerRadius = Math.max(32, 20 + actual * 0.10);
    const upperRadius = Math.max(32, 20 + access * 0.10);

    return {
        centre: actual,
        accessPrestige: access,
        minimum: Math.max(0, actual - lowerRadius),
        maximum: access + upperRadius,
        lowerRadius,
        upperRadius
    };
}

function realZooPrestigeSimilarityWeight(record, window) {
    const difference = Math.abs(realZooPrestige(record) - window.centre);
    // V220.58 split the prestige window into lowerRadius/upperRadius but this
    // helper still read the removed `window.radius`, turning every similarity
    // weight into NaN. Use the appropriate side of the asymmetric window.
    const zooPrestige = realZooPrestige(record);
    const radius = zooPrestige < window.centre
        ? window.lowerRadius
        : Math.max(1, window.maximum - window.centre);
    return Math.max(0.10, 1 - difference / (radius + 1));
}

// Select without replacement. The prestige window is applied first. Geography
// chooses a band independently of how many zoos that band contains, and the
// chosen band is then weighted by prestige similarity. This keeps local zoos
// dominant without letting a province with many records overpower the stated
// geographical percentages.
function selectPrestigeLocationCandidates(candidates, count, seedText = '') {
    const selected = [];
    const actualPrestige=(state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo)
        ?visibleZooPrestige()
        :currentZooPrestige();
    const prestige = playerTradeAccessPrestige(actualPrestige);
    const window = realZooPrestigeWindow(actualPrestige, prestige);
    const geographyWeights = interpolatedPrestigeWeights(
        REAL_ZOO_GEOGRAPHY_PRESTIGE_CURVE,
        prestige
    );
    const remaining = candidates.filter(item => {
        const zooPrestige = realZooPrestige(item.record);
        return zooPrestige >= window.minimum && zooPrestige <= window.maximum;
    });

    while (remaining.length && selected.length < count) {
        // Above 700 prestige, locality gradually stops mattering. Below that,
        // the geography roll is made by band rather than by individual zoo.
        const geographyFade = Math.max(0, Math.min(1, (prestige - 700) / 300));
        const ignoreGeography = seededRoll(
            `${seedText}|geography-fade|${selected.length}`
        ).roll < geographyFade;

        let choicePool = remaining;
        let chosen = null;
        if (ignoreGeography) {
            const weights = choicePool.map(item =>
                realZooPrestigeSimilarityWeight(item.record, window)
            );
            const choiceIndex = weightedIndex(
                weights,
                seededRoll(`${seedText}|prestige-zoo|${selected.length}`).roll
            );
            chosen = choicePool[choiceIndex];
        } else {
            const availableBands = new Set(
                remaining.map(item => realZooGeographyBand(item.record))
            );
            const rollWeights = geographyWeights.map((weight, band) =>
                availableBands.has(band) ? weight : 0
            );
            let chosenBand = weightedIndex(
                rollWeights,
                seededRoll(`${seedText}|geography-band|${selected.length}`).roll
            );

            // A distant domestic zoo is the last normal fallback even when its
            // starting percentage is zero. Farther Europe participates only
            // after the geography curve has explicitly given it weight.
            if (chosenBand < 0) {
                const fallbackOrder = [0, 1, 2, 3];
                if (geographyWeights[4] > 0) fallbackOrder.push(4);
                chosenBand = fallbackOrder.find(band => availableBands.has(band));
            }
            if (!Number.isInteger(chosenBand)) break;

            choicePool = remaining.filter(item =>
                realZooGeographyBand(item.record) === chosenBand
            );
            const weights = choicePool.map(item =>
                realZooPrestigeSimilarityWeight(item.record, window)
            );
            const choiceIndex = weightedIndex(
                weights,
                seededRoll(`${seedText}|prestige-zoo|${selected.length}`).roll
            );
            if (choiceIndex < 0) continue;
            chosen = choicePool[choiceIndex];
        }
        if (!chosen) break;
        selected.push(chosen);
        remaining.splice(remaining.indexOf(chosen), 1);
    }
    return selected;
}

// Same weighted order as selectPrestigeLocationCandidates(), but consume it
// lazily. Autonomous incoming offers only need the FIRST zoo that can make a
// legal offer; building the complete weighted permutation first made a random
// incoming trade an O(n²) foreground operation across the real-zoo database.
function visitPrestigeLocationCandidates(candidates, visit, seedText=''){
    const actualPrestige=(state.gameMode==='true'&&!state.sandboxMode&&!state.visitingZoo)
        ?visibleZooPrestige()
        :currentZooPrestige();
    const prestige=playerTradeAccessPrestige(actualPrestige);
    const window=realZooPrestigeWindow(actualPrestige,prestige);
    const geographyWeights=interpolatedPrestigeWeights(
        REAL_ZOO_GEOGRAPHY_PRESTIGE_CURVE,prestige
    );
    const remaining=candidates.filter(item=>{
        const zooPrestige=realZooPrestige(item.record);
        return zooPrestige>=window.minimum&&zooPrestige<=window.maximum;
    });
    let selectedIndex=0;
    while(remaining.length){
        const geographyFade=Math.max(0,Math.min(1,(prestige-700)/300));
        const ignoreGeography=seededRoll(
            `${seedText}|geography-fade|${selectedIndex}`
        ).roll<geographyFade;
        let choicePool=remaining;
        let chosen=null;
        if(ignoreGeography){
            const weights=choicePool.map(item=>
                realZooPrestigeSimilarityWeight(item.record,window));
            const choiceIndex=weightedIndex(
                weights,seededRoll(`${seedText}|prestige-zoo|${selectedIndex}`).roll);
            chosen=choicePool[choiceIndex];
        }else{
            const availableBands=new Set(
                remaining.map(item=>realZooGeographyBand(item.record)));
            const rollWeights=geographyWeights.map((weight,band)=>
                availableBands.has(band)?weight:0);
            let chosenBand=weightedIndex(
                rollWeights,
                seededRoll(`${seedText}|geography-band|${selectedIndex}`).roll
            );
            if(chosenBand<0){
                const fallbackOrder=[0,1,2,3];
                if(geographyWeights[4]>0)fallbackOrder.push(4);
                chosenBand=fallbackOrder.find(band=>availableBands.has(band));
            }
            if(!Number.isInteger(chosenBand))break;
            choicePool=remaining.filter(item=>
                realZooGeographyBand(item.record)===chosenBand);
            const weights=choicePool.map(item=>
                realZooPrestigeSimilarityWeight(item.record,window));
            const choiceIndex=weightedIndex(
                weights,seededRoll(`${seedText}|prestige-zoo|${selectedIndex}`).roll);
            if(choiceIndex<0){selectedIndex++;continue;}
            chosen=choicePool[choiceIndex];
        }
        if(!chosen)break;
        remaining.splice(remaining.indexOf(chosen),1);
        if(visit(chosen,selectedIndex)===false)return chosen;
        selectedIndex++;
    }
    return null;
}

function firstPrestigeLocationCandidate(candidates,accept,seedText=''){
    let accepted=null;
    visitPrestigeLocationCandidates(candidates,item=>{
        if(!accept(item))return true;
        accepted=item;
        return false;
    },seedText);
    return accepted;
}

function animalFromRealZooName(name) {
    const spec = realZooAnimalSpecByName(name);
    return spec ? {
        id: state.nextId++,
        category: spec.category,
        level: spec.level,
        filename: spec.filename,
        enclosureId: null,
        slotIndex: null,
    } : null;
}

function realZooHoldingKey(recordOrName) {
    return String(
        typeof recordOrName === 'string'
            ? recordOrName
            : recordOrName?.name || ''
    ).trim();
}

function resetRealZooSessionHoldings() {
    state.realZooSessionHoldings = new Map();
    state.realZooTradeDirtyZoos = new Set();

    for (const record of state.realZooData?.zoos || []) {
        if (!record?.name) continue;
        REAL_ZOO_TRADE_SPEC_CACHE.delete(record);
        REAL_ZOO_PRESTIGE_CACHE.delete(record);
        state.realZooSessionHoldings.set(
            realZooHoldingKey(record),
            Array.isArray(record.animals)
                ? [...record.animals]
                : []
        );
    }
}

function realZooSessionAnimalNames(record) {
    const key = realZooHoldingKey(record);

    if (!state.realZooSessionHoldings.has(key)) {
        state.realZooSessionHoldings.set(
            key,
            Array.isArray(record?.animals)
                ? [...record.animals]
                : []
        );
    }

    return state.realZooSessionHoldings.get(key);
}

function playerOwnedTradeKeys() {
    const keys = new Set();

    for (const animal of state.animals || []) {
        if (animal) keys.add(animalCardKey(animal));
    }

    // Explicitly include the outgoing box as well. In the current object
    // model it normally still exists in state.animals until a trade finishes,
    // but keeping this separate makes the rule robust if that changes later.
    if (state.outgoingOffer) {
        keys.add(animalCardKey(state.outgoingOffer));
    }

    return keys;
}

function realZooTradeSpecs(record) {
    if (!record || typeof record !== 'object') return [];
    if (REAL_ZOO_TRADE_SPEC_CACHE.has(record)) {
        return REAL_ZOO_TRADE_SPEC_CACHE.get(record);
    }

    const result = [];
    const seen = new Set();
    for (const name of realZooSessionAnimalNames(record)) {
        const spec = realZooAnimalSpecByName(name);
        if (!spec) continue;

        const key = animalCardKey(spec);
        if (seen.has(key)) continue;
        seen.add(key);
        result.push(spec);
    }

    REAL_ZOO_TRADE_SPEC_CACHE.set(record, result);
    return result;
}

function realZooTradeAnimals(record, excludePlayerOwned = false, playerKeysOverride = null) {
    // Hot trade-prediction paths may inspect many zoos for the same player
    // state. Reuse one ownership Set instead of rebuilding it for every zoo.
    const playerKeys = excludePlayerOwned && !trueModeAllowsDuplicateSpecies()
        ? (playerKeysOverride || playerOwnedTradeKeys())
        : null;
    const result = [];

    for (const spec of realZooTradeSpecs(record)) {
        // Keep the zoo's holding intact, but never newly transfer a card whose
        // front PNG was unavailable.
                if (playerKeys?.has(animalCardKey(spec))) continue;
        // Real-zoo holdings are previews until a trade is actually accepted.
        // Do not allocate a permanent player-animal ID merely because trading,
        // hover hints, or offer validation inspected this card.
        result.push({
            id: null,
            category: spec.category,
            level: spec.level,
            filename: spec.filename,
            enclosureId: null,
            slotIndex: null
        });
    }

    return result;
}

function realZooHasAnimal(record, animal) {
    if (!record || !animal) return false;
    const wanted = animalCardKey(animal);
    return realZooTradeSpecs(record).some(spec => animalCardKey(spec) === wanted);
}

function fictionalOpponentHasAnimal(index, animal) {
    if (!animal) return false;
    const wanted = animalCardKey(animal);
    return (state.opponentTradeStocks[index] || []).some(held =>
        held && animalCardKey(held) === wanted
    );
}

function opponentAlreadyHasAnimal(index, animal) {
    if (isRealOpponentMode()) {
        return realZooHasAnimal(state.opponentProfiles[index]?.realZooRecord, animal);
    }
    return fictionalOpponentHasAnimal(index, animal);
}

function playerAlreadyHasAnimal(animal) {
    if (trueModeAllowsDuplicateSpecies()) return false;
    return Boolean(animal) && playerOwnedTradeKeys().has(animalCardKey(animal));
}

function updateRealZooSessionAfterTrade(record, incoming, outgoing) {
    if (!record || !incoming || !outgoing) return;

    const names = realZooSessionAnimalNames(record);
    const incomingKey = animalCardKey(incoming);
    const outgoingKey = animalCardKey(outgoing);

    // The animal received by the player leaves this zoo for the remainder
    // of the current game session.
    const kept = names.filter(name => {
        const spec = realZooAnimalSpecByName(name);
        return !spec || animalCardKey(spec) !== incomingKey;
    });

    // The player's traded-away animal now belongs to that real zoo and may
    // appear in its future offers. Do not create duplicate holdings.
    const alreadyHasOutgoing = kept.some(name => {
        const spec = realZooAnimalSpecByName(name);
        return spec && animalCardKey(spec) === outgoingKey;
    });

    if (!alreadyHasOutgoing) {
        kept.push(
            String(outgoing.filename || '')
                .replace(/\.png$/i, '')
                .trim()
        );
    }

    state.realZooSessionHoldings.set(
        realZooHoldingKey(record),
        kept
    );
    state.realZooTradeDirtyZoos.add(realZooHoldingKey(record));
    trueWorldMarkLayoutChanged(record);
    REAL_ZOO_TRADE_SPEC_CACHE.delete(record);
    REAL_ZOO_PRESTIGE_CACHE.delete(record);
}

function realZooProfile(record, index) {
    return {
        index,
        name: record.name,
        country: record.country || '',
        province: record.province || '',
        prestige: realZooPrestige(record),
        favourites: Array.isArray(record.preferred_categories)
            ? record.preferred_categories.filter(Boolean).slice(0, 3)
            : [],
        zooTypes: normaliseZooTypes(record.zoo_types || record.zooTypes || 'general'),
        realZooRecord: record
    };
}

function clearRealOpponentDisplay() {
    if (!isRealOpponentMode()) return;
    state.opponentProfiles = [];
    state.opponentTradeStocks = [];
    state.tradeOffers = [];
    state.selectedTradeOpponent = null;
}

function seededRoll(text) {
    let seed = 2166136261;
    for (const ch of String(text)) {
        seed ^= ch.charCodeAt(0);
        seed = Math.imul(seed, 16777619);
    }
    return { seed: seed >>> 0, roll: (seed >>> 0) / 4294967295 };
}

function tradeFrequencyFactor() {
    return Math.max(0, Math.min(1, Number(state.gameOptions.tradeOfferFrequency) / 100));
}

function tradeOfferWindow() {
    return Math.floor(Math.max(0, state.turn - 1) / 3);
}

function tradeOfferCacheKey(outgoing) {
    return `${isRealOpponentMode() ? 'real' : 'fictional'}|${outgoing.id}|${tradeOfferWindow()}`;
}

function cachedTradeAnimalSpec(animal) {
    if (!animal) return null;
    return {
        category: animal.category,
        level: animal.level,
        filename: animal.filename
    };
}

function resolveCachedTradeAnimal(item) {
    if (!item) return null;

    // Trade offers are still previews here. Materialising a cached offer must
    // not call createAnimal(): that allocates an ID, lineage, and player-card
    // ownership side effects before the player has accepted anything.
    if (item.animalSpec?.category && item.animalSpec?.level && item.animalSpec?.filename) {
        return {
            id: null,
            category: item.animalSpec.category,
            level: Number(item.animalSpec.level),
            filename: cleanFilename(item.animalSpec.filename),
            enclosureId: null,
            slotIndex: null
        };
    }

    // Backward compatibility for old cache entries, also side-effect free.
    if (item.animalName) {
        const spec = realZooAnimalSpecByName(item.animalName);
        return spec ? {
            id: null,
            category: spec.category,
            level: Number(spec.level),
            filename: cleanFilename(spec.filename),
            enclosureId: null,
            slotIndex: null
        } : null;
    }

    return null;
}

function cachedTradeAnimalPreview(item) {
    if (!item) return null;

    if (item.animalSpec?.category && item.animalSpec?.level && item.animalSpec?.filename) {
        return {
            category: item.animalSpec.category,
            level: Number(item.animalSpec.level),
            filename: cleanFilename(item.animalSpec.filename),
            enclosureId: null,
            slotIndex: null
        };
    }

    // Legacy cache compatibility without allocating a player animal id.
    if (item.animalName) {
        const spec = realZooAnimalSpecByName(item.animalName);
        return spec ? {
            category: spec.category,
            level: Number(spec.level),
            filename: cleanFilename(spec.filename),
            enclosureId: null,
            slotIndex: null
        } : null;
    }

    return null;
}

function lockedPlayerTradeOfferIsLive(outgoing, item) {
    if (!outgoing || !item) return false;

    if (isRealOpponentMode()) {
        const record = realZooRecordByName(item.recordName);
        if (!record || realZooHasAnimal(record, outgoing)) return false;

        const animal = cachedTradeAnimalPreview(item);
        if (!animal || playerAlreadyHasAnimal(animal)) return false;
        if (!realZooHasAnimal(record, animal)) return false;
        return tradeIncomingHasDestinationAfterOutgoing(animal, outgoing);
    }

    if (!Number.isInteger(item.opponentIndex)) return false;
    if (item.opponentIndex < 0 || item.opponentIndex >= state.unlockedOpponentCount) return false;
    if (!state.opponentProfiles[item.opponentIndex]) return false;
    if (fictionalOpponentHasAnimal(item.opponentIndex, outgoing)) return false;

    const animal = cachedTradeAnimalPreview(item);
    if (!animal || playerAlreadyHasAnimal(animal)) return false;
    if (!tradeIncomingHasDestinationAfterOutgoing(animal, outgoing)) return false;

    return (state.opponentTradeStocks[item.opponentIndex] || [])
        .some(held => held && animalCardKey(held) === animalCardKey(animal));
}

function lockedPlayerTradeOffersHaveLiveOffer(outgoing, cached) {
    return Array.isArray(cached) && cached.some(item =>
        lockedPlayerTradeOfferIsLive(outgoing, item)
    );
}

function materializeLockedPlayerTradeOffers(outgoing, cached) {
    if (!outgoing || !Array.isArray(cached)) return [];

    if (isRealOpponentMode()) {
        const recordsByName = new Map(
            (state.realZooData?.zoos || []).map(record => [record.name, record])
        );

        return cached.map(item => {
            const record = recordsByName.get(item.recordName);
            if (!record) return null;
            if (realZooHasAnimal(record, outgoing)) return null;

            const animal = resolveCachedTradeAnimal(item);
            if (!animal || !true) return null;
            if (playerAlreadyHasAnimal(animal)) return null;
            if (!realZooHasAnimal(record, animal)) return null;
            // the outgoing animal's old slot is deliberately reserved
            // while it sits in Outgoing Offer. Test the incoming animal against
            // the post-trade zoo, not against the currently reserved zoo.
            if (!tradeIncomingHasDestinationAfterOutgoing(animal, outgoing)) return null;

            return { record, animal };
        }).filter(Boolean);
    }

    return cached.map(item => {
        if (!Number.isInteger(item.opponentIndex)) return null;
        if (item.opponentIndex < 0 || item.opponentIndex >= state.unlockedOpponentCount) return null;
        if (!state.opponentProfiles[item.opponentIndex]) return null;
        if (fictionalOpponentHasAnimal(item.opponentIndex, outgoing)) return null;

        const animal = resolveCachedTradeAnimal(item);
        if (!animal || playerAlreadyHasAnimal(animal)) return null;
        // Same reservation rule for fictional opponents: materialise the
        // already-promised offer using the zoo state AFTER outgoing leaves.
        if (!tradeIncomingHasDestinationAfterOutgoing(animal, outgoing)) return null;

        const stillHeld = (state.opponentTradeStocks[item.opponentIndex] || [])
            .some(held => held && animalCardKey(held) === animalCardKey(animal));

        return stillHeld ? { opponentIndex: item.opponentIndex, animal } : null;
    }).filter(Boolean);
}


function cloneCachedOffers(offers) {
    return (offers || []).map(item => ({ ...item }));
}

function cachedPlayerTradeOffers(outgoing) {
    const key = tradeOfferCacheKey(outgoing);
    const cached = state.tradeOfferCache.get(key);
    if (!cached) return null;
    return cloneCachedOffers(cached);
}

function storePlayerTradeOffers(outgoing, offers) {
    const key = tradeOfferCacheKey(outgoing);
    state.tradeOfferCache.set(key, cloneCachedOffers(offers));

    // Keep the cache small. Entries from older three-turn windows are no
    // longer useful once their window has passed.
    const currentWindow = tradeOfferWindow();
    for (const existingKey of state.tradeOfferCache.keys()) {
        const parts = String(existingKey).split('|');
        const windowNumber = Number(parts[parts.length - 1]);
        if (Number.isFinite(windowNumber) && windowNumber < currentWindow - 1) {
            state.tradeOfferCache.delete(existingKey);
        }
    }
}

function seededShuffle(items, seedText) {
    return [...items]
        .map((item, index) => {
            const { seed } = seededRoll(`${seedText}|${index}|${item?.record?.name || item?.opponentIndex || ''}`);
            return { item, seed };
        })
        .sort((a, b) => a.seed - b.seed)
        .map(entry => entry.item);
}

function generateRealZooTradeOffers(outgoing, pendingEmergencyTrade = null) {
    const emergency = pendingEmergencyTrade || emergencyTradeForAnimal(outgoing);

    if (emergency) {
        const selected = [{
            record: emergency.record,
            animal: emergency.animal
        }];

        // Emergency offers are deliberately not cached. Private Pet Trade
        // exists only while the deadlock requires it.
        state.opponentProfiles = selected.map(
            (item, index) => realZooProfile(item.record, index)
        );
        state.opponentTradeStocks = selected.map(
            item => realZooTradeAnimals(item.record, true)
        );
        state.tradeOffers = [{
            opponentIndex: 0,
            animal: emergency.animal
        }];
        state.selectedTradeOpponent = 0;
        renderTrade();
        return;
    }

    // use the exact same prediction/materialisation path as the blue
    // trade-interest glow. If a card glows, dropping that card is therefore
    // guaranteed to expose the same currently-valid offers.
    const locked = predictedPlayerTradeOffers(outgoing);
    const restored = materializeLockedPlayerTradeOffers(outgoing, locked);

    state.opponentProfiles = restored.map((item, index) =>
        realZooProfile(item.record, index)
    );
    state.opponentTradeStocks = restored.map(item =>
        realZooTradeAnimals(item.record, true)
    );
    state.tradeOffers = restored.map((item, index) => ({
        opponentIndex: index,
        animal: item.animal
    }));
    state.selectedTradeOpponent = state.tradeOffers.length ? 0 : null;

    renderTrade();
    // Offer state is complete now. The rendered <img> elements load normally;
    // preloading is only a background cache warm-up and must never delay the UI.
    preloadAnimals(state.tradeOffers.map(offer => offer.animal));
}

function createRealAutonomousOpponentOffer() {
    if (localClassicMatch && humanTradeBlocksAITrading()) return false;
    if (state.outgoingOffer || state.autonomousTradeOffer) return false;

    // The same slider controls spontaneous real-zoo offers.
    if (Math.random() > tradeFrequencyFactor()) return false;

    const records=realZooRecordsAvailable();
    // Everything below is read-only candidate inspection. Compute values that
    // are invariant for the whole pass once.
    const playerKeys=playerOwnedTradeKeys();
    const highestPlayerLevel=Math.max(1,...state.playerLevelsSeen);
    let selectedPossible=null;

    const selectedItem=firstPrestigeLocationCandidate(
        records.map(record=>({record})),
        item=>{
            const record=item.record;
            const profile=realZooProfile(record,0);
            const incomingPool=realZooTradeAnimals(record,true,playerKeys).filter(incoming=>
                incoming.level<=highestPlayerLevel &&
                (trueModeAllowsDuplicateSpecies()||!playerKeys.has(animalCardKey(incoming)))
            );
            if(!incomingPool.length)return false;

            const outgoingByLevel=new Map();
            for(const outgoing of state.animals||[]){
                if(
                    !profile.favourites.includes(outgoing.category) ||
                    realZooHasAnimal(record,outgoing)
                )continue;
                const level=Number(outgoing.level)||1;
                let list=outgoingByLevel.get(level);
                if(!list){list=[];outgoingByLevel.set(level,list);}
                list.push(outgoing);
            }
            if(!outgoingByLevel.size)return false;

            const possible=[];
            for(const incoming of incomingPool){
                const outgoingCandidates=outgoingByLevel.get(Number(incoming.level)||1);
                if(!outgoingCandidates?.length)continue;
                for(const outgoing of outgoingCandidates){
                    if(tradeIncomingHasDestinationAfterOutgoing(incoming,outgoing)){
                        possible.push(incoming);
                        break;
                    }
                }
            }
            if(!possible.length)return false;
            selectedPossible={record,possible};
            return true;
        },
        `real-autonomous-record-order|${state.turn}`
    );

    if(!selectedItem||!selectedPossible)return false;
    const {record,possible}=selectedPossible;
    const animal=weightedRandomItem(
        possible,
        candidate=>animalZooTypeWeight(
            candidate,
            record.zoo_types||record.zooTypes||'general',
            'trade'
        )
    );
    state.opponentProfiles=[realZooProfile(record,0)];
    state.opponentTradeStocks=[possible];
    state.autonomousTradeOffer={
        opponentIndex:0,
        animal,
        offeredTurn:state.turn,
        expiresTurn:state.turn+3
    };
    state.selectedTradeOpponent=0;
    state.tradeOffers=[];
    renderTrade();
    return true;
}


// Public multiplayer trade board. Each zoo owns one listing; listings and AI
// offers coexist and proposals are pairwise, so simultaneous players never
// seize a single global trade slot.
function reconcilePublicTradeProposalsWithListings(){
    if(!localClassicMatch||!Array.isArray(localClassicMatch.pendingPlayerTrades))return;
    // Do NOT infer human-trade validity from the public listing board here.
    // Direct visit-based proposals are intentionally private and may reference
    // animals that were never publicly listed. The authoritative server owns
    // cancellation/invalidation when an animal becomes unavailable and sends
    // that terminal trade state to both participants.
    //
    // The old client-side listing comparison immediately marked every valid
    // private visit proposal `invalid` as soon as the public-listing broadcast
    // arrived, making the new direct-trade workflow disappear before Player 2
    // could act on it.
    if(selectedHumanTradeProposalId&&!localClassicMatch.pendingPlayerTrades.some(o=>
        String(o?.id)===String(selectedHumanTradeProposalId)&&o?.status==='pending'))
        selectedHumanTradeProposalId=null;
}

function ownServerTradeListing(){
    const id=String(localMultiplayerBrowserTransport?.serverPlayerId||'');
    return multiplayerPublicTradeListings.find(x=>String(x?.playerId||'')===id)||null;
}
let multiplayerTradeListingPublishGeneration=0;
function nextMultiplayerTradeListingIntentGeneration(){
    // Use an epoch-based monotonic value rather than a page-local counter.
    // The server intentionally remembers the newest intent across reconnects,
    // so a refreshed browser must not restart at generation 1.
    multiplayerTradeListingPublishGeneration=Math.max(
        multiplayerTradeListingPublishGeneration+1,
        Date.now()
    );
    return multiplayerTradeListingPublishGeneration;
}
function otherServerTradeListings(){
    const id=String(localMultiplayerBrowserTransport?.serverPlayerId||'');
    const active=localClassicMatch?.activePlayerId;
    return multiplayerPublicTradeListings.filter(x=>{
        if(String(x?.playerId||'')===id)return false;
        const serverOwner=(localMultiplayerBrowserTransport?.serverPlayers||[])
            .find(player=>String(player?.playerId||'')===String(x?.playerId||''));
        if(serverOwner&&serverOwner.connected===false)return false;
        const localId=multiplayerLocalPlayerIdForServerId(x?.playerId);
        const snapshot=localClassicMatch?.players?.[localId]?.snapshot;
        const animals=snapshot?.state?.animals;
        // If an authoritative replica says the card has left that zoo, hide a
        // stale listing immediately rather than offering an impossible trade.
        if(Array.isArray(animals)&&!animals.some(a=>String(a?.id)===String(x?.animalId)))return false;

        // A public listing that is currently being USED as the offered side of
        // a pending player-to-player proposal belongs to that negotiation for
        // everyone except its recipient. Without this filter a third player
        // saw the proposer's zoo light up as another available offer simply
        // because the proposer had to publish the card used to bid on somebody
        // else's animal. The recipient still sees every competing proposal as
        // a separate row, which is the intended auction-like behaviour.
        const reservedFor=pendingDirectHumanTrades().find(o=>
            o?.status==='pending' &&
            o.fromPlayerId===localId &&
            String(o.offeredAnimalId)===String(x?.animalId)
        );
        if(reservedFor && reservedFor.toPlayerId!==active)return false;
        return true;
    });
}
async function publishMultiplayerTradeListing(animal){
    if(!serverAuthoritativeMultiplayerActive()||!animal?.id)return false;
    const animalId=String(animal.id);
    const generation=nextMultiplayerTradeListingIntentGeneration();

    // Publishing can be triggered while the card is physically in a drag. Do
    // not serialize that transient drag state (where enclosureId is temporarily
    // null) as the owner's durable zoo. First finish any older commit, then make
    // sure the stable pre-drag owner snapshot is durable. This is especially
    // important for P2 immediately after opening P1's public-offer row: the
    // view/render transition can otherwise leave a queued commit behind and the
    // five-second listing barrier times out even though the zoo is healthy.
    let durableReady=await awaitDurableZooCommitIdle(5000);
    const ownerId=localClassicMatch?.activePlayerId;
    const stableOwnSnapshot=localClassicMatch?.players?.[ownerId]?.snapshot;
    if(durableReady&&stableOwnSnapshot?.state){
        const t=localMultiplayerBrowserTransport;
        let stableSignature='';
        try{stableSignature=JSON.stringify(stableOwnSnapshot);}catch(_){}
        if(stableSignature&&stableSignature!==String(t?.durableZooLastCommittedSignature||'')){
            commitOwnZooStateToServer(stableOwnSnapshot);
            durableReady=await awaitDurableZooCommitIdle(5000);
        }
    }
    // A newer publish/withdraw supersedes this request before it reaches the
    // server. Never resurrect a listing the player has already replaced.
    if(generation!==multiplayerTradeListingPublishGeneration)return false;
    if(!durableReady){
        showGameNotice?.('Could not publish that multiplayer trade offer while the zoo was still syncing.');
        renderTrade?.();
        return false;
    }
    const r=await sendMultiplayerServerAction('trade-listing',{operation:'publish',animalId:animal.id,intentGeneration:generation});
    const ok=r?.type==='action-committed';
    if(!ok&&generation===multiplayerTradeListingPublishGeneration){
        const current=ownServerTradeListing();
        if(!current||String(current.animalId)===animalId){
            multiplayerPublicTradeListings=multiplayerPublicTradeListings.filter(
                x=>String(x?.playerId||'')!==String(localMultiplayerBrowserTransport?.serverPlayerId||'')
            );
            showGameNotice?.('Could not publish that multiplayer trade offer.');
            renderTrade?.();
        }
    }
    return ok&&generation===multiplayerTradeListingPublishGeneration;
}
async function withdrawMultiplayerTradeListing(expectedAnimalId=null){
    if(!serverAuthoritativeMultiplayerActive())return false;
    const generation=nextMultiplayerTradeListingIntentGeneration();
    const durableReady=await awaitDurableZooCommitIdle(5000);
    // If the player published another animal while this withdrawal was waiting
    // for durable zoo sync, the newer intent wins. Sending this old withdrawal
    // afterwards would otherwise delete the newly published listing.
    if(generation!==multiplayerTradeListingPublishGeneration)return false;
    if(!durableReady)return false;
    const r=await sendMultiplayerServerAction('trade-listing',{
        operation:'withdraw',intentGeneration:generation,
        expectedAnimalId:expectedAnimalId==null?null:String(expectedAnimalId)
    });
    return r?.type==='action-committed'&&
        generation===multiplayerTradeListingPublishGeneration;
}
function proposalsForPublicListing(listing){
    const active=localClassicMatch?.activePlayerId;
    const otherLocal=multiplayerLocalPlayerIdForServerId(listing?.playerId);
    const own=ownServerTradeListing();
    if(!active||!otherLocal||!listing?.animalId||!own?.animalId)return [];
    const ownAnimalId=String(own.animalId),otherAnimalId=String(listing.animalId);
    return pendingDirectHumanTrades().filter(o=>{
        if(o.status!=='pending')return false;
        if(o.fromPlayerId===active&&o.toPlayerId===otherLocal)
            return String(o.offeredAnimalId)===ownAnimalId &&
                   String(o.requestedAnimalId)===otherAnimalId;
        if(o.toPlayerId===active&&o.fromPlayerId===otherLocal)
            return String(o.offeredAnimalId)===otherAnimalId &&
                   String(o.requestedAnimalId)===ownAnimalId;
        return false;
    });
}
function proposalForPublicListing(listing){
    const proposals=proposalsForPublicListing(listing);
    return proposals.find(o=>String(o.id)===String(selectedHumanTradeProposalId))||
        proposals.find(o=>o.toPlayerId===localClassicMatch?.activePlayerId)||
        proposals[0]||null;
}
async function proposePublicMultiplayerTrade(listing){
    const own=ownServerTradeListing();
    if(!own?.animalId||!listing?.animalId||String(own.playerId)===String(listing.playerId))return false;
    // Deliberately NO level comparison here. Human players may negotiate any
    // level combination (L1 for L5 included); same-level is an AI-only rule.
    const toLocal=multiplayerLocalPlayerIdForServerId(listing.playerId);
    if(!toLocal)return false;
    const tradeId=`player-trade-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
    const result=await dispatchLocalMultiplayerAction(localClassicMatch.activePlayerId,'send-human-trade-offer',{
        tradeId,offeredAnimalId:own.animalId,requestedPlayerId:toLocal,requestedAnimalId:listing.animalId
    });
    if(result?.ok)showGameNotice?.(`Trade proposed to ${listing.zooName||'the other zoo'}.`);
    return !!result?.ok;
}
function startPublicTradeListingDrag(event,listing){
    if(!listing?.animal||state.drag||state.pan)return;
    event.preventDefault();event.stopPropagation();
    const rect=event.currentTarget.getBoundingClientRect(),image=document.createElement('img');
    image.className='dragging-animal';applyLocalizedAnimalImage(image,listing.animal);
    image.style.width=`${rect.width}px`;image.style.height=`${rect.height}px`;image.style.pointerEvents='none';document.body.appendChild(image);
    state.drag={
        type:'public-human-trade-proposal',image,listing:cloneForSave(listing),
        offsetX:event.clientX-rect.left,offsetY:event.clientY-rect.top,
        startClientX:event.clientX,startClientY:event.clientY,maxDistance:0
    };
    image.style.left=`${event.clientX-state.drag.offsetX}px`;image.style.top=`${event.clientY-state.drag.offsetY}px`;
}
function movePublicTradeListingDrag(event){
    const drag=state.drag;if(drag?.type!=='public-human-trade-proposal')return;
    drag.maxDistance=Math.max(Number(drag.maxDistance)||0,
        Math.hypot(event.clientX-drag.startClientX,event.clientY-drag.startClientY));
    drag.image.style.left=`${event.clientX-drag.offsetX}px`;
    drag.image.style.top=`${event.clientY-drag.offsetY}px`;
}
async function finishPublicTradeListingDrag(event){
    const drag=state.drag;if(drag?.type!=='public-human-trade-proposal')return;
    const listing=drag.listing;
    const target=document.elementFromPoint(event.clientX,event.clientY);
    const droppedOnOwnOffer=!!(outgoingOfferBox&&target&&
        (target===outgoingOfferBox||outgoingOfferBox.contains(target)));
    const deliberate=(Number(drag.maxDistance)||0)>=6;
    drag.image?.remove();state.drag=null;
    // Proposal gesture mirrors the visual trade: drag THEIR OFFER onto YOUR
    // OFFER. A click/release on the incoming card must never silently send one.
    if(!deliberate||!droppedOnOwnOffer||!ownServerTradeListing()){renderTrade();return;}
    await proposePublicMultiplayerTrade(listing);renderTrade();
}
function renderMultiplayerPublicTradeRows(){
    const container=document.getElementById('opponentZoos');if(!container)return;

    // Human offers are peers of AI offers in the chooser, not a second layer
    // laid over the AI list. The old display:contents wrapper left the dynamic
    // rows outside several layout/position assumptions used by the six normal
    // opponent rows; with both kinds active the trade cards could visually
    // cover the chooser instead of exposing the human offer as another option.
    container.querySelectorAll('.multiplayer-human-trade-row').forEach(row=>row.remove());
    document.getElementById('multiplayerPublicTradeRows')?.remove();

    const appendRow=(listing,proposal=null)=>{
        const row=document.createElement('div');
        const template=document.getElementById('opponentName1');
        row.className=template?.className||'opponent-name';
        row.classList.add('wants-trade','multiplayer-human-trade-row');
        const selected=String(selectedMultiplayerPublicListingPlayerId||'')===String(listing.playerId)&&
            String(selectedHumanTradeProposalId||'')===String(proposal?.id||'');
        if(selected)row.classList.add('selected-trade');
        if(proposal?.toPlayerId===localClassicMatch?.activePlayerId)
            row.classList.add('human-trade-proposal-incoming');
        row.style.display='';
        row.dataset.humanTradePlayerId=String(listing.playerId);
        if(proposal)row.dataset.humanTradeProposalId=String(proposal.id);
        row.textContent=listing.zooName||`Player ${listing.seat||''}`;
        const bar=document.createElement('div');bar.className='opponent-preference-bar';
        const seg=document.createElement('span');seg.className='opponent-preference-segment';
        seg.style.background=multiplayerPlayerColour(multiplayerLocalPlayerIdForServerId(listing.playerId));
        bar.appendChild(seg);row.appendChild(bar);
        row.onclick=()=>{
            // Human and AI rows share the same physical YOUR/THEIR OFFER area.
            // Selecting a human negotiation must deselect the AI row completely;
            // otherwise both renderers can consider themselves selected and the
            // offer area becomes a non-interactive hybrid.
            state.selectedTradeOpponent=null;
            selectedMultiplayerPublicListingPlayerId=listing.playerId;
            selectedHumanTradeProposalId=proposal?.id||null;
            const aiDecline=document.getElementById('declineOpponentOffer');
            if(aiDecline)aiDecline.style.display='none';
            renderTrade();
        };
        // Direct child, exactly like opponentName1..6. This makes AI and human
        // incoming offers participate in one ordered chooser and one layout.
        container.appendChild(row);
    };

    for(const listing of otherServerTradeListings()){
        const incoming=proposalsForPublicListing(listing)
            .filter(o=>o.toPlayerId===localClassicMatch?.activePlayerId);
        // Each incoming proposal gets its own normal zoo row, exactly like
        // several simultaneous AI zoos. If there is no incoming proposal, keep
        // one row for the public listing so this player can initiate a trade.
        if(incoming.length)incoming.forEach(proposal=>appendRow(listing,proposal));
        else appendRow(listing,null);
    }
    // The number/width of chooser rows changed; reposition the shared card area
    // after the unified list has settled instead of using the old AI-only bounds.
    positionOpponentTradeArea();
}
function renderSelectedMultiplayerPublicListing(){
    const listing=otherServerTradeListings().find(x=>String(x.playerId)===String(selectedMultiplayerPublicListingPlayerId));
    if(!listing){
        selectedMultiplayerPublicListingPlayerId=null;
        selectedHumanTradeProposalId=null;
        clearDirectHumanTradeActions();
        return false;
    }
    outgoingOfferBox.style.display='';incomingOfferBox.style.display='';
    incomingOfferBox.innerHTML='';incomingOfferBox.classList.add('trade-filled');
    const proposal=proposalForPublicListing(listing);
    const proposalAnimal=proposal?.toPlayerId===localClassicMatch?.activePlayerId
        ? directTradeAnimal(proposal.fromPlayerId,proposal.offeredAnimalId)
        : listing.animal;
    const img=directHumanTradeCard(proposalAnimal||listing.animal,'incoming');
    if(img){
        if(proposal&&proposal.toPlayerId===localClassicMatch?.activePlayerId){
            img.style.cursor='grab';img.title=`${listing.zooName||'This zoo'} offers this for your listed animal — drag into your zoo to accept.`;
            img.addEventListener('pointerdown',e=>{if(e.button===0)startDirectHumanTradeResultDrag(e,proposal);});
        }else{
            img.style.cursor=ownServerTradeListing()?'grab':'not-allowed';
            img.title=ownServerTradeListing()?`Drag this card onto YOUR OFFER to propose your listed animal for this ${listing.zooName||'zoo'} animal.`:'Put one of your animals in YOUR OFFER first.';
            if(ownServerTradeListing())img.addEventListener('pointerdown',e=>{if(e.button===0)startPublicTradeListingDrag(e,listing);});
        }
        incomingOfferBox.appendChild(img);
    }

    // Incoming human proposals use the same decline button styling/position as
    // AI offers. Declining this proposal does not remove either public listing.
    const oldHumanDecline=document.getElementById('declineHumanTradeOffer');
    if(oldHumanDecline)oldHumanDecline.remove();
    const oldHumanCancel=document.getElementById('cancelHumanTradeOffer');
    if(oldHumanCancel)oldHumanCancel.remove();
    const oldPublicWithdraw=document.getElementById('withdrawPublicTradeListing');
    if(oldPublicWithdraw)oldPublicWithdraw.remove();

    // The public human listing is independent from the private AI outgoing
    // card. Give it its own removal control instead of making the display copy
    // draggable and accidentally mutating state.outgoingOffer.
    if(ownServerTradeListing()){
        const withdraw=document.createElement('button');
        withdraw.id='withdrawPublicTradeListing';
        withdraw.type='button';
        withdraw.className='decline-opponent-offer';
        withdraw.textContent='Remove offer';
        withdraw.style.pointerEvents='auto';
        withdraw.title='Remove your animal from the public multiplayer trade board.';
        withdraw.onclick=async()=>{
            withdraw.disabled=true;
            const listingBefore=cloneForSave(ownServerTradeListing());
            const listedAnimalId=String(listingBefore?.animalId||'');
            // Removing a PUBLIC LISTING changes only trade-board state. The
            // animal never leaves the zoo merely because it is listed, so do
            // not route this through animal-drag/removal logic or clear its
            // enclosure reservation.
            const ok=await withdrawMultiplayerTradeListing(listedAnimalId||null);
            if(ok){
                selectedHumanTradeProposalId=null;
                selectedMultiplayerPublicListingPlayerId=null;
                showGameNotice?.('Your multiplayer trade offer was removed.');
                // Reassert the unchanged owning zoo after the listing ACK. This
                // prevents an older transient "card in YOUR OFFER" snapshot from
                // winning a later durable-sync race and making the animal vanish.
                if(listedAnimalId){
                    const stillOwned=(state.animals||[]).some(
                        animal=>String(animal?.id)===listedAnimalId
                    );
                    if(stillOwned){
                        scheduleLocalMultiplayerSync?.('trade-listing-withdraw-preserve-animal');
                        commitOwnZooStateToServer?.(exportCurrentGameState());
                    }
                }
            }else{
                withdraw.disabled=false;
                showGameNotice?.('Could not remove that multiplayer trade offer.');
            }
            renderTrade();
            renderAnimals?.();
            refreshDrawAvailabilityState?.();
        };
        ensureTradeAreaLayout();
        const tradeArea=document.getElementById('opponentTradeArea');
        if(tradeArea)tradeArea.appendChild(withdraw);
    }

    if(proposal&&proposal.toPlayerId===localClassicMatch?.activePlayerId){
        const decline=document.createElement('button');
        decline.id='declineHumanTradeOffer';
        decline.type='button';
        decline.className='decline-opponent-offer';
        decline.textContent='Decline';
        decline.style.pointerEvents='auto';
        decline.onclick=async()=>{
            await dispatchLocalMultiplayerAction(
                localClassicMatch.activePlayerId,'decline-human-trade',{offerId:proposal.id}
            );
            if(String(selectedHumanTradeProposalId||'')===String(proposal.id))
                selectedHumanTradeProposalId=null;
            renderTrade();
        };
        ensureTradeAreaLayout();
        const tradeArea=document.getElementById('opponentTradeArea');
        if(tradeArea)tradeArea.appendChild(decline);
    }else if(proposal&&proposal.fromPlayerId===localClassicMatch?.activePlayerId){
        const cancel=document.createElement('button');
        cancel.id='cancelHumanTradeOffer';
        cancel.type='button';
        cancel.className='decline-opponent-offer';
        cancel.textContent='Cancel';
        cancel.style.pointerEvents='auto';
        cancel.onclick=async()=>{
            await dispatchLocalMultiplayerAction(
                localClassicMatch.activePlayerId,'cancel-human-trade',{offerId:proposal.id}
            );
            if(String(selectedHumanTradeProposalId||'')===String(proposal.id))
                selectedHumanTradeProposalId=null;
            renderTrade();
        };
        ensureTradeAreaLayout();
        const tradeArea=document.getElementById('opponentTradeArea');
        if(tradeArea)tradeArea.appendChild(cancel);
    }
    return true;
}

// ============================================================
// DIRECT HUMAN TRADES — V2.22.88
// ============================================================
function pruneTerminalDirectHumanTrades(){
    if(!localClassicMatch||!Array.isArray(localClassicMatch.pendingPlayerTrades))return;
    const terminal=new Set(['accepted','completed','declined','cancelled','invalid']);
    const active=localClassicMatch.pendingPlayerTrades.filter(o=>!terminal.has(o?.status));
    const finished=localClassicMatch.pendingPlayerTrades.filter(o=>terminal.has(o?.status)).slice(-8);
    localClassicMatch.pendingPlayerTrades=[...finished,...active];
}
function pendingDirectHumanTrades(){
    if(!localClassicMatch)return [];
    pruneTerminalDirectHumanTrades();
    if(!Array.isArray(localClassicMatch.pendingPlayerTrades))localClassicMatch.pendingPlayerTrades=[];
    return localClassicMatch.pendingPlayerTrades;
}
function directTradeAnimalName(a){return a?.name||a?.english_name||a?.fileName||a?.filename||'Animal';}
function directTradeSnapshotAnimals(playerId,{syncActive=true}={}){
    if(syncActive&&playerId===localClassicMatch?.activePlayerId&&!localClassicMatch?.viewingPlayerId)syncActiveZooIntoLocalMatch();
    const list=localClassicMatch?.players?.[playerId]?.snapshot?.state?.animals;
    return Array.isArray(list)?list:[];
}
function directTradeAnimal(playerId,animalId){
    return directTradeSnapshotAnimals(playerId).find(a=>String(a?.id)===String(animalId))||null;
}
function directTradeSnapshotCanReceiveAfterOutgoing(snapshot,incoming,outgoing){
    if(!snapshot?.state||!incoming||!outgoing)return false;
    // Reuse the game's exact placement/compatibility rules by temporarily
    // evaluating the supplied zoo snapshot as state. This is read-only and
    // restores the live zoo immediately.
    const liveState=state;
    const candidate=cloneForSave(snapshot);
    try{
        state=candidate.state||candidate;
        const outgoingId=String(outgoing.id);
        const liveOutgoing=(state.animals||[]).find(a=>String(a?.id)===outgoingId);
        if(liveOutgoing){
            state.animals=state.animals.filter(a=>String(a?.id)!==outgoingId);
        }
        const probe={...cloneForSave(incoming),enclosureId:null,slotIndex:null,
            reservedEnclosureId:null,reservedSlotIndex:null};
        return Boolean(randomEligibleDestinationForAnimal(probe));
    }catch(error){
        console.warn('Could not preflight remote trade capacity:',error);
        return false;
    }finally{
        state=liveState;
    }
}
function humanTradeSoftlockReason(fromId,offered,toId,requested){
    const fromSnap=localClassicMatch?.players?.[fromId]?.snapshot;
    const toSnap=localClassicMatch?.players?.[toId]?.snapshot;
    if(!fromSnap||!toSnap||!offered||!requested)return 'Trade cannot be verified safely right now.';
    if(!directTradeSnapshotCanReceiveAfterOutgoing(fromSnap,requested,offered))
        return `${localMultiplayerPlayerLabel(fromId)} has no valid enclosure space for ${animalDisplayName(requested)} after trading away ${animalDisplayName(offered)}.`;
    if(!directTradeSnapshotCanReceiveAfterOutgoing(toSnap,offered,requested))
        return `${localMultiplayerPlayerLabel(toId)} has no valid enclosure space for ${animalDisplayName(offered)} after trading away ${animalDisplayName(requested)}.`;
    return '';
}
function authoritativeVisitedTradeAnimal(playerId,renderedAnimal){
    if(!renderedAnimal)return null;
    const serverPlayer=multiplayerServerPlayerForLocalId(playerId);
    const transport=localMultiplayerBrowserTransport;
    const ownServerId=String(serverPlayer?.playerId||'');
    // `players[playerId].snapshot` is refreshed from every server zoo-state
    // packet. Resolve the exact authoritative animal from that snapshot rather
    // than carrying an imported/rendered clone through the visit transition.
    const animals=directTradeSnapshotAnimals(playerId,{syncActive:false});
    let exact=animals.find(a=>String(a?.id)===String(renderedAnimal.id));
    if(exact)return exact;
    // Old/mixed snapshots can have a locally regenerated id. Species/card key
    // is a safe fallback only when it identifies exactly one authoritative card.
    const key=animalCardKey(renderedAnimal);
    const matches=animals.filter(a=>animalCardKey(a)===key);
    return matches.length===1?matches[0]:null;
}
function directTradeAvailableAnimals(playerId,{syncActive=true}={}){
    const reserved=new Set();
    for(const offer of pendingDirectHumanTrades()){
        if(offer.status!=='pending')continue;
        reserved.add(`${offer.fromPlayerId}:${offer.offeredAnimalId}`);
        reserved.add(`${offer.toPlayerId}:${offer.requestedAnimalId}`);
    }
    return directTradeSnapshotAnimals(playerId,{syncActive}).filter(a=>a?.id!=null&&!reserved.has(`${playerId}:${a.id}`));
}
function chooseDirectTradeAnimal(playerId,title,{syncActive=true}={}){
    const animals=directTradeAvailableAnimals(playerId,{syncActive});
    return new Promise(resolve=>{
        const shade=document.createElement('div');
        shade.style.cssText='position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.38);display:flex;align-items:center;justify-content:center';
        const box=document.createElement('div');
        box.style.cssText='width:min(560px,90vw);max-height:78vh;overflow:auto;background:#efe3c2;border:1px solid #796b52;border-radius:9px;padding:15px;box-shadow:0 12px 36px #0005;color:#3d3325';
        const heading=document.createElement('div'); heading.textContent=title; heading.style.cssText='font-size:18px;font-weight:800;margin-bottom:10px';
        const grid=document.createElement('div'); grid.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px';
        for(const animal of animals){
            const b=document.createElement('button'); b.type='button';
            b.textContent=`L${animal.level||'?'} · ${animal.category||''} · ${directTradeAnimalName(animal)}`;
            b.style.cssText='text-align:left;padding:7px;cursor:pointer';
            b.onclick=()=>{shade.remove();resolve(animal);}; grid.appendChild(b);
        }
        if(!animals.length){const empty=document.createElement('div');empty.textContent='No animals available.';grid.appendChild(empty);}
        const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';cancel.style.cssText='margin-top:10px;float:right';
        cancel.onclick=()=>{shade.remove();resolve(null);};
        box.append(heading,grid,cancel);shade.appendChild(box);document.body.appendChild(shade);
    });
}
async function createDirectHumanTradeOffer(){
    if(!localClassicMatch)return false;
    const from=localClassicMatch.activePlayerId,to=localClassicMatch.playerIds.find(id=>id!==from);
    if(!to)return false;
    syncActiveZooIntoLocalMatch();
    // Capture the opponent snapshot before opening either modal. Selecting the
    // first animal removes its overlay; that DOM change can trigger normal UI
    // refresh work, so the second selector must not re-sync the active player's
    // live state into the opponent snapshot.
    const offered=await chooseDirectTradeAnimal(from,`Offer from ${localMultiplayerPlayerLabel(from)}`);
    if(!offered)return false;

    // Classic is one-card-per-species. Only show opponent cards for which the
    // completed two-way exchange leaves BOTH zoos duplicate-free.
    const offeredKey=animalCardKey(offered);
    const fromKeys=new Set(directTradeSnapshotAnimals(from,{syncActive:false}).map(animalCardKey));
    const toKeys=new Set(directTradeSnapshotAnimals(to,{syncActive:false}).map(animalCardKey));
    const opponentAnimals=directTradeAvailableAnimals(to,{syncActive:false}).filter(requested=>{
        const requestedKey=animalCardKey(requested);
        if(requestedKey===offeredKey)return false;
        const senderWouldDuplicate=fromKeys.has(requestedKey) && requestedKey!==offeredKey;
        const receiverWouldDuplicate=toKeys.has(offeredKey) && offeredKey!==requestedKey;
        return !senderWouldDuplicate && !receiverWouldDuplicate;
    });

    const requested=await new Promise(resolve=>{
        const animals=opponentAnimals;
        const shade=document.createElement('div');
        shade.style.cssText='position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.38);display:flex;align-items:center;justify-content:center';
        const box=document.createElement('div');
        box.style.cssText='width:min(560px,90vw);max-height:78vh;overflow:auto;background:#efe3c2;border:1px solid #796b52;border-radius:9px;padding:15px;box-shadow:0 12px 36px #0005;color:#3d3325';
        const heading=document.createElement('div');heading.textContent=`Request from ${localMultiplayerPlayerLabel(to)}`;heading.style.cssText='font-size:18px;font-weight:800;margin-bottom:10px';
        const grid=document.createElement('div');grid.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px';
        for(const animal of animals){
            const b=document.createElement('button');b.type='button';
            b.textContent=`L${animal.level||'?'} · ${animal.category||''} · ${directTradeAnimalName(animal)}`;
            b.style.cssText='text-align:left;padding:7px;cursor:pointer';
            b.onclick=()=>{shade.remove();resolve(animal);};grid.appendChild(b);
        }
        if(!animals.length){const empty=document.createElement('div');empty.textContent='No opponent animals available.';grid.appendChild(empty);}
        const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';cancel.style.cssText='margin-top:10px;float:right';
        cancel.onclick=()=>{shade.remove();resolve(null);};
        box.append(heading,grid,cancel);shade.appendChild(box);
        // Defer by one task so the click that closed selector 1 cannot also
        // interact with selector 2 in the same event dispatch.
        setTimeout(()=>document.body.appendChild(shade),0);
    });
    if(!requested)return false;
    pendingDirectHumanTrades().push({
        id:`player-trade-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,
        fromPlayerId:from,toPlayerId:to,offeredAnimalId:offered.id,requestedAnimalId:requested.id,
        status:'pending',createdRevision:localClassicMatch.revision
    });
    localClassicMatch.revision++;
    renderVisitedZooQuickTabs();
    renderTrade();
    return true;
}

function nextDirectTradeAnimalId(snapshot){
    const animals=Array.isArray(snapshot?.state?.animals)?snapshot.state.animals:[];
    const used=new Set(animals.map(animal=>String(animal?.id)));
    let next=Math.max(1,Number(snapshot?.state?.nextId)||1);
    while(used.has(String(next)))next++;
    if(snapshot?.state)snapshot.state.nextId=Math.max(Number(snapshot.state.nextId)||1,next+1);
    return next;
}
function removeDirectTradeAnimal(snapshot,id){
    const list=snapshot?.state?.animals;if(!Array.isArray(list))return null;
    const i=list.findIndex(a=>String(a?.id)===String(id));return i<0?null:list.splice(i,1)[0];
}
function addDirectTradeAnimal(snapshot,animal,placementSource=null,newId=null){
    if(!snapshot?.state||!animal)return false;
    if(!Array.isArray(snapshot.state.animals))snapshot.state.animals=[];
    const copy=cloneForSave(animal);
    if(newId!=null)copy.id=newId;

    // Human trades exchange cards, but Zoo Curator's normal board renderer only
    // displays animals that occupy a valid enclosure slot. Put the incoming
    // animal directly into the slot vacated by the outgoing animal. This mirrors
    // the existing trade UX: ownership changes atomically and neither card can
    // disappear between snapshots/renders.
    if(placementSource){
        copy.enclosureId=placementSource.enclosureId ?? null;
        copy.slotIndex=placementSource.slotIndex ?? null;
        copy.x=placementSource.x ?? copy.x ?? null;
        copy.y=placementSource.y ?? copy.y ?? null;
    }else{
        copy.enclosureId=null;copy.slotIndex=null;copy.x=null;copy.y=null;
    }
    snapshot.state.animals.push(copy);
    return true;
}
async function acceptDirectHumanTradeOffer(id,destination=null,{skipActiveSync=false}={}){
    if(!localClassicMatch)return false;
    // Human-trade acceptance changes ownership and is a progression action.
    // The sender's later collection finishes the two-stage settlement, but the
    // accepting seat must own the turn when the exchange begins.
    if(!localClassicUsesSimultaneousTurns()&&localClassicMatch.turnPlayerId!==localClassicMatch.activePlayerId)return false;
    if(!skipActiveSync)syncActiveZooIntoLocalMatch();
    const offer=pendingDirectHumanTrades().find(o=>o.id===id&&o.status==='pending');
    if(!offer||!directHumanTradeHasParticipant(offer,localClassicMatch.activePlayerId)||
       offer.toPlayerId!==localClassicMatch.activePlayerId)return false;
    const fromSnap=localClassicMatch.players[offer.fromPlayerId].snapshot;
    const toSnap=localClassicMatch.players[offer.toPlayerId].snapshot;
    const offeredNow=directTradeAnimal(offer.fromPlayerId,offer.offeredAnimalId);
    const requestedNow=directTradeAnimal(offer.toPlayerId,offer.requestedAnimalId);
    if(!offeredNow||!requestedNow){
        offer.status='invalid';
        resumeAITradingAfterHumanTrade();
        renderVisitedZooQuickTabs();renderTrade();return false;
    }

    const softlockReason=humanTradeSoftlockReason(
        offer.fromPlayerId,offeredNow,offer.toPlayerId,requestedNow
    );
    if(softlockReason){
        showTradeCapacityBlock(offeredNow,requestedNow,softlockReason);
        return false;
    }

    const offeredKey=animalCardKey(offeredNow), requestedKey=animalCardKey(requestedNow);
    const fromOtherKeys=new Set((fromSnap.state.animals||[])
        .filter(a=>String(a.id)!==String(offer.offeredAnimalId)).map(animalCardKey));
    const toOtherKeys=new Set((toSnap.state.animals||[])
        .filter(a=>String(a.id)!==String(offer.requestedAnimalId)).map(animalCardKey));
    if(offeredKey===requestedKey || fromOtherKeys.has(requestedKey) || toOtherKeys.has(offeredKey)){
        offer.status='invalid';
        resumeAITradingAfterHumanTrade();
        renderTrade();renderVisitedZooQuickTabs();
        return false;
    }

    const offered=removeDirectTradeAnimal(fromSnap,offer.offeredAnimalId);
    const requested=removeDirectTradeAnimal(toSnap,offer.requestedAnimalId);
    if(!offered||!requested)return false;

    // Each incoming animal takes the exact board position vacated by the animal
    // that zoo traded away. IDs remain the incoming animal's IDs; only physical
    // placement is inherited.
    if(destination?.enclosure){
        const receiverPlacement={
            enclosureId:destination.enclosure.id,
            slotIndex:destination.slotIndex,
            x:offered.x??null,
            y:offered.y??null
        };
        addDirectTradeAnimal(toSnap,offered,receiverPlacement,offer.offeredTransferId??nextDirectTradeAnimalId(toSnap));
    }else{
        addDirectTradeAnimal(toSnap,offered,requested,offer.offeredTransferId??nextDirectTradeAnimalId(toSnap));
    }
    // Phase 1 of a human trade: the accepting zoo receives its animal now,
    // while the other animal remains physically in the trade box for the
    // sender to claim later. Store both the card and its former placement so
    // no zoo snapshot needs to contain an invisible/unplaced animal.
    offer.senderClaimAnimal=cloneForSave(requested);
    offer.senderClaimAnimal.id=offer.requestedTransferId??nextDirectTradeAnimalId(fromSnap);
    offer.senderClaimAnimal.enclosureId=null;offer.senderClaimAnimal.slotIndex=null;
    offer.senderClaimAnimal.x=null;offer.senderClaimAnimal.y=null;
    addDirectTradeAnimal(fromSnap,offer.senderClaimAnimal,null,offer.senderClaimAnimal.id);
    offer.senderVacatedPlacement={
        enclosureId:offered.enclosureId??null,
        slotIndex:offered.slotIndex??null,
        x:offered.x??null,
        y:offered.y??null
    };
    offer.status='accepted-awaiting-sender-claim';
    offer.acceptedRevision=++localClassicMatch.revision;
    recordLocalMultiplayerEvent('trade-accepted',{
        offerId:offer.id,
        fromPlayerId:offer.fromPlayerId,
        toPlayerId:offer.toPlayerId
    });
    autoResumeWriteSuppressed=true;
    try{await importGameState(cloneForSave(toSnap),{deferRender:false});}
    finally{autoResumeWriteSuppressed=false;}
    localClassicMatch.activePlayerId=offer.toPlayerId;
    syncActiveZooIntoLocalMatch();
    renderTrade();
    renderVisitedZooQuickTabs();
    persistHumanTradeBoundary('human-trade-accepted-awaiting-claim');
    // Persist the accepting player's post-trade zoo independently too.
    if(!serverAuthoritativeMultiplayerActive())commitOwnZooStateToServer(exportCurrentGameState());
    return true;
}
function resumeAITradingAfterHumanTrade(){
    if(state.gameMode==='true'||state.sandboxMode||humanTradeBlocksAITrading())return;
    scheduleNextAutonomousOpponentOffer();
}
function declineDirectHumanTradeOffer(id,playerId=localClassicMatch?.activePlayerId){
    const offer=pendingDirectHumanTrades().find(o=>o.id===id&&o.status==='pending');
    if(!offer||!directHumanTradeHasParticipant(offer,playerId)||offer.toPlayerId!==playerId)return false;
    offer.status='declined';offer.declinedRevision=++localClassicMatch.revision;
    resumeAITradingAfterHumanTrade();
    renderVisitedZooQuickTabs();renderTrade();return true;
}
function renderDirectHumanTradeControls(strip){
    // V2.22.92: human trading now lives in the normal OUTGOING/INCOMING
    // trade cards. Remove the temporary quick-tab control from older renders.
    strip?.querySelector?.('.direct-human-trade-controls')?.remove();
}

